  ["BirdKeeperVance1BeatenText"] = "Ufa! Você é bom\nmesmo.",
  ["BirdKeeperVance1SeenText"] = "Você conhece os\nPOKéMON pássaro\vlendários?",
  ["BirdKeeperVanceLegendaryBirdsText"] = "ARTICUNO, ZAPDOS\ne MOLTRES são\fos três POKéMON\npássaro lendários\fMas ouvi que tem\noutros pássaros\vlendários também.",
  ["BlackBeltText_VoicesInMyHead"] = "Arooo! Vocês na\nminha cabeça!\fHae? Estou ouvindo\nmeu radio!",
  ["BlackBeltText_WeirdRadio"] = "Meu radio esta\nquebrado?\vSó esse sinal.",
  ["BlackbeltKenjiAfterBattleText"] = "Isso pede medidas\nextremas.\fVou para as\nmontanhas treinar\vna solidão.",
  ["BlackbeltLaoAfterText"] = "POKéMON de luta\ntemem os\vpsíquicos…",
  ["BlackbeltLaoBeatenText"] = "Isso é chocante!",
  ["BlackbeltLaoSeenText"] = "Nada tememos,\nnós, lutadores!",
  ["BlackbeltLungAfterText"] = "Meu POKéMON\nperdeu… Meu\vorgulho está\vquebrado…",
  ["BlackbeltLungBeatenText"] = "Fui despedaçado!",
  ["BlackbeltLungSeenText"] = "Meus punhos fúrios\ndespedaçam seu\vPOKéMON!",
  ["BlackbeltNobAfterText"] = "Perdi! Estou\nsem palavras!",
  ["BlackbeltNobSeenText"] = "Palavras são\ninúteis. Deixe\vos punhos falar!",
  ["BlackbeltWaiAfterBattleText"] = "Não consegui achar\no KARATE KING em\vJOHTO.\fDizem que ele\ntreina em alguma\vcaverna por aí.",
  ["BlackbeltWaiBeatenText"] = "Balancei e\ncapotei!",
  ["BlackbeltWaiSeenText"] = "Estou fortalecendo\nas pernas firmes\fcontra o balanço\ndo navio!",
  ["BlackbeltYoshiAfterText"] = "Você parece ter\num forte laço\vcom seu POKéMON!",
  ["BlackbeltYoshiBeatenText"] = "Isto não é real!",
  ["BlackbeltYoshiSeenText"] = "Meu POKéMON e eu\nestamos unidos\vpela amizade.\fNosso laço\nnunca se quebra!",
  ["BlackthornCitySignText"] = "CIDADE DE\nBLACKTHORN\fUm Refugio\nMontanhoso",
  ["BlackthornCityTrainerTipsText"] = "TRAINER TIPS\fUm POKéMON\nsegurando uma\fMIRACLEBERRY\ncura qualquer\vproblema status.",
  ["BlackthornCooltrainerF1Text"] = "Você vai fazer\nseu POKéMON\vesquecer golpes?",
  ["BlackthornCooltrainerF2Text"] = "Uau, você veio\npela ICE\vPATH?\fVocê deve ser\num treinador!",
  ["BlackthornDragonSpeechHouseDratiniText"] = "DRATINI: Draa!",
  ["BlackthornDragonSpeechHouseGrannyText"] = "CLAIR e LANCE\ntreinaram aqui\fpara aperfeicoar\nsuas habilidades.",
  ["BlackthornGrampsGrantsEntryText"] = "Como CLAIR, a\nmestra do dragão,\fpermitiu, você\npode entrar.",
  ["BlackthornGrampsRefusesEntryText"] = "Só usuarios de\ndragão podem\ftreinar aqui.\nPor favor, va.",
  ["BlackthornGym2FBoulderFellText"] = "O bloco caiu!\npelo buraco!",
  ["BlackthornGymClairText_DescribeTM24"] = "Isto contém\nDRAGONBREATH.\fNão, não tem\nnada a ver com\vminha respiração.\fSe você não\nquiser, não\vprecisa levar.",
  ["BlackthornGymClairText_League"] = "Você já colecionou\ntodas as\vINSÍGNIAS.\fSeu destino é a\nLIGA POKéMON no\fINDIGO PLATEAU.\nSabe como chegar\flá?\nDaqui, vá para\fCIDADE DE\vNEW BARK.\nDepois SURF\fpara o leste.\nA rota lá é\vmuito difícil.\fNão ouse\nperder na\vLIGA POKéMON!\fSe perder, vou\nme sentir ainda\fpior por ter\nperdido para você",
  ["BlackthornGymClairText_YouKeptMeWaiting"] = "CLAIR: Você se\nprovou para mim.\vQuero que você\ffique com\nesta MT.",
  ["BlackthornGymGuideText"] = "Ei!\nFUTURO\fCAMPEÃO!\nJá faz tempo que\fcomecamos, mas\njá estamos quase\flá! Conta comigo!\nCLAIR usa dragões\vmiticos e sagrados\vdo tipo dragão.\fVocê não consegue\nmachuca-los\ffacilmente.\nMas saiba que\feles são fracos\ncontra gelo.",
  ["BlackthornGymGuideWinText"] = "Você foi incrível\nao vencer CLAIR!\fSó falta o desafio\nda LIGA POKéMON.\vVocê esta no\fcaminho para se\ntornar o\vCAMPEÃO POKéMON!",
  ["BlackthornGymSignText"] = "CIDADE DE\nBLACKTHORN\vPOKéMON GYM\vLÍDER: CLAIR\fA Abencoadora\nDragão",
  ["BlackthornMartBlackBeltText"] = "MAX REPEL mantem\nPOKéMON fracos\vlonge de você.\fE o mais duradouro\ndos sprays\vREPEL.",
  ["BlackthornMartCooltrainerMText"] = "Não pode comprar\nMAX REVIVE, mas\frestaura todo\nPOKéMON desmaiado\fCuidado , não\nrestaura PP, os\fPONTOS DE PODER\nnecessarios.",
  ["BlackthornPokecenter1FGentlemanText"] = "No fundo do longe\nINDIGO PLATEAU\fe a LIGA POKéMON\nOuvi os melhores\ftreinadores vão\nde todo o pais.\fQuero ir lá\num dia.",
  ["BlackthornPokecenter1FTwinText"] = "Havia um movimento\nque eu tinha que\fensinar ao meu\nPOKéMON.\fEntão pedi ao\nAPAGADOR DE GOLPES\vesquecer um HM.",
  ["BlackthornYoungsterText"] = "Vou me tornar\num usuário de\vdragão CLAIR.",
  ["BlaineAfterBattleText"] = "BLAINE: Perdi\ndesta vez, mas\fvou vencer na\npróxima.\fQuando eu refizer\no meu GINÁSIO,\fde CINNABAR,\nteremos revanche.",
  ["BlaineFightDoneText"] = "BLAINE: Meus\nPOKéMON de fogo\fficarão ainda mais\nfortes. Veja!",
  ["BlaineIntroText"] = "BLAINE: Uaaah!\fMeu GINÁSIO em\nCINNABAR queimou.\fEu e meus POKéMON\nde fogo ficamos\fsem casa por\ncausa do vulcão.\fBuaaah!\fMas voltei à ativa\ncomo LÍDER de\fGINÁSIO aqui na\ncaverna.\fSe você me vencer\neu te dou\vuma BADGE.\fHa! Melhor levar\nBURN HEAL!",
  ["BlaineWinLossText"] = "BLAINE: Demais.\nEstou esgotado…\fVocê ganhou a\nVOLCANOBADGE!",
  ["BluesHouseSignText"] = "CASA do BLUE",
  ["BoarderBradAfterBattleText"] = "Adoro patinar\ncom meus POKéMON\vneste GINÁSIO!",
  ["BoarderBradBeatenText"] = "Você vê como\nsomos sérios?",
  ["BoarderBradSeenText"] = "Este GINÁSIO\ntem piso liso.\fÉ divertido, não\né?\fMas ei, aqui nós\nnão estamos\vbrincando!",
  ["BoarderDouglasAfterBattleText"] = "O segredo do\npoder de PRYCE…\fEle medita sob\numa cachoeira\fpara fortalecer\nmente e corpo.",
  ["BoarderDouglasBeatenText"] = "Vou te contar o\nsegredo do PRYCE.",
  ["BoarderDouglasSeenText"] = "Conheço o segredo\ndo PRYCE.",
  ["BoarderRonaldAfterBattleText"] = "Acho que existe um\nmovimento que um\fPOKéMON pode usar\nmesmo congelado.",
  ["BoarderRonaldBeatenText"] = "Droga. Não pude\nfazer nada.",
  ["BoarderRonaldSeenText"] = "Vou congelar\nseus POKéMON, você\vnão fará nada!",
  ["BorrowedABicycleText"] = "{PLAYER} pegou\numa BICYCLE.",
  ["BridgetWhitneyCriesText"] = "Ah, não. Você fez\na WHITNEY chorar.\fTudo bem. Ela para\nlogo. Ela sempre\fchora quando\nperde.",
  ["BrockBoulderBadgeText"] = "BROCK: {PLAYER},\nobrigado. Gostei\fde batalhar com\nvocê, mesmo\vmeio chateado.\fEssa BOULDERBADGE\nvai deixar seus\fPOKéMON ainda\nmais fortes.",
  ["BrockFightDoneText"] = "BROCK: O mundo é\nenorme. Ainda tem\fmuitos treinadores\nfortes como você.\fEspere para ver.\nEu também vou\vficar bem mais\vforte.",
  ["BrockIntroText"] = "BROCK: É raro\nreceber desafio\fde treinador\nvindo de JOHTO.\fEu sou o BROCK,\nLÍDER de PEWTER.\fSou especialista\nem POKéMON pedra.\fMeus POKéMON são\nimunes à maioria\fdos ataques\nfísicos. Vai ser\fdifícil causar\nalgum dano.\fVenha!",
  ["BrockWinLossText"] = "BROCK: Os ataques\nfortes do seu\vPOKéMON venceram\vminha defesa…\fVocê é mais forte\ndo que eu pensava\fVá em frente,\nleve a INSÍGNIA.",
  ["BrunoScript_BrunoBeatenText"] = "Por quê? Como a\ngente perdeu?",
  ["BrunoScript_BrunoBeforeText"] = "Eu sou BRUNO, dos\nELITE FOUR.\fEu sempre treino\nao extremo porque\veu acredito no\vnosso potencial.\fFoi assim que a\ngente ficou forte\fVocê aguenta o\nnosso poder?\fHum? Não vejo medo\nem você. Parece\fdeterminado.\nPerfeito!\fPronto, {PLAYER}?\nVai se curvar\fao nosso poder\nesmagador!\fRuu ha!",
  ["BrunoScript_BrunoDefeatText"] = "Tendo perdido, eu\nnão tenho direito\vde dizer nada…\fVá encarar o seu\npróximo desafio!",
  ["BugCatcherAlAfterBattleText"] = "São tão legais,\nmas as meninas\fnão gostam de\nPOKéMON inseto.\fNão sei por quê…",
  ["BugCatcherAlBeatenText"] = "Você provou como é\ndurão…",
  ["BugCatcherAlSeenText"] = "Os insetos são\nlegais e fortes!\fVou provar para\nvocê!",
  ["BugCatcherArnieAfterBattleText"] = "Meu VENONAT ganhou\no Concurso de\fCaptura Insetos\nno NATIONAL PARK.",
  ["BugCatcherArnieBeatenText"] = "Entendi. Então\nvocê luta assim.",
  ["BugCatcherArnieSeenText"] = "Eu vou a qualquer\nlugar onde apareça\vPOKéMON inseto.",
  ["BugCatcherBennyAfterBattleText"] = "POKéMON ficam\nmais fortes se\vevoluem. Sério!",
  ["BugCatcherBennyBeatenText"] = "Só evoluir não\nbasta!",
  ["BugCatcherBennySeenText"] = "POKéMON inseto\nevoluem jovens.\fE por isso ficam\nmais fortes.",
  ["BugCatcherDonAfterText"] = "Fiquei sem POKé\nBALLS enquanto\vcapturava POKéMON\fDevia ter trazido\nmais…",
  ["BugCatcherDonBeatenText"] = "Argh! Você é\nforte demais!",
  ["BugCatcherDonSeenText"] = "Em vez de um\nPOKéMON, achei\vum treinador!",
  ["BugCatcherDougAfterBattleText"] = "POKéMON inseto\nafundam feito\fpelúcia quando\nvocê aperta.\fEu adoro essa\nsensação!",
  ["BugCatcherDougSeenText"] = "Por que as meninas\nnão gostam deles?",
  ["BugCatcherEdAfterBattleText"] = "Arde de verdade\nquando você toma\vbanho.",
  ["BugCatcherEdBeatenText"] = "Ai, ai, ai!",
  ["BugCatcherEdSeenText"] = "Se você anda no\nmato alto de\fshorts, se corta\ntodo?",
  ["BugCatcherJoshAfterBattleText"] = "Deveria ensinar\na eles melhores\vmovimentos.",
  ["BugCatcherJoshSeenText"] = "Você salvou todos\nos SLOWPOKE?\vUfa! Você é fera!\fMas meus POKéMON\nadultos são bem\vdurões também!",
  ["BugCatcherKenAfterBattleText"] = "Dá para achar um\nmonte de POKéMON\vnas árvores!",
  ["BugCatcherKenBeatenText"] = "Ooh, uau. Você é\ndurão, cara!",
  ["BugCatcherKenSeenText"] = "Vou visitar minha\nvovó para pegar\vuns insetos!",
  ["BugCatcherRobAfterBattleText"] = "Vou procurar\nPOKéMON inseto\vmais fortes.",
  ["BugCatcherWade1AfterText"] = "Você pode pegar\nPOKéMON mesmo se\fvocê tiver seis.\nSe pegar um, ele\fvai para a sua\nBOX\vautomaticamente.",
  ["BugCatcherWade1SeenText"] = "Peguei um monte\nde POKéMON. Vamos\vbatalhar com você",
  ["BugCatchingContestExplanationText"] = "O Concurso de\nCaptura Insetos\fé realizado na\nterça, quinta e\fsábado.\nNão só você ganha\fum prêmio por vir,\ncomo também pode\fficar com um\nPOKéMON inseto.",
  ["BugCatchingContestant10AText"] = "KIPP: Estudei\nmuito sobre\vPOKéMON inseto.\fVou vencer\ncom certeza.",
  ["BugCatchingContestant10BStillCompetingText"] = "KIPP: Estudo bem,\nmas isso não é\fsuficiente para\nvencer.",
  ["BugCatchingContestant10BText"] = "KIPP: Você pode\nme dar dicas?\fQuero estudar\nseu estilo.",
  ["BugCatchingContestant1AText"] = "DON: Vou\nvencer! Não me\vatrapalhe.",
  ["BugCatchingContestant1BStillCompetingText"] = "DON: Sorte tem uma\nmuita influência.\fNunca se sabe\nque POKéMON vai\vaparecer.",
  ["BugCatchingContestant1BText"] = "DON: Uau, você me\nvenceu. Você e\vmuito bom.",
  ["BugCatchingContestant2AText"] = "ED: Meu PARASECT\nfaz POKéMON\vdormir com SPORE.",
  ["BugCatchingContestant2BStillCompetingText"] = "ED: Talvez você\nvenca com POKéMON",
  ["BugCatchingContestant2BText"] = "ED: Invidio você.\nNão consegui\vdesta vez.",
  ["BugCatchingContestant3AText"] = "NICK: Crio\nPOKéMON rápidos\vpara batalhas.",
  ["BugCatchingContestant3BStillCompetingText"] = "NICK: Talvez você\nganhe mais pontos\fmaior com um\nPOKéMON incomum.",
  ["BugCatchingContestant3BText"] = "NICK: Muito bem!\nVou criar meus\vPOKéMON melhor.",
  ["BugCatchingContestant4AText"] = "WILLIAM: Não me\nimporto em\vvencer.\fSó procuro\nPOKéMON raros.",
  ["BugCatchingContestant4BStillCompetingText"] = "WILLIAM: Estou\nsatisfeito porque\fpeguei o POKéMON\nque eu queria.",
  ["BugCatchingContestant4BText"] = "WILLIAM: Você e\no vencedor? O que\vvocê capturou?",
  ["BugCatchingContestant5AText"] = "BENNY: Ssh!\nVai espantar o\fSCYTHER. Falo\ncom você depois.",
  ["BugCatchingContestant5BStillCompetingText"] = "BENNY: Eu capturei\num SCYTHER antes,\vmas não venci.",
  ["BugCatchingContestant5BText"] = "BENNY: Parabéns!\nVocê ganhou meu\vrespeito!",
  ["BugCatchingContestant6AText"] = "BARRY: Você\ndeve enfraquecer\fPOKéMON inseto,\njogue POKé BALL.",
  ["BugCatchingContestant6BStillCompetingText"] = "BARRY: É mais\nvencer se você\fcapturar um\nPOKéMON inseto de\fnível alto.\nMas acho que eles\volham mais coisas",
  ["BugCatchingContestant6BText"] = "BARRY: O POKéMON\nque você capturou\v…e incrível!",
  ["BugCatchingContestant7AText"] = "CINDY: O que foi?\fAcha engraçado\numa garota\fcaçando POKéMON\ninseto?",
  ["BugCatchingContestant7BStillCompetingText"] = "CINDY: Eu amo\nPOKéMON insetos!",
  ["BugCatchingContestant7BText"] = "CINDY: Venceu?\nQue ótimo!\fVocê quer ir\ncaçar POKéMON\vinsetos comigo?",
  ["BugCatchingContestant8AText"] = "JOSH: Coleciono\nPOKéMON inseto\fdesde que era\nbem criança.\fNão tem jeito,\nvou vencer!",
  ["BugCatchingContestant8BStillCompetingText"] = "JOSH: Ouvi que\nalguém venceu\vcom um CATERPIE!",
  ["BugCatchingContestant8BText"] = "JOSH: Eu… não\nacredito que perdi\vno concurso…",
  ["BugCatchingContestant9AText"] = "SAMUEL: Se tem\ntempo para\fconversar, procure\nPOKéMON inseto.",
  ["BugCatchingContestant9BStillCompetingText"] = "SAMUEL: Droga.\nAchei que teria\vmelhor pontuação…",
  ["BugCatchingContestant9BText"] = "SAMUEL: Na próxima\nvou vencer.",
  ["BugContestPrizeNoRoomText"] = "Ué? Sua BOLSA está\ncheia.\fVamos guardar isto\npor hoje, então\fvolte quando tiver\nespaço para ele.",
  ["BugsyText_BugMonsAreDeep"] = "POKéMON inseto são\nprofundos. Há\fmuitos mistérios\na explorar.\fEstude bem os\nseus preferidos.",
  ["BugsyText_FuryCutterSpeech"] = "A TM49 contém\nFURY CUTTER.\fSe você não errar,\nele fica mais\vforte a cada vez.\fQuanto mais longa\na batalha, melhor\vele fica.\fNão é ótimo?\nEu que descobri!",
  ["BugsyText_HiveBadgeSpeech"] = "Conhece as\nvantagens da\vHIVEBADGE?\fCom ela, POKéMON\naté o L30 vão\vobedecer você.\fPOKéMON que sabem\nCUT poderão usar\fo golpe fora da\nbatalha também.\fTome, quero que\nfique com isto.",
  ["BugsyText_INeverLose"] = "Eu sou o BUGSY!\nEu nunca perco\fquando o assunto\né POKéMON inseto.\fMinha pesquisa vai\nme tornar a maior\fautoridade em\nPOKéMON inseto!\fDeixe eu mostrar o\nque aprendi nos\vmeus estudos.",
  ["BugsyText_ResearchIncomplete"] = "Uau, incrível!\nVocê é um perito\vem POKéMON!\fMinha pesquisa\nainda não acabou.\fCerto, você venceu\nLeve esta BADGE.",
  ["BurglarCoreyAfterBattleText"] = "Achei uma moeda\nbonita aqui.\fAlguém deve ter\nperdido…",
  ["BurglarCoreyBeatenText"] = "Que azar!\nEu perdi!",
  ["BurglarDuncanAfterBattleText"] = "Roubar e vender!\nÉ o básico do\vcrime, colega!",
  ["BurglarDuncanSeenText"] = "Passe as suas\ncoisas para cá!",
  ["BurglarEddieAfterBattleText"] = "UNDERGROUND\nWAREHOUSE?\fPara que você quer\nir lá?\fNão tem nada lá\nembaixo.",
  ["BurglarEddieSeenText"] = "Abandonaram esta\nobra antes de\vterminar.\fEstou procurando\no que sobrou.",
  ["BurnedTower1FEusineIntroText"] = "EUSINE: Meu nome\né EUSINE.\fEstou atrás de um\nPOKéMON chamado\vSUICUNE.\fE você é…?\f{PLAYER}? Prazer\nem te conhecer!\fOuvi rumores que\nSUICUNE está\fnesta BURNED\nTOWER, então vim\volhar.\fMas onde será que\nele está?",
  ["BurnedTower1FEusineText"] = "EUSINE: Ouvi que\nSUICUNE está\fnesta BURNED\nTOWER, então vim\volhar.\fMas onde será que\nele está?",
  ["BurnedTower1FMortyText"] = "MORTY: O LÍDER DE\nGINÁSIO de\fECRUTEAK precisa\nestudar os\fPOKéMON lendários\n--SUICUNE, ENTEI\fe RAIKOU.\fEUSINE está aqui,\nentão decidi\finvestigar a\nTOWER com ele.",
  ["BurnedTowerB1FEusineText"] = "EUSINE: Eu também\ncavei um buraco\vaqui…\fFiquei chocado!\fSUICUNE passou\ncomo um borrão,\vbem na frente\vdos meus olhos!\fPor dez anos eu\npersegui SUICUNE,\fe finalmente\nconsegui vê-lo.\fEstou emocionado!\f{PLAYER}, devo\ntudo isso a você!\fObrigado!\fOuvi dizer que os\nPOKéMON lendários\fde ECRUTEAK\ntestam os humanos\fdeixando-os se\naproximar.\fVou atrás de\nSUICUNE.\f{PLAYER}, até\nmais um dia!\fAdeus!",
  ["BurnedTowerRival_AfterText1"] = "…Ah, tanto faz.\fVocê nunca ia\nconseguir pegar\fPOKéMON lendário\nmesmo.",
  ["BurnedTowerRival_BeforeText"] = "…… …… ……\f…Ah, é você.\fVocê queria ficar\nmais forte, então\fveio atrás do\nPOKéMON lendário\fque dizem estar\naqui. É essa a sua\vhistória, né?\fPois isso não vai\nacontecer.\fPorque eu vou\npegar ele!\fEu vou ser o maior\ntreinador do\vmundo, então um\vPOKéMON lendário\vseria perfeito\vpara mim.\f…Enfim, tanto faz\nJá estou cansado\fde ter um banana\ncomo você sempre\vaparecendo.",
  ["BurnedTowerRival_LossText"] = "…Hunf!\fÉ por isso que eu\nodeio lutar com\fbananas. É só\nperda de tempo.",
  ["BurnedTowerRival_WinText"] = "…Hunf!\fÉ por isso que eu\nodeio lutar com\fbananas. Não tem\ndesafio nenhum.",
  ["BurnedTowerSignText"] = "BURNED TOWER\fFoi destruída por\num incêndio\vmisterioso.\fFique longe, pois\nnão é seguro.",
  ["CableClubFriendScript.FriendReadyText"] = "O seu amigo\nestá pronto.",
  ["CameraGrunt1BeatenText"] = "Droga… Eu falhei…",
  ["CameraGrunt1SeenText"] = "Ei!\nInvasor à vista!",
  ["CameraGrunt2BeatenText"] = "Tem câmeras nas\nestátuas de\vPOKéMON.\fVamos aparecendo\naté você achar um\vbotão secreto.",
  ["CameraGrunt2SeenText"] = "Minha vez!\nNão tem saída!",
  ["CamperBarryAfterText"] = "Ei, cara. Meu\ndisfarce era fofo\vou não era, hein?",
  ["CamperBarryBeatenText"] = "Meu disfarce era\nperfeito! Droga!",
  ["CamperBarryBeforeText"] = "Uahahaha!\fPode crer, cara.\nEu sou a JANINE!",
  ["CamperDeanAfterBattleText"] = "Meus POKéMON se\nmachucaram antes\fde entrar no ROCK\nTUNNEL.\fÉ melhor levar\neles ao CENTRO\vPOKéMON já.",
  ["CamperDeanBeatenText"] = "Opa! Perigo, cara",
  ["CamperElliotAfterBattleText"] = "Fui humilhado\nna frente da minha\vnamorada…",
  ["CamperElliotBeatenText"] = "Queria que você\ntivesse perdido…",
  ["CamperElliotSeenText"] = "Vou mostrar para\nminha namorada que\veu sou bom!",
  ["CamperIvanAfterBattleText"] = "A música do rádio\nmuda o humor dos\vPOKéMON selvagens",
  ["CamperJerryAfterBattleText"] = "Ei, você!\nTreinador de\vJOHTO!\fBROCK é durão. Vai\nte punir se\fvocê não o levar a\nsério.",
  ["CamperJerryBeatenText"] = "Preciso vencer\nessas batalhas…",
  ["CamperJerrySeenText"] = "Os treinadores\ndeste GINÁSIO\vusam POKéMON de\fpedra. O tipo\npedra tem DEFESA\falta. As batalhas\npodem demorar\fbastante. Você\nestá preparado?",
  ["CamperLloydAfterBattleText"] = "Dei o meu melhor.\nNada a lamentar.",
  ["CamperLloydSeenText"] = "Certo! Sou o Nº 5.\nVou te esmagar!",
  ["CamperRolandAfterText"] = "Se não quiser\nbatalhar, evite\volhar nos olhos.",
  ["CamperRolandBeatenText"] = "Hmmm. Que\ndecepção.",
  ["CamperRolandSeenText"] = "Aquele olhar…\nÉ intrigante.",
  ["CamperSidAfterBattleText"] = "Desculpe. Você não\njogou lixo. Foi\vengano meu.",
  ["CamperSidBeatenText"] = "Eu só estava\navisando…",
  ["CamperSidSeenText"] = "Ei, você!\nNão jogue lixo!",
  ["CamperSpencerAfterBattleText"] = "O que está\nhavendo no LAKE?\fA gente ia\nacampar lá.",
  ["CamperSpencerBeatenText"] = "Perder não tem\ngraça nenhuma…",
  ["CamperSpencerSeenText"] = "Dá para fazer\ntanta coisa com\vmeu POKéMON!",
  ["CamperTedAfterBattleText"] = "Dei o meu melhor\ne não bastou.\fSem desculpa, eu\nadmito que perdi.",
  ["CamperTedSeenText"] = "Eu também crio\nPOKéMON!\fQuer batalhar\ncomigo?",
  ["CamperTodd1AfterText"] = "Talvez eu devesse\ndeixar um no\vDAYCARE. O que eu\vfaço?",
  ["CamperTodd1BeatenText"] = "Eu não fiz um\ntrabalho bom?",
  ["CamperTodd1SeenText"] = "Tenho confiança\nna minha forma\vde criar POKéMON.\fQuer ver?",
  ["CarefulSwimmingSignText"] = "Atenção: cuidado\nao nadar até as\vSEAFOAM ISLANDS.\vPOLÍCIA de\fFUCHSIA",
  ["CatchingTutorialBoxFullText"] = "POKéMON se\nescondem no mato.\fNunca se sabe\nquando saltam…",
  ["CatchingTutorialDebriefText"] = "É assim que se\nfaz.\fSe enfraquecer\nantes, o POKéMON\vé mais fácil.",
  ["CatchingTutorialDeclinedText"] = "Ah. Tudo bem.\fEnfim, se quer\npegar POKéMON,\fvocê tem que\nandar bastante.",
  ["CatchingTutorialIntroText"] = "Já te vi umas\nvezes. Quantos\fPOKéMON você já\npegou?\fQuer que eu mostre\ncomo pegar\vPOKéMON?",
  ["CatchingTutorialRepeatText"] = "Hã? Quer que eu\nmostre como\vpegar POKéMON?",
  ["CeladonCityDeptStoreSignText"] = "Ache tudo o que\nvocê precisa na\vCELADON DEPT.",
  ["CeladonCityFisherText"] = "Este POLIWRATH é\nmeu parceiro.\fSerá que um dia\nele evolui para\vPOKéMON sapo.",
  ["CeladonCityGameCornerSignText"] = "A diversão de\ntodos,CELADON GAME\vCORNER",
  ["CeladonCityGramps1Text"] = "Os GRIMER têm\naparecido muito.\fViu o lago na\nfrente da casa?\fOs GRIMER vivem lá\nagora.\fDe onde saíram?\nIsto é um problema\vsério…",
  ["CeladonCityGramps2Text"] = "Nihihi! Este\nGINÁSIO é ótimo!\fSó entra garota\naqui!",
  ["CeladonCityLassText"] = "De olhar pro chão\nenquanto\fandava, fiquei\ntonto.",
  ["CeladonCityLassText_Mobile"] = "Adoro ficar\ncercada de\vprédios altos!\fNão é verdade que\no POKéMON CENTER\fde GOLDENROD\nficou muito\vmaior?\fQue demais!\nQueria que\vtivesse\fum lugar assim\naqui em KANTO…",
  ["CeladonCityMansionSignText"] = "CELADON MANSION",
  ["CeladonCitySignText"] = "CIDADE DE CELADON\fA Cidade dos\nSonhos Coloridos",
  ["CeladonCityTeacher1Text"] = "Perdi de novo no\ncaça-níquel…\fAgora as garotas\ntambém jogam.\fVocê devia dar\numa olhada.",
  ["CeladonCityTeacher2Text"] = "A CELADON DEPT.\nSTORE tem a maior\fe melhor seleção\nde mercadorias.\fSe não achar\nlá, não acha em\flugar nenhum.\nNossa… pareço\fum vendedor de\nloja.",
  ["CeladonCityTrainerTipsText"] = "DICAS de TREINO\fGUARD SPEC.\nprotege POKéMON\fcontra ataques\nSPECIAL, como\vfogo e água.\fCompre seus itens\nna CELADON DEPT.\vSTORE!",
  ["CeladonCityYoungster1Text"] = "Quer saber um\nsegredo?\fA CELADON MANSION\ntem uma porta\vsecreta.",
  ["CeladonCityYoungster2Text"] = "Está rolando um\nconcurso de comer\vno restaurante.\fSó de ver eles\ncomendo, já me\vsinto inchado…",
  ["CeladonDeptStore1FDirectoryText"] = "1º ANDAR: RECEPÇÃO\nE SERVIÇOS\f2º ANDAR: MERCADO\nDO TREINADOR\f3º: LOJA DE TM\f4º: PRESENTES\f5º: FARMÁCIA\f6º: MÁQ. DE\nVENDAS",
  ["CeladonDeptStore1FGentlemanText"] = "Esta LOJA é da\nmesma rede que a\fde GOLDENROD.\nAs duas foram\freformadas ao\nmesmo tempo,\vjuntas.",
  ["CeladonDeptStore1FReceptionistText"] = "Bem-vindo à LOJA\nDE DEPARTAMENTOS\vCELADON!\fO índice está\nna parede.",
  ["CeladonDeptStore1FTeacherText"] = "É minha primeira\nvez aqui.\fÉ tão grande…\fTenho medo de me\nperder.",
  ["CeladonDeptStore2FDirectoryText"] = "Produtos ótimos\npara treinadores!\f2º ANDAR: MERCADO\nDO TREINADOR",
  ["CeladonDeptStore2FPokefanMText"] = "Me tornei\ntreinador\fpor incentivo do\nmeu filho.\fFico impressionado\ncom a seleção de\vitens práticos.",
  ["CeladonDeptStore2FYoungsterText"] = "Meu pai está tendo\ntrabalho para\fdecorar os nomes\ndos itens e como\feles devem ser\nusados…",
  ["CeladonDeptStore3FDirectoryText"] = "3º ANDAR: LOJA\fDE TM! Deixe seu\nPOKéMON forte!",
  ["CeladonDeptStore3FGameboyKid1Text"] = "Opa! Negociei meu\nPOKéMON sem tirar\fo UPGRADE que o\nPOKéMON tinha.",
  ["CeladonDeptStore3FGameboyKid2Text"] = "Enfim consegui um\nPORYGON!\fSou péssimo nas\nmáquinas, nunca\fjuntaria moedas\npara trocar…\f…Hã?\fO PORYGON trocado\nvirou outro\vPOKéMON!",
  ["CeladonDeptStore3FSuperNerdText"] = "LOJA DE TM vende\nmovimentos raros.",
  ["CeladonDeptStore3FYoungsterText"] = "Não consigo\ndecidir em qual\fPOKéMON usar esta\nTM…",
  ["CeladonDeptStore4FDirectoryText"] = "Dê seu recado\ncom PRESENTES!\f4º: PRESENTES",
  ["CeladonDeptStore4FSuperNerdText"] = "Vim comprar uma\nSURF MAIL para\vminha namorada.",
  ["CeladonDeptStore4FYoungsterText"] = "Este é o único\nlugar onde você\fcompra uma LOVELY\nMAIL.",
  ["CeladonDeptStore5FDirectoryText"] = "5º ANDAR FARMÁCIA",
  ["CeladonDeptStore5FGentlemanText"] = "Quero comprar\nitens que elevem\fos status do\nPOKéMON, mas não\vtenho dinheiro…",
  ["CeladonDeptStore5FSailorText"] = "Quero um PP UP,\npra elevar o PP\fdos golpes, mas\nnão dá comprar",
  ["CeladonDeptStore5FTeacherText"] = "Usar itens neles\ndeixa o POKéMON\vfeliz.\fEles odeiam alguns\nitens, porém…",
  ["CeladonDeptStore6FDirectoryText"] = "6º ANDAR: PRAÇA DO\nTELHADO: VENDAS",
  ["CeladonDeptStore6FSuperNerdText"] = "Uma máquina de\nvendas com roleta\vde prêmios…\fVocê não vê mais\ndessas hoje.",
  ["CeladonDeptStore6FYoungsterText"] = "Ahh! Não há jogos\naqui!\fEu queria jogar…",
  ["CeladonGameCornerFisherFullCoinCaseText"] = "Ei, sua COIN\nCASE está cheia.\fVocê deve estar\nnuma maré de\vsorte também.",
  ["CeladonGameCornerFisherNoCoinCaseText"] = "Ei, você não tem\numa COIN CASE.\fComo vou te dar\nmoedas, se você\vnão tem uma?",
  ["CeladonGameCornerFisherText1"] = "Hahahaha!\fAs moedas não\nparam de sair!\fHã? Quer jogar,\ngaroto?\fVou dividir minha\nsorte com você!",
  ["CeladonGameCornerFisherText2"] = "Hahahaha!\fÉ bom fazer\ncoisas boas para\fas outras\npessoas!",
  ["CeladonGameCornerFishingGuruText"] = "Acho que esta\nmáquina vai pagar\vagora…\fAs chances variam\nentre máquinas.",
  ["CeladonGameCornerGrampsText"] = "Hmm… As chances\nsão melhores na\ffila do PIKACHU,\n…o que fazer?",
  ["CeladonGameCornerLighterText"] = "Há um isqueiro\naqui.",
  ["CeladonGameCornerPokefanMText"] = "As caça-níqueis\nsão todas de\vúltima geração.",
  ["CeladonGameCornerPoster1Text"] = "Ei!\fAtrás deste\npôster…\fNão há nada!",
  ["CeladonGameCornerPoster2Text"] = "Ei!\fAtrás deste\npôster…\fNão há nada!",
  ["CeladonGameCornerPrizeRoomGentlemanText"] = "Queria um MR.MIME\nmas me faltaram\v100 moedas…",
  ["CeladonGameCornerPrizeRoomPharmacistText"] = "Ufa…\fPreciso ficar\ncalmo e frio…\fNão posso perder\na calma, ou\vperco o dinheiro…",
  ["CeladonGameCornerReceptionistText"] = "Bem-vindo!\fVocê pode trocar\nsuas moedas por\fprêmios incríveis\nna casa ao lado.",
  ["CeladonGameCornerSodaCanText"] = "Uma latinha de\frefri. Alguém vem\nbuscar depois…\fHã? Está vazia!",
  ["CeladonGameCornerTeacherText"] = "É esta máquina\nque eu quero.\fEla me limpou\nontem, então\fdeveria pagar\nhoje.",
  ["CeladonGymGuideText"] = "Ei! Futuro\nCAMPEÃO!\fTambém joga nas\ncaça-níqueis?\fEstou tentando\njuntar moedas\vpara um POKéMON\fde prêmio. Mas\nainda não tenho…",
  ["CeladonGymSignText"] = "CIDADE DE CELADON\nPOKéMON GYM\vLÍDER: ERIKA\fA Princesa que\nama a Natureza",
  ["CeladonMansion2FComputerText"] = "{PLAYER} ligou o\nPC.\f…\fAlguém estava no\nmeio de escrever\vum e-mail.\f…Espero que\nvisite KANTO.\fVai se surpreender\ncom quanta coisa\fmuita coisa\nmudou por aqui.\fTambém verá\nvários POKéMON\fque não existem\nem JOHTO.\fAo PRODUTOR\f…",
  ["CeladonMansion2FMeetingRoomSignText"] = "GAME FREAK\nSALA DE ENCONTROS",
  ["CeladonMansion3FDevRoomSignText"] = "GAME FREAK\nSALA DE PRODUÇÃO",
  ["CeladonMansion3FDrawingText"] = "É um desenho\ndetalhado de uma\vmoça bonita.",
  ["CeladonMansion3FGameProgramText"] = "É o programa do\njogo. Mexer nele\fpode causar um bug\nno jogo!",
  ["CeladonMansion3FReferenceMaterialText"] = "Está cheio de\nmateriais de\vreferência e até\vum POKé DOLL.",
  ["CeladonMansionManagerText"] = "Meus POKéMON me\nfazem companhia,\fnunca me sinto\nsozinho.\fAté o MEOWTH\ntraz dinheiro.",
  ["CeladonMansionManagersSuiteSignText"] = "SUÍTE DO GERENTE\nDA MANSÃO CELADON",
  ["CeladonMansionRoofFisherText"] = "Lugares altos--eu\nadoro eles!\fAcho que a única\ncoisa que ama\faltura tanto\nquanto eu\vé a fumaça!",
  ["CeladonMansionRoofGraffitiText"] = "Tem um grafite\nna parede…\f{PLAYER} desenhou\num bigode!",
  ["CeladonMansionRoofHousePharmacistCurseText"] = "O TM03 é CURSE.\fÉ um golpe que\ndrena o PS da\fvítima aos\npoucos.",
  ["CeladonMansionRoofHousePharmacistIntroText"] = "Deixe-me contar\nalgo terrível…",
  ["CeladonMansionRoofHousePharmacistNotNightText"] = "Claro, não é tão\nassustador\fenquanto ainda há\nluz do dia.\fVolte depois do\npôr do sol, tá?",
  ["CeladonMansionRoofHousePharmacistStoryText"] = "Era uma vez\num menino que\fganhou uma\nBICYCLE nova…\fQuis testá-la\nna mesma hora…\fSe divertia tanto\nque nem notou\fque o sol tinha\nse posto…\fVoltando pra casa\nna noite escura,\fe a BICYCLE\nparou de repente\fOs pedais ficaram\npesados!\fQuando parou\nde pedalar, a\fBICYCLE foi\npuxada pra trás!\fComo se fosse\namaldiçoada e\fquisesse levá-lo\npro abismo!\f…\f…\fSHRIEEEEK!\fO menino estava\nsubindo a\vCYCLING ROAD\f…\nTum-tum-tum!\fPor ter ouvido\ncom paciência,\vfique com a TM03!",
  ["CeladonPokecenter1FCooltrainerFText"] = "ERIKA é mestre em\nPOKéMON do tipo\fgrama. Ela vai\nfazer você pagar\vse bobear.",
  ["CeladonPokecenter1FPharmacistText"] = "O esconderijo\nda EQUIPE ROCKET\ffica no porão da\nCASA DE JOGOS.\fAh, espera. Isso\nfoi há três anos.",
  ["CeladonPrizeRoom_AskWhichPrizeText"] = "Qual prêmio você\nquer?",
  ["CeladonPrizeRoom_ComeAgainText"] = "Oh. Volte com\nmais moedas!",
  ["CeladonPrizeRoom_HereYouGoText"] = "Aqui está!",
  ["CeladonPrizeRoom_NoCoinCaseText"] = "Oh? Você não tem\na COIN CASE.",
  ["CeladonPrizeRoom_NotEnoughCoinsText"] = "Você não tem\nmoedas pra isso…",
  ["CeladonPrizeRoom_NotEnoughRoomText"] = "Você não tem\nespaço para isto.",
  ["CeladonPrizeRoom_PrizeVendorIntroText"] = "Bem-vindo!\fTrocamos suas\nmoedas por\vprêmios incríveis",
  ["CeladonVendingNoMoneyText"] = "Opa, dinheiro\ninsuficiente…",
  ["CeladonVendingNoSpaceText"] = "Não há mais espaço\npara coisas…",
  ["CeladonVendingText"] = "Uma máquina de\nvendas! O menu:",
  ["CelebrityText1"] = "Ai, meu Deus.\nVocê me achou.\fPor favor, não\nconte a ninguém.\fEu te dou isto\npara guardar o\vsegredo. Sim?",
  ["CelebrityText2"] = "É duro ser uma\ncelebridade.\fOnde quer que eu\nvá, me perseguem.\fEu só queria\nficar em paz…",
  ["CeruleanBikeShopSignText"] = "Há um aviso…\naqui…\fA BIKE SHOP mudou\npara CIDADE DE\vGOLDENROD em\vJOHTO…",
  ["CeruleanCapeSignText"] = "CERULEAN CAPE\nadiante",
  ["CeruleanCityCooltrainerFText1"] = "Eu e meu SLOWBRO\nformamos uma\vdupla incrível!",
  ["CeruleanCityCooltrainerFText2"] = "SLOWBRO, mostre\nseu CONFUSION!",
  ["CeruleanCityCooltrainerMText1"] = "A USINA de KANTO\nfica perto do fim\fda ROTA 9.\nHouve um acidente\fde algum tipo\npor lá.",
  ["CeruleanCityCooltrainerMText2"] = "Você quer capturar\num de cada tipo de\vPOKéMON?\fDeve ser um\ndesafio e tanto,\vmas parece legal.",
  ["CeruleanCityFisherRocketTipText"] = "Vi o cara suspeito\nir pro CABO de\vCERULEAN.",
  ["CeruleanCityFisherText"] = "Sou fã da\nMISTY do GINÁSIO\vde CERULEAN.",
  ["CeruleanCitySignText"] = "CIDADE DE CERULEAN\fUma Estranha Aura\nAzul a rodeia.",
  ["CeruleanCitySuperNerdText"] = "O CABO ao norte\né um bom lugar\fpra encontros.\nGarotas gostam!",
  ["CeruleanCityYoungsterText1"] = "Aqui havia uma\ncaverna\fcom POKéMON\nhorríveis e\vfortes.",
  ["CeruleanCityYoungsterText2"] = "Hein?\fMeu ITEMFINDER\nestá reagindo…",
  ["CeruleanGymBadgeSpeechHousePokefanMText"] = "Você está juntando\nBADGES de KANTO?",
  ["CeruleanGymGruntBigMistakeText"] = "Ah não! Já viu\nme! Eu fiz um\vgrande erro!",
  ["CeruleanGymGruntByeText"] = "Ei, você! Esquece\nque me viu, tá?\fVocê não viu,\nnem ouviu nada,\ftá?\nBye-bye, garoto!\fTchau, tchau!",
  ["CeruleanGymGruntIntroText"] = "Upa! Eu desculpa!\nVocê não machucou,\vtá?\fEu muito ocupado.\nSem tempo pra\vpapear com você.\vRuim pra mim se\valguém me vê.",
  ["CeruleanGymGuideText"] = "E aí, futuro\ncampeão!\fComo a MISTY\nsaiu, fui me\fdivertir também!\nHe-he-he.",
  ["CeruleanGymGuideWinText"] = "Uau, você mostrou\ncomo é durão.\fComo sempre, foi\numa baita\vbatalha!",
  ["CeruleanGymNote1Text"] = "Desculpe, saí\npor um tempo.\vMISTY, GYM LEADER",
  ["CeruleanGymNote2Text"] = "Como a MISTY saiu,\nnós também.\vGYM TRAINERS",
  ["CeruleanGymSignText"] = "CIDADE DE CERULEAN\nPOKéMON GYM\vLÍDER: MISTY\fA Sereia\nLevada",
  ["CeruleanLockedDoorText"] = "Está trancado…",
  ["CeruleanMart_CooltrainerFText"] = "A MISTY é a única\nna cidade que\fvence os caras\ndo CAPE de\vCERULEAN.",
  ["CeruleanMart_CooltrainerMText"] = "Você vai ver\nmuitos por aí no\fcaminho pro CAPE\nde CERULEAN.\fEles querem ver\ncomo se saem\fcontra outros\ntreinadores.",
  ["CeruleanPokecenter1FGymGuideText"] = "O MAGNET TRAIN\nanda a mais de\f540 km/h. Ele vai\nde KANTO a JOHTO\fem quase nenhum\ntempo.\fIsso aproxima\nJOHTO de você.",
  ["CeruleanPokecenter1FSuperNerdText"] = "A ROTA 9 vai\npara o leste. A\fPOWER PLANT fica\nno fim.",
  ["CeruleanPokecenter1FSuperNerdText_Mobile"] = "Você batalha por\ncelular?\fSe o tempo acabar\ndurante uma luta,\fesperar pra ver\nquem ganhou é\vmuito tenso.",
  ["CeruleanPoliceSignText"] = "Há um aviso…\naqui…\fAcabe com os\nladrões e faça da\fcidade um lugar\nmais alegre!\fPOLÍCIA CERULEAN",
  ["CeruleanPoliceStationFishingGuruText"] = "Ouvi dizer que um\nsujeito esquisito\vestá rondando.\fNão vou tolerar\nse ele acabar\vsendo ladrão.",
  ["CeruleanPoliceStationPokefanFText"] = "Já fomos vítimas\nde assaltantes.",
  ["CeruleanTradeSpeechHouseGrampsText"] = "Ah… Que alegria…",
  ["CeruleanTradeSpeechHouseGrannyText"] = "Meu marido vive\nfeliz com o\vPOKéMON que ele\vganhou em trocas.",
  ["CharcoalKilnApprenticeText1"] = "Para onde foram\nos SLOWPOKE?\fEstão brincando\nem algum lugar?",
  ["CharcoalKilnApprenticeText2"] = "Desculpe, esqueci\nde agradecer.\fIsto é CHARCOAL\nque eu fiz.\fPOKéMON de fogo\nvai adorar\vsegurar isso.",
  ["CharcoalKilnApprenticeText3"] = "Os SLOWPOKE\nvoltaram, e você\vachou FARFETCH'D.\fVocê é o cara!\nBacana, hein!",
  ["CharcoalKilnBossText1"] = "Todos os SLOWPOKE\nsumiram\vda cidade.\fO protetor da\nfloresta pode\vestar bravo…\fPode ser mau\nagouro. É melhor\vficar em casa.",
  ["CharcoalKilnBossText2"] = "Os SLOWPOKE\nvoltaram…\fMas meu APRENDIZ\nnão voltou\vda ILEX FOREST.\fOnde será que\nestá o folgado?",
  ["CharcoalKilnBossText3"] = "Você espantou a\nTEAM ROCKET e foi\fsozinho pra ILEX\nFOREST?\fQue coragem!\nGostei. Vem\vtreinar conosco!",
  ["CharcoalKilnSignText"] = "FORNO DE CARVÃO",
  ["ChefText_Eatathon"] = "Oi!\fEstamos fazendo\numa competição\fde comilança. Não\npodemos atender.",
  ["CherrygroveCitySignText"] = "CIDADE DE\nCHERRYGROVE\fA cidade das\nflores perfumadas",
  ["CherrygroveEvolutionSpeechHouseLassText"] = "POKéMON muda?\fEu ia levar um\nsusto se mudasse!",
  ["CherrygroveEvolutionSpeechHouseYoungsterText"] = "POKéMON ganha\nexperiência em\fbatalha e muda\nde forma.",
  ["CherrygroveGymSpeechHouseBugCatcherText"] = "Quando eu crescer,\neu vou ser LÍDER\vde GINÁSIO!\fBoto meus POKéMON\npara lutar\fcom os do amigo e\ndeixá-los duros.",
  ["CherrygroveGymSpeechHousePokefanMText"] = "Você quer ver o\nquanto é bom\fcomo treinador\nde POKéMON?\fÉ melhor visitar\nos GINÁSIOS por\ftoda JOHTO e\njuntar INSÍGNIAS.",
  ["CherrygroveMartCooltrainerMText"] = "Acabaram as\nPOKé BALLS!\fQuando será que\nchegam mais?",
  ["CherrygroveMartCooltrainerMText_PokeBallsInStock"] = "Tem POKé BALLS em\nestoque! Agora\vposso pegar!",
  ["CherrygroveMartYoungsterText"] = "Quando eu andava\nno mato, um\fPOKéMON inseto\nenvenenou o meu!\fEu segui andando,\nmas aí o meu\vPOKéMON desmaiou.\fÉ bom andar com um\nANTIDOTE.",
  ["CherrygrovePokecenter1FFisherText"] = "É ótimo. Dá para\nguardar quantos\fPOKéMON quiser, e\ntudo de graça.",
  ["CherrygrovePokecenter1FGentlemanText"] = "Aquele PC é livre\npara qualquer\vtreinador usar.",
  ["CherrygrovePokecenter1FTeacherText"] = "O CENTRO DE\nCOMUNICAÇÃO lá em\vcima é novinho.\fMas ainda estão\nterminando ele.",
  ["CherrygrovePokecenter1FTeacherText_CommCenterOpen"] = "O CENTRO DE\nCOMUNICAÇÃO lá em\vcima é novinho.\fJá troquei POKéMON\nlá!",
  ["CherrygroveRivalText_Seen"] = "…\fVocê pegou um\nPOKéMON no LAB.\fQue desperdício.\nUm fraco desses.\f…\fNão entendeu o\nque eu disse?\fPois eu tenho um\nPOKéMON bom.\fVou te mostrar\no que eu digo!",
  ["CherrygroveRivalText_YouLost"] = "…\fMeu nome é ???.\fEu vou ser o\nmelhor treinador\vPOKéMON do\vmundo.",
  ["CherrygroveRivalText_YouWon"] = "…\fMeu nome é ???.\fEu vou ser o\nmelhor treinador\vPOKéMON do\vmundo.",
  ["CherrygroveTeacherText_HaveMapCard"] = "Com POKéMON por\nperto, qualquer\vlugar é bom.",
  ["CherrygroveTeacherText_NoMapCard"] = "Você falou com o\nvelho perto do\vCENTRO POKéMON?\fEle põe um MAPA de\nJOHTO na sua\vPOKéGEAR.",
  ["CherrygroveYoungsterText_HavePokedex"] = "Eu lutei com os\ntreinadores da\vestrada.\fMeus POKéMON\nperderam feio!\fPreciso levar eles\nao CENTRO POKéMON",
  ["CherrygroveYoungsterText_NoPokedex"] = "A casa do\nMR.POKéMON fica\vmais adiante.",
  ["ChoseStarterText"] = "ELM: Acho esse\num ótimo\vPOKéMON também!",
  ["ChuckAfterText"] = "UAHAHAH! Adorei\nbatalhar com você\fMas derrota é\nderrota!\fDe agora em diante\nvou treinar 24\vhoras por dia!",
  ["ChuckExplainBadgeText"] = "A STORMBADGE faz\ntodo POKéMON até\fo L70 obedecer,\naté os trocados.\fEla também deixa\nseu POKéMON usar\fFLY fora da\nbatalha.\fTome, fique com\nisto também!",
  ["ChuckExplainTMText"] = "Isso é o\nDYNAMICPUNCH.\fEle nem sempre\nacerta, mas\fquando acerta,\ncausa confusão!",
  ["ChuckIntroText1"] = "UAHAHAH!\fEntão você chegou\naté aqui!\fVou te avisar:\neu sou durão!\fMeus POKéMON vão\nesmagar pedras e\vquebrar ossos!\fOlhe só isto!",
  ["ChuckIntroText2"] = "CHUCK: Urggh!\n…\fOoooarrgh!",
  ["ChuckIntroText3"] = "Pronto! Com medo\nagora, hein?\fO quê?\nNão tem nada\fa ver com POKéMON?\nÉ verdade!\fVamos lá. Nós dois\nvamos batalhar!",
  ["ChuckLossText"] = "Hã? Quê?\nEu perdi?\fVeja só isso!\nVocê merece a\vSTORMBADGE!",
  ["ChucksWifeBeatChuckText"] = "Mas não dá para\nusar FLY sem a\vBADGE daqui.\fSe vencer o LÍDER\ndo GINÁSIO daqui,\vvenha me ver.\fVou ter um belo\npresente pra você",
  ["ChucksWifeChubbyText"] = "Meu marido perdeu\npara você, então\vtem que treinar.\fAinda bem, porque\nele estava ficando\vmeio gordinho.",
  ["ChucksWifeEasierToFlyText"] = "Você atravessou o\nmar para chegar?\fDeve ter sido\nbem difícil.\fSeria bem mais\nfácil se o seu\fPOKéMON soubesse\nusar FLY…",
  ["ChucksWifeFlySpeechText"] = "Ensine FLY ao seu\nPOKéMON.\fVocê vai poder\nvoar na hora\fpara qualquer\nlugar já\vvisitado.",
  ["ChucksWifeGiveHMText"] = "Essa é a BADGE do\nGINÁSIO daqui!\fEntão você deve\nlevar este HM.",
  ["CianwoodCityLassText"] = "O CHUCK, LÍDER do\nGINÁSIO, treina\fcom os POKéMON\nlutadores dele.",
  ["CianwoodCityPokefanMText"] = "As pedras ao norte\nda cidade podem\vser quebradas.\fElas podem estar\nescondendo algo.\fSeu POKéMON pode\nusar ROCK SMASH\vpara quebrar.",
  ["CianwoodCitySignText"] = "CIDADE DE CIANWOOD\fUm Porto Cercado\npor Mares Bravios",
  ["CianwoodCityUnusedText"] = "Tem várias ilhas\nentre aqui e\vOLIVINE.\fDizem que uma\ncriatura marinha\vmítica mora lá.",
  ["CianwoodCityYoungsterText"] = "Se usar o FLY,\ndá para voltar\fpara OLIVINE na\nhora.",
  ["CianwoodGymGuideText"] = "Os treinadores do\nGINÁSIO daqui são\vuns brutamontes.\fSe eu ficar aqui,\neles podem vir\vpara cima de mim.\fVai uma dica: o\nLÍDER do\fGINÁSIO usa o\ntipo lutador.\fEntão confunda\nele com POKéMON\vpsíquicos.\fAcabe com eles\nantes que usem\fa força\nfísica deles.",
  ["CianwoodGymGuideWinText"] = "{PLAYER}! Você\nganhou! Dá para\vver na sua cara!",
  ["CianwoodGymSignText"] = "CIDADE DE CIANWOOD\nGINÁSIO POKéMON\fLÍDER: CHUCK\fQuem Fala São os\nPunhos Dele",
  ["CianwoodLugiaSpeechHouseLassText"] = "Ouvi dizer que só\ndá para vê-la se\fvocê tiver uma\nSILVER WING.\fEla deve ter o\nmesmo cheiro da\vcriatura.",
  ["CianwoodLugiaSpeechHouseTeacherText"] = "Você veio de\nOLIVINE?\fLembra das quatro\nilhas que ficam\vno caminho?\fOuvi dizer que\numa criatura\vmítica do mar\vse esconde lá.",
  ["CianwoodLugiaSpeechHouseTwinText"] = "Os redemoinhos\nperto das ilhas\fdevem ser causados\npela criatura.",
  ["CianwoodPharmacySignText"] = "500 Anos de\nTradição\fCIDADE DE CIANWOOD\nFARMÁCIA\fTire Suas Dúvidas\nsobre Remédios",
  ["CianwoodPhotoStudioFishingGuruText_No"] = "Ah, que pena.\nAchei que seria\fuma bela\nlembrança…",
  ["CianwoodPhotoStudioFishingGuruText_Question"] = "Você está com uns\nPOKéMON\vmagníficos.\fQue tal uma foto\nde lembrança?",
  ["CianwoodPhotoStudioFishingGuruText_Yes"] = "Certo! Sorria!",
  ["CianwoodPhotoStudioSignText"] = "CIDADE DE CIANWOOD\nESTÚDIO DE FOTO\fTire um Retrato\nde Lembrança!",
  ["CianwoodPokecenter1FLassText"] = "Você conheceu o\nPOKéMANIAC?\fEle vive se\ngabando dos\vPOKéMON raros.",
  ["CianwoodPokecenter1FSuperNerdText"] = "Adoro mostrar os\nPOKéMON que\feu criei.\nVocê não?\fVou entrar em\numa porção de\fbatalhas pra\nmostrar meus\vPOKéMON!",
  ["CianwoodPokecenter1FUnusedText1"] = "Você não sente\nvontade de mostrar\fseus POKéMON pros\namigos?\fQueria poder\nmostrar o POKéMON\fque criei pro meu\namigo em VIOLET.",
  ["CianwoodPokecenter1FUnusedText2"] = "Tenho batalhado\ncom meu amigo em\fVIOLET usando um\nMOBILE ADAPTER.\fEstou perdendo\nde 5-7 pra ele.\vTenho que\vmelhorar!",
  ["CinnabarGymSignText"] = "O que este cartaz\ndiz?\fCINNABAR GYM\nLÍDER: BLAINE",
  ["CinnabarIslandBlueText"] = "Quem é você?\fBem, é óbvio\nque você é um\vtreinador…\fMeu nome é BLUE.\fEu já fui o\nCAMPEÃO, embora\ftenha sido por\npouco tempo…\fAquele RED\nme venceu…\fEnfim, o que\nvocê quer? Quer\fme desafiar ou\no quê?\f…Detesto dizer,\nmas não estou a\ffim de lutar\nagora.\fOlhe ao seu\nredor…\fUm vulcão entra\nem erupção, e de\frepente, uma\ncidade some.\fPodemos ganhar\ne perder em lutas\fde POKéMON. Mas\nse a natureza se\fmexer, morremos\nnum segundo.\f…\fÉ assim que as\ncoisas são…\fMas, enfim, ainda\nsou treinador.\fSe vejo um\nadversário bom,\vme dá vontade de\flutar.\nSe quiser,\vvá ao GINÁSIO de\fVIRIDIAN. Vou te\nenfrentar.",
  ["CinnabarIslandGymSignText"] = "Há um aviso…\naqui…\fO GINÁSIO de\nCINNABAR mudou\vpara as ILHAS\vSEAFOAM.\fBLAINE",
  ["CinnabarIslandSignText"] = "CINNABAR ISLAND\fA Cidade Fogo de\nDesejo Ardente",
  ["CinnabarPokecenter1FCooltrainerFText"] = "BLAINE, do GINÁSIO\nde CINNABAR\fmora sozinho na\nCAVERNA das\vSEAFOAM ISLANDS…",
  ["CinnabarPokecenter1FFisherText"] = "Já faz um ano\ndesde que o vulcão\ventrou em erupção",
  ["ClairIntroText"] = "Sou CLAIR. Eu sou\na melhor mestra\vdo dragão do\fmundo.\nPosso rivalizar\faté com os QUATRO\nGRANDES da LIGA\fPOKéMON.\nAinda quer\fme desafiar?\n…Tudo bem.\fVamos lá!\nComo treinadora,\fvou usar o maximo\ncontra oponente!",
  ["ClairText_DescribeDragonbreathDragonDen"] = "Isto contém\nDRAGONBREATH.\fNão, não tem\nnada a ver com\vminha respiração.\fSe você não\nquiser, não\vprecisa levar.",
  ["ClairText_GiveDragonbreathDragonDen"] = "CLAIR: Tudo bem.\nReconheço seu\fverdadeiro poder.\nEste BADGE é seu",
  ["ClairText_GoToDragonsDen"] = "Não vou admitir\nisso.\fPode ter sido\nderrotada, mas\fvocê ainda não\nesta pronta para\fa LIGA POKéMON.\nSei. Você deveria\vfazer o desafio\fdo usuário\ndragão.\vAtrás deste GYM\fha um lugar\nchamado\fDRAGON'S DEN.\nVa e me traga o\fDRAGON FANG\ndo fundo da DEN.\fEsse e o teste\npara ser aceito\fcomo um\nverdadeiro\vusuário dragão.\vSe conseguir,\fvou aceita-lo\ncomo treinador.\vAté lá, INSÍGNIA!",
  ["ClairWinText"] = "Eu perdi?\fNão acredito.\nDeve haver algum\vengano…",
  ["CoinVendor_Buy500CoinsText"] = "Obrigado! Aqui\nestão 500 fichas.",
  ["CoinVendor_Buy50CoinsText"] = "Obrigado!\nAqui, 50 fichas.",
  ["CoinVendor_CancelText"] = "Sem fichas hoje?\nVolte sempre!",
  ["CoinVendor_CoinCaseFullText"] = "Opa! Sua COIN\nCASE está cheia.",
  ["CoinVendor_IntroText"] = "Precisa de umas\nfichas de jogo?\fSão ¥1000 por\n50 fichas. Quer\vcomprar?",
  ["CoinVendor_NoCoinCaseText"] = "Precisa de fichas\nde jogo?\fAh, você não tem\numa COIN CASE\vpara elas.",
  ["CoinVendor_NotEnoughMoneyText"] = "Você não tem\ndinheiro.",
  ["CoinVendor_WelcomeText"] = "Bem-vindo ao\nGAME CORNER.",
  ["ComeHomeForDSTText"] = "Volte para casa\npara ajustar o\frelógio no horário\nde verão.\fA propósito, você\nsabe usar o\vTELEFONE?",
  ["ContestResults_ConsolationPrizeText"] = "Todos os outros\nganham uma BERRY\vde consolação!",
  ["ContestResults_DidNotWinText"] = "Esperamos que vá\nmelhor na próxima",
  ["ContestResults_JoinUsNextTimeText"] = "Volte para o\npróximo Concurso!",
  ["ContestResults_PartyFullText"] = "Seu grupo está\ncheio, então o\fPOKéMON foi para\na BOX do BILL.",
  ["ContestResults_ReadyToJudgeText"] = "Vamos agora julgar\nos POKéMON que\vvocê pegou.\f……\n……\fJá escolhemos os\nvencedores!\fVocê está pronto\npara isto?",
  ["ContestResults_ReturnPartyText"] = "Vamos devolver o\nPOKéMON que\fguardamos.\nAqui está!",
  ["CooltrainerfBeth1BeatenText"] = "POKéMON não são\narmas de guerra.",
  ["CooltrainerfBeth1SeenText"] = "Perdi para o\n{RIVAL}.\fEle era muito\nforte, mas…\fEra como se ele\nquisesse vencer\va qualquer custo.\fSenti pena dos\nPOKéMON dele.",
  ["CooltrainerfBethAfterText"] = "POKéMON são\nvaliosos parceiros\vpara a vida toda.",
  ["CooltrainerfCarolAfterBattleText"] = "Um dia eu venço\nvocê!",
  ["CooltrainerfCarolBeatenText"] = "Qual é a diferença\nentre nós dois?",
  ["CooltrainerfCarolSeenText"] = "Estou treinando\npara ser CAMPEÃO",
  ["CooltrainerfCybilAfterBattleText"] = "A gente melhora\nvivendo muitas\vbatalhas.\fLutei muito para\nser o que sou\vhoje, uma elite.",
  ["CooltrainerfCybilBeatenText"] = "Não! Assim não\ndá mesmo.",
  ["CooltrainerfCybilSeenText"] = "Você parece forte\fBons treinadores\nprocuram rivais\vfortes por si.",
  ["CooltrainerfEmmaAfterBattleText"] = "Uma vez por semana\num POKéMON vem\vaté a beira.\fEu queria ver\nesse POKéMON…",
  ["CooltrainerfEmmaBeatenText"] = "Prefiro fazer\ncarinho neles!",
  ["CooltrainerfEmmaSeenText"] = "Se o POKéMON que\neu gosto estivesse\vlá, eu iria.\fÉ o que um\ntreinador faz.",
  ["CooltrainerfFranAfterBattleText"] = "Ufa…\fVou ter que\nrepensar o treino",
  ["CooltrainerfFranBeatenText"] = "Argh! Estou tão\nenojado!",
  ["CooltrainerfFranSeenText"] = "Treinamos firme\ncom a CLAIR.\vNão posso perder\vde jeito nenhum!",
  ["CooltrainerfGwenAfterBattleText"] = "Vou treinar\nsozinho até eu\vmelhorar.",
  ["CooltrainerfGwenBeatenText"] = "Aah, não! Você é\nbom demais.",
  ["CooltrainerfGwenSeenText"] = "Estou treinando.\nTopa uma partida?",
  ["CooltrainerfIreneAfterText1"] = "IRENE: Minha irmã\nKATE vai te pegar\vpor isso!",
  ["CooltrainerfIreneAfterText2"] = "IRENE: Esta praia\nnão é ótima?\fÉ o nosso refúgio\nsecreto!",
  ["CooltrainerfIreneBeatenText"] = "IRENE: Ooooh!\nEle é forte!",
  ["CooltrainerfIreneSeenText"] = "IRENE: Aaaai!\nUm menino achou!",
  ["CooltrainerfJennAfterText1"] = "JENN: Não se ache\ndemais! Minha irmã\vKATE é durona!",
  ["CooltrainerfJennAfterText2"] = "JENN: A luz do sol\ndeixa o corpo\vmais forte.",
  ["CooltrainerfJennBeatenText"] = "JENN: Me desculpe,\nIRENE! Maninha!",
  ["CooltrainerfJennSeenText"] = "JENN: Não dá para\nvencer a IRENE e\vficar impune!",
  ["CooltrainerfJoyceAfterBattleText"] = "Eu derrotei\noito LÍDERES,\fentão estava\nconfiante.\fVou ter que\nme esforçar mais.",
  ["CooltrainerfJoyceBeatenText"] = "Não! Eu não\nacredito nisso!",
  ["CooltrainerfJoyceSeenText"] = "Já que você chegou\naté aqui, deve ser\vbom.\fVou dar nessa\nbatalha tudo o\vque tenho!",
  ["CooltrainerfKateAfterText"] = "KATE: Desculpe ter\npulado em cima.\fNunca esperamos\nque alguém nos\fachasse aqui. Você\nnos assustou.",
  ["CooltrainerfKateBeatenText"] = "KATE: Não! Não\nacredito nisso.",
  ["CooltrainerfKateOfferSoftSandText"] = "KATE: Você é forte\ndemais. Eu não\vtive chance.\fTome. Você merece\nisto.",
  ["CooltrainerfKateSeenText"] = "KATE: Você foi bem\nmalvado com as\vminhas irmãzinhas",
  ["CooltrainerfKellyAfterBattleText"] = "Não sou a favor\nde golpes fortes\vdemais.\fQuero ganhar, mas\ntambém não quero\vferir POKéMON.",
  ["CooltrainerfKellySeenText"] = "Qual é a sua\nestratégia?\fÉ tolice usar\ngolpes fortes\vsem critério.",
  ["CooltrainerfLoisAfterBattleText"] = "Pensando bem,\nvi um BUTTERFREE\vrosa.",
  ["CooltrainerfLoisSeenText"] = "O que aconteceu\ncom o GYARADOS\fvermelho? Sumiu?\fDroga. Vim\nà toa?\fJá sei, vamos\nbatalhar!",
  ["CooltrainerfLolaAfterBattleText"] = "Dragões são fracos\ncontra movimentos\vde dragão.",
  ["CooltrainerfLolaSeenText"] = "Os dragões são\nPOKéMON sagrados.\fEles têm muita\nenergia vital.\fSe você não levar\na sério, não vai\fconseguir\nderrotá-los.",
  ["CooltrainerfMeganAfterBattleText"] = "Analiso os POKéMON\nantes e depois da\vevolução.\fEvoluir de verdade\ndeixa os POKéMON\vmais fortes.\fMas as formas\nevoluídas também\vaprendem depois.",
  ["CooltrainerfMeganBeatenText"] = "Ah! Você é\nrealmente forte!",
  ["CooltrainerfMeganSeenText"] = "É raro ver\nalguém por aqui.\fVocê treina\nsozinho?",
  ["CooltrainerfQuinnAfterBattleText"] = "Você é forte.\fDá para ver que\ntreinou bastante.",
  ["CooltrainerfQuinnSeenText"] = "Ei, você aí!\nQuer batalhar?",
  ["CooltrainerfReenaAfterBattleText"] = "Você é um garoto,\nmas não dá para\fte subestimar.\nNem de longe.",
  ["CooltrainerfReenaBeatenText"] = "Ah! Você é\nforte demais!",
  ["CooltrainerfReenaSeenText"] = "Você não deveria\nsubestimar os\fPOKéMON selvagens\ndestas bandas.",
  ["CooltrainermAaronAfterBattleText"] = "POKéMON e o dono\nficam fortes\fcom batalha\nconstante.",
  ["CooltrainermAaronBeatenText"] = "Ufa…\nBoa batalha.",
  ["CooltrainermAaronSeenText"] = "Se um treinador vê\noutro, ele tem\fque fazer um\ndesafio. Esse\fé o nosso\ndestino.",
  ["CooltrainermAllenAfterBattleText"] = "Uau. Você tem\nmuitas BADGES.\fNão é à toa que\né tão forte.\fSerá que o MORTY\ndo GINÁSIO de\fECRUTEAK ainda\nestá treinando?\fEle me arrebentou\nfeio.",
  ["CooltrainermAllenBeatenText"] = "Tch! Foi derrota\ntotal pra mim.",
  ["CooltrainermAllenSeenText"] = "Dá para ver que\nvocê é um bom\vtreinador.\fEu sou bom em\nPOKéMON e vejo que\vvocê também é.",
  ["CooltrainermBlakeAfterBattleText"] = "Se você vencer\nesta trilha dura,\fa verdade será\nrevelada!\fHeh, desculpa, só\nqueria dizer\valgo legal.",
  ["CooltrainermBlakeSeenText"] = "Você parece\nbem forte.\vVamos batalhar!",
  ["CooltrainermBrianAfterBattleText"] = "Um bom treinador\nreconhece outros\vbons treinadores.",
  ["CooltrainermBrianBeatenText"] = "Como eu pensei!",
  ["CooltrainermBrianSeenText"] = "Hm? Você é bom,\nnão é?",
  ["CooltrainermCodyAfterBattleText"] = "Mas espere só!\nMeus POKéMON vão\fficar ainda mais\npoderosos.\fComo treinador\ne POKéMON, seremos\vmais fortes!",
  ["CooltrainermCodyBeatenText"] = "Você é especial…",
  ["CooltrainermGaven3BeatenText"] = "Aaah! A vida é\ntão difícil!",
  ["CooltrainermGaven3SeenText"] = "Passando por\nbatalhas duras,\vvocê ganha poder.",
  ["CooltrainermGavenAfterText"] = "Para chegar à\nLEAGUE POKéMON,\ftem que atravessar\na VICTORY ROAD.\fMas a VICTORY ROAD\né difícil.\fQuase ninguém\nvai lá!",
  ["CooltrainermJakeAfterBattleText"] = "Vai ser difícil\nvencer na LEAGUE.\vPreciso treinar\fmais.\nOuvi dizer que a\fELITE FOUR é\nmais difícil que\fos LÍDERES de\nGINÁSIO.",
  ["CooltrainermKevinAfterBattleText"] = "Foi uma ótima\nbatalha!\fVocê e seu POKéMON\nsão mesmo\vfantásticos!",
  ["CooltrainermKevinBeatenText"] = "Nunca tive uma\nbatalha tão boa!",
  ["CooltrainermKevinNuggetText"] = "Você enfrentou\nmais uma batalha\fdo que esperava,\nmas venceu.\fComo prometido,\nganhou um prêmio.",
  ["CooltrainermKevinSeenText"] = "Mas depois de ver\ncomo você luta,\fquero ver como\nvou me sair.\fQue tal? Deixa eu\nlutar com você!",
  ["CooltrainermMikeAfterBattleText"] = "Agora sei minhas\nlimitações.\fObrigado por me\nmostrar!",
  ["CooltrainermMikeSeenText"] = "Minha chance de\nperder? Nem\vum por cento!",
  ["CooltrainermNickAfterBattleText"] = "Seu estilo POKéMON\né impressionante\ve colorido, sim.\fVocê só vai\nmelhorar!",
  ["CooltrainermNickBeatenText"] = "Você tem um\nestilo brilhante!",
  ["CooltrainermPaulAfterBattleText"] = "Você conhece o\nLANCE, o mestre\fdos dragões?\nNão pode ser.",
  ["CooltrainermPaulBeatenText"] = "Que decepção!",
  ["CooltrainermPaulSeenText"] = "Primeira batalha\ncontra dragões?\fVou mostrar como\nsão durões!",
  ["CooltrainermRyanAfterBattleText"] = "Vejo que você cria\nos seus POKéMON\vcom carinho.\fO laço que vocês\ncriam vai salvar\vvocê nos apertos.",
  ["CooltrainermRyanBeatenText"] = "Você ganhou meu\nrespeito.",
  ["CooltrainermRyanSeenText"] = "O que você acha\nsobre criar\vPOKéMON?",
  ["CooltrainermSeanAfterBattleText"] = "Treinadores de\nJOHTO podem lutar\fcom os LÍDERES de\nKANTO.",
  ["CooltrainermSeanBeatenText"] = "Eu queria ganhar!",
  ["CopycatText_ExplainPass"] = "COPYCAT: Esse é\no PASS do\vMAGNET TRAIN.\fO homem da\nferrovia me deu\fquando derrubaram\na nossa casa velha\vpara a STATION.",
  ["CopycatText_GiveDoll"] = "COPYCAT: Oba!\nÉ a minha POKé\vDOLL de CLEFAIRY!\fViu o rasgo onde a\nperna direita é\fcosturada? Essa é\na prova!",
  ["CopycatText_GivePass"] = "Certo. Aqui está o\nMAGNET TRAIN PASS\vque eu prometi!",
  ["CopycatText_ItsAScream"] = "COPYCAT: Claro!\nÉ hilário!",
  ["CopycatText_Male_1"] = "{PLAYER}: Oi! Você\ngosta de POKéMON?\f{PLAYER}: Ué, não,\neu que perguntei.\f{PLAYER}: Hã?\nVocê é estranha!",
  ["CopycatText_Male_2"] = "{PLAYER}: Oi!\nSoube que você\fperdeu a sua POKé\nDOLL favorita.\f{PLAYER}: Se eu\nachar, você me dá\vum PASS de trem?\f{PLAYER}: Vou\nachar para você.\fVocê acha que\nperdeu quando foi\va CIDADE DE\vVERMILION?",
  ["CopycatText_Male_3"] = "{PLAYER}: Oi!\nMuito obrigado\vpelo PASS!\f{PLAYER}: Como?\f{PLAYER}: É tão\ndivertido imitar\vtudo o que faço?",
  ["CopycatText_QuickMimicking"] = "COPYCAT: Hum?\nParar de imitar?\fMas esse é o meu\nhobby favorito!",
  ["CopycatText_Worried"] = "COPYCAT: Como?\fEu não deveria\ndecidir o que você\vfaz?\fMas eu estou bem\npreocupada… E se\valguém achar ela?",
  ["CopycatsDodrioText2"] = "ESPELHO, ESPELHO\nMEU, HÁ ALGUÉM\fMAIS BELA DO QUE\nEU?",
  ["CopycatsHouse1FPokefanFText"] = "Minha filha é tão\ncentrada nela…\fEla tem só uns\npoucos amigos.",
  ["CopycatsHouse1FPokefanFText_ReturnedMachinePart"] = "Ela perdeu faz\npouco a POKé DOLL\fque um menino deu\na ela faz 3 anos.\fDesde então, ela\nficou ainda melhor\vem imitar…",
  ["CopycatsHouse1FPokefanMText"] = "Minha filha gosta\nde imitar gente.\fA imitação deu a\nela o apelido\fde COPYCAT\naqui na região.",
  ["CopycatsHouse2FDollText"] = "É um POKéMON\nraro! Hã?\fÉ só uma boneca…",
  ["CyclingRoadSignText"] = "CYCLING ROAD\fDescida livre\naté o fim!",
  ["DaisyAllDoneText"] = "DAISY: Aí está!\nTudo pronto.\fViu? Não ficou\nbonito, né?\fÉ um POKéMON\nmuito fofo.",
  ["DaisyAlreadyGroomedText"] = "DAISY: Eu sempre\ntomo chá\fa esta hora. Venha\nme acompanhar.",
  ["DaisyAlrightText"] = "DAISY: Certo, vou\ndeixar ele bonito\vnum instante.",
  ["DaisyCantGroomEggText"] = "DAISY: Foi mal.\nEu não consigo\vescovar um EGG.",
  ["DaisyHelloText"] = "DAISY: Oi! Meu\nirmão mais novo é\fLÍDER do GINÁSIO\nde CIDADE DE\vVIRIDIAN.\fMas ele sai da\ncidade tanto,\fque causa problema\npara o treinador.",
  ["DaisyOfferGroomingText"] = "DAISY: Oi! Chegou\nna hora. Eu ia\vtomar um chá.\fVocê quer me\nacompanhar?\fAh, seus POKéMON\nestão meio sujos.\fVocê quer que eu\nescove um?",
  ["DaisyRefusedText"] = "DAISY: Não quer\nescovar nenhum?\fCerto, vamos só\ntomar chá então.",
  ["DaisyWhichMonText"] = "DAISY: Qual deles\neu devo escovar?",
  ["DanceTheaterCooltrainerMText"] = "Aquele homem vive\ncom seu RHYDON.\fDiz que quer um\nPOKéMON que saiba\vSURF e dançar.\fSerá que ele quer\nfazer um POKéMON\vde nado\vsincronizado?",
  ["DanceTheaterFancyPanelText"] = "É um painel chique\nque é decorado\vcom flores.",
  ["DanceTheaterGrannyText"] = "As KIMONO GIRLS\nsão tão lindas…\fMas elas passam\npor um treino\vrigoroso.\fE também têm que\naprender costumes\fantes de aparecer\nem público.\fMas se você ama\nalgo, tudo é\vpossível.",
  ["DarkCaveBlackthornEntrancePharmacistText1"] = "Uau! Você me\nassustou!\fEstava com\nBLACKGLASSES,\fentão não\nte notei.\fO que estou\nfazendo aqui?\fEi, não se\npreocupe.\fVou te dar\num BLACKGLASSES,\ventão esqueça\vque me viu, ok?",
  ["DarkCaveBlackthornEntrancePharmacistText2"] = "BLACKGLASSES\naumenta o poder\vde golpes",
  ["DarkCaveSignText"] = "DARK CAVE",
  ["DayCareManOutside.FoundAnEggText"] = "Ah, é você!\fEstávamos\ncriando seu\fPOKéMON, e nossa,\nque surpresa!\fSeu POKéMON tinha\num EGG!\fNão sabemos como\nfoi parar lá, mas\fseu POKéMON tinha\nele. Quer pegar?",
  ["DayCareManOutside.IllKeepItThanksText"] = "Tudo bem, vou\nficar com ele.\vValeu!",
  ["DayCareManOutside.NoRoomForEggText"] = "Você não tem\nespaço na equipe.\vVolte mais tarde.",
  ["DayCareManOutside.NotYetText"] = "Ainda não…",
  ["DayCareManOutside.ReceivedEggText"] = "{PLAYER} recebeu\no EGG!",
  ["DayCareManOutside.TakeGoodCareOfEggText"] = "Cuide bem\ndele.",
  ["DayCareManText_GiveOddEgg"] = "Eu sou o DAY-CARE\nMAN.\fVocê sabe sobre\nEGGS?\fEu criava\nPOKéMON com minha\vesposa, sabe.\fFicamos chocados\nao achar um EGG!\fNão é incrível\nisso?\fBem, você não\nquer esse EGG?\fEntão tá, é seu\npra guardar!",
  ["DayCareMonCompatibilityText.BreedAppearsToCareForText"] = "Parece gostar\nde {RAM:D073}.",
  ["DayCareMonCompatibilityText.BreedBrimmingWithEnergyText"] = "Está\ntransbordando de\venergia.",
  ["DayCareMonCompatibilityText.BreedFriendlyText"] = "É amigável com\n{RAM:D073}.",
  ["DayCareMonCompatibilityText.BreedNoInterestText"] = "Não tem interesse\nem {RAM:D073}.",
  ["DayCareMonCompatibilityText.BreedShowsInterestText"] = "Mostra interesse\nem {RAM:D073}.",
  ["DayCareSignText"] = "DAY-CARE\fNós Criamos o Seu\nPOKéMON por Você!",
  ["DayCareText_ComeAgain"] = "Volte sempre.",
  ["DayCareText_DescribeOddEgg"] = "Achei isso quando\ncuidava do\fPOKéMON de\nalguém, antes.\fMas o treinador\nnão quis o\fEGG, então eu\nfiquei com ele.",
  ["DayCareText_GotOddEgg"] = "{PLAYER} recebeu\num ODD EGG!",
  ["DayCareText_PartyFull"] = "Você não tem\nespaço pra isso.",
  ["DayOfWeekSiblingsHousePokedexText1"] = "Tem uma coisa\nescrita aqui.\fLer?",
  ["DayOfWeekSiblingsHousePokedexText2"] = "Aos meus irmãos e\nirmãs:\fTemos orgulho de\nservir treinadores\vde POKéMON.\fQuando o treinador\nfalar com você, dê\valgo útil a ele.\fCom amor,\nMONICA\fContinuar lendo?",
  ["DayOfWeekSiblingsHousePokedexText3"] = "Segunda, MONICA\nROTA 40\fTerça, TUSCANY\nROTA 29\fQuarta, WESLEY\nLAKE OF RAGE\fQuinta, ARTHUR\nROTA 36\fSexta, FRIEDA\nROTA 32\fSábado, SANTOS\nCIDADE DE\vBLACKTHORN\fDomingo, SUNNY\nROTA 37",
  ["DecorationDesc_TownMapPoster.LookTownMapText"] = "É o TOWN MAP.",
  ["DidntChooseStarterText"] = "ELM: Pense bem\ncom calma.\fSeu parceiro é\nimportante.",
  ["DifficultBookshelfText"] = "Está cheia de\nlivros difíceis.",
  ["DiglettsCavePokefanMText"] = "Bando de DIGLETT\npulou do chão!\fIsso foi\nchocante!",
  ["DirectorAfterText"] = "Imploro sua\najuda.\fNão dá pra saber\no que farão\fse controlarem\no transmissor.\fEles podem\naté controlar\fPOKéMON com\num sinal especial\fVocê é o único\nem quem confio.\fPor favor, salve\na RADIO TOWER…\fE todos os\nPOKéMON do país!",
  ["DirectorCardKeyText"] = "DIRECTOR: Use-a\npara abrir as\vpersianas do 3F.",
  ["DirectorIntroText"] = "DIRECTOR: Quem?\nO quê? Você veio\vme resgatar?\fObrigado!\fA RADIO TOWER!\fO que está\nacontecendo lá?\fTomada pela\nTEAM ROCKET?\fAqui. Pegue\na CARD KEY.",
  ["DontKnowTheInstructionsText"] = "Vou ler as\ninstruções.\fLigue a POKéGEAR e\nescolha o ícone\vdo TELEFONE.",
  ["DontLitterSignText"] = "MT.MOON SQUARE\nNão jogue lixo",
  ["DontWantGoodRodText"] = "O quêê? Você não\ngosta de pescar!?\vInacreditável!",
  ["DontWantSuperRodText"] = "Hã? Meus próprios\nolhos erraram?",
  ["DragonDensSignText"] = "DRAGON'S DEN\nA FRENTE",
  ["DragonShrineClairThatCantBeText"] = "Não pode ser!",
  ["DragonShrineClairYouPassedText"] = "Como foi?\fAcho que nem\nadianta perguntar.\fVocê falhou?\f…………\f…O quê? Você\npassou?",
  ["DragonShrineClairYoureLyingText"] = "Você está\nmentindo!\fNem eu fui\naprovada ainda!",
  ["DragonShrineClairsGrandfatherText"] = "Parece que a CLAIR\naprendeu uma\flição valiosa\ncom você.\fAgradeço como avô\ndela.",
  ["DragonShrineComeAgainText"] = "Volte quando\nquiser.",
  ["DragonShrineElder2Text"] = "Faz tempo que\nnenhum treinador\fganhou a rara\naprovação do\vnosso MESTRE.\fNa verdade, não\ndesde o Mestre\vLANCE.",
  ["DragonShrineElder3Text"] = "Você conhece o\njovem Mestre\vLANCE?\fEle se parece\nmuito com nosso\vMESTRE quando\vjovem.\fÉ coisa de\nfamília.",
  ["DragonShrineElderGreetingText"] = "Hum… Que bom te\nver aqui.\fNão precisa\nexplicar por que\vveio.\fA CLAIR te mandou\npra cá, não foi?\fEssa menina dá\ntrabalho…\fSinto muito, mas\nvou ter que te\vtestar.\fNão se preocupe,\nsão só algumas\vperguntas.\fPronto?",
  ["DragonShrineElderScoldsClairText"] = "CLAIR…\fReflita sobre o\nque falta em você\fe o que essa\ncriança tem.",
  ["DragonShrineHereRisingBadgeText"] = "Aqui, esta é a\nRISINGBADGE…\fAnda! Pegue logo!",
  ["DragonShrineIUnderstandText"] = "E-eu entendo…",
  ["DragonShrineMustIInformLanceText"] = "CLAIR!\fEssa criança é\nimpecável, em\vhabilidade e\vespírito!\fAdmita a derrota\ne entregue a\vRISING BADGE!\f…Ou preciso\navisar o LANCE\vsobre isso?",
  ["DragonShrinePartyFullText"] = "Hm? Sua equipe\nde POKéMON está\vcheia.",
  ["DragonShrinePassedTestText"] = "Hum… Entendo…\fVocê se importa\nmuito com\vPOKéMON.\fMuito louvável.\fEssa convicção é\no que importa!\f{PLAYER}, não\nperca essa crença.\fEla vai te guiar\naté a POKéMON\vLEAGUE.",
  ["DragonShrinePlayerReceivedDratiniText"] = "{PLAYER} recebeu\num DRATINI!",
  ["DragonShrinePlayerReceivedRisingBadgeText"] = "{PLAYER} recebeu\nRISINGBADGE.",
  ["DragonShrineQuestion1Text"] = "O que POKéMON\nsignificam pra\vvocê?",
  ["DragonShrineQuestion2Text"] = "O que te ajuda a\nvencer batalhas?",
  ["DragonShrineQuestion3Text"] = "Que tipo de\ntreinador você\vquer enfrentar?",
  ["DragonShrineQuestion4Text"] = "O que é mais\nimportante pra\vcriar POKéMON?",
  ["DragonShrineQuestion5Text"] = "POKéMON fortes.\nPOKéMON fracos.\fQual é mais\nimportante?",
  ["DragonShrineRightAnswerText"] = "Ah, entendo…",
  ["DragonShrineRisingBadgeExplanationText"] = "RISINGBADGE fará\nseus POKéMON\fusarem o golpe\nde escalar\vcachoeiras.\fAlém disso, todos\nos POKéMON vão\fte reconhecer\ncomo treinador\fe obedecer\nseus comandos.\fTambém quero\nque leve esta TM.",
  ["DragonShrineRivalIsInTrainingText"] = "Um garoto da sua\nidade está\vtreinando aqui.\fEle é parecido\ncom a CLAIR\fquando jovem. É\num pouco\vpreocupante…",
  ["DragonShrineSignpostText"] = "SANTUÁRIO DRAGÃO\fUm santuário em\nhonra aos POKéMON\fdragão que viveu\nno DRAGON'S DEN.",
  ["DragonShrineSpeechlessText"] = "…………",
  ["DragonShrineSymbolicDragonText"] = "POKéMON dragão\nsimbolizam nosso\vclã.\fVocê mostrou que\npode ser\vconfiado com um.",
  ["DragonShrineTakeThisDratiniText"] = "Hum… Que bom te\nver aqui.\fSua chegada é\nmuito oportuna.\fTenho algo\npra você.\fPegue este DRATINI\ncomo prova de que\freconheci seu\nvalor.",
  ["DragonShrineWrongAnswerText1"] = "Hã? Não entendi\nbem isso…",
  ["DragonShrineWrongAnswerText2"] = "O que você\ndisse mesmo?",
  ["EarlsPokemonAcademyGameboyKid1Text"] = "Troquei meu melhor\nPOKéMON com o\vcara do meu lado.",
  ["EarlsPokemonAcademyGameboyKid2Text"] = "Hã? O POKéMON que\nacabei de pegar\vsegurando algo!",
  ["EarlsPokemonAcademySignText"] = "ACADEMIA POKéMON\nDO EARL",
  ["EarlsPokemonAcademyYoungster1Text"] = "Estou anotando\na aula do\vprofessor.\fMelhor copiar\no que está no\vquadro também.",
  ["EarlsPokemonAcademyYoungster2Text"] = "POKéMON com uma\nBERRY se cura\vna batalha.\fOutros itens\ntambém podem ser\vsegurados…\fÉ difícil\nanotar tudo…",
  ["EatathonContestPosterText"] = "Competição de\ncomilança! Sem\flimite de tempo!\nbatalha sem fim!\fO maior comedor\nleva tudo grátis!",
  ["EcruteakCityFisherText"] = "Ouvi um boato\nsobre o OLIVINE\vLIGHTHOUSE.\fO POKéMON que\nserve de farol\fficou doente.\nParece que estão\vcom problemas.",
  ["EcruteakCityFisherText_JasmineReturned"] = "O POKéMON do\nOLIVINE LIGHTHOUSE\vfoi curado.\fOs barcos já podem\nsair ao mar de\vnoite em paz.",
  ["EcruteakCityGramps1Text"] = "ECRUTEAK já teve\nduas torres:\fuma a leste e\noutra a oeste.",
  ["EcruteakCityGramps2Text"] = "Ah, jovem.\nVocê aprendeu\fa dançar como as\nKIMONO GIRLS?\fSe for ao DANCE\nTHEATER delas, um\fvelhinho esquisito\ndá algo bacana\vpara você, ouvi.",
  ["EcruteakCityGramps3Text"] = "Há muito\ntempo atrás…\fEsta torre\npegou fogo.\fTrês POKéMON sem\nnome morreram.\fUm POKéMON\narco-íris desceu\fdo céu e os\nressuscitou…\fÉ uma lenda\npassada adiante\fpelos LÍDERES DE\nGINÁSIO de\vECRUTEAK.\fEu?\fEu era um\ntreinador há\vmuito tempo.\vRohoho!",
  ["EcruteakCityLass1Text"] = "Vou treinar lá no\nDANCE THEATER.\fQuer vir junto\ncomigo?",
  ["EcruteakCityLass2Text"] = "Aquela torre era\nbem mais alta,\fmas pegou fogo e\nacabou queimada.",
  ["EcruteakCityLass2Text_ReleasedBeasts"] = "Três POKéMON\ngrandes fugiram\vcada um para um\vlado. O que eram\veles?",
  ["EcruteakCitySignText"] = "CIDADE DE ECRUTEAK\nCidade Histórica\fOnde o Passado\nEncontra o Hoje",
  ["EcruteakCityYoungsterText"] = "Ouvi que POKéMON\nestão em fúria no\fLAKE OF RAGE. Eu\nqueria ver isso.",
  ["EcruteakDanceTheaterSignText"] = "ECRUTEAK DANCE\nTHEATER",
  ["EcruteakGymClosedText"] = "MORTY, o LÍDER DE\nGINÁSIO, não está.\fDesculpe, mas\nvocê tem que sair.\fRohohoho.",
  ["EcruteakGymGuideText"] = "Os treinadores\ndaqui têm motivos\vsecretos.\fSe você vencer,\neles podem contar\fsegredos profundos\nde ECRUTEAK.",
  ["EcruteakGymGuideWinText"] = "Ufa, {PLAYER}. Você\nfoi ótimo!\fEu estava\nencolhido no canto\vde puro terror!",
  ["EcruteakGymSignText"] = "CIDADE DE ECRUTEAK\nGINÁSIO POKéMON\vLÍDER: MORTY\fO Vidente Místico\ndo Futuro",
  ["EcruteakHistoryBookText"] = "HISTÓRIA DE\nECRUTEAK\fQuer ler?",
  ["EcruteakItemfinderAdventureText"] = "Ah. Está numa\naventura com\vseus POKéMON?\fE o que seria\numa aventura sem\vcaça ao tesouro?\fTô certo ou não\nestou certo?",
  ["EcruteakItemfinderToEachHisOwnText"] = "Ah… Cada um com\nseu gosto, né…",
  ["EcruteakItemfinderTrueSpiritText"] = "Ótimo! Você\nentende o real\fespírito de\naventura.\fGostei! Leve\nisto com você.",
  ["EcruteakLugiaSpeechHouseGrampsText"] = "Isso aconteceu\nquando jovem.\fO céu de repente\nficou preto. Um\fPOKéMON gigante\nvoador cobriu\vo sol.\fQue POKéMON\nserá que era?\fParecia um pássaro\ne um dragão.",
  ["EcruteakLugiaSpeechHouseYoungsterText"] = "Será que existe um\nPOKéMON gigante?\fSe ele existe,\ndeve ser forte.",
  ["EcruteakMartGrannyText"] = "Se usar REVIVE,\num POKéMON que\fdesmaiou vai\nacordar.",
  ["EcruteakMartSuperNerdText"] = "Meu EEVEE virou\num ESPEON.\fMas o do meu amigo\nEEVEE virou um\vUMBREON.\fPor que será? Nós\ndois criávamos\fnosso EEVEE do\nmesmo jeito…",
  ["EcruteakPokecenter1FCooltrainerFText"] = "MORTY, o LÍDER\ndo GINÁSIO, é tão\vlegal.\fOs POKéMON dele\nsão fortes também",
  ["EcruteakPokecenter1FGymGuideText"] = "LAKE OF RAGE…\fO aparecimento do\nbando de GYARADOS\fSinto cheiro de\nconspiração. Sei!",
  ["EcruteakPokecenter1FPokefanMText"] = "O jeito das KIMONO\nGIRLS dançarem é\fmaravilhoso. Assim\ncomo elas usam\vseus POKéMON.",
  ["EcruteakPokecenter1FPokefanMTextMobile"] = "Deve estar\nquerendo batalhar\fmais gente, né?\nParece que tem\fum lugar onde\ntreinadores se\vreúnem.\fOnde? Pergunta\nboa.\fÉ logo depois\nda CIDADE DE\vOLIVINE.",
  ["EcruteakPokecenter1F_BillText1"] = "Oi, eu sou o BILL.\nE você é quem?\f{PLAYER}, hein?\nVocê chegou numa\vboa hora.",
  ["EcruteakPokecenter1F_BillText2"] = "Acabei de ajustar\na minha TIME\vCAPSULE.\fVocê sabe que dá\npra trocar POKéMON\vcerto?\fMinha TIME CAPSULE\nfoi feita pra\ftrocar com o\npassado.\fNão pode mandar\nnada que\fnão existia no\npassado.\fSe mandasse, o PC\ndo passado ia\vquebrar.\fEntão é preciso\ntirar tudo que\fnão tinha no\npassado.\fEm resumo, nada\nde golpe novo ou\fPOKéMON novo na\nTIME CAPSULE.\fNão se preocupe.\nJá terminei os\vajustes.\fAmanhã, as TIME\nCAPSULES vão\ffuncionam nos\nCENTROS POKéMON.\fPreciso voltar pra\nGOLDENROD pra ver\va família.\fTchau!",
  ["EcruteakThreeMonText"] = "ECRUTEAK também\nera o lar de três\fPOKéMON corriam\npela cidade.\fDizem que nasceram\nda água e do\frelâmpago e do\nfogo.\fMas não conseguiam\nconter seu poder\vexcessivo.\fPor isso os três\ncorreram como o\fvento até o\ncampo.",
  ["EcruteakTinTowerEntranceGrampsText"] = "Duas torres…\nDois POKéMON…\fMas quando uma\nqueimou, os dois\fPOKéMON voaram\ne nunca voltaram.",
  ["EcruteakTinTowerEntranceSageText"] = "A TIN TOWER é\nproibida a quem\fnão tem a INSÍGNIA\nde ECRUTEAK.\fDesculpe, mas você\ntem que sair.",
  ["EcruteakTinTowerEntranceSageText_GotFogBadge"] = "A TIN TOWER é\nproibida a quem\fsem a BADGE do\nGINÁSIO daqui.\fAh!\fA BADGE do GINÁSIO\nde ECRUTEAK! Pode\vpassar adiante.",
  ["EcruteakTinTowerEntranceSageText_HeardClearBell"] = "O som desse sino\nreflete a alma\vde quem o tem.\fVocê…\fTalvez consiga\natravessar a\vTIN TOWER.\fPor favor, siga\nem frente.",
  ["EcruteakTinTowerEntranceSageText_HearsClearBell"] = "Algo muito\nimportante\vaconteceu.\fSinto muito, mas\nvou ter que pedir\vpra você sair.\f…………\fAh!\fEsse som é do\nCLEAR BELL!\fÉ… é sublime!\fNunca ouvi um som\ntão lindo antes!\fO som desse sino\nreflete a alma\vde quem o tem.\fVocê…\fTalvez consiga\natravessar a\vTIN TOWER.\fPor favor, siga\nem frente.",
  ["EcruteakTinTowerEntranceSageText_NoClearBell"] = "Algo muito\nimportante\vaconteceu.\fSinto muito, mas\nvou ter que pedir\vpra você sair.\f…O que acalma\na alma…\fO TRIO SÁBIO diz\ncoisas tão\fdifíceis de\nentender…",
  ["EcruteakTinTowerEntranceSageText_PleaseDoGoOn"] = "Por favor, siga\nem frente.",
  ["EcruteakTinTowerEntranceWanderingSageText"] = "A TIN TOWER à\nfrente foi feita\fcomo abrigo dos\nPOKéMON que voam.",
  ["EcruteakTinTowerEntranceWanderingSageText_GotClearBell"] = "A TIN TOWER\ntremeu! Um POKéMON\fdeve ter voltado\npro topo!",
  ["EcruteakTwoTowersText"] = "Em ECRUTEAK havia\nduas torres.\fCada torre era\no abrigo de\vPOKéMON voadores.\fMas uma delas\nqueimou até o\vchão.\fOs dois POKéMON\nnão são vistos\vdesde então…\fContinuar lendo?",
  ["ElmAfterTheftText1"] = "ELM: {PLAYER}, isto\né terrível…\fAh, sim, qual foi\na descoberta do\vMR.POKéMON?",
  ["ElmAfterTheftText2"] = "{PLAYER} entregou\no OVO MISTERIOSO\vao PROF.ELM.",
  ["ElmAfterTheftText3"] = "ELM: Isto?",
  ["ElmAfterTheftText4"] = "Mas… Será um OVO\nde POKéMON?\fSe for, é um\ngrande achado!",
  ["ElmAfterTheftText5"] = "ELM: O quê?!?\fO PROF.OAK lhe deu\numa POKéDEX?\f{PLAYER}, é verdade\nmesmo? I-isso é\vincrível!\fEle é ótimo em ver\no potencial das\vpessoas como\vtreinadores.\fUau, {PLAYER}. Você\npode ter o que é\fpreciso para virar\nCAMPEÃO.\fParece que você se\ndá muito bem\vcom POKéMON.\fVocê devia encarar\no desafio do\vGINÁSIO POKéMON.\fO GINÁSIO mais\nperto fica em\vCIDADE DE VIOLET.",
  ["ElmAfterTheftText6"] = "…{PLAYER}. O\ncaminho até o\fcampeonato vai ser\nlongo.\fAntes de partir,\nnão esqueça de\vfalar com sua mãe",
  ["ElmAideHasEggText"] = "ELM: {PLAYER}?\nVocê não achou meu\vassistente?\fEle devia lhe\nentregar o OVO\fno CENTRO POKéMON\nde CIDADE DE\vVIOLET.\fVocê deve ter\nperdido ele. Tente\vencontrá-lo lá.",
  ["ElmDescribesMrPokemonText"] = "MR.POKéMON vai a\ntoda parte e acha\vraridades.\fPena que sejam só\nraras e não muito\vúteis…\f{PLAYER}, conto\ncom você!",
  ["ElmDirectionsText1"] = "MR.POKéMON mora\nperto de\vCHERRYGROVE.\fA próxima cidade.\nÉ quase direto\vdaqui.",
  ["ElmDirectionsText2"] = "Se seu POKéMON se\nmachucar, cure\fele nesta\nmáquina.",
  ["ElmDirectionsText3"] = "Ah, aqui está meu\ntelefone.\fMe ligue se algo\nacontecer.",
  ["ElmGiveEverstoneText1"] = "Obrigado, {PLAYER}!\nVocê nos ajuda a\fdesvendar os\nmistérios POKéMON\fQuero que fique\ncom isto em sinal\vda nossa gratidão",
  ["ElmGiveEverstoneText2"] = "Isso é uma\nEVERSTONE.\fCertas espécies de\nPOKéMON evoluem\fao chegar a certos\nníveis.\fUm POKéMON\nsegurando a\vEVERSTONE não\vevolui.\fDê a um POKéMON\nque você não quer\vque evolua.",
  ["ElmGiveMasterBallText1"] = "ELM: Oi, {PLAYER}!\nGraças a você,\fminha pesquisa vai\nmuito bem!\fLeve isto como\nsinal da minha\vgratidão.",
  ["ElmGiveMasterBallText2"] = "A MASTER BALL é a\nmelhor de todas!\fÉ a BALL suprema!\nCaptura qualquer\fPOKéMON sem\nfalhar nunca.\fSó é dada a\npesquisadores\vPOKéMON de renome\fAcho que você faz\nmelhor uso dela\fdo que eu,\n{PLAYER}!",
  ["ElmGiveTicketText1"] = "ELM: {PLAYER}!\nAí está você!\fLiguei porque\ntenho algo para\vvocê.\fViu? É um\nS.S.TICKET.\fAgora pode pegar\nPOKéMON em KANTO.",
  ["ElmGiveTicketText2"] = "O navio parte de\nCIDADE DE OLIVINE.\fMas isso você já\nsabia, {PLAYER}.\fAfinal, você foi\na toda parte\vcom seus POKéMON.\fMande lembranças\nao PROF.OAK!",
  ["ElmPhoneAssistantText"] = "Alô, {PLAYER}?\fViu meu\nassisten-te? Ele\vestá no\fCENTRO POKéMON de\nCIDADE DE VIOLET.",
  ["ElmPhoneCheckingTheEggText"] = "Alô, {PLAYER}?\fEstamos checando o\nEGG. Ele parece\fmesmo ser um\nEGG de POKéMON.",
  ["ElmPhoneDisasterText"] = "A-alô? {PLAYER}?\nÉ um desastre!\fAh, hum, é\nterrível!\fO que eu faço?\nIsso… Ai, não…\fPor favor volte\npara cá agora!",
  ["ElmPhoneDiscoveredHatchTimeText"] = "Alô, {PLAYER}?\fAcabei de fazer\numa descoberta.\fO tempo que um\nEGG leva para\fchocar depende do\nPOKéMON.",
  ["ElmPhoneDiscoveredPokerusText"] = "Alô, {PLAYER}?\fDescobri uma coisa\nestranha.\fParece que existe\numa coisa chamada\fPOKéRUS que\ninfecta POKéMON.\fSim, é como um\nvírus, por isso se\vchama POKéRUS.\fEle se multiplica\nrápido e infecta\foutros POKéMON.\nMas é só isso.\fNão parece fazer\nnada, e some\fcom o tempo\nsozinho.\fAcho que não é\nnada para se\vpreocupar. Tchau!",
  ["ElmPhoneEggAssistantText"] = "Alô, {PLAYER}?\nDescobrimos uma\fcoisa sobre o\nEGG!\fMeu assistente\nestá no CENTRO\fPOKéMON de CIDADE\nDE VIOLET. Pode\vfalar com ele?",
  ["ElmPhoneEggHatchedText"] = "Alô, {PLAYER}?\nComo está o EGG?\fO quê? Chocou?\nUau! Que tipo de\vPOKéMON é?\fVenha me mostrar\nagora!",
  ["ElmPhoneGiftText"] = "Alô, {PLAYER}?\fTenho uma coisa\naqui para você.\fPode dar uma\npassada no LAB?\fAté mais!",
  ["ElmPhoneHealYourMonText"] = "Alô, {PLAYER}?\fTente não\nexagerar.\fCure seus POKéMON\nsempre que eles se\vmachucarem.",
  ["ElmPhoneHowIsTheEggText"] = "Alô, {PLAYER}?\fComo está o EGG?\nMudou algo?\fSe acontecer algo,\npor favor ligue.",
  ["ElmPhoneInvestigatingEggMovesText"] = "Alô, {PLAYER}?\fAinda é um\nmistério que\fgolpes um POKéMON\nchocado sabe.\fEstamos\ninvestigando isso\vagora.",
  ["ElmPhonePokemonStolenText"] = "{PLAYER}? Estou\nmuito chateado.\fRoubaram um\nPOKéMON daqui.\fComo alguém faz\numa coisa dessas?",
  ["ElmPhoneRadioTowerRocketTakeoverText"] = "{PLAYER}, como\nvão as coisas?\fLiguei porque tem\nalgo estranho\facontecendo com as\ntransmissões.\fEstavam falando\nda TEAM ROCKET.\f{PLAYER}, você\nsabe de alguma\vcoisa?\fSerá que a TEAM\nROCKET voltou?\fNão, isso não pode\nser verdade.\fDesculpe incomodar\nSe cuide!",
  ["ElmPhoneSawMrPokemonText"] = "Alô, {PLAYER}?\fEncontrou o MR.\nPOKéMON? Ótimo!\vVolte em paz!",
  ["ElmPokeBallText"] = "Contém um POKéMON\ncapturado pelo\vPROF.ELM.",
  ["ElmStudyingEggText"] = "ELM: Não desista!\nEu ligo se souber\fde algo sobre\naquele OVO!",
  ["ElmText_CallYou"] = "ELM: {PLAYER}, eu\nligo se algo\vacontecer.",
  ["ElmText_Intro"] = "ELM: {PLAYER}!\nAí está você!\fPreciso lhe pedir\num favor.\fTenho um conhecido\nchamado MR.\vPOKéMON.\fEle vive achando\ncoisas estranhas\fe se gabando das\ndescobertas.\fEnfim, recebi um\ne-mail dele agora\fdizendo que desta\nvez é de verdade.\fÉ intrigante, mas\nestamos ocupados\fcom nossa pesquisa\nde POKéMON.\fVocê poderia ir\nver isso por nós?\fVou lhe dar um\nPOKéMON de\vparceiro.\fSão todos POKéMON\nraros que acabamos\vde encontrar.\fEscolha um deles!",
  ["ElmText_LetYourMonBattleIt"] = "Se um POKéMON\nselvagem aparecer,\vdeixe o seu lutar",
  ["ElmThoughtEggHatchedText"] = "{PLAYER}? Pensei\nque o OVO chocou.\fCadê o\nPOKéMON?",
  ["ElmWaitingEggHatchText"] = "ELM: Ei, aquele\nOVO mudou algo?",
  ["ElmsHouseLabFoodText"] = "Tem comida aqui.\nDeve ser para o\vLAB.",
  ["ElmsHousePCText"] = "POKéMON. De onde\neles vêm?\fPara onde eles\nvão?\fPor que ninguém\nnunca viu um\vPOKéMON nascer?\fQuero saber! Vou\ndedicar a vida\fao estudo dos\nPOKéMON!\f…\fFaz parte dos\nartigos de\vpesquisa do ELM.",
  ["ElmsHousePokemonFoodText"] = "Tem comida aqui.\nDeve ser para os\vPOKéMON.",
  ["ElmsLabHealingMachineText1"] = "Será que isto faz\no quê?",
  ["ElmsLabHealingMachineText2"] = "Curar POKéMON?",
  ["ElmsLabMonEggText"] = "É o EGG de\nPOKéMON que o\vPROF. ELM estuda.",
  ["ElmsLabOfficerText1"] = "Soube que roubaram\num POKéMON aqui…\fEu estava colhendo\ninformações com o\vPROF.ELM.\fPelo visto era um\njovem de cabelo\vlongo e vermelho…\fO quê?\fVocê lutou com um\ntreinador assim?\fPor acaso soube\no nome dele?",
  ["ElmsLabOfficerText2"] = "Certo! Então\n{RIVAL} é o nome.\fObrigado por\najudar na busca!",
  ["ElmsLabPCText"] = "OBSERVAÇÕES SOBRE\nEVOLUÇÃO POKéMON\f…Está escrito\nna tela…",
  ["ElmsLabTrashcanText"] = "A embalagem do\nlanche que o PROF.\vELM comeu está aí",
  ["ElmsLabTravelTip1Text"] = "{PLAYER} abriu um\nlivro.\fDica de viagem 1:\fAperte START para\nabrir o MENU.",
  ["ElmsLabTravelTip2Text"] = "{PLAYER} abriu um\nlivro.\fDica de viagem 2:\fRegistre a viagem\ncom SAVE!",
  ["ElmsLabTravelTip3Text"] = "{PLAYER} abriu um\nlivro.\fDica de viagem 3:\fAbra a BOLSA e\naperte SELECT para\vmover itens.",
  ["ElmsLabTravelTip4Text"] = "{PLAYER} abriu um\nlivro.\fDica de viagem 4:\fVeja os movimentos\ndo POKéMON. Use\fo botão A para\ntrocar de lugar.",
  ["ElmsLabWindowText1"] = "Janela aberta.\fUma brisa gostosa\nentra por ela.",
  ["ElmsLabWindowText2"] = "Ele entrou\npor aqui!",
  ["ElmsLookingForYouText"] = "Ah, {PLAYER}! Nosso\nvizinho, o PROF.\fELM, estava\nprocurando você.\fDisse que queria\nque você fizesse\valgo para ele.\fAh! Quase esqueci!\nSua POKéMON GEAR\fvoltou do\nconserto.\fAqui está!",
  ["ElmsSonText"] = "Quando eu crescer,\nvou ajudar o meu\vpai!\fVou ser um grande\nprofessor\vPOKéMON!",
  ["ElmsWifeText"] = "Oi, {PLAYER}! Meu\nmarido vive tão\focupado, e espero\nque ele fique bem\fQuando mergulha na\npesquisa POKéMON,\fele até esquece\nde comer.",
  ["ErikaAfterBattleText"] = "ERIKA: Perder\ndeixa um gosto\vamargo…\fMas saber que\nhá treinadores\ffortes me espole\na melhorar…",
  ["ErikaBeatenText"] = "ERIKA: Oh!\nAdmito a derrota…\fVocê é realmente\nforte…\fVou lhe dar a\nRAINBOWBADGE…",
  ["ErikaBeforeBattleText"] = "ERIKA: Olá…\nQue tempo\fagradável, hein?\nÉ tão calmo…\fPosso até\ncochilar…\fMe chamo ERIKA.\nSou a LÍDER do\vGINÁSIO CELADON.\f…Oh? Você veio\nde JOHTO?\vQue bom…\fOh. Desculpe, não\npercebi que\fqueria me\ndesafiar.\fMuito bem, mas\nnão vou perder.",
  ["ErikaExplainTMText"] = "ERIKA: Foi uma\npartida adorável.\fMe senti\ninspirada.\vFique com este\fTM.\fÉ GIGA DRAIN.\nÉ um golpe que\fdrena metade do\ndano causado,\vcurando seu\fPOKéMON. Se\nquiser, use…",
  ["ExecutiveM4AfterText"] = "Não, não posso\ndeixar isso me\fabalar. Preciso\navisar os outros…",
  ["ExecutiveM4BeatenText"] = "Eu… Eu não pude\nfazer nada…\fGIOVANNI, por\nfavor me perdoe…",
  ["ExecutiveM4BeforeText"] = "O quê? Quem é você\nEsta é a sala\fdo nosso líder,\nGIOVANNI.\fDesde que acabou\ncom a TEAM ROCKET\fhá três anos, ele\nestá treinando.\fMas temos certeza\nque ele volta\fum dia para\nassumir de novo.\fPor isso estamos\nde guarda.\fNão vou deixar\nninguém mexer\vneste lugar!",
  ["Executivef1AfterBattleText"] = "{PLAYER}, não é?\fUm pirralho como\nvocê não vai\fapreciar a\nmagnificência da\fTEAM ROCKET.\nQue pena. Eu\vadmiro seu poder.",
  ["Executivef1BeatenText"] = "Isso não pode\nser verdade!\fLutei duro, mas\nainda perdi…",
  ["Executivef1SeenText"] = "Oi, garoto.\nLembra de mim do\fHIDEOUT em\nCIDADE DE\vMAHOGANY?\fEu perdi lá, mas\nagora não perco.",
  ["Executivem2AfterBattleText"] = "Você ganhou meu\nrespeito, então\vvai um conselho.\fNão é tarde.\nVocê ainda pode\vvoltar.",
  ["Executivem2BeatenText"] = "A fortaleza\ncaiu!",
  ["Executivem2SeenText"] = "Pare! Sou\nconhecido como a\vfortaleza da TEAM\fROCKET! Você\nnão vai passar!",
  ["FakeDirectorTextAfter"] = "Escondemos o\nDIRETOR real\fno ARMAZEM\nSUBTERRANEO.\fE na ponta do\nSUBTERRANEO.\vMas duvido\fque você\nchegue lá.",
  ["FakeDirectorTextBefore1"] = "V-Você! Você veio\nme resgatar?",
  ["FakeDirectorTextBefore2"] = "Era isso que você\nesperava?\fErrado!\nSou um impostor!\fFingi ser o\nverdadeiro para\fpreparar\nnossa tomada.\fQuer saber onde\nescondemos o\vDIRETOR mesmo?\fClaro, vou te\ncontar. Mas só\vse me vencer!",
  ["FakeDirectorWinText"] = "Tudo bem. Vou te\ncontar.",
  ["FalknerFightDoneText"] = "Há GINÁSIOS\nPOKéMON em cidades\vmais à frente.\fVocê devia testar\nsua habilidade\vnesses GINÁSIOS.\fVou treinar mais\nforte para virar\fo maior mestre de\naves!",
  ["FalknerIntroText"] = "Sou FALKNER, líder\ndo GINÁSIO POKéMON\vde VIOLET!\fDizem que dá para\ncortar as asas de\fPOKéMON voadores\ncom um choque\velétrico…\fNão vou permitir\ntal insulto às\vaves POKéMON!\fVou lhe mostrar o\npoder de verdade\fdas magníficas\naves POKéMON!",
  ["FalknerTMMudSlapText"] = "Usando uma TM, o\nPOKéMON aprende\fna hora um golpe\nnovo.\fPense antes de\nagir: uma TM só\vserve uma vez.\fA TM31 tem\nMUD-SLAP.\fEla reduz a\nmira do inimigo\fenquanto causa\ndano.\fOu seja, é defesa\ne ataque ao mesmo\vtempo.",
  ["FalknerWinLossText"] = "…Droga! As aves\nqueridas do meu\vpai…\fTudo bem.\nPegue isto.\fÉ a ZEPHYRBADGE\noficial da LIGA\vPOKéMON.",
  ["FalknerZephyrBadgeText"] = "A ZEPHYRBADGE\naumenta o ataque\vdos seus POKéMON.\fEla também deixa\no POKéMON usar\fFLASH, se souber,\na qualquer hora.\fTome, leve isto\ntambém.",
  ["FarfetchdText"] = "FARFETCH'D: Kwaa!",
  ["FarmerFText_HealedMiltank"] = "Você curou nossa\nMILTANK, meu bem.\fAgora dá MOOMOO\nMILK de novo.\fToma uma lembrança\npor seu trabalho.",
  ["FarmerFText_InTrouble"] = "Nosso leite vai\naté para KANTO.\fEntão se nossa\nMILTANK não der\fleite, ficamos\nem apuros.",
  ["FarmerFText_SnoreSpeech"] = "Isso aí é o\nSNORE.\fÉ um golpe raro\nque só funciona\fquando o POKéMON\nestá dormindo.\fMelhor pensar bem\nem como usar,\vmeu bem.",
  ["FarmerMText_BuyMilk"] = "Gostou do meu\nMOOMOO MILK?\fÉ meu orgulho e\nalegria, filho.\fDê aos POKéMON\npra recuperar PS!\fTe vendo por só\n¥500.",
  ["FarmerMText_GotMilk"] = "Toma!\nBebe e aproveita!",
  ["FarmerMText_Milking"] = "Melhor eu ir\nordenhar.",
  ["FarmerMText_NoMoney"] = "Desculpa, filho.\nSem grana, nada!",
  ["FarmerMText_NoRoom"] = "Acho que sua\nMOCHILA tá cheia.",
  ["FarmerMText_NoSale"] = "Não quer mais?\nVolte depois, tá?",
  ["FarmerMText_SickCow"] = "A MILTANK não me\ndá leite mais não.\vagora.\fEsta FAZENDA aqui\ntem leite famoso.\fQuase todo mundo\nquer beber.\fEla me dá bastante\nleite se eu der\fmuitas BERRIES,\neu acho.",
  ["FastShip1FGrandpaText"] = "Nossa! Desculpe.\nEstava com\vpressa!\fMinha neta está\nperdida!\fEla é só uma\nmenininha. Se\fvê-la, por favor\nme avise!",
  ["FastShip1FSailor1Text_InOlivine"] = "O FAST SHIP S.S.\nAQUA chegou em\vCIDADE DE OLIVINE.",
  ["FastShip1FSailor1Text_InVermilion"] = "O FAST SHIP S.S.\nAQUA chegou em\vCIDADE DE\vVERMILION.",
  ["FastShip1FSailor1Text_ToOlivine"] = "O FAST SHIP S.S.\nAQUA segue para\vCIDADE DE OLIVINE.\fVamos anunciar\nassim que a gente\vchegar.",
  ["FastShip1FSailor1Text_ToVermilion"] = "O FAST SHIP S.S.\nAQUA segue para\vCIDADE DE\vVERMILION.\fVamos anunciar\nassim que a gente\vchegar.",
  ["FastShip1FSailor2Text"] = "É a sua cabine.\fVocê pode curar\nseus POKéMON\vdormindo na cama.\fO navio chega\nenquanto você\vestá dormindo.",
  ["FastShip1FSailor2Text_FirstTime"] = "É a sua cabine.\fSe seus POKéMON\nestão machucados,\vdurma na cama.\fIsso vai curar\neles.",
  ["FastShip1FSailor3Text"] = "Todo passageiro\naqui é treinador.\fEstão todos loucos\npara batalhar nas\vcabines.",
  ["FastShipArrivedOlivineText"] = "O FAST SHIP S.S.\nAQUA chegou em\vCIDADE DE OLIVINE.",
  ["FastShipArrivedVermilionText"] = "O FAST SHIP S.S.\nAQUA chegou em\vCIDADE DE\vVERMILION.",
  ["FastShipB1FOnDutySailorDirectionsText"] = "O refeitório é\nlogo à frente.\fA escada no fim\nleva à cabine do\vCAPTAIN.",
  ["FastShipB1FOnDutySailorRefusedText"] = "Ai, caramba…\fO CAPTAIN vai\nficar furioso…",
  ["FastShipB1FOnDutySailorSawLittleGirlText"] = "Uma menininha?\fAcho que vi ela\npassar por aqui.",
  ["FastShipB1FOnDutySailorText"] = "Ei, moço. Dá para\nvocê procurar o\vmeu colega?\fEle está vadiando\npor aí, aquele\vpreguiçoso!\fEu queria ir atrás\ndele, mas estou\vde serviço.",
  ["FastShipB1FOnDutySailorThanksText"] = "Valeu, moço!\nDei uma bronca\fboa nele, para\nparar de vadiar!",
  ["FastShipBedText1"] = "Uma cama macia!\nHora de dormir…",
  ["FastShipBedText2"] = "Ah, descansado e\nrenovado!",
  ["FightingDojoBlackBeltText"] = "Olá!\fO KARATE KING,\nmestre do DOJO,\festá numa caverna\nem JOHTO,\vtreinando.",
  ["FightingDojoSign1Text"] = "Tudo o que vai\nvolta!",
  ["FightingDojoSign2Text"] = "Inimigos por\ntodos os lados!",
  ["FightingDojoSignText"] = "Bem-vindos todos!\nFIGHTING DOJO",
  ["FirebreatherBillAfterBattleText"] = "No fim de semana\ndá para ouvir\frugidos estranhos\nlá no fundo.",
  ["FirebreatherBillSeenText"] = "O SUPERSONIC dos\nZUBAT vive\vdeixando eu\vconfuso.\fIsso me irrita\nmuito mesmo!",
  ["FirebreatherBurtAfterBattleText"] = "O maior cuspidor\nde fogo de KANTO\vsou eu.\fMas não o melhor\ntreinador…",
  ["FirebreatherBurtSeenText"] = "Chegue mais perto\ne dê uma olhada!",
  ["FirebreatherLyleAfterBattleText"] = "Acho que o fogo é\nfraco no mar.\fNão faz diferença?\nSério?",
  ["FirebreatherLyleBeatenText"] = "Fsss… A chama\nestá fraquinha…",
  ["FirebreatherOtisAfterBattleText"] = "Quando chove, é\ndifícil dar a\vpartida…",
  ["FirebreatherOtisBeatenText"] = "Está sol, mas eu\nestou encharcado…",
  ["FirebreatherRayAfterBattleText"] = "É o fogo do meu\nPOKéMON que acende\vesta caverna.",
  ["FirebreatherRaySeenText"] = "Com luz, caverna\nnão assusta.\fSe você é forte,\nPOKéMON também\vnão assustam.",
  ["FirebreatherWaltAfterBattleText"] = "A POKéMON March\nno rádio atrai\vPOKéMON do mato.",
  ["FirebreatherWaltBeatenText"] = "Ai! Queimei a\nponta do nariz!",
  ["FirebreatherWaltSeenText"] = "Estou treinando\nmeu sopro de fogo",
  ["Fisher1Text_Concentration"] = "Não fale comigo!\fVocê vai quebrar\na concentração!",
  ["Fisher1Text_Snarfle"] = "…Nhac, nhac…",
  ["Fisher2Text_GulpChew"] = "…Glup… Glup…",
  ["Fisher2Text_Quantity"] = "Quero quantidade\nantes de\fqualidade! Fico\nfeliz quando como",
  ["Fisher3Text_GoldenrodIsBest"] = "A comida é boa\naqui, mas a de\vGOLDENROD é a\vmelhor de todas.",
  ["Fisher3Text_MunchMunch"] = "Nhac, nhac…",
  ["FisherAndreAfterBattleText"] = "Não perco como\npescador! Pesco\vPOKéMON todo dia",
  ["FisherAndreBeatenText"] = "Sou bom pescador,\nmas péssimo como\ftreinador de\nPOKéMON…",
  ["FisherAndreSeenText"] = "Deixe-me batalhar\ncom o POKéMON que\vacabei de pegar!",
  ["FisherArnoldAfterBattleText"] = "Vou voltar a\npescar…",
  ["FisherArnoldBeatenText"] = "Fracasso total…",
  ["FisherArnoldSeenText"] = "Cansei de pescar.\nVamos batalhar!",
  ["FisherBarneyAfterBattleText"] = "Eu acho que a\neletricidade é o\fmais importante\ndo nosso dia.\fSe não fosse,\nninguém teria\ffeito tanto\nalarde quando a\fPOWER PLANT\nparou de vez.",
  ["FisherBarneyBeatenText"] = "A resposta vem\nlogo depois!",
  ["FisherBarneySeenText"] = "O que é mais\nimportante no\vnosso dia a dia?",
  ["FisherEdgarAfterBattleText"] = "São 100 vitórias\ne 101 derrotas.\fNão vou lutar de\nnovo tão cedo.",
  ["FisherEdgarBeatenText"] = "Hmmmm…\nNão está certo.",
  ["FisherEdgarSeenText"] = "Eu pesco até não\naguentar mais.\fE luto até\ncair também.\fÉ essa a minha\nrelação com os\vmeus POKéMON.",
  ["FisherHenryAfterText"] = "POKéMON\nrecém-pegos não\vsão\fpáreo para os bem\ncriados.",
  ["FisherHenrySeenText"] = "Meus POKéMON?\nRecém-pescados!",
  ["FisherJonahAfterBattleText"] = "Pretendo pescar no\npíer de VERMILION",
  ["FisherJonahBeatenText"] = "Eu… já não estou\nentediado…",
  ["FisherJonahSeenText"] = "Mesmo estando no\nmar, eu não posso\vpescar!\fQue tédio!\nVamos batalhar!",
  ["FisherJustinAfterText"] = "Calmo, concentrado\nA essência da\fpesca e dos\nPOKéMON é a\vmesma.",
  ["FisherJustinSeenText"] = "Uau!\fVocê me fez perder\naquele peixe!",
  ["FisherKyleAfterBattleText"] = "O puxão que você\nsente na ROD\fquando fisga um\nPOKéMON…\fÉ a melhor\nsensação para um\vpescador como eu.",
  ["FisherKyleBeatenText"] = "Lembra mesmo?",
  ["FisherKyleSeenText"] = "Você lembra?",
  ["FisherMartinAfterBattleText"] = "Não tenho\npaciência para\vpescar…",
  ["FisherMarvinAfterBattleText"] = "A LURE BALL do\nKURT é a melhor\fpara pegar POKéMON\nfisgado.\fÉ bem mais\neficaz que uma\vULTRA BALL.",
  ["FisherMarvinBeatenText"] = "Perdi, mas me\nsinto melhor.",
  ["FisherMarvinSeenText"] = "Estou numa fase\fDeve ser o\nequipamento.\fVamos lutar para\nmudar o clima!",
  ["FisherRalph1BeatenText"] = "Tch! Quis apressar\nas coisas…",
  ["FisherRalph1SeenText"] = "Sou um bom\npescador, mas um\vtreinador melhor!",
  ["FisherRalphAfterText"] = "Pescar é paixão\nde uma vida.\fPOKéMON são amigos\nde uma vida!",
  ["FisherRaymondAfterBattleText"] = "Por que não pego\nbons POKéMON?",
  ["FisherRaymondBeatenText"] = "Minha linha está\ntoda embaraçada…",
  ["FisherRaymondSeenText"] = "Não importa o que\nfaça, só pego os\fmesmos POKéMON…",
  ["FisherScottAfterBattleText"] = "Como na pesca,\nem POKéMON está\ftudo perdido se\nvocê desistir.",
  ["FisherScottBeatenText"] = "Não! Não nesta\nbatalha!",
  ["FisherScottSeenText"] = "Estou me sentindo\nótimo hoje!\fSinto que poderia\nvencer até\vo CAMPEÃO!",
  ["FisherStephenAfterBattleText"] = "Você já ouviu as\nrádios de KANTO?\fA variedade aqui\né boa.",
  ["FisherStephenBeatenText"] = "Meu rádio idiota\nme distraiu!",
  ["FisherStephenSeenText"] = "Fico tão à vontade\npescando e ouvindo\vuma música no\vmeu rádio.",
  ["FisherWilton1BeatenText"] = "Deixa pra\nlá.",
  ["FisherWiltonHugePoliwagText"] = "Aquele POLIWAG\nque escapou…\vEra enorme.\fJuro que tinha uns\n5 metros!",
  ["FishingDudeText"] = "Eu sou o FISHING\nGURU, o mais velho\vdos FISHING BROS.\fPor acaso conhece\no FISHERMAN\fWILTON? Ele pesca\nna ROTA 44.\fEle me ligou com\numa dica\vincrível.\fGraças a ele, eu\npeguei um monte\fde um POKéMON raro\nQue dia aquele!",
  ["FishingDudesHousePhotoText"] = "É uma foto de\ngente pescando…\fParecem estar\nse divertindo…",
  ["FishingGurusHouseSignText"] = "CASA DO\nFISHING GURU",
  ["FishingSpotSignText"] = "ÁREA de PESCA",
  ["FriedaFridayText"] = "FRIEDA: Oi! Que\ndia você gosta?\fAmo sexta-feira.\nSem dúvida!\fVocê não acha\nótimo também?",
  ["FriedaGaveGiftText"] = "FRIEDA: Dê a um\nPOKéMON que tenha\vataques venenosos\fOh!\fÉ cruel!\fVai se espantar\ncom o quanto\vmelhora eles!",
  ["FriedaGivesGiftText"] = "Aqui, um POISON\nBARB para você!",
  ["FriedaNotFridayText"] = "FRIEDA: Hoje não\né sexta-feira?\fÉ tão sem graça\nquando não é!",
  ["FuchsiaCityPokefanMText"] = "A filha do KOGA\nvirou o LÍDER do\fGINÁSIO depois\nque ele entrou no\vELITE FOUR.",
  ["FuchsiaCitySignText"] = "CIDADE DE FUCHSIA\fVeja! É o Rosa\nda Paixão!",
  ["FuchsiaCityTeacherText"] = "A SAFARI ZONE está\nfechada… Que\fpena, era a\nmaior atração\vde FUCHSIA.",
  ["FuchsiaCityYoungsterText"] = "Um dos ELITE\nFOUR já foi o\fLÍDER do GINÁSIO\nde FUCHSIA.",
  ["FuchsiaGymGuideText"] = "Ei, futuro\nCAMPEÃO!\fOpa! Dê uma boa\nolhada em volta.\fOs treinadores são\ntodos iguais à\vLÍDER, a JANINE.\fQual deles é a\nJANINE real?",
  ["FuchsiaGymGuideWinText"] = "Foi uma batalha\ne tanto, treinador\vde JOHTO!",
  ["FuchsiaGymSignText"] = "CIDADE DE FUCHSIA\nPOKéMON GYM\vLÍDER: JANINE\fA Mestra Ninja\ndos Venenos",
  ["FuchsiaMartCooltrainerFText"] = "A neta do WARDEN\nda SAFARI ZONE\vmora aqui\vna cidade.",
  ["FuchsiaMartFisherText"] = "Eu queria comprar\nlembranças da\fSAFARI ZONE, mas\nestá fechada…",
  ["FuchsiaPokecenter1FCooltrainerFText"] = "Levei um susto\nno GINÁSIO.\fTinha um monte de\nmeninas que eram\vtodas iguais.",
  ["FuchsiaPokecenter1FCooltrainerMText"] = "Ei! Você tem uma\nPOKéDEX de um tipo\vnovo em folha.\fFoi o PROF.OAK que\nte deu?",
  ["FuchsiaPokecenter1FJanineImpersonatorText1"] = "Eu sou a JANINE!\nAbracadabra… Puf!",
  ["FuchsiaPokecenter1FJanineImpersonatorText2"] = "Viu? Agora eu sou\nigualzinha a ela!",
  ["GameFreakCharacterDesignerText"] = "As GÊMEAS são\nadoráveis!\fJASMINE também\né bonita.\fAh, eu as adoro!",
  ["GameFreakGameDesignerAfterDiplomaText"] = "O ARTISTA GRÁFICO\nvai imprimir um\vDIPLOMA pra você.\fDeve mostrá-lo por\naí.",
  ["GameFreakGameDesignerCompletedPokedexText"] = "Uau! Excelente!\nVocê completou sua\vPOKéDEX!\fParabéns!",
  ["GameFreakGameDesignerText"] = "Isso mesmo!\fSou o DESIGNER\ndo JOGO!\fCompletar sua\nPOKéDEX é duro,\vmas não desista!",
  ["GameFreakGraphicArtistPrintDiplomaText"] = "Sou o ARTISTA\nGRÁFICO.\fAh, completou sua\nPOKéDEX?\fPosso imprimir\no seu DIPLOMA?",
  ["GameFreakGraphicArtistRefusedText"] = "Me avise se quiser\nimprimir o\vDIPLOMA.",
  ["GameFreakGraphicArtistText"] = "Sou o ARTISTA\nGRÁFICO.\fEu te desenhei!",
  ["GameFreakProgrammerText"] = "Quem, eu? Sou o\nPROGRAMADOR.\fJogue nas máquinas\ncaça-níqueis!",
  ["GaveGoodRodText"] = "Peixe não existe\nsó no mar.\fEles vão pra onde\nhá água.",
  ["GaveSuperRodText"] = "Tente pescar em\nqualquer lugar\vque tenha água.\fLembre, dá para\npegar POKéMON\fdiferentes com\nRODS diferentes.",
  ["GentlemanAlfredAfterBattleText"] = "Lá em cima tem um\nPOKéMON que mantém\vo farol aceso.\fMas ouvi que ele\nestá doente e\fnão sara com\nremédio comum.",
  ["GentlemanAlfredBeatenText"] = "Ah! Dá para ver\nque você é sério.",
  ["GentlemanAlfredSeenText"] = "Hm? Aqui não é\nlugar de brincar.",
  ["GentlemanEdwardAfterBattleText"] = "Desisto. Filho,\nvocê não precisa\fprocurar. Esqueça\nisso!",
  ["GentlemanEdwardBeatenText"] = "Eu… não consigo\nachar…",
  ["GentlemanEdwardSeenText"] = "Ah, não. Perdi uma\ncoisa que é muito\vimportante.",
  ["GentlemanGregoryAfterBattleText"] = "Quando eu estava\nno exército, o\fLT.SURGE salvou\na minha vida.",
  ["GentlemanGregoryBeatenText"] = "Desculpe, falhei\ncom o LT.SURGE,\vsenhor!",
  ["GentlemanGregorySeenText"] = "Veio derrotar o\nLT.SURGE?\fNão enquanto eu\nestiver aqui!",
  ["GentlemanPrestonAfterBattleText"] = "A JASMINE usava\nPOKéMON de pedra\vcomo o ONIX.",
  ["GentlemanPrestonBeatenText"] = "…suspiro… Preciso\ntreinar mais…",
  ["GentlemanPrestonSeenText"] = "Viajo o mundo\npara treinar meus\vPOKéMON. Quero\vbatalhar com você",
  ["GetStormBadgeText"] = "{PLAYER} recebeu\na STORMBADGE.",
  ["GinaRocketTakeoverRumorText"] = "{PLAYER}, você\nouviu a notícia?\fA TEAM ROCKET\ntomou a RADIO\fTOWER de CIDADE\nDE GOLDENROD.\fEstarão bem os\nfuncionários?",
  ["GiveGoodRodText"] = "Ah, hahaha!\nTemos para nós\vum novo pescador!",
  ["GiveSuperRodText"] = "Isso, isso. Como\neu pensava!\fToma, fã de pesca!\nPegue isto, é uma\vSUPER ROD.",
  ["GoldenrodBikeShopBicycleText"] = "É uma BICYCLE\nnova e brilhante!",
  ["GoldenrodBikeShopClerkAgreedText"] = "Sério? Ótimo!\fDê-me seu nome\ne telefone e\flhe empresto\numa BICYCLE.",
  ["GoldenrodBikeShopClerkFirstRateBikesText"] = "Minhas BICYCLEs\nsão de primeira!\fVocê pode andar\nem qualquer lugar",
  ["GoldenrodBikeShopClerkIntroText"] = "…Suspiro… Me\nmudei, mas não\fvendo minhas\nBICYCLE. Por quê?\fAh, sei! Você\npoderia andar e\vanunciar pra mim?",
  ["GoldenrodBikeShopClerkRefusedText"] = "…Suspiro… Ah,\nse as pessoas\vfossem boas…",
  ["GoldenrodBikeShopJustReleasedCompactBikeText"] = "Recém-lançada!\fBICYCLE compacta\nde primeira!",
  ["GoldenrodCityBikeShopSignText"] = "O mundo é uma\nciclovia!\vBIKE SHOP",
  ["GoldenrodCityCooltrainerF1Text"] = "Aquele homem de\npreto se veste\fcomo a TEAM ROCKET\nQue bobagem!",
  ["GoldenrodCityCooltrainerF1Text_ClearedRadioTower"] = "Aquele de preto\nera mesmo da\fTEAM ROCKET? Não\nacredito nisso!",
  ["GoldenrodCityCooltrainerF2Text"] = "A RADIO TOWER de\nCIDADE DE\vGOLDENROD é\vum cartão-postal.\fEstão com uma\npromoção\vrolando agora.\fEles modificam\na sua POKéGEAR,\fpara ela virar\num rádio também.",
  ["GoldenrodCityCooltrainerF2Text_GotRadioCard"] = "Oh, sua POKéGEAR\ntoca rádio agora!",
  ["GoldenrodCityFlowerShopSignText"] = "LOJA DE FLORES\nLindas e Floridas",
  ["GoldenrodCityGameCornerSignText"] = "Seu parquinho!\fCIDADE DE\nGOLDENROD\vGAME CORNER",
  ["GoldenrodCityGrampsText"] = "Ufa! Esta cidade\né grande. Não sei\fonde fica\nnada.",
  ["GoldenrodCityLassText"] = "O homem daquela\ncasa avalia os\vnomes que você dá\fEle até renomeia\no seu POKéMON.",
  ["GoldenrodCityMoveTutorAsk4000CoinsOkayText"] = "Vai custar 4000\nfichas. Tudo bem?",
  ["GoldenrodCityMoveTutorAskTeachAMoveText"] = "Posso ensinar\ngolpes incríveis\fpro seu POKéMON,\nse quiser.\fQuer que eu\nensine um golpe\vnovo?",
  ["GoldenrodCityMoveTutorAwwButTheyreAmazingText"] = "Ah… Mas eles são\nincríveis…",
  ["GoldenrodCityMoveTutorBButText"] = "M-mas…",
  ["GoldenrodCityMoveTutorFarewellKidText"] = "Uahahá!\nAté mais, garoto!",
  ["GoldenrodCityMoveTutorHmTooBadText"] = "Hum, que pena.\nVou ter que\vpegar dinheiro\vem casa…",
  ["GoldenrodCityMoveTutorIfYouUnderstandYouveMadeItText"] = "Se você entende\no que há de\fincrível nesse\ngolpe, já é um\fbom treinador.",
  ["GoldenrodCityMoveTutorWhichMoveShouldITeachText"] = "Uahahá! Você não\nvai se arrepender!\fQual golpe devo\nensinar?",
  ["GoldenrodCityMoveTutorYouDontHaveEnoughCoinsText"] = "…Você não tem\nfichas suficientes\vaqui…",
  ["GoldenrodCityNameRaterSignText"] = "NAME RATER\fAvalie os apelidos\ndos seus POKéMON",
  ["GoldenrodCityPokeComCenterSignText"] = "Dicas de Celular!\nPOKéCOM CENTER",
  ["GoldenrodCityPokefanMText"] = "Construíram a nova\nRADIO TOWER para\ftrocar a velha,\nque rangia.",
  ["GoldenrodCityRadioTowerSignText"] = "CIDADE DE\nGOLDENROD\vRADIO TOWER",
  ["GoldenrodCityRocket1Text"] = "Saia do caminho!\nCai fora!",
  ["GoldenrodCityRocket2Text"] = "Tomar a RADIO\nTOWER…\fO quê? Não é da\nsua conta!",
  ["GoldenrodCityRocket3Text"] = "POKéMON? Não são\nnada além de\fferramentas para\nganhar dinheiro!",
  ["GoldenrodCityRocket4Text"] = "Nosso sonho logo\nvai se realizar…\fFoi uma luta tão\nlonga…",
  ["GoldenrodCityRocket5Text"] = "Ei, pirralho! Você\nnão é daqui!\vSuma!",
  ["GoldenrodCityRocket6Text"] = "Venha provar o\nverdadeiro terror\vda TEAM ROCKET!",
  ["GoldenrodCityRocketScoutText1"] = "Então esta é a\nRADIO TOWER…",
  ["GoldenrodCityRocketScoutText2"] = "O que você quer,\npentelho? Some!",
  ["GoldenrodCitySignText"] = "CIDADE DE\nGOLDENROD\fA cidade festiva\nde muito charme",
  ["GoldenrodCityStationSignText"] = "CIDADE DE\nGOLDENROD\vESTAÇÃO",
  ["GoldenrodCityUndergroundSignNorthText"] = "ENTRADA DO\nSUBTERRÂNEO",
  ["GoldenrodCityUndergroundSignSouthText"] = "ENTRADA DO\nSUBTERRÂNEO",
  ["GoldenrodCityYoungster1Text"] = "Sei que tem uma\nBIKE SHOP nova,\fmas não acho ela\nem lugar nenhum.",
  ["GoldenrodCityYoungster2Text"] = "E-he-he-he…\fLevei bronca\npor brincar no\fsubsolo da\nDEPT.STORE.",
  ["GoldenrodDeptStore1FBugCatcherText"] = "Mamãe é boa em\ncaçar promoção.\fEla sempre compra\nas coisas mais\vbaratas.",
  ["GoldenrodDeptStore1FDirectoryText"] = "1F BALCÃO\f2F MERCADO DO\n   TREINADOR\f3F COLEÇÃO DE\n   BATALHA\f4F REMÉDIOS\f5F CANTO DAS TM\f6F TERRAÇO",
  ["GoldenrodDeptStore1FGentlemanText"] = "A DEPT.STORE tem\numa boa\vvariedade.\fMas alguns itens\nsó saem como\fprêmios do\nGAME CORNER.",
  ["GoldenrodDeptStore1FPokefanFText"] = "Estou doida para\ncomprar hoje!",
  ["GoldenrodDeptStore1FReceptionistText"] = "Bem-vindo à\nDEPT.STORE!",
  ["GoldenrodDeptStore2FCooltrainerFText"] = "Ganhei meu ABRA\nna CASA DE JOGOS.\fAgora é meu\nmelhor parceiro.",
  ["GoldenrodDeptStore2FDirectoryText"] = "SUA COMPANHEIRA\nDE VIAGEM\f2º ANDAR: MERCADO\nDO TREINADOR",
  ["GoldenrodDeptStore2FGentlemanText"] = "Esta LOJA me faz\nver que GOLDENROD\fé uma cidade\ngrande.\fA seleção daqui\nnão tem igual\vem nenhum lugar.",
  ["GoldenrodDeptStore2FUnusedText1"] = "Vamos vender itens\npra POKéMON\vsegurar.\fIsso é um\npresente grátis.\vDeixe um POKéMON\vsegurar.",
  ["GoldenrodDeptStore2FUnusedText2"] = "Ao dar itens\npros POKéMON\vsegurarem,\facho que\ntreinadores vão\vcriar novas\vtécnicas de\vbatalha.",
  ["GoldenrodDeptStore2FYoungsterText"] = "A POKéGEAR pode\nguardar até dez\vnúmeros.\fÉ difícil\ndecidir quais\vguardar.",
  ["GoldenrodDeptStore3FDirectoryText"] = "Para os que Buscam\na Vitória\f3F COLECAO\nDE BATALHA",
  ["GoldenrodDeptStore3FRockerText"] = "Ei! Em batalha,\nvocê usa X\vSPECIAL?\fÉ demais. Ele\naumenta muito\vos SPECIAL!",
  ["GoldenrodDeptStore3FSuperNerdText"] = "Eu, eu, eu sou bem\nimpaciente!\fUso X SPEED na\nbatalha para\vacelerar POKéMON.",
  ["GoldenrodDeptStore4FBugCatcherText"] = "IRON: a DEFESA do\nPOKéMON sobe.",
  ["GoldenrodDeptStore4FCooltrainerMText"] = "Ei. Amo POKéMON\nfortes.\fDou PROTEIN a\neles para elevar\vo ATTACK.",
  ["GoldenrodDeptStore4FDirectoryText"] = "Vamos Turbinar\nSeu POKéMON!\f4º ANDAR REMÉDIOS",
  ["GoldenrodDeptStore4FGameboyKidText"] = "Alguns POKéMON\nevoluem quando\fsão trocados por\ncabo Game Link.\fConheço quatro:\nMACHOKE, KADABRA,\fHAUNTER e, hum,\nGRAVELER.\fDizem que existem\noutros também.",
  ["GoldenrodDeptStore5FCarrieMysteryGiftExplanationText"] = "MYSTERY GIFT.\fCom um pequeno\nbip, você\vganha um presente",
  ["GoldenrodDeptStore5FCarrieMysteryGiftRequiresGBCText"] = "O MYSTERY GIFT\nexige um\vGame Boy Color.",
  ["GoldenrodDeptStore5FDirectoryText"] = "Personalize seu\nPOKéMON\f5º ANDAR: TM",
  ["GoldenrodDeptStore5FLassText"] = "Aos domingos, uma\nmoça vem olhar\vos POKéMON.\fEla até dá\nTM de presente!",
  ["GoldenrodDeptStore5FPokefanMText"] = "Não dá para\nrenomear um\vPOKéMON trocado.\fO nome mostra o\ncarinho do\ftreinador antigo\npor ele.",
  ["GoldenrodDeptStore5FReceptionistItLooksEvilHowAboutThisTMText"] = "Parece mau. Que\ntal esta TM para\vele?",
  ["GoldenrodDeptStore5FReceptionistItsAdorableText"] = "É adorável!\fEnsine bons\nmovimentos de TM.",
  ["GoldenrodDeptStore5FReceptionistOhYourMonDotDotDotText"] = "Olá. Oh, seu\nPOKéMON…",
  ["GoldenrodDeptStore5FReceptionistThereAreTMsPerfectForMonText"] = "Com certeza há\nTM perfeita para\fo seu\nPOKéMON.",
  ["GoldenrodDeptStore5FReceptionistThisMoveShouldBePerfectText"] = "Ele é muito\nafeiçoado a você.\fEste golpe deve\nser perfeito para\vvocês dois.",
  ["GoldenrodDeptStore6FDirectoryText"] = "Descanse um pouco\ndas compras!\f6º ANDAR: TERRAÇO",
  ["GoldenrodDeptStore6FLassText"] = "Você ouve a\nLUCKY CHANNEL?\fSe quer vencer,\ntroque POKéMON\fcom o máximo de\ngente para ter\fnúmeros de ID\ndiferentes.",
  ["GoldenrodDeptStore6FSuperNerdText"] = "Se estiver cansado\ntente as bebidas\vdas máquinas.\fSeu POKéMON vai\namar também.",
  ["GoldenrodDeptStoreB1FBlackBelt1Text"] = "Ei, garoto!\nVocê nos atrasa!\fNosso esquema\né trabalhar\fnos bastidores,\nonde ninguém vê!",
  ["GoldenrodDeptStoreB1FBlackBelt2Text"] = "Perco a vontade\nde trabalhar se\valguém me vê.\fAnda, garoto,\ncai fora!",
  ["GoldenrodDeptStoreB1FBlackBelt3Text"] = "Oohah! Oohah!\fAs coisas no\nchão são lixo.\fLeve-as se\nquiser!",
  ["GoldenrodDeptStoreRoofBugCatcherText"] = "Meu POKéMON\nsempre fica\fparalisado ou\nenvenenado\fbem na hora H…\fVim comprar um\nFULL HEAL.\fSerá que ainda\ntem?",
  ["GoldenrodDeptStoreRoofFisherText"] = "Como? Quem disse\nque adulto não\vpode gostar disso?\fVou voltar todo\ndia pra\fcolecionar todas\nas bonecas!",
  ["GoldenrodDeptStoreRoofPokefanFText"] = "Ufa, estou\ncansada.\fÀs vezes venho\naté o terraço\fpra descansar\ndas compras.",
  ["GoldenrodDeptStoreRoofPokefanMText"] = "Tem uma coisa que\neu quero muito,\fmas não tenho\ndinheiro pra isso…\fTalvez eu venda\nas BERRIES que\veu coletei…",
  ["GoldenrodDeptStoreRoofSuperNerdOhWowText"] = "Nossa!",
  ["GoldenrodDeptStoreRoofSuperNerdQuitBotheringMeText"] = "Para de me\nincomodar?",
  ["GoldenrodDeptStoreRoofTeacherText"] = "Nossa, está tudo\ntão barato!\fComprei tanto\nque minha BOLSA\vlotou!",
  ["GoldenrodDeptStoreRoofTwinText"] = "Aqui tem promoção\nde vez em\vquando.",
  ["GoldenrodDeptStoreSignText"] = "Tudo em produtos\nPOKéMON!\fCIDADE DE\nGOLDENROD\vDEPT.STORE",
  ["GoldenrodFlowerShopFloriaItReallyWasAMonText"] = "Então era mesmo\num POKéMON!",
  ["GoldenrodFlowerShopFloriaWonderIfSisWillLendWaterBottleText"] = "Quando contei pra\nminha irmã sobre\fa árvore mole,\nela disse que é\vperigoso.\fSe eu vencer a\nWHITNEY, será que\fela empresta a\ngarrafa d'água\vdela…",
  ["GoldenrodFlowerShopFloriaYouBeatWhitneyText"] = "Nossa, você venceu\na WHITNEY? Legal!",
  ["GoldenrodFlowerShopTeacherAskWantToBorrowWaterBottleText"] = "Quer pegar\nemprestada a\fgarrafa d'água\ntambém? Não quero\fque faça nada\nperigoso com ela.",
  ["GoldenrodFlowerShopTeacherDontDoAnythingDangerousText"] = "Não faça nada\nmuito perigoso!",
  ["GoldenrodFlowerShopTeacherHeresTheSquirtbottleText"] = "Ah, você é melhor\nque a WHITNEY…\fVai ficar tudo\nbem, então. Aqui\vestá a\vSQUIRTBOTTLE!",
  ["GoldenrodFlowerShopTeacherLalalaHavePlentyOfWaterText"] = "Lalala lalalala.\nMuita água,\vminha linda!",
  ["GoldenrodFlowerShopTeacherMySisterWentToSeeWigglyTreeRoute36Text"] = "Já viu aquela\nárvore que se\fmexe, crescendo\nna ROTA 36?\fMinha irmãzinha\nficou empolgada\fe foi ver de\nperto…\fEstou preocupada…\nNão é perigoso?",
  ["GoldenrodGameCornerCooltrainerFText"] = "Não paro até\nconseguir vencer!",
  ["GoldenrodGameCornerCooltrainerMText"] = "A vida é um jogo.\nVou virar\vcartas até cair!",
  ["GoldenrodGameCornerGentlemanText"] = "Ensinei BLIZZARD\nao meu POKéMON.\fFoi difícil juntar\nas moedas para\fele, mas valeu\na pena.",
  ["GoldenrodGameCornerLeftTheirDrinkText"] = "Alguém deixou a\nbebida aqui.\fCheira doce.",
  ["GoldenrodGameCornerPharmacistText"] = "Sempre jogo nesta\nmáquina.\fAcho que ela paga\nmais que outras.",
  ["GoldenrodGameCornerPokefanFText"] = "Vira-cartas…\fPrefiro aos\ncaça-níqueis\fporque é mais\nfácil de calcular\fas chances.\nMas paga menos.",
  ["GoldenrodGameCornerPokefanM1Text"] = "Adoro esta nova\ncaça-níqueis.\fÉ mais desafiadora\nque as de\vCELADON.",
  ["GoldenrodGameCornerPokefanM2Text"] = "Perdi nas\ncaça-níqueis,\fgastei tudo\nna vira-cartas…\fFiquei tão nervoso\nque joguei fora\fminha COIN CASE\nno UNDERGROUND.",
  ["GoldenrodGameCornerPrizeVendorConfirmPrizeText"] = "{RAM:D099}.\nEstá certo?",
  ["GoldenrodGameCornerPrizeVendorHereYouGoText"] = "Aqui está!",
  ["GoldenrodGameCornerPrizeVendorIntroText"] = "Bem-vindo!\fTrocamos suas\nmoedas de jogo\vpor prêmios bons!",
  ["GoldenrodGameCornerPrizeVendorNeedMoreCoinsText"] = "Precisa de mais\nmoedas ainda!",
  ["GoldenrodGameCornerPrizeVendorNoCoinCaseText"] = "Oh? Você não tem\na COIN CASE.",
  ["GoldenrodGameCornerPrizeVendorNoMoreRoomText"] = "Desculpe. Você\nnão pode carregar",
  ["GoldenrodGameCornerPrizeVendorQuitText"] = "OK. Guarde suas\nmoedas e\vvolte sempre!",
  ["GoldenrodGameCornerPrizeVendorWhichPrizeText"] = "Qual prêmio você\nquer?",
  ["GoldenrodGymGuideText"] = "E aí! Futuro\nCAMPEÃO!\fEste GINÁSIO é de\ntreinadores de\vPOKéMON normais.\fRecomendo que use\nPOKéMON do tipo\vlutador.",
  ["GoldenrodGymGuideWinText"] = "Ganhou? Ótimo! Eu\nestava ocupado\volhando as moças.",
  ["GoldenrodGymSignText"] = "CIDADE DE\nGOLDENROD\vGINÁSIO POKéMON\vLÍDER: WHITNEY\fA garota\nlinda demais!",
  ["GoldenrodHappinessRaterPokefanMText"] = "Vivo perdendo\nbatalhas e meus\fPOKéMON acabam\ndesmaiando…\fTalvez por isso\nmeus POKéMON não\vgostem de mim…",
  ["GoldenrodHappinessRaterTeacherText"] = "Se você tratar\nbem seu POKéMON,\fele vai te amar\nde volta.\fAh? Deixa eu ver\nseu {RAM:D099}…",
  ["GoldenrodHappinessRaterTwinText"] = "Quando uso item\nno POKéMON, ele\vfica todo feliz!",
  ["GoldenrodHappinessRatingText_LooksMean"] = "Ele não parece\ngostar de você.\vParece bravo.",
  ["GoldenrodHappinessRatingText_LovesYouALot"] = "Ele parece muito\nfeliz! Deve te\vamar muito.",
  ["GoldenrodHappinessRatingText_NotUsedToYou"] = "Trate ele melhor.\nEle ainda não\vconfia em você.",
  ["GoldenrodHappinessRatingText_QuiteCute"] = "Ele é bem fofo.",
  ["GoldenrodHappinessRatingText_ReallyTrustsYou"] = "Tenho a sensação\nde que ele\vconfia em você.",
  ["GoldenrodMagnetTrainStationGentlemanText"] = "Sou o PRESIDENTE.\fMeu sonho era\nconstruir um trem\fmais rápido que\nqualquer POKéMON.\fEle realmente\naproxima JOHTO e\vKANTO.",
  ["GoldenrodMagnetTrainStationOfficerAreYouComingAboardText"] = "Vamos partir logo\npara SAFFRON.\fVocês virão\na bordo?",
  ["GoldenrodMagnetTrainStationOfficerArrivedInGoldenrodText"] = "Chegamos a\nGOLDENROD!\fEsperamos vê-lo\nde novo.",
  ["GoldenrodMagnetTrainStationOfficerHopeToSeeYouAgainText"] = "Esperamos vê-lo\nnovamente!",
  ["GoldenrodMagnetTrainStationOfficerRightThisWayText"] = "Posso ver seu\nRAIL PASS?\fCerto. Venha por\naqui, senhor.",
  ["GoldenrodMagnetTrainStationOfficerTheTrainHasntComeInText"] = "O trem não\nchegou…\fJá sei! Vou levar\nos passageiros\vnas costas!\fNão vai dar.",
  ["GoldenrodMagnetTrainStationOfficerYouDontHaveARailPassText"] = "Desculpe. Você\nnão tem RAIL PASS",
  ["GoldenrodPPSpeechHouseFisherText"] = "Uma vez, numa\nbatalha, meu\fPOKéMON não\nconseguia agir.\fOs POWER POINTS,\nou PP, dos seus\fgolpes tinham\nacabado.",
  ["GoldenrodPPSpeechHouseLassText"] = "Às vezes, um\nPOKéMON saudável\fnão consegue usar\nseus golpes.\fSe isso ocorrer,\ncurar no CENTRO\vPOKéMON ou usar\vum item.",
  ["GoldenrodPokecenter1FAskGiveAwayAnEonMailText"] = "Quer doar um\nEON MAIL?",
  ["GoldenrodPokecenter1FGameboyKidText"] = "O COLOSSEUM\nnos andares do\fCENTRO POKéMON,\né para batalhas\fvia link.\nOs recordes de\fluta na parede,\nnão posso perder.",
  ["GoldenrodPokecenter1FLassText"] = "Um POKéMON de\nnível mais alto\vnem sempre vence.\fEle pode até ter\ndesvantagem de\vtipo.\fAcho que não\nexiste um único\fPOKéMON que seja\no mais forte.",
  ["GoldenrodPokecenter1FPlayerGaveAwayTheEonMailText"] = "{PLAYER} doou o\nEON MAIL.",
  ["GoldenrodPokecenter1FPokefanFAnotherTimeThenText"] = "Ah… Bom, fica pra\noutra hora, então.",
  ["GoldenrodPokecenter1FPokefanFDaughterWillBeDelightedText"] = "Minha filha vai\nficar radiante!",
  ["GoldenrodPokecenter1FPokefanFDoYouHaveEonMailText"] = "Nossa, sua bolsa\nestá tão pesada!\fAh! Por acaso\nvocê tem algo\vchamado EON MAIL?\fMinha filha quer\numa.\fVocê pode abrir\nmão de uma, não?",
  ["GoldenrodPokecenter1FPokefanFThisIsForYouText"] = "Ah, que ótimo!\nObrigada, querido!\fToma, isso é pra\nvocê em troca!",
  ["GoldenrodPokecenter1FPokefanFTooBadText"] = "Ah? Não tem uma?\nQue pena.",
  ["GoldenrodPokecenter1FWeHopeToSeeYouAgainText_2"] = "Esperamos te ver\nde novo.",
  ["GoldenrodUndergroundBasementKeyOpenedDoorText"] = "A CHAVE DO PORAO\nabriu a porta.",
  ["GoldenrodUndergroundNoEntryText"] = "NÃO ENTRE\nALEM DESTE PONTO",
  ["GoldenrodUndergroundOlderHaircutBrotherAllDoneText"] = "Pronto! Feito!",
  ["GoldenrodUndergroundOlderHaircutBrotherAskWhichMonText"] = "Qual POKéMON\ndevo arrumar?",
  ["GoldenrodUndergroundOlderHaircutBrotherOfferHaircutText"] = "Bem-vindo!\fEu administro o\nPOKéMON SALON!\fSou o mais velho e\nmelhor dos dois\vHAIRCUT BROTHERS.\fPosso deixar seu\nPOKéMON bonito\vpor apenas R$500.\fGostaria\ndisso?",
  ["GoldenrodUndergroundOlderHaircutBrotherOneHaircutADayText"] = "Faco apenas um\ncorte por dia.\vJá acabei.",
  ["GoldenrodUndergroundOlderHaircutBrotherThatsAShameText"] = "E isso mesmo?\nQue pena!",
  ["GoldenrodUndergroundOlderHaircutBrotherWatchItBecomeBeautifulText"] = "Certo! Observe\nficar bonito!",
  ["GoldenrodUndergroundOlderHaircutBrotherYoullNeedMoreMoneyText"] = "Você precisa de\nmais grana.",
  ["GoldenrodUndergroundSwitchRoomEntrances_SuperNerdText"] = "Fui desafiado\npara uma batalha\vlá embaixo.\fÉ perigoso\nlá. Melhor\vtomar cuidado.",
  ["GoldenrodUndergroundSwitchRoomEntrances_TeacherText"] = "Há lojas\nlá embaixo…\fMas também\nhá treinadores.\fTenho medo\nde descer.",
  ["GoldenrodUndergroundTheDoorIsOpenText"] = "Porta aberta.",
  ["GoldenrodUndergroundTheDoorsLockedText"] = "Porta trancada…",
  ["GoldenrodUndergroundWeAreNotOpenTodayText"] = "Não estamos\nabertos hoje.",
  ["GoldenrodUndergroundYoungerHaircutBrotherAllDoneText"] = "Pronto!\nTudo feito!",
  ["GoldenrodUndergroundYoungerHaircutBrotherAskWhichMonText"] = "Certo, qual\nPOKéMON?",
  ["GoldenrodUndergroundYoungerHaircutBrotherHowDisappointingText"] = "Não?\nQue pena!",
  ["GoldenrodUndergroundYoungerHaircutBrotherIllMakeItLookCoolText"] = "Certo! Vou\ndeixar legal!",
  ["GoldenrodUndergroundYoungerHaircutBrotherOfferHaircutText"] = "Bem-vindo ao\nPOKéMON SALON!\fSou o mais jovem\ne menos caro\vdos dois IRTOS\vCABELEIREIROS.\fVou arrumar seu\nPOKéMON por\vapenas R$300.\fComo vai?",
  ["GoldenrodUndergroundYoungerHaircutBrotherOneHaircutADayText"] = "Faco apenas um\ncorte por dia.\fDesculpe, mas já\nacabei.",
  ["GoldenrodUndergroundYoungerHaircutBrotherShortOnFundsText"] = "Você esta um pouco\nsem dinheiro.",
  ["GoldenrodVendingNoMoneyText"] = "Opa, dinheiro\ninsuficiente…",
  ["GoldenrodVendingNoSpaceText"] = "Não há mais espaço\npara coisas…",
  ["GoldenrodVendingText"] = "Uma máquina de\nvendas! O menu:",
  ["GotElmsNumberText"] = "{PLAYER} anotou o\ntelefone do ELM.",
  ["GotMapCardText"] = "A POKéGEAR de\n{PLAYER} tem MAPA!",
  ["GruntF1AfterBattleText"] = "SLOWPOKETAILS\ncrescem rápido!\fQual o problema\nde vender elas?",
  ["GruntF1BeatenText"] = "Seu pirralho!",
  ["GruntF1SeenText"] = "Parar as TAILS?\fÉ, tente vencer\ntodos nós então!",
  ["GruntF2AfterBattleText"] = "Você me venceu e\nnão vou esquecer!",
  ["GruntF2SeenText"] = "Hahaha!\fQue tédio.\nFoi fácil\fdemais tomar\neste lugar!\fVamos, me\ndivirta!",
  ["GruntF3AfterBattleText"] = "Vá para onde você\nquiser! Some!\vNão estou nem aí!",
  ["GruntF3SeenText"] = "Está perdido? Não,\nnão pode estar.\fVocê não tem\ncara de assustado\fVou te dar\num motivo para\vse assustar!",
  ["GruntF4AfterBattleText"] = "Eu amo a minha\nbeleza!\fQuem liga para\nos POKéMON?",
  ["GruntF4BeatenText"] = "Ah, não! Eles são\ntão inúteis!",
  ["GruntF4SeenText"] = "Não acho os\nPOKéMON fofos?\fVou achar os meus\nfofos, depois que\fderrotarem os\nseus!",
  ["GruntF5AfterBattleText"] = "A senha da sala\ndo chefe é\fSLOWPOKETAIL.\fMas não adianta\nse você não tiver\vas duas senhas.",
  ["GruntF5BeatenText"] = "Está bem. Pare.\nEu conto.",
  ["GruntF5SeenText"] = "Se eu sei a\nsenha?\fTalvez.\fMas nenhum fracote\nvai conseguir!",
  ["GruntM10AfterBattleText"] = "Não acredito!\nFui derrotado!",
  ["GruntM10BeatenText"] = "Não pode ser!",
  ["GruntM10SeenText"] = "Pretende salvar\no DIRECTOR?\fIsso não será\npossível, pois vou\vte derrotar!",
  ["GruntM11AfterBattleText"] = "Eu também estou\nconfuso… O botão\fda ponta é o que\nse aperta antes…",
  ["GruntM11BeatenText"] = "Droga! Afundei\npor indecisão!",
  ["GruntM11SeenText"] = "Abre uma persiana,\noutra fecha.\fAposto que não\nchega onde quer!",
  ["GruntM13AfterBattleText"] = "Você tem sangue\nde gelo para\vpeitar a ROCKET.",
  ["GruntM13BeatenText"] = "Urk! É, se acha\nesperto, hein?",
  ["GruntM13SeenText"] = "Não ligo se você\nestá perdido.\fApareceu aqui,\nvirou vítima e\vpronto!",
  ["GruntM14AfterBattleText"] = "Eu perdi…\fPor favor me\nperdoe, GIOVANNI!",
  ["GruntM14SeenText"] = "Você não passa\ndaqui!\fNão tenho piedade\ndos inimigos, nem\vdos pirralhos!",
  ["GruntM15AfterBattleText"] = "Hyuck-hyuck-hyuck!\nFoi demais!\vVou me lembrar!",
  ["GruntM15BeatenText"] = "Hyuck-hyuck-hyuck!\nEntão é assim?",
  ["GruntM15SeenText"] = "Hyuck-hyuck-hyuck!\nLembro de você!\fVocê me pegou\nno esconderijo!",
  ["GruntM16AfterBattleText"] = "Eu nem sei onde\nas armadilhas\vestão.\fVocê vai ter que\njuntar coragem\ve caminhar.",
  ["GruntM16SeenText"] = "Heheh. Está se\nachando sortudo?\fVai lá, dê mais\num passo.\fTemos armadilhas\npostas no chão!",
  ["GruntM17AfterBattleText"] = "Heh, eu sou só um\nGRUNT.\fEu não sei a\nsenha. Azar\vo seu.",
  ["GruntM17SeenText"] = "A porta não\nabre?\fOra, claro.\nPrecisa de uma\fsenha que só a\nTEAM ROCKET sabe.",
  ["GruntM18AfterBattleText"] = "Eu apanhei de uma\ncriança na última\vmissão também.\fQuando a gente\nestava roubando\fPOKéMON, um garoto\nruivo de olhar\fmau me\narrasou…",
  ["GruntM18SeenText"] = "Ah, uma criança?\nNão gosto disso,\fmas tenho que\neliminar você.",
  ["GruntM19AfterBattleText"] = "Heh, só o chefe\nsabe a senha\vdaquela porta.\fOnde está o chefe?\nSei lá. Vá\vprocurar você.",
  ["GruntM19SeenText"] = "Seu pestinha\ninsuportável!",
  ["GruntM1BeatenText"] = "Você foi bem hoje\npirralho, mas\vespere a próxima!",
  ["GruntM1SeenText"] = "O que você quer?\fSe atrapalhar o\nnosso trabalho,\vnão terá piedade!",
  ["GruntM24AfterBattleText"] = "A TEAM ROCKET vai\nseguir em frente,\vesperando a volta\vdo GIOVANNI.\fFaremos o que for\npreciso.",
  ["GruntM24BeatenText"] = "Ele acabou comigo",
  ["GruntM25AfterBattleText"] = "Certo. Uma dica!\fMude a ordem em\nque você aperta.\fIsso muda o jeito\nque as persianas\vabrem e fecham.",
  ["GruntM25SeenText"] = "Kwahaha!\fConfuso com as\npersianas, né?\fEu conto um\nsegredo se você\vme vencer!",
  ["GruntM28AfterBattleText"] = "Ruarrr-rarr-rarr!\fA senha da sala\ndo chefe…\fAhn…, eu acho que\né RATICATE TAIL.",
  ["GruntM28BeatenText"] = "Ruarrr-rarr-rarr!\nVocê é bom!",
  ["GruntM28SeenText"] = "Ruarrr-rarr-rarr!\fVocê está me\ndesafiando?\fHah! Você é louco,\nmas tem coragem!\fDisso eu gosto!\fSe me vencer, eu\nconto para você\fuma senha da sala\ndo chefe!",
  ["GruntM29AfterBattleText"] = "Sim, a gente vem\ncortando o rabo\fdos SLOWPOKE e\nvendendo elas.\fTudo o que fazemos\né por lucro.\fIsso mesmo!\nSomos a TEAM\fROCKET, e fazemos\ntudo por grana!",
  ["GruntM29BeatenText"] = "Arrgh! Hoje NÃO é\no meu dia!",
  ["GruntM29SeenText"] = "Droga! Eu estava\nde guarda lá em\fcima quando um\nvelho gritou.\fMe assustou tanto\nque eu caí aqui\vembaixo.\fAcho que vou\ndescontar a raiva\vem você!",
  ["GruntM2AfterBattleText"] = "A gente precisa da\ngrana, mas vender\vSLOWPOKETAILS?\fÉ duro ser um\nROCKET GRUNT!",
  ["GruntM2BeatenText"] = "Simplesmente…\nForte demais…",
  ["GruntM2SeenText"] = "Parar de tirar\nSLOWPOKETAILS?\fSe obedecêssemos,\na fama da TEAM\vROCKET acabava!",
  ["GruntM3AfterBattleText"] = "É forte demais.\fNosso plano pode\nruir. Preciso\vavisar os outros…",
  ["GruntM3BeatenText"] = "Muito forte! Nós\ntemos que vigiar…",
  ["GruntM3SeenText"] = "Finalmente\nassumimos a\vRADIO TOWER!\fAgora todos vão\nconhecer o terror\fde verdade da\nTEAM ROCKET!\fVamos mostrar\ncomo assustamos!",
  ["GruntM4AfterBattleText"] = "Não vamos deixar\nvocê arruinar os\vnossos planos!",
  ["GruntM4BeatenText"] = "Ugh! Não fica\nengraçadinho!",
  ["GruntM4SeenText"] = "Há três anos, a\nTEAM ROCKET foi\vobrigada a parar.\fMas agora a volta\nvem com tudo!",
  ["GruntM5AfterBattleText"] = "Não somos sempre\nmalvados. Fazemos\vo que gostamos.",
  ["GruntM5BeatenText"] = "Você acha que é\num herói?",
  ["GruntM5SeenText"] = "Somos TEAM ROCKET,\nos que exploram\vos POKéMON!\fAmamos ser\nmalvados! Medo?",
  ["GruntM6AfterBattleText"] = "Nossos EXECUTIVOS\nestão tentando\vtomar este lugar.\fEles têm um plano\ngrande. Queria\vsaber o que é.",
  ["GruntM6BeatenText"] = "Argh. Desisto.",
  ["GruntM6SeenText"] = "Ei, ei! Sai do\nnosso caminho!",
  ["GruntM7AfterBattleText"] = "Falhei no meu\ntrabalho…\fVou ter desconto\nno meu salário…",
  ["GruntM7SeenText"] = "Recebi ordens\nrígidas.\fVou esmagar quem\ndesafiar a TEAM\vROCKET!",
  ["GruntM8AfterBattleText"] = "Estou péssimo por\nter perdido!\fDroga! Odeio\nPOKéMON inúteis!",
  ["GruntM8BeatenText"] = "Tá brincando!",
  ["GruntM8SeenText"] = "É ótimo mandar\nos POKéMON\vcometer crimes.",
  ["GruntM9AfterBattleText"] = "O quê?! Passou\npelos nossos,\vno UNDERGROUND?\fComo conseguiu?",
  ["GruntM9BeatenText"] = "Estou feito!",
  ["GruntM9SeenText"] = "Por que a persiana\nabriu? Você tem\falgo a ver com\nisso?",
  ["GuideGentGiftText"] = "Aqui…\fÉ a minha casa!\nObrigado pela\vcompanhia.\fDeixe eu lhe dar\num presentinho.",
  ["GuideGentIntroText"] = "Você é um\ntreinador novato,\vné? Dá para ver!\fTudo bem! Todo\nmundo já foi\vnovato um dia!\fSe quiser, posso\nte ensinar umas\vcoisas.",
  ["GuideGentMartText"] = "Esta é uma LOJA\nPOKéMON.\fVendem BALLS para\npegar POKéMON\fselvagens e outros\nitens úteis.",
  ["GuideGentNoText"] = "Oh… É algo que\ngosto de fazer…\fTudo bem. Venha\nquando quiser.",
  ["GuideGentPokecenterText"] = "Este é um CENTRO\nPOKéMON. Curam\fseu POKéMON num\ninstante.\fVocê vai depender\nmuito deles,\fé bom aprender\nsobre eles.",
  ["GuideGentPokegearText"] = "A POKéGEAR fica\nmais útil quando\vvocê põe CARDS.\fBoa sorte na sua\njornada!",
  ["GuideGentRoute30Text"] = "A ROTA 30 fica\npor aqui.\fTreinadores lutam\ncom seus POKéMON\fpreferidos lá.\nVale ver.",
  ["GuideGentSeaText"] = "Este é o mar,\ncomo você vê.\fAlguns POKéMON só\nsão achados\vna água.",
  ["GuideGentTourText1"] = "Certo, então!\nMe siga!",
  ["GuideGentsHouseGuideGentText"] = "Quando eu era\npequeno, eu era um\vtreinador craque!\fVai um conselho:\npegue um monte\vde POKéMON!\fTrate todos eles\ncom bondade!",
  ["GuideGentsHouseSignText"] = "CASA DO GUIA",
  ["GuitaristClydeAfterBattleText"] = "Falando na RADIO\nSTATION,\fqual é o número da\nsorte da semana?",
  ["GuitaristClydeBeatenText"] = "Uau!\nDistorção total!",
  ["GuitaristClydeSeenText"] = "Vou fazer um teste\ncom as minhas\fmúsicas na RADIO\nSTATION.",
  ["GuitaristVincentAfterBattleText"] = "Se as armadilhas\nfuncionassem,\fvocê já estaria\nfrito…",
  ["GuitaristVincentBeatenText"] = "Ooh, que choque!",
  ["GuitaristVincentSeenText"] = "LT.SURGE viu meu\npotencial com\fPOKéMON\nelétricos.\fAcha que vai me\nvencer?",
  ["HallOfFame_LanceText"] = "LANCE: Faz muito\ntempo que eu não\vvenho aqui.\fÉ aqui que a gente\nhonra os CAMPEÕES\fda LEAGUE por toda\na eternidade.\fOs POKéMON\ncorajosos deles\vtambém entram.\fHoje, aqui, a\ngente viu surgir\fum novo CAMPEÃO\nda LEAGUE, um\ftreinador que tem\ncompaixão e\fconfiança nos\nseus POKéMON.\fUm treinador que\nvenceu por meio\fda perseverança e\nda determinação.\fO novo CAMPEÃO da\nLEAGUE, que tem\ftudo para ser\num grande!\f{PLAYER}, deixe eu\nregistrar você\fe seus parceiros\ncomo CAMPEÕES!",
  ["HappinessText1"] = "Você não domou\no seu POKéMON.\fSe não for legal,\nele emburra.",
  ["HappinessText2"] = "POKéMON ficam mais\namigos se você\fpassar tempo\ncom eles.",
  ["HappinessText3"] = "Uau! Você e seu\nPOKéMON são muito\vunidos!",
  ["HaveGoodRodText"] = "E aí, como vai?\nPegou uma grande?",
  ["HiddenPowerGuyText1"] = "…Você vagou muito\nlonge…\fAqui eu meditei.\nDentro de mim,\fum novo poder\ndespertou.\fDeixe-me dividir\nmeu poder com\fseu POKéMON.\nTome, criança.",
  ["HiddenPowerGuyText2"] = "Vê isto? É o\nHIDDEN POWER!\fEle extrai o\npoder do POKéMON\vpra atacar.\fLembre-se: o tipo\ne o poder dependem\vdo POKéMON\vque o usa.",
  ["HiddenPowerGuyText3"] = "Estou meditando…",
  ["HikerAnthony2AfterText"] = "Nós HIKERS somos\nmelhores nas\vmontanhas.",
  ["HikerAnthony2BeatenText"] = "Uau, garoto! Você\ntem mais gás.",
  ["HikerBaileyAfterBattleText"] = "Acabou. Tudo bem.\nNós HIKERS somos\vassim mesmo.",
  ["HikerBaileyBeatenText"] = "Piedade! Você me\nmostrou a força!",
  ["HikerBenjaminAfterBattleText"] = "Perder parece\npouca coisa se\fvocê olha para o\ncéu enorme!",
  ["HikerBenjaminSeenText"] = "Ah, que bom estar\nao ar livre!\vMe sinto livre!",
  ["HikerDanielAfterBattleText"] = "Fui enganado e\ncomprei uma\vSLOWPOKETAIL.\fTenho pena do\npobre POKéMON.",
  ["HikerDanielBeatenText"] = "Uau! Fui derrotado\nfeio!",
  ["HikerDanielSeenText"] = "Uau! Que\nsurpresa!\fNão esperava ver\nninguém aqui!",
  ["HikerErikAfterBattleText"] = "Vou voltar para o\nICE PATH de\fBLACKTHORN e\ntreinar mais.",
  ["HikerJimAfterBattleText"] = "A alergia está me\nfazendo espirrar!\vAtchiiim!",
  ["HikerKennyAfterBattleText"] = "O relevo parece\nque não muda\vnunca.\fMas ele muda sim,\naos pouquinhos,\vcom o tempo.",
  ["HikerKennySeenText"] = "Eu devia ir ao\nROCK TUNNEL pegar\vum ONIX.",
  ["HikerLeonardAfterBattleText"] = "Eu moro aqui.\fVocê também pode,\nse quiser.\fTem espaço de\nsobra, sabe.",
  ["HikerLeonardBeatenText"] = "Uahahah! Você é\ndanado!",
  ["HikerLeonardSeenText"] = "Veja só!\nUma visita!",
  ["HikerMichaelAfterBattleText"] = "Nossa, como eu\namo PS UP! Hmmm!\fFico bebendo o\ndos meus POKéMON!\fNão me controlo!",
  ["HikerMichaelBeatenText"] = "Meus POKéMON não\ntiveram garra!",
  ["HikerMichaelSeenText"] = "Ei! Você tem\ngarra! Mas sabe?\fQuando o assunto é\ngarra pura, o cara\vsou eu!",
  ["HikerNolandAfterBattleText"] = "Será que tem\nalguma montanha\fboa para escalar\nem KANTO?",
  ["HikerNolandBeatenText"] = "Isso é demais\npara mim!",
  ["HikerNolandSeenText"] = "Está sozinho?\nEntão vamos lutar",
  ["HikerParry3BeatenText"] = "Uahahah! Eu sou o\ngrande perdedor!",
  ["HikerParry3SeenText"] = "Meus POKéMON são\npura força!",
  ["HikerParryAfterBattleText"] = "Eu não sou bom de\npensar, sabe?\fEntão eu vou de\nforça mesmo!",
  ["HikerPhillipAfterBattleText"] = "Estou perdido faz\nmuito tempo…\fNão me importo de\nficar aqui, mas\vque fome!",
  ["HikerRussellAfterBattleText"] = "Muito bem, então!\nEu decidi.\fNão vou sair daqui\naté meus POKéMON\vficarem fortes!",
  ["HikerSidneyAfterBattleText"] = "A POWER PLANT fica\ndo outro lado de\vum riacho.",
  ["HikerSidneyBeatenText"] = "Ah, droga!\nPerdi essa…",
  ["HikerSidneySeenText"] = "Vou te contar um\nsegredo.\fMas primeiro a\ngente luta!",
  ["HikerTimAfterBattleText"] = "Batalha é uma\nquestão de foco.",
  ["HikerTimBeatenText"] = "Eu estava ocupada\ncantando…",
  ["HikerTimSeenText"] = "Ela vem descendo a\nMT.SILVER quando\vela vier…\fA MT.SILVER fica\nem JOHTO, né?",
  ["HikerTimothyAfterBattleText"] = "A melhor coisa que\njá me\faconteceu foi\nconhecer POKéMON.",
  ["HikerTimothyBeatenText"] = "Derrotas…\nTambém estão lá!",
  ["HikerTimothySeenText"] = "Por que eu subo\nmontanhas?\fPorque elas estão\nlá.\fPor que eu treino\nPOKéMON?\fPorque eles estão\nlá!",
  ["HomepageText"] = "POKéMON JOURNAL\nPÁGINA INICIAL…\fNão foi\natualizada…",
  ["HouseForSaleSignText"] = "O que é isto?\fCasa à venda…\nNinguém mora aí.",
  ["HurryUpElmIsWaitingText"] = "O PROF.ELM está\nesperando você.\fVá logo, querido!",
  ["IcePathB2FMahoganySideBoulderText"] = "Está cravado\nno gelo.",
  ["IlexForestApprenticeAfterText"] = "Nossa! Muito\nobrigado mesmo!\fO POKéMON do meu\nchefe não me\vobedece porque eu\vnão tenho BADGE.",
  ["IlexForestApprenticeIntroText"] = "Ah, cara… Meu\nchefe vai ficar\vfurioso…\fO FARFETCH'D que\nusa CUT nas\fárvores para o\ncarvão fugiu.\fNão dá para eu\nprocurar ele aqui\vna ILEX FOREST.\fÉ grande, escura\ne assustadora…",
  ["IlexForestAzaleaGateGrannyText"] = "A FLORESTA é\ncuidada pelo\vseu protetor.\fNada de\ntraquinagens!",
  ["IlexForestAzaleaGateOfficerText"] = "A ILEX FOREST\né grande. Cuidado!\vNão se perca.",
  ["IlexForestSignpostText"] = "A ILEX FOREST tem\ntanta árvore que\fnão dá para ver\no céu.\fFique de olho em\nitens que possam\vter caído por aí.",
  ["ImBehindYouText"] = "{PLAYER}, vá!\fEstou com você\naté o fim!",
  ["IncenseBurnerText"] = "O que é isto?\fAh, é um\nincensário!",
  ["IndigoPlateauPokecenter1FCooltrainerMText"] = "Na POKéMON LEAGUE\nvocê vai ser\ftestado pelos\nELITE FOUR.\fTem que vencer\ntodos eles. Se\fperder, começa\ntudo de novo!",
  ["IndigoPlateauSignText"] = "INDIGO PLATEAU\fO Objetivo Final\ndos Treinadores!\fLIGA POKéMON HQ",
  ["InsertedTheCardKeyText"] = "{PLAYER} inseriu\na CHAVE-CARTAO.",
  ["InstructionsNextText"] = "Os números ficam\nsalvos na memória\fÉ só escolher o\nnome para ligar.\fQue prático,\nnão é mesmo?",
  ["IrwinRocketTakeoverRumorText"] = "{PLAYER}, você\nsabia?\fOuvi dizer que\nRADIO TOWER foi\ftomada pela TEAM\nROCKET.\fMas o que é\na TEAM ROCKET?",
  ["IsItDSTText"] = "Estamos no horário\nde verão agora?",
  ["ItemfinderExplanationText"] = "Há muitos itens\nespalhados por aí\fE que não são\nóbvios.\fUse o ITEMFINDER\npra checar se há\fum item no chão\nperto de você.\fEle não mostra o\nlugar exato,\fentão vai ter que\nprocurar.\fAh! Ouvi dizer que\nhá itens\fna BURNED TOWER\nde ECRUTEAK.",
  ["JanineText_ApplyMyself"] = "JANINE: Eu vou\nme dedicar mesmo\fe melhorar as\nminhas técnicas.\fQuero ficar melhor\nque o meu pai\ve que você!",
  ["JanineText_DisappointYou"] = "Fufufufu…\fSinto muito\ndesapontar você…\fÉ só brincadeira!\fEu sou a real!\fJANINE, do GINÁSIO\nde FUCHSIA!",
  ["JanineText_ToughOne"] = "JANINE: Você é\ndurão. Venceu\vcom certeza…\fAqui, a SOULBADGE.\nPegue.",
  ["JanineText_ToxicSpeech"] = "JANINE: Você é\nmuito forte! Tenho\vum presente!\fÉ TOXIC, um veneno\npoderoso que\fvai comendo os PS\nda vítima.",
  ["JasmineAmphyHangOnText"] = "…AMPHY, aguenta!",
  ["JasmineAmphyHowAreYouFeelingText"] = "JASMINE: …\fAMPHY, como você\nse sente?",
  ["JasmineCianwoodPharmacyText"] = "JASMINE: … Este\nPOKéMON sempre\fmanteve o mar\naceso à noite.\f…Mas ele\nadoeceu… Está\vofegando…\f…Sei que há\numa ótima\fPHARMACY em\nCIANWOOD…\fMas isso fica\nalém do mar…\fE não posso\ndeixar o AMPHY…",
  ["JasmineCureAmphyText"] = "JASMINE: …Este\nremédio curará\vo AMPHY?",
  ["JasmineDontBeOffendedText"] = "JASMINE: …Hum,\nnão se ofenda,\vpor favor…\f…AMPHY não\naceitará nada\vde mais ninguém…",
  ["JasmineGetSomeMedicineText"] = "…Pode buscar\num remédio para\vmim? Por favor?",
  ["JasmineISeeText"] = "JASMINE: …Vejo…",
  ["JasmineThankYouText"] = "JASMINE: …Oh,\nque alívio…\fÉ tão\nmaravilhoso…\fMuito, muito\nobrigada.\f…Voltarei\nao GYM…",
  ["JugglerFritzAfterBattleText"] = "Chega de navio\npara mim. Da\fpróxima vez eu vou\nde MAGNET TRAIN.",
  ["JugglerFritzBeatenText"] = "Não consigo mais\nme mexer…",
  ["JugglerFritzSeenText"] = "Urrf…\nEstou enjoado!",
  ["JugglerHortonAfterBattleText"] = "Nada de se achar\npor me vencer.\fLT.SURGE é muito\ndurão.",
  ["JugglerHortonBeatenText"] = "Gwaaah!\nFui superado…",
  ["JugglerHortonSeenText"] = "Vou te derrubar!\nPrepare-se para\vlevar um choque!",
  ["JugglerIrwin1BeatenText"] = "Ufa! Que choque\nfoi esse!",
  ["JugglerIrwin1SeenText"] = "Veja como eu sou\nbom com a BALL!",
  ["JugglerIrwinAfterBattleText"] = "Eu ia deslumbrar\nvocê com o meu\vPOKéMON premiado.\fMas a sua força\nme eletrizou!",
  ["KantoRadioStationSignText"] = "RÁDIO KANTO\nSTATION\fSeus Programas\nFavoritos no Ar\v24 Horas!",
  ["KarenScript_KarenBeatenText"] = "Bom, você é bom\nmesmo. Gosto disso\vnum treinador.",
  ["KarenScript_KarenBeforeText"] = "Eu sou KAREN, dos\nELITE FOUR.\fVocê é {PLAYER}?\nQue divertido.\fEu amo POKéMON\ndo tipo sombrio.\fAcho a imagem\nselvagem e dura\fdeles atraente. E\neles são fortes.\fAcha que dá conta\ndeles? Só tente\vme entreter.\fVamos lá.",
  ["KarenScript_KarenDefeatText"] = "POKéMON forte.\fPOKéMON fraco.\fIsso é só a\npercepção egoísta\vdas pessoas.\fTreinador de\nverdade tenta\fvencer com os\nseus favoritos.\fGosto do seu\nestilo. Você\ventende.\fVá em frente, o\nCAMPEÃO espera.",
  ["KimonoGirlKuniAfterBattleText"] = "Treinei muito e\nme achava capaz\fde batalhar. Mas\nacho que não.",
  ["KimonoGirlKuniBeatenText"] = "Você é mais forte\ndo que aparenta.",
  ["KimonoGirlKuniSeenText"] = "Oh, você é um\ntreinador fofo.\vQuer batalhar?",
  ["KimonoGirlMikiAfterBattleText"] = "Continuo dançando\nporque há gente\fque gosta do\nque eu faço.\fMeus POKéMON\nme animam.",
  ["KimonoGirlMikiBeatenText"] = "Ooh, você também\né bom em POKéMON.",
  ["KimonoGirlMikiSeenText"] = "Gosta da minha\ndança? Também sou\vboa com POKéMON.",
  ["KimonoGirlNaokoAfterBattleText"] = "Eu gostei do\nduelo. Queria\vte ver de novo.",
  ["KimonoGirlNaokoBeatenText"] = "Oh, você é muito\nforte.",
  ["KimonoGirlSayoAfterBattleText"] = "O ritmo é\nimportante para\fdançar e para\nPOKéMON.",
  ["KimonoGirlSayoBeatenText"] = "Oh, tão perto!\nQuase te peguei!",
  ["KimonoGirlSayoSeenText"] = "Eu sempre danço\ncom meus POKéMON.\fClaro, eu também\nos treino.",
  ["KimonoGirlZukiAfterBattleText"] = "Coloco uma flor\ndiferente no\vgrampo todo mês.",
  ["KimonoGirlZukiBeatenText"] = "Não tenho mais\nPOKéMON…",
  ["KimonoGirlZukiSeenText"] = "Minha presilha é\nbonita, não?\fOh. Uma batalha\nde POKéMON?",
  ["KnowTheInstructionsText"] = "Não é só ligar a\nPOKéGEAR e\fescolher o ícone\ndo TELEFONE?",
  ["KogaScript_KogaBeatenText"] = "Ah!\nVocê provou o seu\vvalor!",
  ["KogaScript_KogaBeforeText"] = "Fuahahahaha!\fEu sou KOGA, dos\nELITE FOUR.\fEu vivo nas\nsombras, ninja!\fMeu estilo é\nintrincado e vai\vdestruir você!\fConfusão, sono,\nveneno…\fPrepare-se para\nser vítima da\vminha técnica!\fFuahahahaha!\fPOKéMON não é só\nforça bruta,\fvocê vai ver isso\nlogo, logo!",
  ["KogaScript_KogaDefeatText"] = "Eu joguei em você\ntudo o que eu\vconsegui reunir.\fMas meu esforço\nfalhou. Preciso\vafiar minha arte.\fVá para a próxima\nsala e ponha suas\vforças à prova!",
  ["KurtLeaveSlowpokeWellText"] = "KURT: Muito bem,\n{PLAYER}!\fA TEAM ROCKET\nfoi embora.\fMinhas costas\nmelhoraram. Vamos\vsair daqui.",
  ["KurtsGranddaughterDadText"] = "Meu pai trabalha\nna SILPH, onde ele\vestuda POKé BALL.\fEu fico em casa\ncom o vovô e o\vSLOWPOKE.",
  ["KurtsGranddaughterLonelyText"] = "O vovô saiu…\nQue solidão…",
  ["KurtsGranddaughterSlowpokeBackText"] = "O SLOWPOKE que meu\npai deu voltou!\fA TAIL dele está\ncrescendo!",
  ["KurtsGranddaughterSlowpokeGoneText"] = "Os SLOWPOKE se\nforam… Será que\fgente ruim levou\neles?",
  ["KurtsHouseCelebiStatueText"] = "É uma estátua do\nprotetor da\vfloresta.",
  ["KurtsHouseKurtAhHaISeeText"] = "Ah-rá! Entendi!\nEntão…",
  ["KurtsHouseKurtAskYouHaveAnApricornText"] = "KURT: Tem um\nAPRICORN para mim\fÓtimo! Vou virar\nele numa BALL.",
  ["KurtsHouseKurtBallsFromApricornsText"] = "KURT: Eu faço\nBALLS de APRICORN\fColha eles das\nárvores e traga\vaqui.\fEu faço BALLS\ncom eles.",
  ["KurtsHouseKurtDontBotherMeText"] = "KURT: Trabalhando!\nNão me amole!",
  ["KurtsHouseKurtGranddaughterHelpingWorkFasterText"] = "KURT: Agora que\nminha neta está\fme ajudando, eu\ntrabalho bem mais\vrápido.",
  ["KurtsHouseKurtHonoredToMakeBallsText"] = "KURT: {PLAYER}!\fVocê se saiu\ncomo um herói\vno POÇO.\fGostei do estilo!\fSeria uma honra\nfazer BALLS\fpara um treinador\ncomo você.\fÉ tudo que tenho\nagora, mas leve.",
  ["KurtsHouseKurtImCheckingItNowText"] = "Estou checando\nagora.",
  ["KurtsHouseKurtItWillTakeADayText"] = "KURT: Vai levar um\ndia para a BALL.\fVolte depois\npara pegar.",
  ["KurtsHouseKurtJustFinishedYourBallText"] = "KURT: Ah, {PLAYER}!\nAcabei de terminar\vsua BALL. Tome!",
  ["KurtsHouseKurtMakingBallsMustWaitText"] = "Hm? Quem é você?\f{PLAYER}, é? Quer\nque eu faça umas\vBALLS?\fDesculpe, mas isso\nvai esperar.\fConhece a TEAM\nROCKET? Ah, não\fimporta. Eu conto\nde qualquer forma\fA TEAM ROCKET é\numa gangue má que\fusa POKéMON para\no trabalho sujo.\fEra para eles\nterem se desfeito\vhá três anos.\fEnfim, estão no\nPOÇO, cortando\fSLOWPOKETAILS para\nvender!\fEntão eu vou lá\ndar uma lição\vdolorosa neles!\fAguente firme,\nSLOWPOKE! O velho\vKURT está indo!",
  ["KurtsHouseKurtThatsALetdownText"] = "KURT: Ah…\nQue decepção.",
  ["KurtsHouseKurtThisBallStartedToShakeText"] = "{PLAYER}!\fEssa BALL começou\na tremer enquanto\veu checava.\fDeve ter algo\nnela!",
  ["KurtsHouseKurtTurnedOutGreatText"] = "KURT: Ficou muito\nboa.\fTente pegar\nPOKéMON com ela.",
  ["KurtsHouseKurtWhatIsThatText"] = "O-o que é isso?\fNunca vi uma\ndessas antes.\fParece muito com\numa POKé BALL,\fmas parece ser\noutra coisa.\fDeixa eu checar\npra você.",
  ["KurtsHouseOakPhotoText"] = "…Um PROF.OAK\njovem?",
  ["KurtsHouseSignText"] = "CASA DO KURT",
  ["KurtsHouseSlowpokeText"] = "SLOWPOKE: …\nBocejo?",
  ["LabWhereGoingText"] = "ELM: Espere! Aonde\nvocê vai?",
  ["LakeOfRageCooltrainerFText"] = "Meus olhos me\nenganaram? Eu vi\fum GYARADOS\nvermelho no LAKE…\fMas eu achava que\nGYARADOS eram\vazuis, não?",
  ["LakeOfRageGotRedScaleText"] = "{PLAYER} conseguiu\numa RED SCALE.",
  ["LakeOfRageGrampsText"] = "Os GYARADOS estão\nfuriosos!\fÉ mau agouro!",
  ["LakeOfRageGrampsText_ClearedRocketHideout"] = "Hahah! Os MAGIKARP\nestão mordendo!",
  ["LakeOfRageGyaradosCryText"] = "GYARADOS: Gyasha!",
  ["LakeOfRageLanceAskHelpText"] = "LANCE: Hm? Você\nvai me ajudar?",
  ["LakeOfRageLanceForcedToEvolveText"] = "Este lago está\ncheio de GYARADOS\ve mais nada…\fEntão os MAGIKARP\nestão sendo\vforçados a\vevoluir…",
  ["LakeOfRageLanceIntroText"] = "Você veio aqui\npor causa dos\vboatos?\fVocê é {PLAYER}?\nSou LANCE, um\vtreinador igual.\fOuvi uns boatos\ne vim aqui para\vinvestigar…\fVi o jeito que\nvocê batalhou,\v{PLAYER}.\fDá para ver que\nvocê é treinador\fde bastante\nhabilidade.\fSe não se importa,\nquer me ajudar a\vinvestigar?",
  ["LakeOfRageLanceRadioSignalText"] = "LANCE: Excelente!\fParece que estão\nforçando os\fMAGIKARP do LAKE\na evoluir.\fUma transmissão de\nrádio misteriosa\fvinda de MAHOGANY\né a causa.\fEspero por você,\n{PLAYER}.",
  ["LakeOfRageLanceRefusedText"] = "Ah… Bem, se você\nmudar de ideia,\vme ajude.",
  ["LakeOfRageMagikarpHouseUnusedRecordText"] = "RECORDE ATUAL\f{RAM:D099}\npego por\v{RAM:D0AC}",
  ["LakeOfRageSignText"] = "LAKE OF RAGE,\ntambém chamado de\vGYARADOS LAKE.",
  ["LakeOfRageSuperNerdText"] = "Ouvi que este lago\nfoi feito por\vGYARADOS em fúria\fSerá que tem\nalguma ligação\fcom esse surto\ntodo de agora?",
  ["LanceBattleAfterText"] = "…Ufa.\fVocê ficou mesmo\npoderoso,\v{PLAYER}.\fSeus POKéMON\nresponderam ao\fjeito forte e\níntegro.\fComo treinador,\nvocê vai crescer\fjunto com os seus\nPOKéMON.",
  ["LanceBattleIntroText"] = "LANCE: Eu estava\nesperando você.\f{PLAYER}!\fEu sabia que você,\ncom seu talento,\fia acabar\nchegando até mim.\fNão é hora de\npalavras agora.\fVamos batalhar\npara decidir quem\fé o mais forte\nde nós dois.\fComo o treinador\nmais poderoso e\fcomo CAMPEÃO da\nPOKéMON LEAGUE…\fEu, LANCE, mestre\ndos dragões,\vaceito o desafio!",
  ["LanceBattleWinText"] = "…Acabou.\fMas é uma sensação\nestranha.\fNão estou bravo\npor ter perdido.\vEstou feliz.\fFeliz por ter\nvisto nascer\fum grande novo\nCAMPEÃO!",
  ["LanceGetPasswordText"] = "LANCE: Precisa de\nduas senhas para\fentrar na sala\ndo chefe.\fSó uns poucos\nROCKETS conhecem\vessas senhas.\fAquele ROCKET ali\nteve a bondade\vde me contar.\f{PLAYER}, vamos\nbuscar as senhas.",
  ["LanceHealsText1"] = "LANCE: Você está\nbem?\fSeus POKéMON estão\nmachucados.\fTome, dê um pouco\ndo meu remédio\vpara eles.",
  ["LanceHealsText2"] = "LANCE: {PLAYER},\nvamos dar o nosso\vmelhor por eles.",
  ["LancesRoomMaryInterviewText"] = "MARY: Vamos\nentrevistar o novo\vCAMPEÃO!",
  ["LancesRoomMaryNoInterviewText"] = "MARY: Ah, espere!\nA gente não fez\va entrevista!",
  ["LancesRoomMaryOhNoOakText"] = "MARY: Ah, não!\nAcabou tudo!\fPROF.OAK, se você\nnão demorasse…",
  ["LancesRoomNoisyText"] = "LANCE: Isto está\nficando barulhento\vdemais…\f{PLAYER}, pode\nvir comigo?",
  ["LancesRoomOakCongratulationsText"] = "PROF.OAK: Ah,\n{PLAYER}!\fFaz muito tempo\nque não te vejo.\fVocê está mesmo\nmais maduro.\fA sua conquista\nda LEAGUE é\vfantástica!\fSua dedicação,\nconfiança e amor\fpelos seus POKéMON\nfizeram isso.\fSeus POKéMON foram\nnotáveis também.\fPorque acreditaram\nem você como\ftreinador, eles\nperseveraram.\fParabéns,\n{PLAYER}!",
  ["LassAliceAfterText"] = "Como você vai\ndescobrir quem é\va LÍDER real?",
  ["LassAliceBeatenText"] = "Eu te enganei…",
  ["LassAliceBeforeText"] = "Fufufu!\fEu sou a JANINE,\na LÍDER!\fNão, não sou!\nCaiu, otário!",
  ["LassBridgetAfterBattleText"] = "Tento vencer a\nWHITNEY, mas… É\vdeprimente.\fEstou bem! Se eu\nperder, tentarei\fde novo da próxima\nvez!",
  ["LassBridgetSeenText"] = "Gosto mais de POKé\nMON fofos do que\vdos fortes.\fMas tenho POKéMON\nfortes e fofos!",
  ["LassCarrieAfterBattleText"] = "No mundo dos\nPOKéMON, será que\fé mais forte:\nmacho ou fêmea?",
  ["LassCarrieBeatenText"] = "Droga… Pensei que\nvocê fosse fraco…",
  ["LassCarrieSeenText"] = "Não pense que sou\nfácil de vencer!",
  ["LassConnie1AfterBattleText"] = "Certo. Qualquer um\nficaria preocupado\vse o POKéMON dele\vestivesse ferido.\fVou rezar pelo\nPOKéMON daqui,\fpara a JASMINE\nvoltar ao GINÁSIO",
  ["LassConnie1BeatenText"] = "Aaai! POKéMON!",
  ["LassConnie1SeenText"] = "A JASMINE é a\nLÍDER daqui.\fPretendo trazer\nela de volta.\fÉ melhor ninguém\natrapalhar!",
  ["LassDana1BeatenText"] = "Entendi. Então dá\npara lutar assim.",
  ["LassDana1SeenText"] = "Você é bom em\ntreinar?\fSe for, pode me\nmostrar como?",
  ["LassDanaMoomooMilkText"] = "Eu sei de uma\nboa!\fO leite da MOOMOO\nFARM é famoso pelo\vsabor.",
  ["LassEllenAfterBattleText"] = "Dei o meu melhor.\nNada a lamentar.",
  ["LassEllenBeatenText"] = "Como eu perdi?",
  ["LassEllenSeenText"] = "Sou o segundo.\nAgora é sério!",
  ["LassKriseAfterBattleText"] = "Pelo seu olhar,\npensei que você\vgostava de mim.\fAfinal, eu sou\nfofa!",
  ["LassKriseSeenText"] = "Olá? Por que você\nfica me olhando?\fAh, uma batalha?",
  ["LassLauraAfterBattleText"] = "Dei o meu melhor.\nNada a lamentar.",
  ["LassLauraSeenText"] = "Eu sou o Nº 4!\nJá está cansado?",
  ["LassLindaBeatenText"] = "Ooh… Eu perdi…\nVocê não é fraco…",
  ["LassLindaBeforeText"] = "Te enganei!\nHahaha!",
  ["LassMichelleAfterBattleText"] = "Nós não temos\nnada contra os\fmeninos. Só há\nassuntos que só\fgarotas podem\nconversar.",
  ["LassMichelleSeenText"] = "Espere! Aqui só\nentram garotas!",
  ["LassShannonAfterBattleText"] = "Dei o meu melhor.\nNada a lamentar.",
  ["LassShannonBeatenText"] = "Só pode ser piada",
  ["LassShannonSeenText"] = "Sou o último da\nfila, mas eu digo:\vsou durão!",
  ["LavRadioTower1FDirectoryText"] = "1F RECEPÇÃO\n2F VENDAS\v3F PESSOAL\v4F PRODUÇÃO\v5F SALA DO\v   DIRETOR",
  ["LavRadioTower1FGentlemanText"] = "Ah, não, não!\fA gente está fora\ndo ar desde que a\fPOWER PLANT\nparou.\fTodo o esforço de\nabrir esta rádio\fvira pó se eu\nnão for ao ar.\fEstou arruinado!",
  ["LavRadioTower1FGentlemanText_GotExpnCard"] = "Com essa coisa,\nvocê pega\fos programas de\nrádio de KANTO.\fGahahahaha!",
  ["LavRadioTower1FGentlemanText_ReturnedMachinePart"] = "Ah! Então você é\no {PLAYER} que\fresolveu o caso\nda POWER PLANT?\fGraças a você, eu\nnão fui demitido.\fSério, você é um\nsalva-vidas!\fPor favor, aceite\nisto de presente.",
  ["LavRadioTower1FOfficerText"] = "Desculpe, mas você\nsó pode visitar\vo térreo.\fDesde que a RADIO\nTOWER de JOHTO\ffoi tomada por uma\ngangue, a gente\fteve que reforçar\na segurança.",
  ["LavRadioTower1FPokeFluteSignText"] = "Anime seus POKéMON\ncom o som suave\fda POKé FLUTE\nno CANAL 20",
  ["LavRadioTower1FReceptionistText"] = "Bem-vindo!\nFique à vontade\fpara olhar tudo\nneste andar.",
  ["LavRadioTower1FReferenceLibraryText"] = "Nossa! Uma\nprateleira cheia\vde CDs e vídeos\vde POKéMON.\fDeve ser a\nbiblioteca de\vreferência.",
  ["LavRadioTower1FSuperNerd1Text"] = "Muita gente aqui\ntrabalha duro\fna RADIO\nTOWER.\fDevem estar dando\no melhor para\vbons programas.",
  ["LavRadioTower1FSuperNerd2Text"] = "Olá, camarada!\fEu sou o super\nMUSIC DIRECTOR!\fHã? Seu POKéGEAR\nnão pega os meus\fprogramas.\nQue azar!\fSe pegar o EXPN\nCARD, você\fconsegue ouvir.\nVá atrás de um!",
  ["LavRadioTower1FSuperNerd2Text_GotExpnCard"] = "Olá, camarada!\fEu sou o super\nMUSIC DIRECTOR!\fSou responsável\npelas melodias\flindas que vão\npara o ar.\fNão seja quadrado.\nPegue a sua música\vno ar!",
  ["LavenderMartPokefanMText"] = "REPEL é coisa\nnecessária se\fvai explorar uma\ncaverna.\fMesmo gostando de\nexplorar, ainda\fnão fui a todas\nas cavernas.",
  ["LavenderMartRockerText"] = "Ouvi falar de um\nartesão que\ffaz POKé BALLS sob\nmedida na cidade\fde AZALEA, em\nJOHTO. Eu queria.",
  ["LavenderMartSignText"] = "Que prédio e\ntanto, não é?\fÉ a RADIO TOWER\nde KANTO.",
  ["LavenderPokecenter1FGentlemanText"] = "Ao norte de\nLAVENDER fica o\fROCK TUNNEL. Vá\npor ele até a\vPOWER PLANT.",
  ["LavenderPokecenter1FTeacherText"] = "Tem um programa\nde rádio que toca\va POKé FLUTE.\fAh? Seu rádio\nprecisa do EXPN\vCARD para pegar.",
  ["LavenderPokecenter1FYoungsterText"] = "A RADIO STATION\nnão pode ir ao ar\fporque a POWER\nPLANT parou.",
  ["LavenderPokecenter1FYoungsterText_ReturnedMachinePart"] = "O DIRECTOR da\nRADIO STATION\vficou bem feliz.\fEle disse que\nvoltaram ao ar\fporque a POWER\nPLANT está\vrodando de novo.",
  ["LavenderSpeechHousePokefanFText"] = "LAVENDER é uma\nvila pequena e\fquieta, no pé da\nmontanha.\fFicou um pouco\nmais movimentada\fdesde que a RADIO\nTOWER foi feita.",
  ["LavenderTownGrampsText"] = "As pessoas vêm de\nlonge para\fhomenagear as\nalmas dos\vPOKéMON.",
  ["LavenderTownPokefanMText"] = "Que prédio é\nesse, hein?\fÉ a TORRE de\nRÁDIO de KANTO.",
  ["LavenderTownSignText"] = "CIDADE DE LAVENDER\fA Cidade Nobre\nRoxa",
  ["LavenderTownTeacherText"] = "KANTO tem muito\nprograma de rádio",
  ["LavenderTownYoungsterText"] = "Você precisa de\numa POKé FLUTE pra\vacordar\fPOKéMON. Todo\ntreinador sabe\vdisso!",
  ["LeaderBlueAfterText"] = "BLUE: …\fEstá bem, eu\nerrei. Você\fé o cara mesmo.\nÉ bom treinador.\fMas eu vou vencer\nvocê um dia.\fNão vá esquecer\ndisso!",
  ["LeaderBlueBeforeText"] = "BLUE: Ei! Enfim\nchegou aqui, né?\fEu não tava a fim\nem CINNABAR,\fmas agora estou\npronto para você.\f…\fEstá me dizendo\nque venceu JOHTO\vinteira?\fHa! Então os\nGINÁSIOS de JOHTO\vdevem ser fracos.\fEi, não esquenta\ncom isso.\fEu vou saber se\nvocê é bom ou não\fbatalhando com\nvocê agora.\fPronto, garoto?",
  ["LeaderBlueEpilogueText"] = "BLUE: Escuta.\fÉ bom você não\nperder até eu te\vvencer. Entendeu?",
  ["LeaderBlueWinText"] = "BLUE: O quê?\fComo diabos eu\nperdi para você?\f…\fTsc, está bem…\nToma, pegue isto,\va EARTHBADGE.",
  ["LookTownMapText"] = "É o TOWN MAP.",
  ["LtSurgeFightDoneText"] = "SURGE: Ei, garoto!\nAinda dando duro\vpor aí?\fEu e meus POKéMON\ntambém estamos!",
  ["LtSurgeIntroText"] = "SURGE: Ei,\ngarotinho!\fTenho que admitir.\nPode não ser lá\fmuito esperto me\ndesafiar, mas\vtem coragem!\fQuando o assunto é\nPOKéMON elétrico,\vsou o número um!\fNunca perdi no\ncampo de batalha.\fVou fritar você\nigual fritei meus\vinimigos!",
  ["LtSurgeThunderBadgeText"] = "SURGE: A\nTHUNDERBADGE\vaumenta a\vvelocidade.\fConsidere isso a\nprova de que você\fme venceu. Use com\norgulho, ouviu?",
  ["LtSurgeWinLossText"] = "SURGE: Arrrgh!\nVocê é forte!\fCerto. A sua\nTHUNDERBADGE!",
  ["MagazineBookshelfText"] = "Revistas de\nPOKéMON… POKéMON\vPAL,\fPOKéMON HANDBOOK,\nPOKéMON GRAPH…",
  ["MagikarpLengthRaterText_Bonus"] = "O recorde é o que\nimporta.\fConsidere isso\num bônus!",
  ["MagikarpLengthRaterText_LakeOfRageHistory"] = "O LAKE OF RAGE é\nna verdade uma\fcratera feita por\nGYARADOS em fúria\fA cratera encheu\nde água de chuva\fe assim nasceu\no LAKE.\fÉ a história que\nveio do tataravô\fdo tataravô do\nmeu vovô.\fAntigamente dava\npara pescar\fMAGIKARP animados\nali, mas…\fEu não entendo o\nque está havendo.",
  ["MagikarpLengthRaterText_Memento"] = "Uau! Este aqui é\nexcepcional!\fTiro o chapéu\npara você!\fLeve isto de\nlembrança!",
  ["MagikarpLengthRaterText_MenInBlack"] = "O LAKE não está\nnormal desde que\faqueles homens de\npreto chegaram.",
  ["MagikarpLengthRaterText_NotMagikarp"] = "O quê? Isso não é\num MAGIKARP!",
  ["MagikarpLengthRaterText_Refused"] = "Ah… Então você não\npegou um bom\fo bastante?\nFica pra próxima.",
  ["MagikarpLengthRaterText_TooShort"] = "Uau! Este aqui é\nexcepcional!\f…Eu queria poder\ndizer isso, mas\fjá vi um maior\nantes.",
  ["MagikarpLengthRaterText_WorldsLargestMagikarp"] = "O LAKE OF RAGE\nvoltou ao normal.\fOs MAGIKARP\nvoltaram.\fAinda posso ver\nmeu sonho de achar\vo maior MAGIKARP\vdo mundo.\fVocê tem uma ROD?\nSe tiver, por\vfavor me ajude.",
  ["MagikarpLengthRaterText_YouHaveAMagikarp"] = "Ah, você tem um\nMAGIKARP! Vamos\fver o tamanho\ndesse bichinho.",
  ["MahoganyGymGuideText"] = "O PRYCE é veterano\ne treina POKéMON\fhá uns\n50 anos.\fDizem que ele é\nbom em congelar\fadversários com\ngolpes de gelo.\fOu seja, você tem\nque derreter ele\fcom sua ambição\nem chamas!",
  ["MahoganyGymGuideWinText"] = "O PRYCE é bom,\nmas você é de\voutro nível!\fFoi uma batalha\nquente que\funiu duas\ngerações!",
  ["MahoganyGymSignText"] = "CIDADE DE MAHOGANY\nGINÁSIO POKéMON\vLÍDER: PRYCE\fO Mestre da\nDureza do Inverno",
  ["MahoganyMart1FBlackBeltText"] = "Heheh! O\nexperimento\vfuncionou que é\vuma beleza.\fMAGIKARP não valem\nnada, mas\fGYARADOS dão muito\ndinheiro.",
  ["MahoganyMart1FBlackBeltText_LanceEntered"] = "Urrgh…\fOs POKéMON dragão\ndele são fortes…",
  ["MahoganyMart1FLanceDragoniteHyperBeamText"] = "LANCE: DRAGONITE,\nHYPER BEAM.",
  ["MahoganyMart1FLanceRadioText"] = "Por que demorou,\n{PLAYER}?\fComo eu pensei, o\nsinal de rádio\festranho vem\ndaqui.",
  ["MahoganyMart1FLanceSplitUpText"] = "LANCE: {PLAYER},\nvamos nos separar\fpara vasculhar.\nEu vou primeiro.",
  ["MahoganyMart1FLanceStairsText"] = "A escada está\nbem aqui.",
  ["MahoganyMart1FPharmacistText_LanceEntered"] = "Arrgh… Você achou\na escada\vsecreta…",
  ["MahoganyMart1FRageCandyBarText"] = "Olá, garoto(a)!\fQue tal uma\nRAGECANDYBAR?\fÉ o que se come\nem MAHOGANY!",
  ["MahoganyPokecenter1FCooltrainerFText"] = "POKéMON ficam mais\nfortes ao evoluir\fmas aprendem os\ngolpes bem mais\vdevagar.",
  ["MahoganyPokecenter1FPokefanMText"] = "O quê? A TEAM\nROCKET voltou\vde novo?\fVi uns homens de\npreto no LAKE OF\vRAGE…",
  ["MahoganyPokecenter1FYoungsterText"] = "Seguro meu POKéMON\nde evoluir cedo\vdemais.\fFaço aprenderem\ncertos golpes\vantes de deixar\veles evoluírem.",
  ["MahoganyRedGyaradosSpeechHouseBlackBeltText"] = "Ouvi que apareceu\num GYARADOS\vvermelho no LAKE.\fÉ estranho, pois\naté GYARADOS\fcomuns são raros\nnaquele lago…",
  ["MahoganyRedGyaradosSpeechHouseTeacherText"] = "Meu programa de\nrádio favorito? O\vPOKéMON MUSIC.",
  ["MahoganyRedGyaradosSpeechHouseTeacherText_RocketsInRadioTower"] = "Ando ouvindo\nrisadas no\frádio…\nÉ arrepiante.",
  ["MahoganyTownFisherText"] = "Já que veio até\naqui, aproveite\fpara passear um\npouco.\fVá para o norte\ne dê uma olhada\fno LAKE OF RAGE\nagora mesmo.",
  ["MahoganyTownGrampsText"] = "Vai lá ver o\nGYARADOS em fúria\vno LAKE?",
  ["MahoganyTownGrampsText_ClearedRocketHideout"] = "Os MAGIKARP\nvoltaram para o\vLAKE OF RAGE.\fDeve ser uma boa\nnotícia para os\vpescadores de lá.",
  ["MahoganyTownLassText"] = "Visite a loja da\nVovó. Ela vende\fcoisas que mais\nninguém tem.",
  ["MahoganyTownRagecandybarSignText"] = "Em CIDADE DE\vMAHOGANY,\nProve um\vRAGECANDYBAR!",
  ["MahoganyTownSignText"] = "CIDADE DE MAHOGANY\fBem-vindo ao Lar\ndos Ninjas",
  ["ManiaText_AskLookAfterShuckle"] = "Estou em choque!\fUm cara da sua\nidade, de olhar\fduro e cabelo\ncomprido entrou.\fEle me assustou e\nlevou o meu\vPOKéMON precioso!\fAinda tenho um,\nmas e se ele\vvoltar?\fVocê parece forte.\nVocê pode cuidar\fdo meu POKéMON\npor um tempo?",
  ["ManiaText_CanIHaveMyMonBack"] = "Oi! Como está o\nmeu POKéMON?\fAcho que estou\nseguro agora. Pode\vdevolver ele?",
  ["ManiaText_GotShuckle"] = "{PLAYER} recebeu\num POKéMON.",
  ["ManiaText_HappinessSpeech"] = "Para o POKéMON,\nser feliz é estar\fcom uma pessoa que\ntrata ele bem.",
  ["ManiaText_IfHeComesBack"] = "Ai, não… O que eu\nfaço se ele\vvoltar?",
  ["ManiaText_PartyFull"] = "O time de POKéMON\nestá cheio.",
  ["ManiaText_SameAsBeingRobbed"] = "Ah, não, não…\nIsso é a mesma\vcoisa que roubo.",
  ["ManiaText_ShuckleLikesYou"] = "O meu POKéMON\ngostou de você.\fEstá bem, pode\nficar com ele.\fMas prometa ser\nbom com ele!",
  ["ManiaText_ShuckleNotThere"] = "Ei, você não está\ncom o meu\vPOKéMON.",
  ["ManiaText_TakeCareOfShuckle"] = "Ah, obrigado!\fCuide bem dele,\npor favor!",
  ["ManiaText_ThankYou"] = "Obrigado!",
  ["MartNoMoneyText"] = "Você não tem\ndinheiro.",
  ["MartSignText"] = "Tudo Que Seu\nPOKéMON Precisa\fLOJA POKéMON",
  ["MediumDorisAfterBattleText"] = "Droga! Esqueci\nque eu previ que\vperderia para ti",
  ["MediumDorisBeatenText"] = "Mesmo te lendo,\neu perdi…",
  ["MediumDorisSeenText"] = "Fufufufu…\nVejo com clareza.\fEu enxergo\nna sua alma!",
  ["MediumGraceAfterBattleText"] = "Tudo bem. Eu vou\ncontar o segredo\fdo piso\ninvisível.\fO caminho está\nna nossa frente!",
  ["MediumGraceSeenText"] = "Confuso com nosso\npiso invisível?\fVença-me se quiser\numa dica!",
  ["MediumMarthaAfterBattleText"] = "Quem quiser vencer\nmais, vencerá!",
  ["MediumRebeccaAfterBattleText"] = "De onde vem a\nsua força?",
  ["MediumRebeccaBeatenText"] = "Forte…\nForte demais…",
  ["MediumRebeccaSeenText"] = "A força de todos\nque você venceu\vvem para mim!",
  ["MeetArthurText"] = "ARTHUR: Quem e\nvocê?\fSou ARTHUR de\nquinta-feira.",
  ["MeetFriedaText"] = "FRIEDA: Oba!\nÉ sexta-feira!\fSou a FRIEDA de\nsexta!\fPrazer!",
  ["MeetMonicaText"] = "MONICA: Prazer, eu\nsou a MONICA de\fsegunda.",
  ["MeetSantosText"] = "SANTOS: …\fÉ sábado…\fSou SANTOS\ndo sábado…",
  ["MeetSunnyText"] = "SUNNY: Oi!\fEu sou o SUNNY de\nsábado, ou seja,\vhoje é sábado!",
  ["MeetTuscanyText"] = "TUSCANY: Creio eu\nque esta é a\fprimeira vez que\nnos vemos?\fPermita-me que eu\nme apresente.\fSou TUSCANY, de\nterça-feira.",
  ["MeetWesleyText"] = "WESLEY: Olá, como\nvai você?\fJá que hoje é\nquarta-feira,\fsou o WESLEY da\nquarta.",
  ["MerchandiseShelfText"] = "Um monte de\nprodutos de\vPOKéMON!",
  ["MistyFightDoneText"] = "MISTY: Existem\nmuitos treinadores\vfortes em JOHTO?\vComo você, aliás?\fVou viajar\num dia e quero\fbatalhar com\ntreinadores bons.",
  ["MistyIntroText"] = "MISTY: Eu já te\nesperava, praga!\vPode ter muitas\fGYM BADGES de\nJOHTO, mas não\fvai me levar de\nbobeira!\vMeus POKéMON de\fágua são\ndurões!",
  ["MistyWinLossText"] = "MISTY: Você é\nmuito bom…\fAdmito que você\né habilidoso…\fToma. É a\nCASCADEBADGE.",
  ["MobileBattleRoom_EstablishingCommsText"] = "Estabelecendo\ncomunicação…",
  ["MobileBattleRoom_HealText"] = "Seus POKéMON\nserão totalmente\vcurados antes\vda batalha.",
  ["MobileTradeRoom_EstablishingCommsText"] = "Estabelecendo\ncomunicação…",
  ["MomDeterminedText"] = "Isso parece bem\ndifícil.\fMas, {PLAYER}, eu\nsei que você é\fdeterminado. Vai\nficar bem, né?",
  ["MomGivesPokegearText"] = "POKéMON GEAR, ou\nsó POKéGEAR.\fÉ essencial se\nvocê quer ser um\vbom treinador.\fAh, falta ajustar\no dia da semana.\fNão pode esquecer\ndisso!",
  ["MomImportantToSaveText"] = "É importante\nguardar dinheiro.",
  ["MomOKIllSaveText"] = "Certo. Eu guardo\nseu dinheiro.",
  ["MomPhoneGreetingText"] = "Alô?\fAh, oi, {PLAYER}!\nTrabalhando duro?",
  ["MomPhoneHangUpText"] = "{PLAYER}, continue\nassim! Estou\vtorcendo, filho!",
  ["MomPhoneLectureText"] = "Alô?\f…… {PLAYER}?\nO PROF.ELM me\fdisse que você foi\nnuma viagem longa\fQueria que tivesse\nme contado…\fE o dinheiro?\nEu guardo?",
  ["MomPhoneNoGymQuestText"] = "Alô?\fOi, {PLAYER}! Se\njá terminou o\fseu recado, volte\npara casa, filho.",
  ["MomPhoneNoPokedexText"] = "Alô?\fAh, oi, {PLAYER}!\nVocê está numa\fmissão do PROF.\nELM? Se comporte!",
  ["MomPhoneNoPokemonText"] = "Alô?\fAh, oi, {PLAYER}!\nO PROF.ELM não\vestava esperando?",
  ["MomYoureNotSavingText"] = "Ah, {PLAYER},\nvocê não está\fguardando nada.\nQuer guardar?",
  ["MonicaGaveGiftText"] = "MONICA: É um\nitem que aumenta\fo poder de golpes\nde voar.\fEquipe um POKéMON\npássaro com\vesse item.",
  ["MonicaGivesGiftText"] = "Em sinal de\namizade, um\vpre-sente pra\vvocê!",
  ["MonicaMondayText"] = "MONICA: Meus\nirmãos e irmãs\festão espalhados\npor aí.\fTente encontrá-los\ntodos!",
  ["MonicaNotMondayText"] = "MONICA: Acho que\nhoje não é\vsegunda. Triste…",
  ["MoomooFarmSignText"] = "MOOMOO FARM\fProve Nosso Leite\nFresco e Saboroso",
  ["MortyFightDoneText"] = "Entendo…\fSua jornada levou\nvocê a lugares\vbem distantes.\fE você testemunhou\nmuito mais coisas\vdo que eu.\fEu invejo você\npor isso…",
  ["MortyIntroText"] = "Que bom que você\nveio.\fAqui em ECRUTEAK,\nos POKéMON sempre\vforam venerados.\fDizem que POKéMON\nlendários surgem\fpara os\ntreinadores\vrealmente\vpoderosos.\fEu acreditei\nnisso, e por isso\ftreinei aqui em\nsegredo sempre.\fCom isso, hoje eu\nvejo o que outros\vnão veem.\fSó mais um pouco…\fCom um pouco mais,\neu poderia ver\fum futuro em que\neu encontro o\vPOKéMON lendário.\fVocê vai me ajudar\na chegar nesse\vnível!",
  ["MortyText_FogBadgeSpeech"] = "Com a FOGBADGE,\nPOKéMON até o L50\fvão obedecer\nvocê.\fPOKéMON que sabem\nSURF também podem\fusar o golpe a\nqualquer hora.\fQuero que fique\ncom isto também.",
  ["MortyText_ShadowBallSpeech"] = "É o SHADOW BALL.\nCausa dano e pode\freduzir a\nSPCL.DEF.\fUse se ele te\nagradar.",
  ["MortyWinLossText"] = "Ainda não sou bom\no bastante…\fTudo bem. Esta\nBADGE é sua.",
  ["MountMoonGiftShopLassText"] = "Quando o sol se\npõe, os CLEFAIRY\vvêm brincar.",
  ["MountMoonRivalTextAfter"] = "…… …… ……\f…Você venceu, de\nforma justa.\fAdmito. Mas isto\nnão é o fim.\fVou me tornar o\nmaior treinador de\vPOKéMON.\fPorque esses caras\nestão comigo.\f…Escute, {PLAYER}.\fUm dia desses, vou\nprovar\fo quanto sou bom\nderrotando você.",
  ["MountMoonRivalTextBefore"] = "…… …… ……\fFaz tempo, hein,\n{PLAYER}.\f…Desde que perdi\npra você, pensei\fno que faltava\naos meus\vPOKéMON…\fE chegamos a\numa resposta.\f{PLAYER}, agora\nvamos te mostrar!",
  ["MountMoonRivalTextLoss"] = "…… …… ……\fQuitei minha\ndívida com você.\fCom meus POKéMON,\nvou derrotar o\fCAMPEÃO e me\ntornar o melhor\vdo mundo.",
  ["MountMoonRivalTextWin"] = "…… …… ……\fPensei que meus\nPOKéMON eram\fos melhores que\npodiam ser…\f…Mas ainda\nnão bastou…",
  ["MountMortarB1FKiyoFullPartyText"] = "Você não tem\nespaço no time!",
  ["MountMortarB1FKiyoGotTyrogueText"] = "TYROGUE é do\ntipo lutador.\fEle evolui e\nfica mais forte.\fContinue firme\nno treino. Eu\vtambém sigo.\fAdeus!",
  ["MountMortarB1FKiyoIntroText"] = "Ei!\fEu sou o KARATE\nKING!\fTreino sozinho\naqui no escuro!\fVocê!\nBatalhe comigo!\fHwaaarggh!",
  ["MountMortarB1FKiyoWinText"] = "Waaaarggh!\nFui derrotado!",
  ["MountMortarB1FReceiveMonText"] = "{PLAYER} recebeu\nTYROGUE.",
  ["MountMortarB1FTyrogueRewardText"] = "Estou arrasado…\fMeu treino\nainda não bastou.\fMas derrota é\nderrota. Admito.\fComo prova de\nque você venceu,\fvou lhe dar um\nPOKéMON lutador.",
  ["MoveDeletersHouseSignText"] = "CASA DO\nAPAGADOR GOLPES",
  ["MrFujiText"] = "MR.FUJI: Olá.\fHum… Parece que\nvocê cria os seus\fPOKéMON com amor\ne bondade.\fQuem ama POKéMON\nvem aqui prestar\frespeito aos que\njá se foram.\fDeixe as suas\ncondolências\fpara as almas dos\nPOKéMON que foram\fTenho certeza que\nisso os alegra.",
  ["MrFujisHouseLassText"] = "Tem gente de\ncoração frio que\vlarga o POKéMON.\fO vô acolhe os\ncoitados sem lar\fe cuida deles com\ncarinho.",
  ["MrFujisHouseSuperNerdText"] = "O MR.FUJI mora\naqui, mas não\festá em casa.\fEle deve estar na\nSOUL HOUSE.",
  ["MrPokemonIntroText1"] = "Olá, olá! Você\ndeve ser {PLAYER}.\fO PROF.ELM disse\nque você viria.",
  ["MrPokemonIntroText2"] = "Isto é o que eu\nquero que o\vPROF.ELM examine.",
  ["MrPokemonIntroText3"] = "Conheço um casal\nque cuida de um\vDAY-CARE.\fForam eles que me\nderam esse EGG.\fFiquei intrigado,\nentão mandei uma\vcarta ao ELM.\fEm evolução de\nPOKéMON, o ELM\vé a autoridade.",
  ["MrPokemonIntroText4"] = "Até o PROF.OAK\naqui reconhece.",
  ["MrPokemonIntroText5"] = "Se a minha ideia\nestiver certa, o\vELM vai saber.",
  ["MrPokemonText_AlwaysNewDiscoveries"] = "A vida é uma\ndelícia! Sempre\fnovas descobertas\npara fazer!",
  ["MrPokemonText_Disappointed"] = "Que decepção.\nAcontece que isso\vé bem raro.",
  ["MrPokemonText_GimmeTheScale"] = "Hum? Essa SCALE!\nO que é isso?\vGYARADOS rubro?\fIsso é raro!\nEu, eu quero…\f{PLAYER}, quer\ntrocar comigo?\fPosso oferecer\neste EXP.SHARE que\vganhei do OAK.",
  ["MrPokemonText_ImDependingOnYou"] = "Estou contando\ncom você!",
  ["MrPokemonsHouseDirectionsSignText"] = "CASA DO MR.POKéMON\nEm frente!",
  ["MrPokemonsHouseSignText"] = "LAR DE MR.POKéMON",
  ["MrPokemonsHouse_BrokenComputerText"] = "É um computador\ngrande. Hum. Está\vquebrado.",
  ["MrPokemonsHouse_ForeignMagazinesText"] = "Está cheio de\nrevistas de fora.\fNem dá para ler\nos títulos…",
  ["MrPokemonsHouse_GetDexText"] = "{PLAYER} recebeu\na POKéDEX!",
  ["MrPokemonsHouse_GotEggText"] = "{PLAYER} recebeu\no MYSTERY EGG.",
  ["MrPokemonsHouse_MrPokemonHealText"] = "Você vai voltar\nao PROF.ELM?\fAqui. Seus POKéMON\nprecisam de um\vdescanso.",
  ["MrPokemonsHouse_OakText1"] = "OAK: Aha! Então\nvocê é {PLAYER}!\fSou o OAK! Um\npesquisador.\fEu estava só\nvisitando meu\vamigo MR.POKéMON.\fSoube que você\nfazia um favor\fpara o PROF.ELM,\ne esperei aqui.\fOh! O que é isto?\nUm POKéMON raro!\fVamos ver…\fHum, entendi!\fEntendo por que\no PROF.ELM te deu\fum POKéMON para\nesta tarefa.\fPara pesquisadores\ncomo o PROF.ELM e\feu, POKéMON são\nnossos amigos.\fEle viu que você\ntrataria os seus\fPOKéMON com amor\ne cuidado.\f…Ah!\fVocê parece ser\nde confiança.\fQue tal você\nme ajudar?\fViu? Esta é a\nversão mais nova\vda POKéDEX.\fEla grava sozinha\nos dados dos\fPOKéMON que você\nviu ou pegou.\fÉ uma enciclopédia\nde ponta!",
  ["MrPokemonsHouse_OakText2"] = "Vá conhecer muitos\ntipos de POKéMON\fe complete essa\nPOKéDEX!\fMas eu fiquei\ntempo demais.\fTenho que ir a\nGOLDENROD para o\vmeu programa.\f{PLAYER}, eu estou\ncontando contigo!",
  ["MrPokemonsHouse_StrangeCoinsText"] = "Um monte de moedas\nestranhas!\fTalvez sejam de\noutro país…",
  ["MrPsychicText1"] = "…\f…\f…\f…Já sei!\fVocê queria isto!",
  ["MrPsychicText2"] = "A TM29 é PSYCHIC.\fEla pode baixar o\nSPECIAL do\valvo.",
  ["MrPsychicsHouseSignText"] = "CASA do\nSR.PSIQUICO",
  ["MtMoonSquareSignText"] = "MT.MOON SQUARE\fÉ só subir as\nescadas.",
  ["MtMortarSign1Text"] = "MOUNT MORTAR\fWATERFALL CAVE\nInterior",
  ["MtMortarSign2Text"] = "MOUNT MORTAR\fWATERFALL CAVE\nInterior",
  ["MtSilverSignText"] = "MT.SILVER",
  ["MysticWaterGuyTextAfter"] = "Volto a pescar,\nentão.",
  ["MysticWaterGuyTextBefore"] = "Um POKéMON que eu\npeguei tinha algo\fAcho que é\nMYSTIC WATER.\fNão preciso dele,\nvocê quer?",
  ["NationalParkBattleNoticeText"] = "O que diz este\naviso?\fBatalhe somente no\nmato, por favor.\fNATIONAL PARK\nSEDE DA GUARDA",
  ["NationalParkBugContestBattleNoticeText"] = "O que diz este\naviso?\fBatalhe somente no\nmato, por favor.\fNATIONAL PARK\nSEDE DA GUARDA",
  ["NationalParkBugContestRelaxationSquareText"] = "PRAÇA DO DESCANSO\nNATIONAL PARK",
  ["NationalParkBugContestTrainerTipsText"] = "TRAINER TIPS\fPara imprimir uma\nMAIL, abra ela e\vaperte START.",
  ["NationalParkGameboyKidText"] = "Estou imprimindo a\nminha POKéDEX.\fDá para imprimir\noutras coisas,\fcomo MAIL e suas\nBOXES do PC.",
  ["NationalParkLassText"] = "Olhe! Veja a minha\nbolsa!\fImprimi os meus\nfavoritos da\fPOKéDEX e colei\nna minha bolsa.",
  ["NationalParkPersianText"] = "PERSIAN: Fufusha!",
  ["NationalParkPokefanFText"] = "Esta é uma MAIL da\nminha filha.\vEla me anima.",
  ["NationalParkRelaxationSquareText"] = "PRAÇA DO DESCANSO\nNATIONAL PARK",
  ["NationalParkTeacher1Text"] = "Atenção, por\nfavor!\f…Opa, preciso\nparar de pensar\fcomo professora o\ntempo todo.\fVocê deve ser um\ntreinador POKéMON\fJá que se esforça\ntanto, quero que\fvocê fique com\nisto.",
  ["NationalParkTeacher1Text_GotQuickClaw"] = "Dê essa QUICK CLAW\na um POKéMON.\fÀs vezes ele ataca\nprimeiro na\vbatalha.",
  ["NationalParkTeacher2Text"] = "Eu passeio pelo\nPARK, mas nunca\fentro no meio do\nmato.\fTreinadores sempre\nquerem batalhar…",
  ["NationalParkTrainerTipsText"] = "TRAINER TIPS\fPara imprimir uma\nMAIL, abra ela e\vaperte START.",
  ["NationalParkYoungster1Text"] = "Estou brincando\ncom adesivos que\vtirei da POKéDEX.",
  ["NationalParkYoungster2Text"] = "Se eu ganhar, fico\ncom o adesivo da\vPOKéDEX dele.",
  ["NewBarkTownElmsHouseSignText"] = "CASA DO ELM",
  ["NewBarkTownElmsLabSignText"] = "LAB POKéMON ELM",
  ["NewBarkTownPlayersHouseSignText"] = "Casa de {PLAYER}",
  ["NewBarkTownRivalText1"] = "……\fEntão este é o\nfamoso LAB POKéMON\vdo ELM…",
  ["NewBarkTownRivalText2"] = "…O que você está\nolhando?",
  ["NewBarkTownSignText"] = "CIDADE DE NEW BARK\fA cidade onde\nos ventos do\vrecomeço sopram",
  ["NoLitteringSignText"] = "Não jogue lixo.\fLeve seu lixo\ncom você.",
  ["NoRoomForLeftoversText"] = "Mas {PLAYER} não\npode levar mais",
  ["NurseAskHealText"] = "Podemos curar seus\nPOKéMON até a\vsaúde perfeita.\fCuramos os seus\nPOKéMON?",
  ["NurseDayText"] = "Olá!\nBem-vindo ao nosso\vCENTRO POKéMON.",
  ["NurseGoodbyeText"] = "Esperamos ver você\nde novo.",
  ["NurseMornText"] = "Bom dia!\nBem-vindo ao nosso\vCENTRO POKéMON.",
  ["NurseNiteText"] = "Boa noite!\nSaiu tarde, hein?\fBem-vindo ao nosso\nCENTRO POKéMON.",
  ["NursePokerusText"] = "Seus POKéMON\nparecem ter formas\vde\fvida minúsculas\ngrudadas neles.\fSeus POKéMON estão\nsaudáveis e bem de\vmodo geral.\fMas não podemos\ndizer mais nada\fnum CENTRO\nPOKéMON.",
  ["NurseReturnPokemonText"] = "Obrigada por\nesperar.\fSeus POKéMON estão\ncurados.",
  ["NurseTakePokemonText"] = "Certo, posso ver\nseus POKéMON?",
  ["OakLabDexCheckText"] = "Como vai a sua\nPOKéDEX?\fVamos ver…",
  ["OakLabGoodbyeText"] = "Se estiver por\nperto, espero que\vvolte a visitar.",
  ["OakNoKantoBadgesText"] = "OAK: Hum? Você não\nestá juntando as\vINSÍGNIAS daqui?\fOs LÍDERES daqui\nsão tão fortes\fquanto os que você\nvenceu em JOHTO.\fEu recomendo que\nvocê desafie\veles.",
  ["OakWelcomeKantoText"] = "OAK: Ah, {PLAYER}!\nQue bom que você\fveio de tão longe\naté KANTO.\fO que você acha\ndos treinadores\fdaqui?\nBem durões, né?",
  ["OakYesKantoBadgesText"] = "OAK: Ah, você está\njuntando as\vINSÍGNIAS daqui.\fImagino que seja\ndifícil, mas a\fexperiência vai\najudar você.\fVenha me ver\ncom todas elas.\fTenho um presente\npara você.\fContinue firme,\n{PLAYER}!",
  ["OaksAssistant1Text"] = "O programa POKéMON\nTALK do PROF\fnão passa aqui\nem KANTO.\fÉ uma pena, eu\nqueria ouvir.",
  ["OaksAssistant2Text"] = "Graças ao seu\ntrabalho na\vPOKéDEX, a\vpesquisa\fdo PROF está indo\nmuito bem.",
  ["OaksAssistant3Text"] = "Não conte a\nninguém, mas o\fPOKéMON TALK não é\nao vivo.",
  ["OaksLabPCText"] = "Tem uma mensagem\nde e-mail no PC.\f…\fPROF.OAK, como vai\na sua pesquisa?\vTudo indo bem?\fEu continuo\nbatalhando.\fOuvi rumores de\nque {PLAYER} está\fficando bem\nconhecido por aí.\fFico muito feliz\nde saber disso.\fELM, de CIDADE DE\nNEW BARK 8-)",
  ["OaksLabPoster1Text"] = "Aperte START para\nabrir o MENU.",
  ["OaksLabPoster2Text"] = "A opção SAVE está\nno MENU.\fUse de tempos em\ntempos.",
  ["OaksLabSignText"] = "LABORATÓRIO de\nPESQUISA do OAK",
  ["OaksLabTrashcanText"] = "Não tem nada\naqui dentro…",
  ["OfferGoodRodText"] = "OLIVINE fica no\nmar!\fE se fica no mar,\ncom certeza há\vpeixes!\fPesco aqui há\n30 anos.\fQuer encarar o\nmar e pescar\vtambém?",
  ["OfferSuperRodText"] = "Eu sou o irmão\nmais novo do\vFISHING GURU.\fVejo que você\ngosta de pescar.\fNão tenho a menor\ndúvida disso!\fE aí? Sei que\nestou certo.",
  ["OfficerDirkAfterBattleText"] = "Sabe, a noite tem\nas diversões dela\vtambém.\fMas não exagere,\ntá bom?",
  ["OfficerDirkBeatenText"] = "Opa!",
  ["OfficerDirkPrettyToughText"] = "Seus POKéMON são\nbem fortes.\fVocê pode ir a\nqualquer lugar.",
  ["OfficerDirkSeenText"] = "O perigo espreita\nà noite!",
  ["OfficerKeithAfterText"] = "É, não vejo nada\nde errado hoje.\fComporte-se e não\narrume confusão.",
  ["OfficerKeithDaytimeText"] = "Estou de ronda\natrás de gente\vsuspeita.",
  ["OfficerKeithSeenText"] = "Quem vem lá?\nO que você está\vaprontando?",
  ["OfficerKeithWinText"] = "Você é um garoto\ndurão.",
  ["OfficerText_AvoidGrass"] = "Use este portão\npra não andar\vna grama.",
  ["OfficerText_FoundTM"] = "Fui expulso do\nmeu posto por\vaqueles de preto.\fEles deixaram\nisto para trás.\fIsso me deixa\ndesconfortável.\vPode levar?",
  ["OlivineCafeFishingGuruText"] = "Cruzando o mar?\nEntão escute!\fHá redemoinhos\nno caminho para\vCIANWOOD.\fSeu POKéMON tem\nque saber de um\fgolpe pra passar\ndos redemoinhos.",
  ["OlivineCafeSailorText"] = "Sempre que venho\npra esta cidade,\feu sempre visito\no OLIVINE CAFE.\fTudo no cardápio\nme faz sentir\fmais forte. Não\nconsigo parar!",
  ["OlivineCafeStrengthSailorText"] = "Hah! Seus POKéMON\nparecem mesmo ser\vpesos-leves!\fEles não têm força\npra mover de lado\vos pedregulhos.\fTome, use isto\ne ensine o golpe\vSTRENGTH a eles!\fVai precisar da\nBADGE do GINÁSIO\fde GOLDENROD pra\nusar fora de luta",
  ["OlivineCafeStrengthSailorText_GotStrength"] = "No mar, a única\ncoisa que conta\fSó dá pra contar\ncom você mesmo.\fTenho orgulho do\nmeu corpo sarado!",
  ["OlivineCityBattleTowerSignText"] = "BATTLE TOWER AQUI\nAbrindo Agora!",
  ["OlivineCityBattleTowerSignText_NotYetOpen"] = "BATTLE TOWER AQUI",
  ["OlivineCityPortSignText"] = "OLIVINE PORT\nPÍER DO FAST SHIP",
  ["OlivineCityRivalText"] = "…\fVocê de novo?\fNão precisa entrar\nem pânico. Eu não\fperco tempo com\nbananas como você\fFalando em fracos,\na LÍDER daqui\fdo GINÁSIO não\nestá aqui.\fDizem que está\ncuidando de um\fPOKéMON doente no\nLIGHTHOUSE.\fHunf! Bu-hu-hu!\nÉ só largar os\vPOKéMON doentes!\fUm POKéMON que não\npode batalhar não\vvale nada!\fPor que você não\nvai treinar no\vLIGHTHOUSE?\fVai que. Talvez te\ndeixe um pouco\vmenos fraco!",
  ["OlivineCitySailor1Text"] = "Estradas escuras\nsão perigosas\vde noite.\fMas na escuridão\ntotal da noite,\fo mar é ainda\nmais traiçoeiro!\fSem a luz do farol\ndo LIGHTHOUSE\fpara guiar, navio\nnenhum navega.",
  ["OlivineCitySailor2Text"] = "Olá, rapazinho!\nO mar é doce!\fCante comigo!\nEi-ô! Puxa a corda\vcom força!…",
  ["OlivineCitySignText"] = "CIDADE DE OLIVINE\fO Porto Mais Perto\nde Outras Terras",
  ["OlivineCityStandingYoungsterPokedexText"] = "Uau, você tem uma\nPOKéDEX!\fIsso é\nsimplesmen-te\vdemais.",
  ["OlivineCityStandingYoungsterPokegearText"] = "Essa coisa que\nvocê tem, é uma\vPOKéGEAR, né? Uau,\vque legal.",
  ["OlivineGymGuidePreText"] = "A JASMINE, LÍDER\ndo GINÁSIO, está\vno LIGHTHOUSE.\fEla cuida de um\nPOKéMON doente.\fUm treinador forte\nprecisa ter\vcompaixão.",
  ["OlivineGymGuideText"] = "A JASMINE usa o\ntipo aço, que é\vbem recente.\fEu não sei quase\nnada sobre ele.",
  ["OlivineGymGuideWinText"] = "Aquilo foi demais\fEntão o tipo aço,\nhein?\fFoi um encontro\nimediato de tipo\vdesconhecido!",
  ["OlivineGymSignText"] = "CIDADE DE OLIVINE\nGINÁSIO POKéMON\vLÍDER: JASMINE\fA Garota Blindada\nda Defesa",
  ["OlivineHouseBetaRhydonText"] = "RHYDON: Grrugooh!",
  ["OlivineHouseBetaTeacherText"] = "Quando meu POKéMON\nficou doente, o\fFARMACÊUTICO de\nECRUTEAK fez um\vremédio pra mim.",
  ["OlivineLighthouse1FPokefanFText"] = "Antigamente,\nPOKéMON\viluminavam\fo mar em volta de\nOLIVINE à noite.\fO LIGHTHOUSE foi\nfeito em honra a\vesses POKéMON.",
  ["OlivineLighthouse1FSailorText"] = "As pessoas treinam\nneste LIGHTHOUSE.\fNão é fácil subir\npor causa de todos\vos treinadores.",
  ["OlivineLighthouseSignText"] = "OLIVINE LIGHTHOUSE\nTambém Conhecido\vpor GLITTER",
  ["OlivineMartCooltrainerFText"] = "Seus POKéMON já\nsabem o golpe pra\fcarregar pessoas\nsobre a água?",
  ["OlivineMartLassText"] = "Meu BUTTERFREE\nveio do namorado\vlá do exterior.\fEle trouxe um MAIL\nque ele mandou.\fQuer saber o que\ndiz?\fVamos ver… Não!\nÉ um segredo!",
  ["OlivinePokecenter1FFisherText"] = "Os marinheiros\nsão generosos.\fUm me ensinou\no STRENGTH.\fAgora meu POKéMON\nmove pedregulhos.",
  ["OlivinePokecenter1FTeacherText"] = "Tem uma pessoa\nem CIDADE DE\vCIANWOOD\vatravés do mar.\fEu ouvi ele se\ngabar dos seus\vPOKéMON raros.",
  ["OlivinePortAskBoardText"] = "Bem-vindo ao FAST\nSHIP S.S.AQUA.\fVai embarcar\nhoje?",
  ["OlivinePortAskTicketText"] = "Posso ver o seu\nS.S.TICKET?",
  ["OlivinePortCantBoardText"] = "Desculpe. Não dá\npara embarcar.",
  ["OlivinePortComeAgainText"] = "Esperamos vê-lo\nnovamente!",
  ["OlivinePortCooltrainerFText"] = "Tem um monte de\nPOKéMON em KANTO.\fQueria poder ir…",
  ["OlivinePortFishingGuru1Text"] = "SHELLDER é fácil\nde pegar aqui.\fEm outros lugares\né meio raro.",
  ["OlivinePortFishingGuru2Text"] = "Quantas RODS você\ntem?\fRODS diferentes\npegam POKéMON\vdiferentes.",
  ["OlivinePortFlashTicketText"] = "{PLAYER} mostrou\no S.S.TICKET.\fÉ isso.\nObrigado!",
  ["OlivinePortFridayShipText"] = "O FAST SHIP zarpa\nna sexta que vem.",
  ["OlivinePortMondayShipText"] = "O FAST SHIP vai\nzarpar segunda.",
  ["OlivinePortNoTicketText"] = "{PLAYER} tentou\nmostrar o S.S.\vTICKET…\f…Mas não tem!\fDesculpe!\nSó pode embarcar\fquem tiver um\nS.S.TICKET.",
  ["OlivinePortPassagePokefanMText"] = "O FAST SHIP S.S.\nAQUA vai a KANTO\fàs segundas e\nsextas.",
  ["OlivinePortSailorBeforeHOFText"] = "Não queremos que\nvocê caia no mar,\fentão não pode\nentrar.",
  ["OlivinePortSailorGetOnBoardText"] = "Vamos partir logo.\nPor favor, suba\va bordo.",
  ["OlivinePortYoungsterText"] = "O S.S.AQUA usa\njatos e desliza\vsobre as ondas!",
  ["OlivinePunishmentSpeechHouseDadText"] = "No caminho para\nCIANWOOD, existem\fHá quatro ilhas\ndesertas.\fCrianças ruins são\nlevadas pras ilhas\vcomo castigo!",
  ["OlivinePunishmentSpeechHouseDaughterText"] = "Quando me meto em\nenrascada, papai\vsempre me assusta",
  ["PalletTownFisherText"] = "Tecnologia é\nincrível!\fDá pra trocar\nPOKéMON no tempo\vcomo e-mail.",
  ["PalletTownSignText"] = "CIDADE DE PALLET\fUm lugar sereno,\nde paz e pureza",
  ["PalletTownTeacherText"] = "Eu também crio\nPOKéMON.\fEles servem de\nmeus guardas",
  ["PewterCityBugCatcherText"] = "De noite, CLEFAIRY\nvêm pra brincar no\vMT.MOON.\fMas nem toda\nnoite.",
  ["PewterCityCooltrainerFText"] = "Já visitou o\nPEWTER GYM?\fO LÍDER usa\nPOKéMON de pedra.",
  ["PewterCityGrampsText"] = "Ah, você veio de\ntão longe, de\vJOHTO?\fIsso traz\nmemórias. Quando\veu\fera jovem, ia a\nJOHTO treinar.\fVocê me lembra\nmuito do que eu\fera, jovem como\nvocê.\fQuero que fique\ncom um item que\vachei em JOHTO.",
  ["PewterCityGrampsText_GotSilverWing"] = "Ir a lugares\nnovos, conhecer\vgente nova…\fEssa é a alegria\nde viajar.",
  ["PewterCityMtMoonGiftShopSignText"] = "Há um aviso…\nLOJA do\fMT.MOON GIFT SHOP\nagora aberta!",
  ["PewterCitySignText"] = "CIDADE DE PEWTER\nA Cidade Cinzenta",
  ["PewterCityWelcomeSignText"] = "Bem-vindo a\nCIDADE DE PEWTER!",
  ["PewterGymGuideText"] = "Ei! Futuro\nCAMPEÃO!\fVocê está indo bem\nEstá enfrentando\fos LÍDERES de\nGINÁSIO de KANTO?\fSão gente forte e\ndedicada,\figual aos LÍDERES\nde JOHTO.",
  ["PewterGymGuideWinText"] = "Ei! Futuro\nCAMPEÃO!\fO GINÁSIO não te\ndeu trabalho.\fO jeito que você\nassumiu o comando\ffoi inspirador.\nFalo sério.",
  ["PewterGymSignText"] = "CIDADE DE PEWTER\nPOKéMON GYM\vLÍDER: BROCK\fO Treinador\nde pedra",
  ["PewterMartSuperNerdText"] = "Teve um velho\nestranho que\vvendia MAGIKARP.\fEle dizia que os\nMAGIKARP do\fLAKE OF RAGE eram\nexcelentes.",
  ["PewterMartYoungsterText"] = "Oi! Olha o meu\nGYARADOS!\fCriei ele desde\nMAGIKARP. Não dá\fpara acreditar em\ncomo ficou forte.",
  ["PewterMuseumSignText"] = "Há um aviso…\naqui…\fPEWTER MUSEUM OF\nSCIENCE está\vfechado…",
  ["PewterNidoranSpeechHouseSuperNerdText"] = "NIDORAN, pata!",
  ["PewterPokecenter1FBugCatcherText"] = "Quase todo POKéMON\nfica com sono\fse ouve um\nJIGGLYPUFF cantar\fTem vários golpes\nque só dá para\fusar enquanto o\nPOKéMON dorme.",
  ["PewterPokecenter1FTeacherText"] = "…É, e o GINÁSIO\nde CINNABAR\fsumiu. Eu fiquei\nespantado.\f…Sim? Estou no\ntelefone. Sai!",
  ["PewterSnoozeSpeechHouseGrampsText"] = "Gosto de cochilar\ncom o rádio ligado\v…Zzzz…",
  ["PharmacistDescribeSecretpotionText"] = "Minha SECRETPOTION\né forte demais.\fSó ofereço numa\nemergência.",
  ["PharmacistGiveSecretpotionText"] = "Seus POKéMON\nparecem bem.\fTem algo\npreocupando você?\f…\fO POKéMON do\nLIGHTHOUSE está\vem apuros?\fJá sei!\fIsto deve\nresolver.",
  ["PhoneThankYouText"] = "Obrigado!",
  ["PicnickerBrookeAfterBattleText"] = "Confio mais nos\nmeus POKéMON que\vno meu namorado.",
  ["PicnickerBrookeBeatenText"] = "Nossa! Você é\ntão forte!",
  ["PicnickerBrookeSeenText"] = "Meu namorado é\nfraco, não dá para\vcontar com ele.",
  ["PicnickerCindyAfterText"] = "Você deve estar\nficando cansado.",
  ["PicnickerCindyBeatenText"] = "Droga!\nEu queria ganhar!",
  ["PicnickerCindyBeforeText"] = "Eu sou a JANINE!\fComo você soube\nque eu era real?\fVamos batalhar!",
  ["PicnickerDebraAfterBattleText"] = "SAFFRON, CELADON…\nOuvi que tem\fmuitas cidades\ngrandes em KANTO.",
  ["PicnickerDebraBeatenText"] = "Uau! Você é forte\ndemais!",
  ["PicnickerDebraSeenText"] = "Estou entediado.\nQuer batalhar?",
  ["PicnickerEdnaAfterBattleText"] = "Economizar energia\né importante, mas\fo meio ambiente é\nainda mais.",
  ["PicnickerEdnaSeenText"] = "As pessoas não\ndeviam deixar\vlixo por aí.",
  ["PicnickerErin1SeenText"] = "Eu também crio\nPOKéMON!\fVamos lutar!",
  ["PicnickerErinAfterBattleText"] = "Já fui a muitos\nGINÁSIOS, mas o\fde GOLDENROD é o\nmeu favorito.\fEle é cheio de\nflores lindas!",
  ["PicnickerGina1AfterText"] = "Você é forte\ndemais para ser\vmeu parceiro.",
  ["PicnickerGina1BeatenText"] = "Ah, não! Eu não\nconsigo ganhar…",
  ["PicnickerGina1SeenText"] = "Você é treinador?\fVamos fazer uma\nbatalha de treino",
  ["PicnickerHeidiAfterBattleText"] = "A gente assa um\nmonte de doces\fe divide com todo\nmundo. É delícia!",
  ["PicnickerHeidiSeenText"] = "Você já foi a um\npiquenique?\fÉ muito\ndivertido!",
  ["PicnickerHopeAfterBattleText"] = "Ouvi que CLEFAIRY\nvêm na MT.MOON.\fMas onde será\nque eles estão?",
  ["PicnickerHopeBeatenText"] = "Aah, você é forte\ndemais.",
  ["PicnickerHopeSeenText"] = "Tenho a impressão\nde que vou ganhar\fVamos ver se eu\nestou certo!",
  ["PicnickerKimAfterBattleText"] = "As BADGES de\nGINÁSIO são lindas\vEu coleciono.",
  ["PicnickerKimBeatenText"] = "Ah. Eu não\nconsegui…",
  ["PicnickerKimSeenText"] = "Você vai para o\nGINÁSIO? Eu vou!",
  ["PicnickerLiz1AfterText"] = "E eu estava numa\nboa conversa.",
  ["PicnickerLiz1BeatenText"] = "Vai com calma!\nQue maldade!",
  ["PicnickerLiz1SeenText"] = "Aham. É, e\nsabe como é…\fComo? Batalhar?\nEstou ao telefone\fAh, tá bom. Mas\nseja rápido.",
  ["PicnickerSharonAfterBattleText"] = "……Vou treinar\nmais um pouco…",
  ["PicnickerTanyaAfterBattleText"] = "Olha todas as\nsuas INSÍGNIAS.\fNão é à toa que\nnão venci!",
  ["PicnickerTanyaSeenText"] = "Oh, uma batalha?\nQue assustador,\vmas tudo bem!",
  ["PicnickerTiffanyBeatenText"] = "Brinquei demais!",
  ["PicnickerTiffanySeenText"] = "Você também vai\nao LAKE OF RAGE?\fVamos brincar um\npouquinho!",
  ["PicnickerTiffanyWantsPicnicText"] = "Estou num\npiquenique com\vPOKéMON\fNão quer vir?",
  ["PictureBookshelfText"] = "Uma coleção\ninteira de livros\vde POKéMON!",
  ["PlateauRivalLoseText"] = "…\fUfa…\nCom meus amigos,\feu vou ser o\nCAMPEÃO!",
  ["PlateauRivalText1"] = "Espere aí.\fVocê vai encarar\no desafio da\fPOKéMON LEAGUE\nagora?\fIsso não vai\nacontecer.\fMeus POKéMON super\nbem treinados\fvão acabar com\nvocê.\f{PLAYER}!\nEu te desafio!",
  ["PlateauRivalText2"] = "…Droga… Eu ainda\nnão consigo…\fEu… eu preciso\npensar mais nos\vmeus POKéMON…\fHumpf! Tente não\nperder!",
  ["PlayerHandedSecretpotionText"] = "{PLAYER} entregou\na SECRETPOTION\va JASMINE.",
  ["PlayerNeighborRadioText1"] = "POKéMON TALK DO\nPROF.OAK! Não\vperca a próxima!",
  ["PlayerNeighborRadioText2"] = "CANAL POKéMON!",
  ["PlayerNeighborRadioText3"] = "Aqui é a DJ MARY,\nsua parceira!",
  ["PlayerNeighborRadioText4"] = "POKéMON!\nCANAL POKéMON…",
  ["PlayerReceivedPlainBadgeText"] = "{PLAYER} recebeu\na PLAINBADGE.",
  ["PlayerReceivedRainbowBadgeText"] = "{PLAYER} recebeu\na RAINBOWBADGE.",
  ["PlayersHouse1FFridgeText"] = "Vamos ver o que há\nna geladeira…\fFRESH WATER e uma\nboa LEMONADE!",
  ["PlayersHouse1FSinkText"] = "A pia está\nimpecável. A mamãe\vgosta dela limpa.",
  ["PlayersHouse1FStoveText"] = "Prato da mamãe!\fHAMBÚRGUER VULCÃO\nDE CINNABAR!",
  ["PlayersHouse1FTVText"] = "Passa um filme na\nTV: estrelas no\fcéu e dois\nmeninos no trem…\fÉ melhor eu ir\nandando também!",
  ["PlayersNeighborsDaughterText"] = "PIKACHU é um\nPOKéMON evoluído.\fFiquei espantado\ncom as descobertas\vdo PROF.ELM.\fEle é bem famoso\npela pesquisa da\vevolução.\f…suspiro…\fEu queria poder\nser pesquisador\vcomo ele…",
  ["PlayersRadioText1"] = "POKéMON TALK DO\nPROF.OAK! Não\vperca a próxima!",
  ["PlayersRadioText2"] = "CANAL POKéMON!",
  ["PlayersRadioText3"] = "Aqui é a DJ MARY,\nsua parceira!",
  ["PlayersRadioText4"] = "POKéMON!\nCANAL POKéMON…",
  ["PokecenterSignText"] = "Cure Seus POKéMON!\nCENTRO POKéMON",
  ["PokecomCenterAdminOfficeMobileComputer1Text"] = "É um aviso sobre\nonde os MOBILE\fADAPTERS devem\nser usados…",
  ["PokecomCenterAdminOfficeMobileComputer1Text_MobileCenter"] = "Pra usar o TRADE\nCORNER ou ler as\fPOKéMON NEWS,\nvocê precisa\vligar pro MOBILE\vCENTER.\fVocê deve se\nregistrar no\fMOBILE CENTER\nantes de conectar\vlá.",
  ["PokecomCenterAdminOfficeMobileComputer1Text_PokeComClub"] = "Tem um POKéCOM\nCLUB no andar de\fcima de qualquer\nPOKéMON CENTER.\fLá você pode\nbatalhar ou\ftrocar com um\namigo distante\vusando um MOBILE\vADAPTER.\fPra conectar, seu\namigo precisa ter\fo mesmo tipo de\nMOBILE ADAPTER\fque você.",
  ["PokecomCenterAdminOfficeMobileComputer2Text"] = "É um aviso sobre\ncomo usar o\vtelefone…",
  ["PokecomCenterAdminOfficeMobileComputer2Text_DontUsePhone"] = "Se o servidor\nestiver ocupado,\ftalvez não seja\npossível entrar.\fSe for o caso,\nligue depois.\fSe você não\nconseguir entrar\fou não entender\nos erros,\fligue pro suporte\nou leia as\vinstruções.",
  ["PokecomCenterAdminOfficeMobileComputer2Text_UsePhone"] = "Confira se seu\ntelefone e o\fMOBILE ADAPTER\nestão bem\vconectados.\fConfira se o\nsinal do telefone\vsem fio está\vforte.\fNão toque nem\ndesligue o\vtelefone ao\vconectar.",
  ["PokecomCenterAdminOfficeMobileComputer3Text"] = "O ADMINISTRATION\nOFFICE recebeu um\ve-mail. Ele diz…\f…… …… ……\fPra equipe do\nPOKéCOM CENTER…\fA comunicação sem\nfio permitiu que\ftreinadores de\nPOKéMON interajam\fpor todo o país.\nVamos continuar\ftrabalhando pro\ndia em que todos\ftreinadores do\nmundo possam se\vconectar sem\vbarreiras!\f…… …… ……",
  ["PokecomCenterAdminOfficeMobileScientist1Text"] = "O POKéCOM CENTER e\no MOBILE CENTER\vforam feitos pra\vatender trocas e\vbatalhas com\vtreinadores\vdistantes e\vestranhos.",
  ["PokecomCenterAdminOfficeMobileScientist2Text"] = "Quando você\nconectou com\falguém por\ncelular pela\vprimeira vez,\fnão ficou\nimpressionado?\fQuando minha\nprimeira\fdeu certo, fiquei\ntão impressionado\vque tremi todo!",
  ["PokecomCenterAdminOfficeMobileScientist3Text"] = "Conseguiram\nconstruir esse\flugar enorme\ngraças aos\vavanços em\vtecnologia sem\vfio.",
  ["PokefanBeverlyCuteMonText"] = "Minha amiga tem um\nMARILL. É tão\ffofo! Queria ter\num MARILL.",
  ["PokefanMDerekText_NotBragging"] = "Não vou ouvir\nvocê se gabar!\fNós POKé FANS\ntemos a regra de\fnão ouvir os\noutros se gabarem",
  ["PokefanfBeverly1BeatenText"] = "Talvez eu não\nte vença na luta…\fMas os meus são\nbem mais bonitos.",
  ["PokefanfBeverly1SeenText"] = "Meus POKéMON são\ntão fofos. Vou\vmostrar a você.",
  ["PokefanfGeorgiaAfterBattleText"] = "Ah, sim! Tenho que\nbuscar meu POKéMON\vno DAY-CARE!",
  ["PokefanfGeorgiaBeatenText"] = "O que eu ia\nfazer mesmo?",
  ["PokefanfGeorgiaSeenText"] = "Vou fazer compras\nna DEPT.STORE e\vdepois…",
  ["PokefanfRuthAfterBattleText"] = "Você conhece os\nPOKéMON bebês?\fAposto que são\nadoráveis!",
  ["PokefanfRuthBeatenText"] = "Não me importo\nde perder.",
  ["PokefanfRuthSeenText"] = "Que POKéMON\nqueridos.\fVamos mostrar os\nnossos POKéMON\vao mesmo tempo.",
  ["PokefanmAlexAfterBattleText"] = "Todo mundo não\nsonha um dia ser\vum rei?",
  ["PokefanmAlexBeatenText"] = "Como… Como ousa\nzombar da realeza",
  ["PokefanmBrandonAfterText"] = "Meu POKéMON sabia\ngolpes que eu nem\vsabia que tinha.\fIsso me confundiu\ndemais!",
  ["PokefanmBrandonBeatenText"] = "Por que termina\nassim?",
  ["PokefanmBrandonSeenText"] = "Acabei de pegar\nmeu POKéMON de\vvolta no DAY-CARE\fVamos ver o quanto\nele ficou forte!",
  ["PokefanmCarterAfterBattleText"] = "SQUIRTLE,\nCHARMANDER e\vBULBASAUR…\fAcho que é uma boa\nmistura.",
  ["PokefanmColinAfterBattleText"] = "Você viaja\nsozinho?\fSua mãe não fica\npreocupada?",
  ["PokefanmColinSeenText"] = "Ei, filho! Quer\nbatalhar comigo?",
  ["PokefanmDerekBeatenText"] = "Nem consigo me\ngabar…",
  ["PokefanmDerekSeenText"] = "Você se importa se\neu me gabar dos\vmeus POKéMON?",
  ["PokefanmJeremyAfterBattleText"] = "Preciso ir ao\nPOKéMON SALON e\vdeixá-los lindos!",
  ["PokefanmJeremyBeatenText"] = "Ah, não! Meus\nlindos POKéMON!",
  ["PokefanmJeremySeenText"] = "O que você acha?\nMeus POKéMON são\vlindos, não são?",
  ["PokefanmJoshuaAfterBattleText"] = "Você parece ter\nmuitos POKéMON,\fmas PIKACHU ainda\né o melhor.",
  ["PokefanmJoshuaSeenText"] = "Nihihi! Quer\nbatalhar com a\vminha gangue?",
  ["PokefanmRobertAfterBattleText"] = "Olha o que você\nfez com o POKéMON\fEu não vou\nesquecer disso…",
  ["PokefanmRobertBeatenText"] = "Eu diria que essa\nfoi derrota minha",
  ["PokefanmRobertSeenText"] = "Você gosta de\nPOKéMON, né?\fEu também!",
  ["PokefanmTrevorAfterBattleText"] = "Se você tem BADGES\nde KANTO, elas\fajudam nas lutas\npor link.",
  ["PokefanmTrevorBeatenText"] = "Nossa! Forte\ndemais para mim!",
  ["PokefanmTrevorSeenText"] = "Você batalhou com\ntodos do GINÁSIO?",
  ["PokefanmWilliamAfterBattleText"] = "Perdi a batalha,\nmas meus POKéMON\fganham o prêmio\npor serem fofos.",
  ["PokefanmWilliamSeenText"] = "Adoramos nossos\nPOKéMON, mesmo que\veles não gostem.\fÉ isso que é\nser um FAN.",
  ["PokemaniacAndrewAfterBattleText"] = "Só eu e os meus\nPOKéMON. Estou\vlouco de alegria.",
  ["PokemaniacAndrewSeenText"] = "Quem está aí?\fDeixe eu e meus\nPOKéMON em paz!",
  ["PokemaniacBenAfterBattleText"] = "Do que mais eu\ngosto além de\vPOKéMON?\fA MARY do rádio.\nDeve ser fofa!",
  ["PokemaniacBenBeatenText"] = "Como você pôde\nfazer isso comigo",
  ["PokemaniacBrentAfterBattleText"] = "Eu ficaria feliz\nsó de ter um\vPOKéMON raro.",
  ["PokemaniacBrentBeatenText"] = "Ah, meus pobres\nPOKéMON queridos!",
  ["PokemaniacBrentSeenText"] = "Ei! Você tem algum\nPOKéMON raro?",
  ["PokemaniacCalvinAfterBattleText"] = "Devo reunir e\ndivulgar o que\vdescobri.\fQuem sabe eu fique\nfamoso como o\vPROF.ELM.",
  ["PokemaniacCalvinBeatenText"] = "Você demonstrou\nem mim!",
  ["PokemaniacCalvinSeenText"] = "Vim de tão longe\npara fazer minha\vpesquisa POKéMON.\fDeixe eu mostrar\no que descobri\vnuma luta real!",
  ["PokemaniacDonaldAfterBattleText"] = "Está fazendo uma\nPOKéDEX? Aqui vai\vuma dica boa.\fO HIKER da ROTA\n33, o ANTHONY, é\vgente boa.\fEle te liga se vir\nalgum POKéMON\vraro.",
  ["PokemaniacDonaldBeatenText"] = "Gaah! Eu perdi!\nQue raiva!",
  ["PokemaniacDonaldSeenText"] = "Acho que você tem\nuns POKéMON raros\vaí com você.\fDeixe eu ver!",
  ["PokemaniacEthanAfterBattleText"] = "A LILY é legal,\nmas a MARY é a\fmelhor!\nQuero conhecer as\vrádios de JOHTO!",
  ["PokemaniacEthanSeenText"] = "Você conhece a\nLILY? Ela é uma\vDJ de KANTO.",
  ["PokemaniacIssacAfterBattleText"] = "Seus POKéMON vão\ngostar mais de\fvocê se der um\ntrato no pelo.",
  ["PokemaniacIssacSeenText"] = "Meus POKéMON\nacabaram de tosar\fVou mostrar como\neles são fortes!",
  ["PokemaniacLarryAfterBattleText"] = "Toda sexta dá para\nouvir rugidos de\fPOKéMON lá do\nfundo da caverna.",
  ["PokemaniacLarryBeatenText"] = "Ugh. Meus pobres\nPOKéMON…",
  ["PokemaniacLarrySeenText"] = "Eu ando por toda\nparte procurando\vPOKéMON.\fVocê também está\nprocurando?\fEntão você é meu\nrival de coleção!",
  ["PokemaniacRonAfterBattleText"] = "Não tem problema\nas pessoas\fgostarem de tipos\ndiferentes.\fPOKéMON não é só\nter o mais\vpoderoso.",
  ["PokemaniacRonBeatenText"] = "Meu NIDOKING foi\nmuito bem!",
  ["PokemaniacRonSeenText"] = "Você acredita\nnisso?\fUm cara chamado\n{RIVAL} zoou os\vmeus POKéMON!\fDroga! Meu POKéMON\né ótimo!",
  ["PokemaniacShaneAfterBattleText"] = "Você está fazendo\numa POKéDEX?\fUau, deve conhecer\nalguns POKéMON\vbem raros!\fPosso ver?\nPor favor?",
  ["PokemaniacShaneBeatenText"] = "Devia ter usado\na MOON STONE…",
  ["PokemaniacShaneSeenText"] = "EI!\fEste é o meu lugar\nsecreto! Some,\vseu forasteiro!",
  ["PokemaniacZachAfterBattleText"] = "Se um POKéMON tem\ncores diferentes\fdo normal, ele\nvale mais.\fO quê? Isso não\né verdade?",
  ["PokemaniacZachBeatenText"] = "Oooh, seus POKéMON\nsão atraentes.",
  ["PokemaniacZachSeenText"] = "Faço qualquer\ncoisa para pôr a\vmão em raros!",
  ["PokemonFanClubBraggingSignText"] = "Se alguém se gaba,\ngabe-se também!",
  ["PokemonFanClubChairmanDidYouVisitToHearAboutMyMonText"] = "Eu sou o CHAIRMAN\ndo POKéMON FAN\vCLUB.\fJá criei mais de\n150 POKéMON.\fEu sou bem\nexigente quando o\vassunto é POKéMON\fVocê veio só para\nouvir sobre os\vmeus POKéMON?",
  ["PokemonFanClubChairmanHowDisappointingText"] = "Que decepção…\fVolte se quiser\nouvir.",
  ["PokemonFanClubChairmanIWantYouToHaveThisText"] = "Obrigado por me\nouvir. Quero que\vfique com isto!",
  ["PokemonFanClubChairmanItsARareCandyText"] = "É um RARE CANDY\nque deixa POKéMON\vmais forte.\fEu prefiro deixar\nos meus fortes\fbatalhando, então\nfique com ele.",
  ["PokemonFanClubChairmanMoreTalesToTellText"] = "Olá, {PLAYER}!\fVeio me ver de\nnovo para falar\vdos meus POKéMON?\fNão? Ah… eu tinha\nmais histórias…",
  ["PokemonFanClubChairmanRapidashText"] = "Ótimo!\nEntão escute!\fBom… meu RAPIDASH\nfavorito…\fEle… fofo… lindo…\nesperto… demais…\ve… incrível… ah…\vvocê acha?…\vDemais… selvagem…\vbelo… gentil…\veu amo ele!\fAbraçar… quando…\ndorme… quentinho…\ve fofo… Ah, e…\vespetacular…\varrebatador…\vdivino…\vOpa! Olha a hora!\vPrendi você tempo\vdemais!",
  ["PokemonFanClubClefairyDollText"] = "É um CLEFAIRY!\nHã?\fAh, é mesmo. É uma\nPOKé DOLL de\vCLEFAIRY.",
  ["PokemonFanClubClefairyGuyClefairyIsSoAdorableText"] = "Eu amo o jeito\nque o CLEFAIRY\fbalança o dedo\nquando vai usar\fMETRONOME.\nÉ tão adorável!",
  ["PokemonFanClubClefairyGuyGoingToGetARealClefairyText"] = "Você vai ver. Eu\nvou conseguir\fum CLEFAIRY de\nverdade de amigo.",
  ["PokemonFanClubClefairyGuyMakingDoWithADollIFoundText"] = "Eu amo CLEFAIRY,\nmas nunca peguei\fum. Então me viro\ncom uma\fPOKé DOLL que eu\nachei.",
  ["PokemonFanClubClefairyGuyPackIsJammedFullText"] = "Sua BOLSA está\nlotada.",
  ["PokemonFanClubClefairyGuyTakeThisDollBackToGirlText"] = "Ah, entendi. A\nmenina que perdeu\festa DOLL sofre…\fCerto. Você leva\nesta POKé DOLL\fde volta para a\ncoitadinha?\fEu ainda faço\namizade com um\fCLEFAIRY um dia.\nSem problema!",
  ["PokemonFanClubListenSignText"] = "Vamos ouvir os\noutros treinadores\vcom educação.",
  ["PokemonFanClubPlayerReceivedDollText"] = "{PLAYER} recebeu\nPOKé DOLL.",
  ["PokemonFanClubReceptionistText"] = "Nosso CHAIRMAN\nfala demais quando\vé sobre POKéMON…",
  ["PokemonFanClubSignText"] = "POKéMON FAN CLUB\fTodos os Fãs de\nPOKéMON",
  ["PokemonFanClubTeacherText"] = "Olha o meu querido\nBAYLEEF!\fA folha na cabeça\ndele é tão fofa!",
  ["PowerPlantGymGuide1GeneratorUpAndRunningText"] = "O gerador está\nligado e no ar.\fEstá gerando\neletricidade!",
  ["PowerPlantGymGuide1SomeoneStoleAPartText"] = "Alguém levou\numa peça que é\fessencial para\no gerador.\fSem ela, o\ngerador novo\vnão serve!",
  ["PowerPlantGymGuide2GeneratorIsRunningAgainText"] = "O gerador está\nrodando de novo!",
  ["PowerPlantGymGuide2PowerPlantUpAndRunningText"] = "Esta POWER PLANT\ntinha sido\vabandonada.\fNós reativamos\nela pra dar\fenergia pro\nMAGNET TRAIN.",
  ["PowerPlantGymGuide4MagnetTrainConsumesElectricityText"] = "O MAGNET TRAIN\ngasta muita\veletricidade.\fNão anda se o\nnovo gerador\vnão funciona.",
  ["PowerPlantGymGuide4WeCanGetMagnetTrainRunningText"] = "Legal! Podemos\nfinalmente pôr o\fMAGNET TRAIN\nde novo no ar!",
  ["PowerPlantManagerIWontForgiveCulpritText"] = "MANAGER: Não vou\nperdoar não!\fO culpado pode\nchorar, pedindo\fperdão, mas ainda\nvou moer ele!\fHahahahaha!",
  ["PowerPlantManagerMyBelovedGeneratorText"] = "MANAGER: Meu\namado gerador!\fContinua soltando\neletricidade!",
  ["PowerPlantManagerTM07IsZapCannonText"] = "MANAGER: TM07 é\nmeu ZAP CANNON.\fÉ uma técnica\npoderosa!\fNão é bem\nprecisa, mas\facerta em cheio!\nBate forte!",
  ["PowerPlantManagerTakeThisTMText"] = "Uau! Valeu!\fTome este TM\ncomo recompensa!",
  ["PowerPlantManagerThatsThePartText"] = "MANAGER: Ah! Sim!\fÉ a PART que\nfaltava do meu\vquerido gerador!\vVocê achou?",
  ["PowerPlantManagerWhoWouldRuinMyGeneratorText"] = "MANAGER: Eu vou\nexplodir alguém!\vQuem se atreve\fa estragar meu\ngerador?\fGastei tanto\ntempo nele!\fSe eu pegar,\nele vai ver o que\fé um ZAP\nCANNON!",
  ["PowerPlantOfficer1AThiefBrokeInText"] = "Um ladrão invadiu\na POWER PLANT…\fO que o mundo\nestá virando?",
  ["PowerPlantOfficer1CeruleanShadyCharacterText"] = "Acabei de saber\nde CERULEAN.\fAo que parece,\num sujeito\festranho anda\nrondando por aí.",
  ["PowerPlantOfficer1CouldIAskForYourCooperationText"] = "Posso pedir sua\ncooperação?",
  ["PowerPlantOfficer1HaveToBeefUpSecurityText"] = "Vamos ter que\nreforçar nossa\vsegurança.",
  ["PowerPlantOfficer2ManagerHasBeenCheerfulText"] = "Como o gerador\nfoi consertado,\fo MANAGER está\nbem animado.",
  ["PowerPlantOfficer2ManagerHasBeenSadAndFuriousText"] = "O MANAGER da\nPOWER PLANT está\vlogo à frente.\fMas como alguém\nquebrou o gerador,\vele ficou\vtriste e\vfurioso…",
  ["PowerPlantSignText"] = "KANTO POWER PLANT",
  ["PrintDayCareText.HaveNoRoomText"] = "Você não tem\nespaço para isto.",
  ["PrintDayCareText.NotEnoughMoneyText"] = "Você não tem\ndinheiro.",
  ["PryceText_CherishYourPokemon"] = "Quando o gelo e a\nneve derretem, a\vprimavera chega.\fVocê e seus\nPOKéMON vão ficar\fjuntos por muitos\nanos ainda.\fValorize o tempo\nde vocês!",
  ["PryceText_GlacierBadgeSpeech"] = "Essa BADGE aumenta\nos status SPECIAL\vdos POKéMON.\fEla também deixa\nseu POKéMON usar\vWHIRLPOOL para\vcruzar redemoinho\fE isto… Isto é um\npresente meu!",
  ["PryceText_IcyWindSpeech"] = "Essa TM contém o\nICY WIND.\fEle causa dano e\nreduz VELOCIDADE.\fEle demonstra\na dureza do\vinverno.",
  ["PryceText_Impressed"] = "Ah, estou\nimpressionado com\vvocê.\fCom essa vontade\nforte, você vai\fsuperar todos os\nobstáculos.\fVocê é digno desta\nBADGE!",
  ["PryceText_Intro"] = "POKéMON vivem\nmuitas coisas na\fvida deles, assim\ncomo nós.\fEu também já vi\ne sofri muito\vna minha vida.\fComo sou mais\nvelho, deixe eu\vmostrar o que é.\fEstou com POKéMON\ndesde antes\fde você\nnascer.\fEu não perco\nfácil.\fEu, PRYCE, o\ntreinador do\finverno, vou\nmostrar meu poder",
  ["PsychicFidelAfterBattleText"] = "Força na\nconvicção…\fVocê é forte\nporque acredita\vnos seus POKéMON.",
  ["PsychicFidelBeatenText"] = "Não previ a sua\nforça…",
  ["PsychicFidelSeenText"] = "Eu consigo ver…\fTudo o que há\npara ver em você…",
  ["PsychicFranklinAfterBattleText"] = "Você fortaleceu a\nalma, não só as\vhabilidades.",
  ["PsychicFranklinBeatenText"] = "Sua alma tem mais\nforça que a minha",
  ["PsychicFranklinSeenText"] = "O poder psíquico\né o poder da sua\valma.",
  ["PsychicGilbertAfterBattleText"] = "Com sua força,\nvocê vai bem na\vLEAGUE.\fÉ o que diz minha\npremonição.",
  ["PsychicGilbertBeatenText"] = "Você é demais!",
  ["PsychicGilbertSeenText"] = "Não diga nada!\fDeixe-me adivinhar\no que você pensa.\fMmmmmmm…\fAchei! Você está\nno desafio da\vLEAGUE POKéMON!",
  ["PsychicGregAfterBattleText"] = "Fazer o POKéMON\ndormir ou deixar\vele paralisado são\vboas técnicas.",
  ["PsychicGregBeatenText"] = "Perdi. Que\ntristeza…",
  ["PsychicGregSeenText"] = "POKéMON não fazem\nnada se estiverem\vdormindo.\fVou mostrar como\nisso é assustador",
  ["PsychicHermanAfterBattleText"] = "…\fPerdi de olhos\nfechados…",
  ["PsychicJaredAfterBattleText"] = "O KARATE KING,\nmestre do\fFIGHTING DOJO, foi\narrasado agora\vpela SABRINA.",
  ["PsychicJaredSeenText"] = "O FIGHTING DOJO\ndo lado já foi\vo GINÁSIO daqui.",
  ["PsychicMarkAfterBattleText"] = "Eu seria forte\nse pudesse saber\fo que meu oponente\nestá pensando.",
  ["PsychicMarkSeenText"] = "Vou ler os\nseus pensamentos!",
  ["PsychicNathanAfterBattleText"] = "Gosto de pensar\naqui.",
  ["PsychicNathanSeenText"] = "Hmmm… Este é um\nlugar estranho.",
  ["PsychicNormanAfterBattleText"] = "Sabe como cada\nPOKéMON tem uma\vhabilidade?\fCom gente é igual\nCada um tem um\vpotencial\vdiferente.",
  ["PsychicNormanBeatenText"] = "Ooh, seus POKéMON\ntêm potencial.",
  ["PsychicNormanSeenText"] = "Deixa eu ver do\nque os seus\vPOKéMON são bons.",
  ["PsychicPhilAfterBattleText"] = "É importante ter\nconvicção do seu\vlado.",
  ["PsychicPhilBeatenText"] = "Arrgh… Que\nderrota chocante…",
  ["PsychicPhilSeenText"] = "Eu vou ganhar,\ncom certeza!",
  ["PsychicRichardAfterBattleText"] = "Pessoas e POKéMON\ncrescem com suas\vexperiências.\fNão fique parado\ne acomodado.",
  ["PsychicRichardSeenText"] = "Uau, olha todas\nessas BADGES!\vImpressionado.\fMas você não\nse satisfaz só\fcoletando elas,\nné?",
  ["PsychicRodneyAfterBattleText"] = "Entendi. Dá para\nouvir a rádio de\vJOHTO no navio.",
  ["PsychicRodneyBeatenText"] = "…Estou ouvindo\nalguma coisa!",
  ["PsychicRodneySeenText"] = "Psiu! Meu cérebro\nestá captando\vsinais de rádio!",
  ["RadioTower1FDirectoryText"] = "1F RECEPÇÃO\n2F VENDAS\f3F PESSOAL\n4F PRODUÇÃO\f5F SALA DO\n   DIRETOR",
  ["RadioTower1FLassText"] = "O BEN é um DJ\nfabuloso.\fA voz doce dele\nme derrete!",
  ["RadioTower1FLuckyChannelSignText"] = "LUCKY CHANNEL!\fGanhe com os IDs\ndos seus POKéMON!\fTroque POKéMON e\ncolecione IDs\vdiferentes!",
  ["RadioTower1FLuckyNumberManAskToPlayText"] = "Oi, você veio pelo\nLUCKY NUMBER\vSHOW?\fQuer que eu veja\nos números de ID\vdos seus POKéMON?\fSe der sorte, você\nganha um prêmio.",
  ["RadioTower1FLuckyNumberManCheckIfMatchText"] = "Vamos ver se você\nacertou algum.",
  ["RadioTower1FLuckyNumberManComeAgainText"] = "Volte semana que\nvem para o próximo\vLUCKY NUMBER.",
  ["RadioTower1FLuckyNumberManDotDotDotText"] = "……\n……",
  ["RadioTower1FLuckyNumberManNoRoomForYourPrizeText"] = "Não há espaço para\no seu prêmio.\fAbra espaço e\nvolte logo aqui.",
  ["RadioTower1FLuckyNumberManNoneOfYourIDNumbersMatchText"] = "Não, nenhum dos\nseus IDs combina.",
  ["RadioTower1FLuckyNumberManOkayMatchText"] = "Ei! Você acertou\nos três últimos\vnúmeros!\fGanhou o segundo\nprêmio, um EXP.\vSHARE!",
  ["RadioTower1FLuckyNumberManPerfectMatchText"] = "Uau! Você acertou\nos cinco números\vem cheio!\fTemos um ganhador\ndo grande prêmio!\fVocê ganhou uma\nMASTER BALL!",
  ["RadioTower1FLuckyNumberManThisWeeksIdIsText"] = "O número de ID\ndesta semana é\v{RAM:D099}.",
  ["RadioTower1FLuckyNumberManWeakMatchText"] = "Ooh, você acertou\nos dois últimos\vnúmeros.\fGanhou o terceiro\nprêmio, um PP UP.",
  ["RadioTower1FPokegearIsARadioText"] = "A POKéGEAR de\n{PLAYER} agora toca\vrádio também!",
  ["RadioTower1FRadioCardWomanNotTakingQuizText"] = "Ah. Entendo. Tente\nde novo se mudar\vde ideia.",
  ["RadioTower1FRadioCardWomanOfferQuizText"] = "Temos uma promoção\nde quiz especial\vrolando agora.\fAcerte cinco\nperguntas e ganhe\vum RADIO CARD.\fEncaixe ele na sua\nPOKéGEAR e toque\fo rádio a qualquer\nhora e lugar.\fQuer responder ao\nquiz?",
  ["RadioTower1FRadioCardWomanQuestion1Text"] = "Pergunta 1:\fO TOWN MAP pode\nser exibido em uma\vPOKéGEAR?",
  ["RadioTower1FRadioCardWomanQuestion2Text"] = "Correto!\nPergunta 2:\fNIDORINA pode ser\nsomente fêmea?",
  ["RadioTower1FRadioCardWomanQuestion3Text"] = "Na mosca!\nPergunta 3:\fO KURT, artesão de\nPOKé BALLS, usa\vAPRICORNS?",
  ["RadioTower1FRadioCardWomanQuestion4Text"] = "Até aqui tudo bem!\nPergunta 4:\fMAGIKARP não sabe\naprender TM?",
  ["RadioTower1FRadioCardWomanQuestion5Text"] = "Uau! Certo de novo\nEsta é a última\vpergunta:\fPROF.OAK'S POKéMON\nTALK é um programa\vmuito popular.\fA MARIE é a\ncoapresentadora?",
  ["RadioTower1FRadioCardWomanTuneInText"] = "Sintonize nossos\nshows de rádio.",
  ["RadioTower1FRadioCardWomanWrongAnswerText"] = "Ah, que pena.\nSinto muito, mas\fvocê errou.\nTente de novo!",
  ["RadioTower1FRadioCardWomanYouWinText"] = "Bingo! Acertou!\nParabéns!\fEste é seu prêmio,\num RADIO CARD!",
  ["RadioTower1FReceptionistNoToursText"] = "Olá. Sinto muito,\nmas hoje não temos\vvisitas guiadas\vdisponíveis.",
  ["RadioTower1FReceptionistWelcomeText"] = "Bem-vindo!",
  ["RadioTower1FYoungsterText"] = "Adoro a MARY, do\nPOKéMON TALK.\fSó conheço a voz\ndela, mas nunca\va vi.",
  ["RadioTower2FBlackBelt1Text"] = "Desculpe. Somente\npessoal autorizado\valém daqui.\fNão era assim\nantes.\fAlgo esta errado\ncom o DIRETOR\v…",
  ["RadioTower2FBlackBelt2Text"] = "Sinta-se livre\npara olhar.\fO DIRETOR esta\nbom de novo,\vcomo era antes.",
  ["RadioTower2FBuenaAlreadyPlayedText"] = "BUENA: Desculpe…\fVocê só tem uma\nchance por dia.\fVolte amanhã pra\ntentar de novo!",
  ["RadioTower2FBuenaCallMeText"] = "BUENA: Vou adorar\nouvir você!",
  ["RadioTower2FBuenaCardIsFullText"] = "BUENA: Seu BLUE\nCARD está cheio.\fTroque por um\nprêmio incrível!",
  ["RadioTower2FBuenaComeBackAfterListeningText"] = "BUENA: Volte\ndepois de ouvir\fmeu programa, tá?\nAté mais!",
  ["RadioTower2FBuenaCorrectAnswerText"] = "BUENA: EBAAA!\nAcertou!\fVocê sintonizou!\nQue felicidade!\fGanhou um ponto!\nParabéns!",
  ["RadioTower2FBuenaDidYouForgetText"] = "BUENA: Ah…\nNão é isso…\fEsqueceu a\nsenha?",
  ["RadioTower2FBuenaDoYouKnowPasswordText"] = "BUENA: Oi!\nVocê sintonizou\vmeu programa?\fLembra a senha\nde hoje?",
  ["RadioTower2FBuenaEveryoneSayPasswordText"] = "BUENA: Todo mundo\npronto?\fQuero ouvir vocês\ngritarem a senha\fde hoje pro\n{PLAYER}!",
  ["RadioTower2FBuenaJoinTheShowText"] = "BUENA: Nossa!\nObrigada!\fQual era seu\nnome mesmo?\f…{PLAYER}, certo!\fVem, {PLAYER}.\nEntra no show.",
  ["RadioTower2FBuenaNoBlueCardText"] = "BUENA: Ah? Você\nesqueceu de\vtrazer seu BLUE\vCARD?\fNão posso dar\npontos se você\vnão tem ele.",
  ["RadioTower2FBuenaOfferNumberAgainText"] = "BUENA: {PLAYER},\nvocê quer\fregistrar meu\nnúmero?",
  ["RadioTower2FBuenaOfferPhoneNumberText"] = "BUENA: Ah! Seu\nBLUE CARD chegou\fa 30 pontos hoje!\nQue incrível!\fHum… Não tem\nprêmio por chegar\va 30, mas…\fVocê veio tanto,\n{PLAYER}.\fVou fazer uma\noferta especial!\fQue tal o meu\nnúmero de\vtelefone?",
  ["RadioTower2FBuenaPasswordIsHelpText"] = "BUENA: Hã?\nA senha de hoje?\fHELP, é claro!",
  ["RadioTower2FBuenaReceptionistNoCardText"] = "Não dá pra trocar\npontos sem\vseu BLUE CARD.\fNão esqueça seu\nBLUE CARD!",
  ["RadioTower2FBuenaReceptionistPointsForPrizesText"] = "Você pode trocar\nseus pontos\fpor um prêmio\nlindo, à escolha!",
  ["RadioTower2FBuenaSadRejectedText"] = "BUENA: Ah… É um\nprêmio especial…",
  ["RadioTower2FBuenaShowIntroductionText"] = "BUENA: Oi! Eu sou\na BUENA!\fVocê conhece um\nprograma de rádio\vchamado PASSWORD?\fSe você me disser\na senha do\fprograma, você\nganha pontos.\fGuarde esses\npontos e troque\fcom aquela moça\ndoce ali\fpor prêmios\nà escolha!\fAqui está!\fSeu próprio\ncartão de pontos!",
  ["RadioTower2FBuenaThanksForComingText"] = "BUENA: Isso!\nNosso convidado\ffoi {PLAYER}.\nObrigada por vir!\fEspero que todos\nvocês ouvintes\fvenham também!\nVou esperar!",
  ["RadioTower2FBuenaTuneInAfterSixText"] = "BUENA: Sintonize\no PASSWORD\ftoda noite das 6\nà meia-noite!\fSintonize e venha\nfazer uma visita!",
  ["RadioTower2FBuenaTuneInToMyShowText"] = "BUENA: Sintonize\no PASSWORD SHOW!",
  ["RadioTower2FBuenaYourPhoneIsFullText"] = "BUENA: {PLAYER},\nsua lista de\ftelefones não tem\nespaço pra mim…",
  ["RadioTower2FOaksPKMNTalkSignText"] = "TALK POKéMON\nDO PROF.OAK\fO Show Mais Quente\nno Ar!",
  ["RadioTower2FPokemonRadioSignText"] = "Em Qualquer Lugar\nPOKéMON Radio",
  ["RadioTower2FRegisteredBuenasNumberText"] = "{PLAYER} salvou o\nnúmero da BUENA.",
  ["RadioTower2FSalesSignText"] = "2F VENDAS",
  ["RadioTower2FSuperNerdText"] = "Você pode ouvir\na radio em\vqualquer lugar.",
  ["RadioTower2FTeacherText"] = "Canções de ninar\nna radio podem\vfazer dormir.",
  ["RadioTower2FTeacherText_Rockets"] = "Por que eles\nquerem tomar conta\vda RADIO TOWER?",
  ["RadioTower3FCardKeySlotText"] = "E o slot da\nCHAVE-CARTAO.",
  ["RadioTower3FCooltrainerFIsDirectorSafeText"] = "O DIRETOR\nesta seguro?",
  ["RadioTower3FCooltrainerFItsSunnyDayText"] = "E SUNNY DAY.\nFortalece\vmovimentos de fogo\vpor um tempo.",
  ["RadioTower3FCooltrainerFPleaseSaveDirectorText"] = "O chefe da TEAM\nROCKET trancou\vele mesmo lá.\fMas o DIRETOR\npode abrir.\fEle esta no\nquinto andar.\fSalve-o!",
  ["RadioTower3FCooltrainerFYouWereMarvelousText"] = "Você foi\nmaravilhoso!",
  ["RadioTower3FCooltrainerFYoureMyHeroText"] = "Obrigado!\nVocê e meu herói!\fIsto e um simbolo\nde gratidão.",
  ["RadioTower3FGymGuideText"] = "Trabalhamos 24h\npor dia para\ftransmitir\nprogramas legais.\fVou dar o meu\nmelhor para\vtrabalhar!",
  ["RadioTower3FGymGuideText_Rockets"] = "Para treinadores,\nPOKéMON são\vseus parceiros.\fE terrível como a\nTEAM ROCKET esta\ftentando controlar\nPOKéMON.",
  ["RadioTower3FPersonnelSignText"] = "3F PESSOAL",
  ["RadioTower3FPokemonMusicSignText"] = "MÚSICA POKéMON\ncom o DJ BEN",
  ["RadioTower3FSuperNerdText"] = "Temos gravações\ndos gritos de\ftodos os POKéMON\nencontrados.\fDevemos ter uns\n200 tipos.",
  ["RadioTower4FDJMaryText"] = "MARY: Por que?\nPor que tenho que\vsofrer com isso?\fMEOWTH me ajuda!",
  ["RadioTower4FDJMaryText_After"] = "MARY: Por favor,\nsintonize no\fmeu programa\nTALK POKéMON.",
  ["RadioTower4FDJMaryText_ClearedRockets"] = "MARY: Oh! Você e\nmeu salvador!\fVai aceitar isso\ncomo obrigada?",
  ["RadioTower4FDJMaryText_GivePinkBow"] = "MARY: E perfeito\npara POKéMON\fque conhecem\nataques normais.",
  ["RadioTower4FFisherText"] = "Ouvi a radio\nquando estava\vnas RUÍNAS.\fOuvi uma\ntransmissão lá.",
  ["RadioTower4FProductionSignText"] = "4F PRODUCAO",
  ["RadioTower4FStudio2SignText"] = "4F ESTUDIO 2",
  ["RadioTower5FDirectorDescribeClearBellText"] = "Antigamente tinha\numa torre bem\vaqui na CIDADE DE\vGOLDENROD.\fMas ela era velha\ne rangia.\fEntão trocamos\npela nossa RADIO\vTOWER.\fAchamos esse\nsino durante a\vconstrução.\fOuvi dizer que\nvários POKéMON\fviviam em\nGOLDENROD antes.\fTalvez…\fEsse sino tenha\nalguma ligação\fcom a TIN TOWER\nem CIDADE DE\vECRUTEAK…\fAh!\fIsso me lembra…\fOuvi a TEAM ROCKET\ncochichando.\fParece que tem\nalgo acontecendo\vna TIN TOWER.\fNão sei o que\nestá acontecendo,\fmas você devia\ndar uma olhada.\fBom, é melhor eu\nir pro meu\vESCRITÓRIO.",
  ["RadioTower5FDirectorText"] = "DIRETOR: Ola,\n{PLAYER}!\fSabe, eu amo\nPOKéMON.\fConstrui esta\nRADIO TOWER para\fexpressar meu amor\npor POKéMON.\fSeria bom se as\npessoas curtissem\vnossos programas.",
  ["RadioTower5FDirectorThankYouText"] = "DIRETOR: {PLAYER},\nobrigado!\fSuas ações\ncorajosas\fsalvaram POKéMON\nem todo o pais.\fSei que não e\nmuito, mas por\vfavor, aceite.",
  ["RadioTower5FDirectorsOfficeSignText"] = "5F ESCRITORIO\nDO DIRETOR",
  ["RadioTower5FRocketBossAfterText"] = "Como pode ser?\fNossos sonhos se\ntornaram nada.\fNão fui a altura\nda tarefa afinal.\fComo GIOVANNI fez\nantes de mim,\fvou dissolver a\nTEAM ROCKET hoje.\fAdeus.",
  ["RadioTower5FRocketBossBeforeText"] = "Oh? Você conseguiu\nchegar até aqui?\fVocê deve ser um\nbom treinador.\fNossos planos são\ntomar esta RADIO\fESTACAO e anunciar\nnosso retorno.\vIsso deve trazer\fnosso chefe\nGIOVANNI de volta\fde seu treinamento\nsolo.\fVamos recuperar\nnossa glória\vanterior.\fNão vou permitir\nque você atrapalhe\vnossos planos.",
  ["RadioTower5FRocketBossWinText"] = "Não! Perdoe-me,\nGIOVANNI!",
  ["RadioTower5FStudio1SignText"] = "5F ESTUDIO 1",
  ["RadioTowerJigglypuffText"] = "JIGGLYPUFF:\nJiggly…",
  ["RadioTowerMeowthText"] = "MEOWTH: Meowth…",
  ["RageCandyBarMerchantNoRoomText"] = "Você não tem\nespaço para isto.",
  ["RageCandyBarMerchantNotEnoughMoneyText"] = "Você não tem\ndinheiro.",
  ["RageCandyBarMerchantRefusedText"] = "Ah, tudo bem…",
  ["RageCandyBarMerchantSavorItText"] = "Ótimo! Aproveite!",
  ["RageCandyBarMerchantSoldOutText"] = "O RAGECANDYBAR\nesgotou.\fEstou fechando.\nNão me amole,\vgarotinho.",
  ["RageCandyBarMerchantTryOneText"] = "Oi, garotinho! Vi\nque você é novo em\vCIDADE DE\vMAHOGANY.\fJá que é novo aqui\ntem que provar um\fdelicioso\nRAGECANDYBAR!\fAgora mesmo, é seu\npor apenas ¥300!\vQuer um?",
  ["ReceivedBoulderBadgeText"] = "{PLAYER} recebeu\na BOULDERBADGE.",
  ["ReceivedCascadeBadgeText"] = "{PLAYER} recebeu\na CASCADEBADGE.",
  ["ReceivedEeveeText"] = "{PLAYER} recebeu\num EEVEE!",
  ["ReceivedMarshBadgeText"] = "{PLAYER} recebeu\na MARSHBADGE.",
  ["ReceivedSecretpotionText"] = "{PLAYER} recebeu\na SECRETPOTION.",
  ["ReceivedThunderBadgeText"] = "{PLAYER} recebeu\na THUNDERBADGE.",
  ["ReceivedVolcanoBadgeText"] = "{PLAYER} recebeu\na VOLCANOBADGE.",
  ["ReceivedZephyrBadgeText"] = "{PLAYER} recebeu\na ZEPHYRBADGE.",
  ["RecordedBillsNumberText"] = "{PLAYER} anotou\no número do BILL.",
  ["RedsHouse1FTVText"] = "Tem programas aqui\nque não passam\vem JOHTO…",
  ["RedsHouse2FN64Text"] = "{PLAYER} jogou o\nN64.\fMelhor ir andando,\nnão há tempo!",
  ["RedsHouse2FPCText"] = "Parece que isto\nnão é usado\vfaz muito tempo…",
  ["RedsHouseSignText"] = "CASA do RED",
  ["RedsMomText1"] = "Oi!\fO RED está fora\nfaz muito tempo.\fE também não\nligou, então eu\fnão faço ideia de\nonde ele está nem\vdo que faz.\fDizem que sem\nnotícia é sinal\fde que vai bem,\nmas eu me\vpreocupo com ele.",
  ["RedsMomText2"] = "Fico com medo do\nRED se machucar\fou ficar doente,\nmas ele é rapaz.\fTenho orgulho de\nele fazer o que\fquer.",
  ["RhydonText"] = "RHYDON: Grogoh\ngrugrooh!",
  ["RivalCherrygroveLossText"] = "Hunf. Isso foi\nperda de tempo.",
  ["RivalCherrygroveWinText"] = "Hunf. Feliz por\nter ganhado?",
  ["RivalText_Training1"] = "…\nO quê? {PLAYER}?\f…Não, não vou\nbatalhar agora…\fMeus POKéMON\nnão estão prontos\fNão posso\nforçá-los agora.\fPreciso ser\ndisciplinado\fpara me tornar\no maior treinador",
  ["RivalText_Training2"] = "…\fUfa…\fAprenda a\nse afastar.",
  ["RockSmashGuyText1"] = "Wa-hey!\fEu ia quebrar\nessa árvore\fcom meu soco\ndireto.\fMas não consegui!\nSou um fracasso!",
  ["RockSmashGuyText2"] = "Você tirou\naquela árvore?\fImpressionado!\nQuero que você\vtenha isso.",
  ["RockSmashGuyText3"] = "Isso e ROCK SMASH.\nVocê pode quebrar\fpedras com um\nsó golpe bem\fmirado.\nSe houver pedras\fno seu caminho,\napenas quebre\vtodas!",
  ["RockerBaseLanceElectrodeFaintText"] = "É esta máquina\nque está causando\vtodo o problema.\fNão vejo nenhum\nbotão nela…\fNão temos escolha.\nVamos ter que\fderrubar todos os\nELECTRODE.\fIsso deve impedir\na máquina de\ftransmitir aquele\nsinal estranho.\fOs POKéMON não têm\nculpa, então isso\fme deixa com\nremorso.\f{PLAYER}, vamos\ndividir a tarefa.",
  ["RocketBaseB2FDeactivateTransmitterText"] = "O transmissor de\nrádio finalmente\fparou a\ntransmissão\vmaligna.",
  ["RocketBaseB2FTransmitterText"] = "É o transmissor\nde rádio que está\fmandando o sinal\nsinistro.\fEstá funcionando\na todo vapor.",
  ["RocketBaseBossDontMeddleText"] = "O quê? Você tinha\num cúmplice?\fCadê o seu\nsenso de honra?\fComo chefe\ninterino no lugar\fdo GIOVANNI, vou\nmostrar o erro\fque é se meter\ncom a TEAM ROCKET",
  ["RocketBaseBossFThrashText"] = "Não podemos ter um\npirralho como você\vsolto por aí.\fFaz mal para o\norgulho da TEAM\vROCKET, sabe.\fPor mais forte que\nseja, não dá para\fencarar nós dois\nao mesmo tempo.\fSinto muito, bebê.\nPrepare-se para\vapanhar.",
  ["RocketBaseBossRetreatText"] = "…Este esconderijo\njá era…\fMas tudo bem.\nO experimento de\vtransmissão foi um\vsucesso total.\fNão importa mais\no que acontece\vcom este lugar.\fTemos planos bem\nmaiores.\fVocê vai conhecer\no verdadeiro\fpoder da TEAM\nROCKET em breve.\fAproveite enquanto\npode…\fFufufufu…",
  ["RocketBaseBossWinText"] = "Tch, você é forte\nmesmo.\fQue pena.\fSe você entrasse\nna TEAM ROCKET,\fpodia virar um\nEXECUTIVO.",
  ["RocketBaseDoorKnowPasswordText"] = "A porta fechou…\f{PLAYER} digitou\na senha.\fA porta abriu!",
  ["RocketBaseDoorNoPasswordText"] = "A porta fechou…\fPrecisa de senha\npara abrir.",
  ["RocketBaseExecutiveFHoldItText"] = "Pare bem\naí!",
  ["RocketBaseLanceElectrodeDoneText"] = "LANCE: Aquele\nsinal estranho\vfinalmente parou.\fO LAKE deve estar\nnormal de novo.\fVocê é o herói!\nMuito obrigado\fem nome de todos\nos POKéMON.\fAh, sim. Você\ndevia levar isto.\fAchei aqui, mas\nnão tenho uso\vnenhum para isso.",
  ["RocketBaseLanceMonMasterText"] = "{PLAYER}…\fO caminho até se\ntornar MESTRE\fPOKéMON é longo e\ndifícil.\fSabendo disso,\nvocê vai seguir?\f…\fEntendo. Não, você\ntem razão.\fSe desistisse\nassim tão fácil,\fnunca teria\ncorrido atrás\fdesse sonho para\ncomeçar.\fEspero ver você\nde novo!",
  ["RocketBaseLancePostBattleText"] = "LANCE: É isso.\nDerrotamos todos\fos ROCKETS daqui.\fMas estou\npreocupado com o\vrapaz\fcom quem batalhei\nno caminho…",
  ["RocketBaseLancePowerOffText"] = "Desculpe, {PLAYER}\nVi como você ia\fbem, então eu só\nfiquei de fora.\fAgora só falta\numa coisa:\fdesligar aquele\nsinal de rádio.",
  ["RocketBaseLanceShareFunText"] = "Ei! Não seja tão\negoísta. Divida a\vdiversão.",
  ["RocketBaseLanceWhirlpoolText"] = "É o WHIRLPOOL.\nEnsine para um\fPOKéMON e cruze\náguas revoltas.\fMas lembre-se\nde uma coisa.\fSó dá para usar\nfora de batalha\fcom a BADGE do\nGINÁSIO MAHOGANY.",
  ["RocketBaseLancesSideText"] = "LANCE: Deixe este\nlado comigo.",
  ["RocketBaseMurkrowText"] = "MURKROW: A senha\né…\fSALVE GIOVANNI.",
  ["RocketBaseRivalText"] = "…\fEu não disse que\neu ia\fdestruir a TEAM\nROCKET?\f…Me diga, quem era\no cara de capa\fque usava POKéMON\ndragão?\fMeus POKéMON não\nforam páreo.\fNão ligo de ter\nperdido. Eu venço\fele com POKéMON\nmais fortes.\fO que me incomoda\né o que ele falou\fEle disse que eu\nnão amo e não\fconfio o bastante\nnos meus POKéMON.\fFico furioso de\nter perdido para\vum bonzinho.\f…Hunf! Não tenho\ntempo para gente\vcomo você!",
  ["RocketText_AllYouGot"] = "Então pague o que\ntiver, por favor.",
  ["RocketText_MakingABundle"] = "Hihihi. Estamos\nenchendo o bolso.\fTodo mundo quer\nver o que rola\fno LAKE OF\nRAGE.",
  ["RocketText_ThankYou"] = "Obrigado, senhor!",
  ["RocketText_TollFee"] = "Pare aí, moço!\nmoço!\fO pedágio é ¥1000\npara passar.",
  ["Route10Pokecenter1FCooltrainerFText"] = "Quando você sai,\ndá pra ver o\ftelhado de um\nprédio grande.\fEssa é a POWER\nPLANT.",
  ["Route10Pokecenter1FGentlemanText"] = "Um CENTRO POKéMON\nperto de caverna?\fIsso é muito\nconveniente!",
  ["Route10Pokecenter1FGymGuideText"] = "O MANAGER da\nPOWER PLANT quer\fachar um homem\ncom POKéMON bom.\fEle precisa de\najuda pra pegar\fde volta algo que\nfoi roubado.",
  ["Route10Pokecenter1FGymGuideText_ReturnedMachinePart"] = "Ouvi que a TEAM\nROCKET se reuniu\fde novo em JOHTO,\nmas se desfez.\fEu não sabia\nde nada disso.",
  ["Route10SignText"] = "ROTA 10\fCIDADE DE CERULEAN\nCIDADE DE LAVENDER",
  ["Route11SignText"] = "ROTA 11",
  ["Route12SignText"] = "ROTA 12\fNORTE: CIDADE DE\nLAVENDER",
  ["Route13DirectionsSignText"] = "Norte: CIDADE DE\nLAVENDER\fOeste: CIDADE DE\nFUCHSIA",
  ["Route13SignText"] = "ROTA 13\fNorte: SILENCE\nBRIDGE",
  ["Route13TrainerTipsText"] = "DICAS de TREINO\fOlhe! Bem ali,\nno lado esquerdo\vdo poste.",
  ["Route15FuchsiaGateOfficerText"] = "Você está fazendo\numa POKéDEX?\fIsso é e tanto.\nNão desista!",
  ["Route15SignText"] = "ROTA 15\fCIDADE DE FUCHSIA\nCIDADE DE LAVENDER",
  ["Route16FuchsiaSpeechHouseSuperNerdText"] = "Se você descer a\nCYCLING ROAD,\fvocê vai parar\nem CIDADE DE\vFUCHSIA.",
  ["Route16GateCannotPassText"] = "Ei! Pare!\fVocê não pode ir\npara a CYCLING\fROAD sem\nBICYCLE.",
  ["Route16GateOfficerText"] = "A CYCLING ROAD\ncomeça aqui. É\ftudo ladeira\nabaixo, e bem\vemocionante!\fUma sensação\nque só se sente\fem navio\nou trem.",
  ["Route17Route18GateCannotPassText"] = "Espera! Você não\ntem BICYCLE?\fA CYCLING ROAD\nfica aqui.\fVocê precisa de\nBICYCLE pra ir",
  ["Route17Route18GateOfficerText"] = "CYCLING ROAD\na subida começa",
  ["Route18SignText"] = "ROTA 18\fCIDADE DE CELADON\nCIDADE DE FUCHSIA",
  ["Route19Fisher1Text"] = "Desculpe. Esta\nestrada está em\vobras.\fSe quiser chegar\na CINNABAR, é\fmelhor ir pro sul\nde CIDADE DE\vPALLET.",
  ["Route19Fisher1Text_RocksCleared"] = "Estou todo suado.\nHora de nadar!",
  ["Route19Fisher2Text"] = "Quem sabe quanto\ntempo pra mover\veste pedregulho…",
  ["Route19Fisher2Text_RocksCleared"] = "As obras na\nestrada\vterminaram.\fAgora posso voltar\na pescar.",
  ["Route19FuchsiaGateOfficerText"] = "O vulcão de\nCINNABAR estourou\fEle jogou pedras\nque fecharam a\vROTA 19 de vez.\fFico pensando se\no povo de CINNABAR\vestá a salvo…",
  ["Route19FuchsiaGateOfficerText_RocksCleared"] = "Nenhum morador de\nCINNABAR se feriu\fcom a erupção.\nQue ótimo!",
  ["Route19SignText"] = "ROTA 19\fCIDADE DE FUCHSIA\nSEAFOAM ISLANDS",
  ["Route1SignText"] = "ROTA 1\fCIDADE DE PALLET\nCIDADE DE VIRIDIAN",
  ["Route24RocketAfterBattleText"] = "OK. Contar meu\nsegredo vou.\fMACHINE PART\neu roubei,\fno GYM de\nCERULEAN escondi.\fNa água pus.\nProcure no\fmeio da água\ndo GYM.\fGaroto, mas\nnão me esqueça!\fGanhar de você\na TEAM ROCKET\fvai. De JOHTO\nvirão meus\famigos. E a\nvingança virá!",
  ["Route24RocketBeatenText"] = "Aiii! Não, não,\nnão, não acredito\vem mim!\fMuito forte\nvocê é! Eu não\vte aguento!",
  ["Route24RocketDisappearsText"] = "…\fO quê? A TEAM\nROCKET tchau\ftchau? Acabou,\ndisse você?\fOh, não! O que\nfaço agora\vcomigo?",
  ["Route24RocketSeenText"] = "Ei, menino! Eu\nda TEAM ROCKET\vsou tipo cara!\fDe outro país\nvim, treinador\vnúmero um, eu!\fPensei eu, se\na energia parar,\fpânico grande\npara daqui gente!\fSegredo meu\nmissão é, então\vnão falo!\fMas! Se batalha\nganhar de mim,\fsou homem e meu\nsegredo conto.\fEi, garoto!\nBatalha começar!",
  ["Route25MistyDateText"] = "MISTY: Aii!\nPor que você\ftinha de vir\nagora?\fSabe como\nchamam gente\vcomo você?\fPraga! Ouviu\ndireito? Praga!\f…\f…Oh? Essas BADGES\nvocê tem… São\vBADGES de JOHTO?\fSe tem oito,\ndeve ser bom.\fCerto, então.\nVem ao GYM.\fVou adorar\nbatalhar contigo!\fSou a MISTY, a\nLÍDER do GYM\vde CERULEAN.",
  ["Route26HealHouseKeepAtItText"] = "Pronto!\fSeus POKéMON estão\ncom boa cara!\fContinue assim!",
  ["Route26HealHouseRestAWhileText"] = "Seus POKéMON estão\nmeio cansados.\fÉ bom deixar eles\ndescansar.",
  ["Route26SignText"] = "ROTA 26\fPOKéMON LEAGUE\nRECEPTION GATE",
  ["Route27FisherHeyText"] = "Ei!",
  ["Route27FisherText"] = "Sabe o que você\nacabou de fazer?\fVocê deu seu\nprimeiro passo\vem KANTO.\fConfira no\nmapa da POKéGEAR",
  ["Route28SignText"] = "ROTA 28",
  ["Route29CooltrainerMText_WaitingForDay"] = "Estou esperando\nPOKéMON que\fsó aparecem\nde dia.",
  ["Route29CooltrainerMText_WaitingForMorning"] = "Estou esperando\nPOKéMON que\fsó aparecem de\nmanhã.",
  ["Route29CooltrainerMText_WaitingForNight"] = "Estou esperando\nPOKéMON que\fsó aparecem à\nnoite.",
  ["Route29FisherText"] = "Quis dar uma\npausa, e salvei\fpara guardar meu\nprogresso.",
  ["Route29Route46GateOfficerText"] = "Não dá para subir\nbarranco.\fMas dá para pular\nde cima deles e\vcortar caminho.",
  ["Route29Route46GateYoungsterText"] = "Tipos diferentes\nde POKéMON surgem\vdepois daqui.\fSe quiser pegar\ntodos eles,\ftem que procurar\nem todo lugar.",
  ["Route29Sign1Text"] = "ROTA 29\fCIDADE DE\vCHERRYGROVE\vCIDADE DE NEW BARK",
  ["Route29Sign2Text"] = "ROTA 29\fCIDADE DE\vCHERRYGROVE\vCIDADE DE NEW BARK",
  ["Route29TeacherText"] = "Viu aqueles\nbarrancos? Dá medo\vpular deles.\fMas dá para ir a\nNEW BARK sem\fpassar pelo\nmato.",
  ["Route29YoungsterText"] = "E aí. Como estão\nseus POKéMON?\fSe estão fracos\ne sem preparo,\ffique fora do\nmato.",
  ["Route2DiglettsCaveSignText"] = "CAVERNA DIGLETT",
  ["Route2GateScientistText"] = "Você é {PLAYER}?\fEu trabalho como\nAIDE do PROF.OAK.\fEu não fazia ideia\nque você viria.\fO LAB do PROF.OAK\nfica perto, em\vCIDADE DE PALLET.",
  ["Route2NuggetHouseFisherText"] = "Oi! Nossa, que bom\nver você.\fVocê é a primeira\nvisita que eu\vtenho faz tempo.\fEstou super feliz!\nDeixa eu te dar\vum presentinho.",
  ["Route2NuggetHouseFisherText_GotNugget"] = "Isso é um NUGGET.\fEu não tenho\nsabedoria a dar,\fentão isso vai\nter que servir!",
  ["Route2SignText"] = "ROTA 2\fCIDADE DE VIRIDIAN\nCIDADE DE PEWTER",
  ["Route30BerrySpeechHouseCheckTreesText"] = "Olhe as árvores\natrás de BERRIES.\vElas só caem.",
  ["Route30BerrySpeechHouseMonEatBerriesText"] = "Sabe, POKéMON\ncome BERRIES.\fBom, o meu POKéMON\nficou mais forte\vcomendo uma BERRY\fToma. Vou dividir\numa com você!",
  ["Route30CooltrainerFText"] = "Não sou treinador\fMas se olhar nos\nolhos de um,\vprepare-se.",
  ["Route30SignText"] = "ROTA 30\fCIDADE DE VIOLET\nCIDADE DE\vCHERRYGROVE",
  ["Route30TrainerTipsText"] = "DICA AO TREINADOR\fNão roube POKéMON\ndos outros!\fPOKé BALLS só se\njogam em POKéMON\vselvagens!",
  ["Route30YoungsterText_DirectionsToMrPokemonsHouse"] = "A casa do\nMR.POKéMON? Fica\vum pouco adiante.",
  ["Route30YoungsterText_EveryoneIsBattling"] = "Todo mundo se\ndiverte lutando!\vFaça o mesmo!",
  ["Route31CooltrainerMText"] = "DARK CAVE…\fSe um POKéMON\niluminasse, eu\vexploraria.",
  ["Route31SignText"] = "ROTA 31\fCIDADE DE VIOLET\nCIDADE DE\vCHERRYGROVE",
  ["Route31VioletGateCooltrainerFText"] = "Eu vim longe\ndemais. Melhor\vligar para casa!",
  ["Route31VioletGateOfficerText"] = "Oi, cara!\nVocê visitou a\vSPROUT TOWER?",
  ["Route31YoungsterText"] = "Achei um bom\nPOKéMON na DARK\vCAVE.\fVou criar ele\npara encarar o\vFALKNER.\fEle é o líder do\nGINÁSIO de VIOLET",
  ["Route32CooltrainerMText_AideIsWaiting"] = "{PLAYER}, né?\nUm cara de óculos\festava procurando\npor você.\fVá ver você mesmo.\nEle espera por\fvocê no CENTRO\nPOKéMON.",
  ["Route32CooltrainerMText_ExperiencesShouldBeUseful"] = "O que viveu em\nCIDADE DE VIOLET\fdeve ser útil na\nsua jornada.",
  ["Route32CooltrainerMText_HaveThisSeed"] = "Você tem bons\nPOKéMON aí.\fDeve ser do treino\nque você deu\fneles por\nCIDADE DE VIOLET.\fO treino no\nGINÁSIO deve ter\fajudado bastante.\nSem dúvida.\fComo lembrança de\nCIDADE DE VIOLET,\vleve isto.\fAumenta a força\ndos ataques de\vplanta.",
  ["Route32CooltrainerMText_UnusedSproutTower"] = "Já foi na\nSPROUT TOWER?\fSe você visitar a\nCIDADE DE VIOLET,\fvão esperar que\nvocê treine lá.\fÉ básico pra\ntreinadores. Vá\vpra SPROUT TOWER!",
  ["Route32CooltrainerMText_VioletGym"] = "Você já foi ao\nGINÁSIO POKéMON?\fDá para testar seu\nPOKéMON e você\vmesmo lá.\fÉ um rito de\npassagem para todo\vtreinador!",
  ["Route32CooltrainerMText_WhatsTheHurry"] = "Espera aí!\nQual é a pressa?",
  ["Route32Pokecenter1FCooltrainerFText"] = "O que devo dar\nao meu POKéMON?\fTalvez um item\nque aumente o\vATAQUE…",
  ["Route32Pokecenter1FFishingGuruText_After"] = "Ei, garoto. Como\nestão mordendo?",
  ["Route32Pokecenter1FFishingGuruText_GiveOldRod"] = "Pescar é ótimo!\fSe há água,\nseja no mar ou\fem um riacho,\nuse sua ROD.",
  ["Route32Pokecenter1FFishingGuruText_No"] = "Oh. Que\ndecepção…",
  ["Route32Pokecenter1FFishingGuruText_Question"] = "Este é um ótimo\nlugar pra pescar.\fVocê viu gente\npescando? Que tal\vvocê?\fQuer uma das\nminhas RODS?",
  ["Route32Pokecenter1FFishingGuruText_Yes"] = "Heh, que bom\nouvir isso.\fAgora você é\npescador também!",
  ["Route32RuinsOfAlphGateOfficerText"] = "RUÍNAS DE ALPH\fUm Turismo de\nVer e Tocar\fTente os painéis\nde pedra!",
  ["Route32RuinsOfAlphGatePokefanMText"] = "Está estudando\nas RUÍNAS?\fVejo um cientista\nem formação.",
  ["Route32RuinsOfAlphGateYoungsterText"] = "Há desenhos\nnas pedras.\fTentei mover\neles. Será que\vsão o quê?",
  ["Route32RuinsSignText"] = "RUINS OF ALPH\nENTRADA LESTE",
  ["Route32SignText"] = "ROTA 32\fCIDADE DE VIOLET\nCIDADE DE AZALEA",
  ["Route32UnionCaveSignText"] = "UNION CAVE\nEm frente",
  ["Route32UnusedFisher1AfterText"] = "Por que o cara ao\nmeu lado pega\vPOKéMON bons?",
  ["Route32UnusedFisher1BeatenText"] = "Nada dá certo\npra mim agora…",
  ["Route32UnusedFisher1SeenText"] = "Só pego sempre\no mesmo POKéMON…\fTalvez uma\nbatalha mude as\vcoisas pra mim.",
  ["Route32UnusedFisher2AfterText"] = "Você precisa de\numa boa ROD pra\fpegar POKéMON\nbons.",
  ["Route32UnusedFisher2BeatenText"] = "Ai. Não tive\nsorte dessa vez.",
  ["Route32UnusedFisher2SeenText"] = "Rá, hoje estou em\nalta. Que tal uma\vbatalha, garoto?",
  ["Route32UnusedText"] = "Os pescadores\ngritaram comigo\vpor incomodar.",
  ["Route33LassText"] = "Ufa, ufa…\fFinalmente saí\ndaquela caverna.\fEra bem maior do\nque eu esperava.\fFiquei cansado\ndemais pra\vexplorar tudo\fentão vim pra\nfora.",
  ["Route33SignText"] = "ROTA 33",
  ["Route34IlexForestGateLassText"] = "Viu o santuário\nem honra ao\vprotetor?\fEle vigia a\nFLORESTA através\vdos tempos.\fAcho que deve ser\num POKéMON do tipo\vgrama.",
  ["Route34IlexForestGateTeacherText"] = "Ah, querido. Faz\numa POKéDEX?\fDeve ser difícil\nse os POKéMON\fnão aparecem.\nTente usar a TM.",
  ["Route34IlexForestSignText"] = "ILEX FOREST\nATRAVÉS DO PORTÃO",
  ["Route34SignText"] = "ROTA 34\fCIDADE DE\vGOLDENROD\vCIDADE DE AZALEA\fILEX FOREST Em\nalgum ponto",
  ["Route34TrainerTipsText"] = "TRAINER TIPS\fÁrvores de BERRY\ndão BERRIES novas\vtodo dia.\fAnote que árvore\ndá qual tipo de\vBERRY.",
  ["Route35GoldenrodGateFisherText"] = "Eu fico pensando\nquantos tipos de\fPOKéMON existem\nno mundo.\fHá três anos,\no PROF.OAK disse\fque existiam 150\ntipos diferentes.",
  ["Route35GoldenrodGatePlayerReceivedAMonWithMailText"] = "{PLAYER} recebeu\nPOKéMON com MAIL.",
  ["Route35GoldenrodGatePokefanFText"] = "Uma árvore\nestranha bloqueia\fa estrada.\nEla se mexe\fse você falar.\nDizem que ela\fficou selvagem\ncom SQUIRTBOTTLE.",
  ["Route35GoldenrodGatePokefanFText_FoughtSudowoodo"] = "Gosto do POKéMON\nLullaby que toca\vno rádio.",
  ["Route35GoldenrodGateRandyAskTakeThisMonToMyFriendText"] = "Ei, moço!\nPode fazer um\vfavor?\fPode levar este\nPOKéMON com MAIL\vpro meu amigo?\fNa ROTA 31.",
  ["Route35GoldenrodGateRandyCantCarryAnotherMonText"] = "Não pode levar\noutro POKéMON…",
  ["Route35GoldenrodGateRandyMyPalWasSnoozingRightText"] = "Meu amigo estava\ncochilando, né?\vO que eu disse?",
  ["Route35GoldenrodGateRandyOhNeverMindThenText"] = "Oh… Deixa pra\nlá…",
  ["Route35GoldenrodGateRandySomethingForYourTroubleText"] = "Valeu, moço! Você\nfez a entrega\vpor mim!\fTome algo\npela ajuda!",
  ["Route35GoldenrodGateRandyThanksText"] = "Vai? Perfeito!\nValeu, moço!\fMeu amigo é\num cara gordinho\vque só cochila.\fVocê vai\nreconhecer fácil!",
  ["Route35GoldenrodGateRandyWeirdTreeBlockingRoadText"] = "Pode ler,\nmas não perca!\vROTA 31!\fAh, sim. Tinha\numa árvore\vesquisita na\festrada. Será\nque tiraram?",
  ["Route35NationalParkGateOfficer1AskToParticipateText"] = "Hoje é {RAM:D099}.\nOu seja, tem\fConcurso de Caça\naos Insetos hoje.\fAs regras são\nsimples.\fUsando um dos\nseus POKéMON,\fpegue um POKéMON\ninseto pra julgar.\fQuer tentar?",
  ["Route35NationalParkGateOfficer1AskToUseFirstMonText"] = "Ih…\fVocê tem mais de\num POKéMON.\fVai ter que usar\n{RAM:D099}, o\fprimeiro POKéMON\nda sua equipe.\fEstá tudo bem\npra você?",
  ["Route35NationalParkGateOfficer1ChooseMonAndComeBackText"] = "Escolha o\nPOKéMON que vai\fusar no Contest,\ne vem me ver.",
  ["Route35NationalParkGateOfficer1ContestIsOverText"] = "O Concurso de\nhoje acabou.\fEsperamos que\nparticipe depois.",
  ["Route35NationalParkGateOfficer1EggAsFirstMonText"] = "Opa…\nVocê tem um EGG\fcomo primeiro\nPOKéMON inicial.\fTroque com o\nPOKéMON que você\fquer usar,\ne vem me ver.",
  ["Route35NationalParkGateOfficer1ExplainsRulesText"] = "Quem pegar o\ninseto mais\vforte vence\vo jogo.\fVocê tem 20\nminutos.\fSe ficar sem\nPARK BALLS, já\vera.\fPode ficar com\no último inseto\vque pegar.\fVai lá e pega\no inseto mais\fforte que\npuder!",
  ["Route35NationalParkGateOfficer1FirstMonCantBattleText"] = "Opa… O primeiro\fPOKéMON da equipe\nnão pode lutar.\fTroque com o\nPOKéMON que você\fquer usar, e vem\nme ver.",
  ["Route35NationalParkGateOfficer1GiveParkBallsText"] = "Aqui estão as\nPARK BALLS pro\vConcurso.",
  ["Route35NationalParkGateOfficer1MakeRoomText"] = "Opa…\nSua equipe e a\fPC BOX estão\ncheias.\fNão tem espaço\npra pôr o inseto\vque você pegar.\fFaça um espaço\nna equipe ou na\fPC BOX e\nvem me ver.",
  ["Route35NationalParkGateOfficer1OkGoFinishText"] = "Certo. Volte\npra fora e\vtermine.",
  ["Route35NationalParkGateOfficer1TakePartInFutureText"] = "Certo. Esperamos\nque participe\vno futuro.",
  ["Route35NationalParkGateOfficer1WaitAtNorthGateText"] = "Certo. Espere no\nPortão Norte\fpelo anúncio\ndos vencedores.",
  ["Route35NationalParkGateOfficer1WantToFinishText"] = "Ainda faltam\n{RAM:D099}\vminuto(s).\fQuer terminar\nagora?",
  ["Route35NationalParkGateOfficer1WeHoldContestsText"] = "Fazemos Concursos\nno PARK toda\fhora. Deveria\ntentar.",
  ["Route35NationalParkGateOfficer1WellHoldYourMonText"] = "Certo, seguramos\nseus outros\vPOKéMON.",
  ["Route35NationalParkGatePlayerReceivedParkBallsText"] = "{PLAYER} recebeu\n20 PARK BALLS.",
  ["Route35NationalParkGatePlayersMonLeftWithHelperText"] = "POKéMON de\n{PLAYER} ficaram\vcom o HELPER.",
  ["Route35NationalParkGateYoungsterText"] = "Quando é o\npróximo Concurso\vde Insetos?",
  ["Route35SignText"] = "ROTA 35",
  ["Route36LassText"] = "Uma árvore\nestá bloqueando\vo caminho para\fCIDADE DE\nGOLDENROD.\vEstá me impedindo\fde comprar.\nAlguém deve agir.",
  ["Route36LassText_ClearedSudowoodo"] = "Aquela árvore\ndesapareceu sem\vrastro.\fAh! Aquela árvore\nera um POKéMON?",
  ["Route36NationalParkGateOfficer1AskToParticipateText"] = "Hoje é {RAM:D099}.\nOu seja, tem\fConcurso de Caça\naos Insetos hoje.\fAs regras são\nsimples.\fUsando um dos\nseus POKéMON,\fpegue um POKéMON\ninseto pra julgar.\fQuer tentar?",
  ["Route36NationalParkGateOfficer1AskToUseFirstMonText"] = "Ih…\fVocê tem mais de\num POKéMON.\fVai ter que usar\n{RAM:D099}, o\fprimeiro POKéMON\nda sua equipe.\fEstá tudo bem\npra você?",
  ["Route36NationalParkGateOfficer1ChooseMonAndComeBackText"] = "Escolha o\nPOKéMON que vai\fusar no Contest,\ne vem me ver.",
  ["Route36NationalParkGateOfficer1ContestIsOverText"] = "O Concurso de\nhoje acabou.\fEsperamos que\nparticipe depois.",
  ["Route36NationalParkGateOfficer1EggAsFirstMonText"] = "Opa…\nVocê tem um EGG\fcomo primeiro\nPOKéMON inicial.\fTroque com o\nPOKéMON que você\fquer usar,\ne vem me ver.",
  ["Route36NationalParkGateOfficer1ExplainsRulesText"] = "A pessoa que\ncapturar o\vPOKéMON inseto\vmais forte é a\fvencedora.\nVocê tem 20\fminutos.\nSe ficar sem PARK\vBALLS, acabou.\fVocê pode ficar\ncom o último\vPOKéMON que\fcapturar.\nVá e capture o\fPOKéMON inseto\nmais forte!",
  ["Route36NationalParkGateOfficer1FirstMonCantBattleText"] = "Opa… O primeiro\fPOKéMON da equipe\nnão pode lutar.\fTroque com o\nPOKéMON que você\fquer usar, e vem\nme ver.",
  ["Route36NationalParkGateOfficer1GiveParkBallsText"] = "Aqui estão as\nPARK BALLS pro\vConcurso.",
  ["Route36NationalParkGateOfficer1HeresThePrizeText"] = "{PLAYER}?\fAqui esta o prêmio\nque estavamos\vpara você.",
  ["Route36NationalParkGateOfficer1MakeRoomText"] = "Opa…\nSua equipe e seu\fPC BOX estão\ncheios.\fVocê não tem\nonde guardar o\vPOKéMON inseto\fque capturar.\nLibere espaço na\fequipe ou na BOX,\ndepois volte.",
  ["Route36NationalParkGateOfficer1OkGoFinishText"] = "OK. Volte lá fora\ne termine\vo que falta.",
  ["Route36NationalParkGateOfficer1SomeMonOnlySeenInParkText"] = "Alguns POKéMON só\npodem ser vistos\vno PARQUE.",
  ["Route36NationalParkGateOfficer1TakePartInFutureText"] = "Certo. Esperamos\nque participe\vno futuro.",
  ["Route36NationalParkGateOfficer1WaitHereForAnnouncementText"] = "OK. Por favor\nespere aqui pelo\fanuncio dos\nvencedores.",
  ["Route36NationalParkGateOfficer1WantToFinishText"] = "Ainda faltam\n{RAM:D099}\vminuto(s).\fQuer terminar\nagora?",
  ["Route36NationalParkGateOfficer1WellHoldPrizeText"] = "Opa… Seu PACK\nesta cheio.\fGuardaremos seu\nprêmio, mas\vsó por hoje.\fLibere espaço,\ndepois volte.",
  ["Route36NationalParkGateOfficer1WellHoldYourMonText"] = "Tudo bem. Vamos\nguardar os outros\vdurante o teste.",
  ["Route36NationalParkGatePlayerReceivedParkBallsText"] = "{PLAYER} recebeu\n20 PARK BALLS.",
  ["Route36NationalParkGatePlayersMonLeftWithHelperText"] = "POKéMON de\n{PLAYER} ficaram\vcom o HELPER.",
  ["Route36RuinsOfAlphGateGrampsText"] = "Você viu aquela\nárvore estranha\vna estrada?\fIsso pode explicar\npor que menos\fpessoas visitam\nas RUÍNAS.",
  ["Route36RuinsOfAlphGateOfficerText"] = "Não se pergunta\nquem faria algo\vassim?\vE por quê?",
  ["Route36SignText"] = "ROTA 36",
  ["Route36TrainerTips1Text"] = "TRAINER TIPS\fStatus de POKéMON\nvariam , mesmo\vdentro da mesma\fespécie. Seus\nstatus podem\fser parecidos. Mas\nas diferenças\fse tornar claras\nconforme crescem.",
  ["Route36TrainerTips2Text"] = "TRAINER TIPS\fUse DIG para ir\nà entrada de\vqualquer lugar.\fÉ conveniente\npara explorar\fcavernas e outros\nlugares assim.",
  ["Route37SignText"] = "ROTA 37",
  ["Route38EcruteakGateOfficerText"] = "De onde mesmo você\né?\fDe CIDADE DE\vNEW BARK?\fO PROF.ELM mora\nperto daí, certo?\fVocê veio de bem\nlonge pra chegar.",
  ["Route38SignText"] = "ROTA 38\fCIDADE DE OLIVINE\nCIDADE DE ECRUTEAK",
  ["Route38TrainerTipsText"] = "TRAINER TIPS\fSe um POKéMON está\ntentando evoluir,\vdá para impedir.\fAperte o Botão B\ndurante a\vevolução.\fIsso assusta o\nPOKéMON e para a\vevolução dele.",
  ["Route39BarnAskGiveBerryText"] = "Dar uma BERRY pra\nMILTANK?",
  ["Route39BarnGaveBerryText"] = "{PLAYER} deu uma\nBERRY à MILTANK.",
  ["Route39BarnItsCryIsWeakText"] = "O choro é fraco…",
  ["Route39BarnLittleHealthierText"] = "A MILTANK ficou\nmais saudável!",
  ["Route39BarnNoBerriesText"] = "{PLAYER} não tem\nBERRIES…",
  ["Route39BarnQuiteHealthyText"] = "MILTANK ficou\nbem saudável!",
  ["Route39BarnRefusedBerryText"] = "{PLAYER} não quer\ndar uma BERRY.\fMILTANK triste.",
  ["Route39BarnTotallyHealthyText"] = "MILTANK ficou\nmuito saudável!",
  ["Route39BarnTwinMoomooIsSickText"] = "MOOMOO doente…\fEla precisa de\nmuitas BERRIES.",
  ["Route39BarnTwinWereFeedingMoomooText"] = "Dando comida pra\nMOOMOO!",
  ["Route39SignText"] = "ROTA 39\fCIDADE DE OLIVINE\nCIDADE DE ECRUTEAK",
  ["Route39TrainerTipsText"] = "TRAINER TIPS\fUse HEADBUTT nas\nárvores para\vderrubar POKéMON.\fTipos diferentes\nde POKéMON caem\vdas árvores.\fUse HEADBUTT em\ntoda árvore!",
  ["Route3MtMoonSquareSignText"] = "MT.MOON SQUARE\fÉ só subir as\nescadas.",
  ["Route40BattleTowerGateRockerText"] = "Vai pra\nBATTLE TOWER?\fÉ segredo, mas se\nvocê ganhar\fmuito, pode\nganhar presentes\vespeciais.",
  ["Route40BattleTowerGateTwinText"] = "Os níveis dos\nPOKéMON que quero\fusar são todos\ndiferentes.\fPreciso treinar\neles agora!",
  ["Route40BattleTowerGateUnusedText1"] = "Também veio ver\na BATTLE\vTOWER?\fMas acho que ainda\nnão pode entrar.",
  ["Route40BattleTowerGateUnusedText2"] = "A BATTLE TOWER\nabriu.\fQuero ir, mas\nainda não pensei\fnuma frase boa\npra quando eu\vganhar.",
  ["Route40BattleTowerGateUnusedText3"] = "Vou treinar meus\nPOKéMON pra ficar\fpronto pra\nBATTLE TOWER.",
  ["Route40Lass1Text"] = "Mesmo não\nvendo daqui,\fCIANWOOD fica\ndo outro lado",
  ["Route40Lass2Text"] = "Vim de navio pra\nOLIVINE, pra ver\fas vistas e curtir\no ambiente.\fPor ser um porto,\né bem diferente\vde uma cidade\vgrande.",
  ["Route40PokefanMText"] = "Hm! Tem um prédio\ngrande à frente!\fO que é aquilo?",
  ["Route40PokefanMText_Mobile"] = "Hm! Olha só esses\ntreinadores\vsérios entrando\vaos montes.\fO quê? O quê?",
  ["Route40SignText"] = "ROTA 40\fCIDADE DE CIANWOOD\nCIDADE DE OLIVINE",
  ["Route40StandingYoungsterText"] = "Já foi na\nBATTLE TOWER?\fAcho que muitos\ntreinadores fortes\fjá se reuniram\nlá.\fMas com tantos\nBADGES que você\ftem, não deve ir\nnada mal.",
  ["Route42EcruteakGateOfficerText"] = "O MOUNT MORTAR é\num labirinto.\fCuidado pra não\nse perder lá.",
  ["Route42Sign1Text"] = "ROTA 42\fCIDADE DE ECRUTEAK\nCIDADE DE MAHOGANY",
  ["Route42Sign2Text"] = "ROTA 42\fCIDADE DE ECRUTEAK\nCIDADE DE MAHOGANY",
  ["Route43MahoganyGateOfficerRocketsClearedText"] = "Ninguém mais vai\nao LAKE OF RAGE\vnesses dias.",
  ["Route43MahoganyGateOfficerText"] = "Só quem vai ao\nLAKE OF RAGE\fpassou por aqui\nultimamente.",
  ["Route43Sign1Text"] = "ROTA 43\fLAKE OF RAGE\nCIDADE DE MAHOGANY",
  ["Route43Sign2Text"] = "ROTA 43\fLAKE OF RAGE\nCIDADE DE MAHOGANY",
  ["Route43TrainerTipsText"] = "TRAINER TIPS\fTodo POKéMON tem\nprós e contras\fconforme o tipo\ndele.\fSe os tipos são\ndiferentes, um de\fnível mais alto\npode até perder.\fAprenda que tipos\nsão fortes e\ffracos contra o\nseu POKéMON.",
  ["Route44Sign1Text"] = "ROTA 44\nICE PATH a frente",
  ["Route44Sign2Text"] = "ROTA 44\fCIDADE DE MAHOGANY\vCIDADE DE\nBLACKTHORN",
  ["Route45DummyText"] = "Eu sou muito,\nmuito forte!\fTem algum lugar\npra provar quão\vforte eu sou?",
  ["Route45SignText"] = "ROTA 45\nMONTANHA a frente",
  ["Route46SignText"] = "ROTA 46\nMONTANHA a frente",
  ["Route5CleanseTagHouseGrannyText1"] = "Iiiaaah!\fEu sinto uma\nsombra sinistra\vpairando em você.\fLeve isto para\nafastar ela!",
  ["Route5CleanseTagHouseGrannyText2"] = "Você estava em\nperigo mortal, mas\vestá protegido.",
  ["Route5CleanseTagHouseTeacherText"] = "Minha avó gosta de\nafastar o que ela\facredita serem\nespíritos ruins.\fDesculpe se ela\nassustou você.",
  ["Route5PokefanMText"] = "A estrada está\nfechada até que\fo problema na\nUSINA se resolva.",
  ["Route5SaffronGateOfficerText"] = "Você é de JOHTO,\nnão é?\fO que achou de\nKANTO? É bacana,\vnão concorda?",
  ["Route5UndergroundPathEntranceTeacherText"] = "Muitas cidades de\nJOHTO são antigas\fEu adoraria\nvisitar!",
  ["Route5UndergroundPathSignText"] = "UNDERGROUND PATH\fCIDADE DE\vCERULEAN\vCIDADE DE\vVERMILION",
  ["Route6PokefanMText"] = "A estrada está\nfechada até que\fo problema na\nUSINA se resolva.",
  ["Route6SaffronGuardMagnetTrainText"] = "O MAGNET TRAIN\né a coisa mais\ffamosa de\nSAFFRON.",
  ["Route6SaffronGuardWelcomeText"] = "Bem-vindo à\nCIDADE DE SAFFRON,\vlar do MAGNET\vTRAIN!\f…É o que eu diria\nnormalmente, mas\fo MAGNET TRAIN\nnão está rodando.\fEle não recebe\neletricidade\fporque tem algo\nde errado\fcom a POWER\nPLANT.",
  ["Route6UndergroundPathSignText"] = "UNDERGROUND PATH\fCIDADE DE\vCERULEAN\vCIDADE DE\vVERMILION",
  ["Route7LockedDoorText"] = "Está trancado…",
  ["Route7SaffronGuardPowerPlantText"] = "Você soube do\nacidente na USINA\vDE ENERGIA?\fFica a leste,\nperto da CIDADE DE\vLAVENDER.",
  ["Route7SaffronGuardSeriousText"] = "Levo meu trabalho\nde GUARDA a sério\fEi! Você tem uma\nPOKéDEX.\fCerto. Você pode\npassar.",
  ["Route7UndergroundPathSignText"] = "Que aviso é esse?\f…Os treinadores\nmal-educados têm\fbatalhado no\nUNDERGROUND PATH.\fPor causa das\nreclamações dos\vmoradores locais,\vo UNDERGROUND PATH\vfoi lacrado\vindefinidamente.\fCELADON POLÍCIA",
  ["Route8LockedDoorText"] = "Está trancado…",
  ["Route8SaffronGateOfficerText"] = "Você já foi a\nCIDADE DE\vLAVENDER?\fTem uma RADIO\nTOWER bem alta.",
  ["Route8UndergroundPathSignText"] = "O cartaz rasgado…\fImpossível\nler…",
  ["Route9SignText"] = "ROTA 9\fCIDADE DE CERULEAN\nROCK TUNNEL",
