  ["RuinsOfAlphAerodactylChamberDescriptionText"] = "Este POKéMON\nvoador atacava\fa presa com\ndentes de serra.",
  ["RuinsOfAlphAerodactylChamberUnownText"] = "É texto de UNOWN!",
  ["RuinsOfAlphAerodactylChamberWallHoleText"] = "Tem um buraco\ngrande na parede!",
