  ["RuinsOfAlphHoOhChamberUnownText"] = "É texto de UNOWN!",
  ["RuinsOfAlphHoOhChamberWallHoleText"] = "Tem um buraco\ngrande na parede!",
  ["RuinsOfAlphHoOhChamberWallPatternLeftText"] = "Padrões\napareceram nas\vparedes…",
