  ["TEXT_FAST_SHIP_CABINS_NNW_NNE_NE_BG_003"] = "Não tem nada\naqui dentro…",
  ["TEXT_FAST_SHIP_CABINS_NNW_NNE_NE_OBJ_001"] = "{PLAYER} tentou\nmostrar o S.S.\vTICKET…\f…Mas não tem!\fDesculpe!\nSó pode embarcar\fquem tiver um\nS.S.TICKET.",
  ["TEXT_FAST_SHIP_CABINS_NNW_NNE_NE_OBJ_001_AFTER"] = "Treinadores de\nJOHTO podem lutar\fcom os LÍDERES de\nKANTO.",
  ["TEXT_FAST_SHIP_CABINS_NNW_NNE_NE_OBJ_001_BEATEN"] = "Eu queria ganhar!",
  ["TEXT_FAST_SHIP_CABINS_NNW_NNE_NE_OBJ_001_SEEN"] = "Vou pra KANTO\ntestar minhas\vhabilidades.",
  ["TEXT_FAST_SHIP_CABINS_NNW_NNE_NE_OBJ_002"] = "Um dia eu venço\nvocê!",
  ["TEXT_FAST_SHIP_CABINS_NNW_NNE_NE_OBJ_002_AFTER"] = "Um dia eu venço\nvocê!",
  ["TEXT_FAST_SHIP_CABINS_NNW_NNE_NE_OBJ_002_BEATEN"] = "Qual é a diferença\nentre nós dois?",
  ["TEXT_FAST_SHIP_CABINS_NNW_NNE_NE_OBJ_002_SEEN"] = "Estou treinando\npara ser CAMPEÃO",
  ["TEXT_FAST_SHIP_CABINS_NNW_NNE_NE_OBJ_003"] = "A LILY é legal,\nmas a MARY é a\fmelhor!\nQuero conhecer as\vrádios de JOHTO!",
  ["TEXT_FAST_SHIP_CABINS_NNW_NNE_NE_OBJ_003_AFTER"] = "A LILY é legal,\nmas a MARY é a\fmelhor!\nQuero conhecer as\vrádios de JOHTO!",
  ["TEXT_FAST_SHIP_CABINS_NNW_NNE_NE_OBJ_003_BEATEN"] = "Aaaargh!",
  ["TEXT_FAST_SHIP_CABINS_NNW_NNE_NE_OBJ_003_SEEN"] = "Você conhece a\nLILY? Ela é uma\vDJ de KANTO.",
  ["TEXT_FAST_SHIP_CABINS_NNW_NNE_NE_OBJ_004"] = "Será que tem\nalguma montanha\fboa para escalar\nem KANTO?",
  ["TEXT_FAST_SHIP_CABINS_NNW_NNE_NE_OBJ_004_AFTER"] = "Será que tem\nalguma montanha\fboa para escalar\nem KANTO?",
  ["TEXT_FAST_SHIP_CABINS_NNW_NNE_NE_OBJ_004_BEATEN"] = "Isso é demais\npara mim!",
  ["TEXT_FAST_SHIP_CABINS_NNW_NNE_NE_OBJ_004_SEEN"] = "Está sozinho?\nEntão vamos lutar",
  ["TEXT_FAST_SHIP_CABINS_NNW_NNE_NE_OBJ_005"] = "É, eu sou\nmarinheiro sim.\fEu não estava\nvadiando!\fEsta cabine estava\nvazia, então eu só\vtirei um cochilo!\fAh, deixa para lá!\nVamos batalhar!",
  ["TEXT_FAST_SHIP_CABINS_NNW_NNE_NE_OBJ_006"] = "Eu desisto.\nVocê não precisa\folhar. Esquece\nisso!",
  ["TEXT_FAST_SHIP_CABINS_NNW_NNE_NE_OBJ_006_AFTER"] = "Desisto. Filho,\nvocê não precisa\fprocurar. Esqueça\nisso!",
  ["TEXT_FAST_SHIP_CABINS_NNW_NNE_NE_OBJ_006_SEEN"] = "Ah, não. Perdi uma\ncoisa que é muito\vimportante.",
  ["TEXT_FAST_SHIP_CABINS_NNW_NNE_NE_OBJ_007"] = "Achei uma moeda\nbonita aqui.\fAlguém deve ter\nperdido…",
  ["TEXT_FAST_SHIP_CABINS_NNW_NNE_NE_OBJ_007_AFTER"] = "Achei uma moeda\nbonita aqui.\fAlguém deve ter\nperdido…",
  ["TEXT_FAST_SHIP_CABINS_NNW_NNE_NE_OBJ_007_BEATEN"] = "Que azar!\nEu perdi!",
  ["TEXT_FAST_SHIP_CABINS_NNW_NNE_NE_OBJ_007_SEEN"] = "Eba!\nSorte!",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_BG_001"] = "Não tem nada\naqui dentro…",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_001"] = "Ufa! Obrigado por\nter vindo junto.\fEntreter aquela\nmenininha foi\vexaustivo.",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_002"] = "Olá, filho…\nNão acho a minha\vneta.\fSe ela está no\nnavio, tudo bem.\fMas e se ela caiu\nno mar?\fEla é uma criança\nelétrica, então\fpode amolar alguém\nEstou aflito…",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_003"] = "Me diverti muito\nbrincando!",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_004"] = "CAPTAIN, brinca um\npouco comigo?\fEstou entediado!\nQuero brincar!",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_005"] = "Você viaja\nsozinho?\fSua mãe não fica\npreocupada?",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_005_AFTER"] = "Você viaja\nsozinho?\fSua mãe não fica\npreocupada?",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_005_BEATEN"] = "Você é forte!",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_005_SEEN"] = "Ei, filho! Quer\nbatalhar comigo?",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_006"] = "Bebê é um jeito\ngrosso de chamar\vnós, meninas!",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_006_AFTER"] = "Bebê é um jeito\ngrosso de chamar\vnós, meninas!",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_006_BEATEN"] = "Ah! Perdemos!",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_006_SEEN"] = "Você acha que eu\nsou bebê?\vIsso não é justo!",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_007"] = "Às vezes crianças\nsão mais espertas\vque adultos!",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_007_AFTER"] = "Às vezes crianças\nsão mais espertas\vque adultos!",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_007_BEATEN"] = "Ah! Perdemos!",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_007_SEEN"] = "Eu não sou bebê!\fNão é bonito falar\nassim com a dama!",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_008"] = "O seu telefone não\ntem memória para\vmais números.",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_008_AFTER"] = "Entendi. Dá para\nouvir a rádio de\vJOHTO no navio.",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_008_BEATEN"] = "…Estou ouvindo\nalguma coisa!",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_008_SEEN"] = "Psiu! Meu cérebro\nestá captando\vsinais de rádio!",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_009"] = "Preciso ir ao\nPOKéMON SALON e\vdeixá-los lindos!",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_009_AFTER"] = "Preciso ir ao\nPOKéMON SALON e\vdeixá-los lindos!",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_009_BEATEN"] = "Ah, não! Meus\nlindos POKéMON!",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_009_SEEN"] = "O que você acha?\nMeus POKéMON são\vlindos, não são?",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_010"] = "Ah, sim! Tenho que\nbuscar meu POKéMON\vno DAY-CARE!",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_010_AFTER"] = "Ah, sim! Tenho que\nbuscar meu POKéMON\vno DAY-CARE!",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_010_BEATEN"] = "O que eu ia\nfazer mesmo?",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_010_SEEN"] = "Vou fazer compras\nna DEPT.STORE e\vdepois…",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_011"] = "Você devia usar a\nBALL certa para\vcada situação.",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_011_AFTER"] = "Você devia usar a\nBALL certa para\vcada situação.",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_011_BEATEN"] = "Espera! Para! Não!\nPor favor!",
  ["TEXT_FAST_SHIP_CABINS_SE_SSE_CAPTAINS_CABIN_OBJ_011_SEEN"] = "Que tipos de POKé\nBALLS você tem\vcom você?",
  ["TEXT_FAST_SHIP_CABINS_SW_SSW_NW_BG_001"] = "Uma cama macia!\nHora de dormir…",
  ["TEXT_FAST_SHIP_CABINS_SW_SSW_NW_BG_002"] = "Uma cama macia!\nHora de dormir…",
  ["TEXT_FAST_SHIP_CABINS_SW_SSW_NW_BG_003"] = "Não tem nada\naqui dentro…",
  ["TEXT_FAST_SHIP_CABINS_SW_SSW_NW_OBJ_001"] = "Fsss… A chama\nestá fraquinha…",
  ["TEXT_FAST_SHIP_CABINS_SW_SSW_NW_OBJ_001_AFTER"] = "Acho que o fogo é\nfraco no mar.\fNão faz diferença?\nSério?",
  ["TEXT_FAST_SHIP_CABINS_SW_SSW_NW_OBJ_001_BEATEN"] = "Fsss… A chama\nestá fraquinha…",
  ["TEXT_FAST_SHIP_CABINS_SW_SSW_NW_OBJ_001_SEEN"] = "Vou pra KANTO\nfazer shows de\vcuspir fogo!",
  ["TEXT_FAST_SHIP_CABINS_SW_SSW_NW_OBJ_002"] = "Ooh, uau. Você é\ndurão, cara!",
  ["TEXT_FAST_SHIP_CABINS_SW_SSW_NW_OBJ_002_AFTER"] = "Dá para achar um\nmonte de POKéMON\vnas árvores!",
  ["TEXT_FAST_SHIP_CABINS_SW_SSW_NW_OBJ_002_BEATEN"] = "Ooh, uau. Você é\ndurão, cara!",
  ["TEXT_FAST_SHIP_CABINS_SW_SSW_NW_OBJ_002_SEEN"] = "Vou visitar minha\nvovó para pegar\vuns insetos!",
  ["TEXT_FAST_SHIP_CABINS_SW_SSW_NW_OBJ_003"] = "{PLAYER} tentou\nmostrar o S.S.\vTICKET…\f…Mas não tem!\fDesculpe!\nSó pode embarcar\fquem tiver um\nS.S.TICKET.",
  ["TEXT_FAST_SHIP_CABINS_SW_SSW_NW_OBJ_003_AFTER"] = "Uma viagem é o\nmelhor remédio\vpara um coração\fpartido.\nMas a viagem de\vFAST SHIP é curta",
  ["TEXT_FAST_SHIP_CABINS_SW_SSW_NW_OBJ_003_BEATEN"] = "Meu peito chora…",
  ["TEXT_FAST_SHIP_CABINS_SW_SSW_NW_OBJ_003_SEEN"] = "Estou tentando\nesquecer as mágoas\vVamos batalhar!",
  ["TEXT_FAST_SHIP_CABINS_SW_SSW_NW_OBJ_004"] = "{PLAYER} tentou\nmostrar o S.S.\vTICKET…\f…Mas não tem!\fDesculpe!\nSó pode embarcar\fquem tiver um\nS.S.TICKET.",
  ["TEXT_FAST_SHIP_CABINS_SW_SSW_NW_OBJ_004_AFTER"] = "Falando na RADIO\nSTATION,\fqual é o número da\nsorte da semana?",
  ["TEXT_FAST_SHIP_CABINS_SW_SSW_NW_OBJ_004_BEATEN"] = "Uau!\nDistorção total!",
  ["TEXT_FAST_SHIP_CABINS_SW_SSW_NW_OBJ_004_SEEN"] = "Vou fazer um teste\ncom as minhas\fmúsicas na RADIO\nSTATION.",
  ["TEXT_FIGHTING_DOJO_BG_001"] = "Tudo o que vai\nvolta!",
  ["TEXT_FIGHTING_DOJO_OBJ_001"] = "Olá!\fO KARATE KING,\nmestre do DOJO,\festá numa caverna\nem JOHTO,\vtreinando.",
  ["TEXT_FUCHSIA_CITY_BG_001"] = "CIDADE DE FUCHSIA\fVeja! É o Rosa\nda Paixão!",
  ["TEXT_FUCHSIA_CITY_OBJ_001"] = "Um dos ELITE\nFOUR já foi o\fLÍDER do GINÁSIO\nde FUCHSIA.",
  ["TEXT_FUCHSIA_CITY_OBJ_002"] = "A filha do KOGA\nvirou o LÍDER do\fGINÁSIO depois\nque ele entrou no\vELITE FOUR.",
  ["TEXT_FUCHSIA_CITY_OBJ_003"] = "A SAFARI ZONE está\nfechada… Que\fpena, era a\nmaior atração\vde FUCHSIA.",
  ["TEXT_FUCHSIA_GYM_OBJ_001"] = "Fufufufu…\fSinto muito\ndesapontar você…\fÉ só brincadeira!\fEu sou a real!\fJANINE, do GINÁSIO\nde FUCHSIA!",
  ["TEXT_FUCHSIA_GYM_OBJ_002"] = "Fufufu!\fEu sou a JANINE,\na LÍDER!\fNão, não sou!\nCaiu, otário!",
  ["TEXT_FUCHSIA_GYM_OBJ_003"] = "Te enganei!\nHahaha!",
  ["TEXT_FUCHSIA_GYM_OBJ_004"] = "Eu sou a JANINE!\fComo você soube\nque eu era real?\fVamos batalhar!",
  ["TEXT_FUCHSIA_GYM_OBJ_005"] = "Uahahaha!\fPode crer, cara.\nEu sou a JANINE!",
  ["TEXT_FUCHSIA_GYM_OBJ_006"] = "Ei, futuro\nCAMPEÃO!\fOpa! Dê uma boa\nolhada em volta.\fOs treinadores são\ntodos iguais à\vLÍDER, a JANINE.\fQual deles é a\nJANINE real?",
  ["TEXT_FUCHSIA_MART_OBJ_001"] = "Eu queria comprar\nlembranças da\fSAFARI ZONE, mas\nestá fechada…",
  ["TEXT_FUCHSIA_MART_OBJ_002"] = "Eu queria comprar\nlembranças da\fSAFARI ZONE, mas\nestá fechada…",
  ["TEXT_FUCHSIA_MART_OBJ_003"] = "A neta do WARDEN\nda SAFARI ZONE\vmora aqui\vna cidade.",
  ["TEXT_FUCHSIA_POKECENTER1_F_OBJ_001"] = "Bom dia!\nBem-vindo ao nosso\vCENTRO POKéMON.",
  ["TEXT_FUCHSIA_POKECENTER1_F_OBJ_002"] = "Ei! Você tem uma\nPOKéDEX de um tipo\vnovo em folha.\fFoi o PROF.OAK que\nte deu?",
  ["TEXT_FUCHSIA_POKECENTER1_F_OBJ_003"] = "Levei um susto\nno GINÁSIO.\fTinha um monte de\nmeninas que eram\vtodas iguais.",
  ["TEXT_FUCHSIA_POKECENTER1_F_OBJ_004"] = "Eu sou a JANINE!\nAbracadabra… Puf!",
  ["TEXT_GOLDENROD_BIKE_SHOP_OBJ_001"] = "…Suspiro… Me\nmudei, mas não\fvendo minhas\nBICYCLE. Por quê?\fAh, sei! Você\npoderia andar e\vanunciar pra mim?",
  ["TEXT_GOLDENROD_CITY_OBJ_001"] = "Construíram a nova\nRADIO TOWER para\ftrocar a velha,\nque rangia.",
  ["TEXT_GOLDENROD_CITY_OBJ_002"] = "Sei que tem uma\nBIKE SHOP nova,\fmas não acho ela\nem lugar nenhum.",
  ["TEXT_GOLDENROD_CITY_OBJ_003"] = "Aquele homem de\npreto se veste\fcomo a TEAM ROCKET\nQue bobagem!",
  ["TEXT_GOLDENROD_CITY_OBJ_004"] = "A RADIO TOWER de\nCIDADE DE\vGOLDENROD é\vum cartão-postal.\fEstão com uma\npromoção\vrolando agora.\fEles modificam\na sua POKéGEAR,\fpara ela virar\num rádio também.",
  ["TEXT_GOLDENROD_CITY_OBJ_005"] = "E-he-he-he…\fLevei bronca\npor brincar no\fsubsolo da\nDEPT.STORE.",
  ["TEXT_GOLDENROD_CITY_OBJ_006"] = "O homem daquela\ncasa avalia os\vnomes que você dá\fEle até renomeia\no seu POKéMON.",
  ["TEXT_GOLDENROD_CITY_OBJ_007"] = "Ufa! Esta cidade\né grande. Não sei\fonde fica\nnada.",
  ["TEXT_GOLDENROD_CITY_OBJ_008"] = "Então esta é a\nRADIO TOWER…",
  ["TEXT_GOLDENROD_CITY_OBJ_009"] = "Saia do caminho!\nCai fora!",
  ["TEXT_GOLDENROD_CITY_OBJ_010"] = "Tomar a RADIO\nTOWER…\fO quê? Não é da\nsua conta!",
  ["TEXT_GOLDENROD_CITY_OBJ_011"] = "POKéMON? Não são\nnada além de\fferramentas para\nganhar dinheiro!",
  ["TEXT_GOLDENROD_CITY_OBJ_012"] = "Nosso sonho logo\nvai se realizar…\fFoi uma luta tão\nlonga…",
  ["TEXT_GOLDENROD_CITY_OBJ_013"] = "Ei, pirralho! Você\nnão é daqui!\vSuma!",
  ["TEXT_GOLDENROD_CITY_OBJ_014"] = "Venha provar o\nverdadeiro terror\vda TEAM ROCKET!",
  ["TEXT_GOLDENROD_DEPT_STORE1_F_BG_001"] = "1F BALCÃO\f2F MERCADO DO\n   TREINADOR\f3F COLEÇÃO DE\n   BATALHA\f4F REMÉDIOS\f5F CANTO DAS TM\f6F TERRAÇO",
  ["TEXT_GOLDENROD_DEPT_STORE1_F_OBJ_001"] = "Bem-vindo à\nDEPT.STORE!",
  ["TEXT_GOLDENROD_DEPT_STORE1_F_OBJ_002"] = "Estou doida para\ncomprar hoje!",
  ["TEXT_GOLDENROD_DEPT_STORE1_F_OBJ_003"] = "Mamãe é boa em\ncaçar promoção.\fEla sempre compra\nas coisas mais\vbaratas.",
  ["TEXT_GOLDENROD_DEPT_STORE1_F_OBJ_004"] = "A DEPT.STORE tem\numa boa\vvariedade.\fMas alguns itens\nsó saem como\fprêmios do\nGAME CORNER.",
  ["TEXT_GOLDENROD_DEPT_STORE2_F_OBJ_001"] = "A POKéGEAR pode\nguardar até dez\vnúmeros.\fÉ difícil\ndecidir quais\vguardar.",
  ["TEXT_GOLDENROD_DEPT_STORE2_F_OBJ_002"] = "A POKéGEAR pode\nguardar até dez\vnúmeros.\fÉ difícil\ndecidir quais\vguardar.",
  ["TEXT_GOLDENROD_DEPT_STORE2_F_OBJ_003"] = "A POKéGEAR pode\nguardar até dez\vnúmeros.\fÉ difícil\ndecidir quais\vguardar.",
  ["TEXT_GOLDENROD_DEPT_STORE2_F_OBJ_004"] = "Ganhei meu ABRA\nna CASA DE JOGOS.\fAgora é meu\nmelhor parceiro.",
  ["TEXT_GOLDENROD_DEPT_STORE2_F_OBJ_005"] = "Esta LOJA me faz\nver que GOLDENROD\fé uma cidade\ngrande.\fA seleção daqui\nnão tem igual\vem nenhum lugar.",
  ["TEXT_GOLDENROD_DEPT_STORE3_F_OBJ_001"] = "Eu, eu, eu sou bem\nimpaciente!\fUso X SPEED na\nbatalha para\vacelerar POKéMON.",
  ["TEXT_GOLDENROD_DEPT_STORE3_F_OBJ_002"] = "Eu, eu, eu sou bem\nimpaciente!\fUso X SPEED na\nbatalha para\vacelerar POKéMON.",
  ["TEXT_GOLDENROD_DEPT_STORE3_F_OBJ_003"] = "Ei! Em batalha,\nvocê usa X\vSPECIAL?\fÉ demais. Ele\naumenta muito\vos SPECIAL!",
  ["TEXT_GOLDENROD_DEPT_STORE4_F_OBJ_001"] = "Ei. Amo POKéMON\nfortes.\fDou PROTEIN a\neles para elevar\vo ATTACK.",
  ["TEXT_GOLDENROD_DEPT_STORE4_F_OBJ_002"] = "Ei. Amo POKéMON\nfortes.\fDou PROTEIN a\neles para elevar\vo ATTACK.",
  ["TEXT_GOLDENROD_DEPT_STORE4_F_OBJ_003"] = "IRON: a DEFESA do\nPOKéMON sobe.",
  ["TEXT_GOLDENROD_DEPT_STORE4_F_OBJ_004"] = "Alguns POKéMON\nevoluem quando\fsão trocados por\ncabo Game Link.\fConheço quatro:\nMACHOKE, KADABRA,\fHAUNTER e, hum,\nGRAVELER.\fDizem que existem\noutros também.",
  ["TEXT_GOLDENROD_DEPT_STORE5_F_OBJ_002"] = "Aos domingos, uma\nmoça vem olhar\vos POKéMON.\fEla até dá\nTM de presente!",
  ["TEXT_GOLDENROD_DEPT_STORE5_F_OBJ_003"] = "Não dá para\nrenomear um\vPOKéMON trocado.\fO nome mostra o\ncarinho do\ftreinador antigo\npor ele.",
  ["TEXT_GOLDENROD_DEPT_STORE5_F_OBJ_004"] = "Não dá para\nrenomear um\vPOKéMON trocado.\fO nome mostra o\ncarinho do\ftreinador antigo\npor ele.",
  ["TEXT_GOLDENROD_DEPT_STORE5_F_OBJ_005"] = "MYSTERY GIFT.\fCom um pequeno\nbip, você\vganha um presente",
  ["TEXT_GOLDENROD_DEPT_STORE5_F_OBJ_006"] = "Olá. Oh, seu\nPOKéMON…",
  ["TEXT_GOLDENROD_DEPT_STORE6_F_BG_003"] = "Uma máquina de\nvendas! O menu:",
  ["TEXT_GOLDENROD_DEPT_STORE6_F_BG_004"] = "Uma máquina de\nvendas! O menu:",
  ["TEXT_GOLDENROD_DEPT_STORE6_F_BG_005"] = "Uma máquina de\nvendas! O menu:",
  ["TEXT_GOLDENROD_DEPT_STORE6_F_BG_006"] = "Uma máquina de\nvendas! O menu:",
  ["TEXT_GOLDENROD_DEPT_STORE6_F_OBJ_001"] = "Você ouve a\nLUCKY CHANNEL?\fSe quer vencer,\ntroque POKéMON\fcom o máximo de\ngente para ter\fnúmeros de ID\ndiferentes.",
  ["TEXT_GOLDENROD_DEPT_STORE6_F_OBJ_002"] = "Se estiver cansado\ntente as bebidas\vdas máquinas.\fSeu POKéMON vai\namar também.",
  ["TEXT_GOLDENROD_DEPT_STORE_B1_F_OBJ_005"] = "Ei, garoto!\nVocê nos atrasa!\fNosso esquema\né trabalhar\fnos bastidores,\nonde ninguém vê!",
  ["TEXT_GOLDENROD_DEPT_STORE_B1_F_OBJ_006"] = "Perco a vontade\nde trabalhar se\valguém me vê.\fAnda, garoto,\ncai fora!",
  ["TEXT_GOLDENROD_DEPT_STORE_B1_F_OBJ_007"] = "Oohah! Oohah!\fAs coisas no\nchão são lixo.\fLeve-as se\nquiser!",
  ["TEXT_GOLDENROD_FLOWER_SHOP_OBJ_002"] = "Conhece a árvore\nque anda?\fSe você a regar,\nela pula de\vsurpresa!",
  ["TEXT_GOLDENROD_GAME_CORNER_OBJ_002"] = "Bem-vindo!\fTrocamos suas\nmoedas de jogo\vpor prêmios bons!",
  ["TEXT_GOLDENROD_GAME_CORNER_OBJ_003"] = "Bem-vindo!\fTrocamos suas\nmoedas de jogo\vpor prêmios bons!",
  ["TEXT_GOLDENROD_GAME_CORNER_OBJ_004"] = "Sempre jogo nesta\nmáquina.\fAcho que ela paga\nmais que outras.",
  ["TEXT_GOLDENROD_GAME_CORNER_OBJ_005"] = "Sempre jogo nesta\nmáquina.\fAcho que ela paga\nmais que outras.",
  ["TEXT_GOLDENROD_GAME_CORNER_OBJ_006"] = "Adoro esta nova\ncaça-níqueis.\fÉ mais desafiadora\nque as de\vCELADON.",
  ["TEXT_GOLDENROD_GAME_CORNER_OBJ_007"] = "A vida é um jogo.\nVou virar\vcartas até cair!",
  ["TEXT_GOLDENROD_GAME_CORNER_OBJ_008"] = "Vira-cartas…\fPrefiro aos\ncaça-níqueis\fporque é mais\nfácil de calcular\fas chances.\nMas paga menos.",
  ["TEXT_GOLDENROD_GAME_CORNER_OBJ_009"] = "Não paro até\nconseguir vencer!",
  ["TEXT_GOLDENROD_GAME_CORNER_OBJ_010"] = "Ensinei BLIZZARD\nao meu POKéMON.\fFoi difícil juntar\nas moedas para\fele, mas valeu\na pena.",
  ["TEXT_GOLDENROD_GAME_CORNER_OBJ_011"] = "Perdi nas\ncaça-níqueis,\fgastei tudo\nna vira-cartas…\fFiquei tão nervoso\nque joguei fora\fminha COIN CASE\nno UNDERGROUND.",
  ["TEXT_GOLDENROD_GYM_OBJ_001"] = "Oi! Sou WHITNEY!\fTodo mundo curtia\nPOKéMON, então eu\ventrei também!\fPOKéMON são\nfofos demais!\fQuer batalhar?\nEstou avisando,\veu sou boa!",
  ["TEXT_GOLDENROD_GYM_OBJ_002"] = "No mundo dos\nPOKéMON, será que\fé mais forte:\nmacho ou fêmea?",
  ["TEXT_GOLDENROD_GYM_OBJ_002_AFTER"] = "No mundo dos\nPOKéMON, será que\fé mais forte:\nmacho ou fêmea?",
  ["TEXT_GOLDENROD_GYM_OBJ_002_BEATEN"] = "Droga… Pensei que\nvocê fosse fraco…",
  ["TEXT_GOLDENROD_GYM_OBJ_002_SEEN"] = "Não pense que sou\nfácil de vencer!",
  ["TEXT_GOLDENROD_GYM_OBJ_003"] = "Tento vencer a\nWHITNEY, mas… É\vdeprimente.\fEstou bem! Se eu\nperder, tentarei\fde novo da próxima\nvez!",
  ["TEXT_GOLDENROD_GYM_OBJ_003_AFTER"] = "Tento vencer a\nWHITNEY, mas… É\vdeprimente.\fEstou bem! Se eu\nperder, tentarei\fde novo da próxima\nvez!",
  ["TEXT_GOLDENROD_GYM_OBJ_003_BEATEN"] = "Ah, não, não!",
  ["TEXT_GOLDENROD_GYM_OBJ_003_SEEN"] = "Gosto mais de POKé\nMON fofos do que\vdos fortes.\fMas tenho POKéMON\nfortes e fofos!",
  ["TEXT_GOLDENROD_GYM_OBJ_004"] = "Uau, você deve ser\nbom pra me vencer!\vContinue assim!",
  ["TEXT_GOLDENROD_GYM_OBJ_004_AFTER"] = "Uau, você deve ser\nbom pra me vencer!\vContinue assim!",
  ["TEXT_GOLDENROD_GYM_OBJ_004_BEATEN"] = "Vejamos… Ops,\nacabou?",
  ["TEXT_GOLDENROD_GYM_OBJ_004_SEEN"] = "Oh, que treinador\nbonitinho! Gosto\fde você, mas não\nvou me segurar!",
  ["TEXT_GOLDENROD_GYM_OBJ_005"] = "Ensinei ao MEOWTH\ngolpes para lidar\vcom todo tipo…",
  ["TEXT_GOLDENROD_GYM_OBJ_005_AFTER"] = "Ensinei ao MEOWTH\ngolpes para lidar\vcom todo tipo…",
  ["TEXT_GOLDENROD_GYM_OBJ_005_BEATEN"] = "Não! Oh, MEOWTH,\nme desculpe!",
  ["TEXT_GOLDENROD_GYM_OBJ_005_SEEN"] = "Dê o seu melhor,\nou eu vou te\vderrubar!",
  ["TEXT_GOLDENROD_GYM_OBJ_006"] = "E aí! Futuro\nCAMPEÃO!\fEste GINÁSIO é de\ntreinadores de\vPOKéMON normais.\fRecomendo que use\nPOKéMON do tipo\vlutador.",
  ["TEXT_GOLDENROD_HAPPINESS_RATER_BG_001"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_GOLDENROD_HAPPINESS_RATER_BG_002"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_GOLDENROD_HAPPINESS_RATER_OBJ_002"] = "Vivo perdendo\nbatalhas e meus\fPOKéMON acabam\ndesmaiando…\fTalvez por isso\nmeus POKéMON não\vgostem de mim…",
  ["TEXT_GOLDENROD_HAPPINESS_RATER_OBJ_003"] = "Quando uso item\nno POKéMON, ele\vfica todo feliz!",
  ["TEXT_GOLDENROD_MAGNET_TRAIN_STATION_OBJ_001"] = "O trem não\nchegou…\fJá sei! Vou levar\nos passageiros\vnas costas!\fNão vai dar.",
  ["TEXT_GOLDENROD_MAGNET_TRAIN_STATION_OBJ_002"] = "Sou o PRESIDENTE.\fMeu sonho era\nconstruir um trem\fmais rápido que\nqualquer POKéMON.\fEle realmente\naproxima JOHTO e\vKANTO.",
  ["TEXT_GOLDENROD_NAME_RATER_BG_001"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_GOLDENROD_NAME_RATER_BG_002"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_GOLDENROD_NAME_RATER_OBJ_001"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_GOLDENROD_PPSPEECH_HOUSE_BG_001"] = "Revistas de\nPOKéMON… POKéMON\vPAL,\fPOKéMON HANDBOOK,\nPOKéMON GRAPH…",
  ["TEXT_GOLDENROD_PPSPEECH_HOUSE_BG_002"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_GOLDENROD_PPSPEECH_HOUSE_OBJ_001"] = "Uma vez, numa\nbatalha, meu\fPOKéMON não\nconseguia agir.\fOs POWER POINTS,\nou PP, dos seus\fgolpes tinham\nacabado.",
  ["TEXT_GOLDENROD_PPSPEECH_HOUSE_OBJ_002"] = "Às vezes, um\nPOKéMON saudável\fnão consegue usar\nseus golpes.\fSe isso ocorrer,\ncurar no CENTRO\vPOKéMON ou usar\vum item.",
  ["TEXT_GOLDENROD_UNDERGROUND_BG_001"] = "Porta trancada…",
  ["TEXT_GOLDENROD_UNDERGROUND_OBJ_001"] = "Acho que tenho que\nfazer as coisas\vdireito…",
  ["TEXT_GOLDENROD_UNDERGROUND_OBJ_001_AFTER"] = "Acho que tenho que\nfazer as coisas\vdireito…",
  ["TEXT_GOLDENROD_UNDERGROUND_OBJ_001_SEEN"] = "Fui expulso do\nGAME CORNER.\fEu tentei\ntrapacear com\vmeu POKéMON…",
  ["TEXT_GOLDENROD_UNDERGROUND_OBJ_002"] = "Eu sei as\nvantagens de\vtipo.\fMas eu só uso um\ntipo de POKéMON.",
  ["TEXT_GOLDENROD_UNDERGROUND_OBJ_002_AFTER"] = "Eu sei as\nvantagens de\vtipo.\fMas eu só uso um\ntipo de POKéMON.",
  ["TEXT_GOLDENROD_UNDERGROUND_OBJ_002_BEATEN"] = "Ai, ai, ai!",
  ["TEXT_GOLDENROD_UNDERGROUND_OBJ_002_SEEN"] = "Você leva o tipo\nem conta durante\va batalha?\fSe souber as\nvantagens do tipo\fvai se sair melhor\nna batalha.",
  ["TEXT_GOLDENROD_UNDERGROUND_OBJ_003"] = "Seus POKéMON vão\ngostar mais de\fvocê se der um\ntrato no pelo.",
  ["TEXT_GOLDENROD_UNDERGROUND_OBJ_003_AFTER"] = "Seus POKéMON vão\ngostar mais de\fvocê se der um\ntrato no pelo.",
  ["TEXT_GOLDENROD_UNDERGROUND_OBJ_003_BEATEN"] = "Aiii!",
  ["TEXT_GOLDENROD_UNDERGROUND_OBJ_003_SEEN"] = "Meus POKéMON\nacabaram de tosar\fVou mostrar como\neles são fortes!",
  ["TEXT_GOLDENROD_UNDERGROUND_OBJ_004"] = "Está fazendo uma\nPOKéDEX? Aqui vai\vuma dica boa.\fO HIKER da ROTA\n33, o ANTHONY, é\vgente boa.\fEle te liga se vir\nalgum POKéMON\vraro.",
  ["TEXT_GOLDENROD_UNDERGROUND_OBJ_004_AFTER"] = "Está fazendo uma\nPOKéDEX? Aqui vai\vuma dica boa.\fO HIKER da ROTA\n33, o ANTHONY, é\vgente boa.\fEle te liga se vir\nalgum POKéMON\vraro.",
  ["TEXT_GOLDENROD_UNDERGROUND_OBJ_004_BEATEN"] = "Gaah! Eu perdi!\nQue raiva!",
  ["TEXT_GOLDENROD_UNDERGROUND_OBJ_004_SEEN"] = "Acho que você tem\nuns POKéMON raros\vaí com você.\fDeixe eu ver!",
  ["TEXT_GOLDENROD_UNDERGROUND_OBJ_007"] = "Bem-vindo!\fEu administro o\nPOKéMON SALON!\fSou o mais velho e\nmelhor dos dois\vHAIRCUT BROTHERS.\fPosso deixar seu\nPOKéMON bonito\vpor apenas R$500.\fGostaria\ndisso?",
  ["TEXT_GOLDENROD_UNDERGROUND_OBJ_008"] = "Bem-vindo ao\nPOKéMON SALON!\fSou o mais jovem\ne menos caro\vdos dois IRTOS\vCABELEIREIROS.\fVou arrumar seu\nPOKéMON por\vapenas R$300.\fComo vai?",
  ["TEXT_GOLDENROD_UNDERGROUND_SWITCH_ROOM_ENTRANCES_BG_001"] = "Está escrito\nSWITCH 1.",
  ["TEXT_GOLDENROD_UNDERGROUND_SWITCH_ROOM_ENTRANCES_BG_002"] = "Está escrito\nSWITCH 2.",
  ["TEXT_GOLDENROD_UNDERGROUND_SWITCH_ROOM_ENTRANCES_BG_003"] = "Está escrito\nSWITCH 3.",
  ["TEXT_GOLDENROD_UNDERGROUND_SWITCH_ROOM_ENTRANCES_BG_004"] = "Está escrito\nEMERGÊNCIA.",
  ["TEXT_GOLDENROD_UNDERGROUND_SWITCH_ROOM_ENTRANCES_OBJ_001_AFTER"] = "Roubar e vender!\nÉ o básico do\vcrime, colega!",
  ["TEXT_GOLDENROD_UNDERGROUND_SWITCH_ROOM_ENTRANCES_OBJ_001_BEATEN"] = "Piedade!",
  ["TEXT_GOLDENROD_UNDERGROUND_SWITCH_ROOM_ENTRANCES_OBJ_001_SEEN"] = "Passe as suas\ncoisas para cá!",
  ["TEXT_GOLDENROD_UNDERGROUND_SWITCH_ROOM_ENTRANCES_OBJ_002_AFTER"] = "UNDERGROUND\nWAREHOUSE?\fPara que você quer\nir lá?\fNão tem nada lá\nembaixo.",
  ["TEXT_GOLDENROD_UNDERGROUND_SWITCH_ROOM_ENTRANCES_OBJ_002_BEATEN"] = "Passou dos\nlimites!",
  ["TEXT_GOLDENROD_UNDERGROUND_SWITCH_ROOM_ENTRANCES_OBJ_002_SEEN"] = "Abandonaram esta\nobra antes de\vterminar.\fEstou procurando\no que sobrou.",
  ["TEXT_GOLDENROD_UNDERGROUND_SWITCH_ROOM_ENTRANCES_OBJ_003_AFTER"] = "Você tem sangue\nde gelo para\vpeitar a ROCKET.",
  ["TEXT_GOLDENROD_UNDERGROUND_SWITCH_ROOM_ENTRANCES_OBJ_003_BEATEN"] = "Urk! É, se acha\nesperto, hein?",
  ["TEXT_GOLDENROD_UNDERGROUND_SWITCH_ROOM_ENTRANCES_OBJ_003_SEEN"] = "Não ligo se você\nestá perdido.\fApareceu aqui,\nvirou vítima e\vpronto!",
  ["TEXT_GOLDENROD_UNDERGROUND_SWITCH_ROOM_ENTRANCES_OBJ_004"] = "Droga! Afundei\npor indecisão!",
  ["TEXT_GOLDENROD_UNDERGROUND_SWITCH_ROOM_ENTRANCES_OBJ_004_AFTER"] = "Eu também estou\nconfuso… O botão\fda ponta é o que\nse aperta antes…",
  ["TEXT_GOLDENROD_UNDERGROUND_SWITCH_ROOM_ENTRANCES_OBJ_004_BEATEN"] = "Droga! Afundei\npor indecisão!",
  ["TEXT_GOLDENROD_UNDERGROUND_SWITCH_ROOM_ENTRANCES_OBJ_004_SEEN"] = "Abre uma persiana,\noutra fecha.\fAposto que não\nchega onde quer!",
  ["TEXT_GOLDENROD_UNDERGROUND_SWITCH_ROOM_ENTRANCES_OBJ_005_AFTER"] = "Certo. Uma dica!\fMude a ordem em\nque você aperta.\fIsso muda o jeito\nque as persianas\vabrem e fecham.",
  ["TEXT_GOLDENROD_UNDERGROUND_SWITCH_ROOM_ENTRANCES_OBJ_005_BEATEN"] = "Ai…\nEstraguei tudo.",
  ["TEXT_GOLDENROD_UNDERGROUND_SWITCH_ROOM_ENTRANCES_OBJ_005_SEEN"] = "Kwahaha!\fConfuso com as\npersianas, né?\fEu conto um\nsegredo se você\vme vencer!",
  ["TEXT_GOLDENROD_UNDERGROUND_SWITCH_ROOM_ENTRANCES_OBJ_006_AFTER"] = "Vá para onde você\nquiser! Some!\vNão estou nem aí!",
  ["TEXT_GOLDENROD_UNDERGROUND_SWITCH_ROOM_ENTRANCES_OBJ_006_BEATEN"] = "Como você pôde?",
  ["TEXT_GOLDENROD_UNDERGROUND_SWITCH_ROOM_ENTRANCES_OBJ_006_SEEN"] = "Está perdido? Não,\nnão pode estar.\fVocê não tem\ncara de assustado\fVou te dar\num motivo para\vse assustar!",
  ["TEXT_GOLDENROD_UNDERGROUND_SWITCH_ROOM_ENTRANCES_OBJ_007"] = "Há lojas\nlá embaixo…\fMas também\nhá treinadores.\fTenho medo\nde descer.",
  ["TEXT_GOLDENROD_UNDERGROUND_SWITCH_ROOM_ENTRANCES_OBJ_008"] = "Fui desafiado\npara uma batalha\vlá embaixo.\fÉ perigoso\nlá. Melhor\vtomar cuidado.",
  ["TEXT_GOLDENROD_UNDERGROUND_WAREHOUSE_OBJ_001"] = "A TEAM ROCKET vai\nseguir em frente,\vesperando a volta\vdo GIOVANNI.\fFaremos o que for\npreciso.",
  ["TEXT_GOLDENROD_UNDERGROUND_WAREHOUSE_OBJ_001_AFTER"] = "A TEAM ROCKET vai\nseguir em frente,\vesperando a volta\vdo GIOVANNI.\fFaremos o que for\npreciso.",
  ["TEXT_GOLDENROD_UNDERGROUND_WAREHOUSE_OBJ_001_BEATEN"] = "Ele acabou comigo",
  ["TEXT_GOLDENROD_UNDERGROUND_WAREHOUSE_OBJ_001_SEEN"] = "Como você chegou\naté aqui?\fNão tem jeito.\nVou acabar com\vvocê.",
  ["TEXT_GOLDENROD_UNDERGROUND_WAREHOUSE_OBJ_002"] = "Eu perdi…\fPor favor me\nperdoe, GIOVANNI!",
  ["TEXT_GOLDENROD_UNDERGROUND_WAREHOUSE_OBJ_002_AFTER"] = "Eu perdi…\fPor favor me\nperdoe, GIOVANNI!",
  ["TEXT_GOLDENROD_UNDERGROUND_WAREHOUSE_OBJ_002_BEATEN"] = "Droga!",
  ["TEXT_GOLDENROD_UNDERGROUND_WAREHOUSE_OBJ_002_SEEN"] = "Você não passa\ndaqui!\fNão tenho piedade\ndos inimigos, nem\vdos pirralhos!",
  ["TEXT_GOLDENROD_UNDERGROUND_WAREHOUSE_OBJ_003"] = "Hyuck-hyuck-hyuck!\nFoi demais!\vVou me lembrar!",
  ["TEXT_GOLDENROD_UNDERGROUND_WAREHOUSE_OBJ_003_AFTER"] = "Hyuck-hyuck-hyuck!\nFoi demais!\vVou me lembrar!",
  ["TEXT_GOLDENROD_UNDERGROUND_WAREHOUSE_OBJ_003_BEATEN"] = "Hyuck-hyuck-hyuck!\nEntão é assim?",
  ["TEXT_GOLDENROD_UNDERGROUND_WAREHOUSE_OBJ_003_SEEN"] = "Hyuck-hyuck-hyuck!\nLembro de você!\fVocê me pegou\nno esconderijo!",
  ["TEXT_GOLDENROD_UNDERGROUND_WAREHOUSE_OBJ_004"] = "DIRECTOR: Quem?\nO quê? Você veio\vme resgatar?\fObrigado!\fA RADIO TOWER!\fO que está\nacontecendo lá?\fTomada pela\nTEAM ROCKET?\fAqui. Pegue\na CARD KEY.",
  ["TEXT_GUIDE_GENTS_HOUSE_OBJ_001"] = "Quando eu era\npequeno, eu era um\vtreinador craque!\fVai um conselho:\npegue um monte\vde POKéMON!\fTrate todos eles\ncom bondade!",
  ["TEXT_ICE_PATH_B1_F_OBJ_001"] = "Cure Seus POKéMON!\nCENTRO POKéMON",
  ["TEXT_ICE_PATH_B1_F_OBJ_002"] = "Cure Seus POKéMON!\nCENTRO POKéMON",
  ["TEXT_ICE_PATH_B1_F_OBJ_003"] = "Cure Seus POKéMON!\nCENTRO POKéMON",
  ["TEXT_ICE_PATH_B1_F_OBJ_004"] = "Cure Seus POKéMON!\nCENTRO POKéMON",
  ["TEXT_ICE_PATH_B3_F_OBJ_002"] = "Cure Seus POKéMON!\nCENTRO POKéMON",
  ["TEXT_ILEX_FOREST_BG_001"] = "A ILEX FOREST tem\ntanta árvore que\fnão dá para ver\no céu.\fFique de olho em\nitens que possam\vter caído por aí.",
  ["TEXT_ILEX_FOREST_BG_005"] = "SANTUÁRIO da ILEX\nFOREST…\fÉ em honra ao\nprotetor da\vfloresta…",
  ["TEXT_ILEX_FOREST_OBJ_008_AFTER"] = "Um POKéMON que eu\nnunca vi\fcaiu da árvore\nquando usei\vHEADBUTT.\fDevia usar\nHEADBUTT em\voutros lugares\vtambém.",
  ["TEXT_ILEX_FOREST_OBJ_008_BEATEN"] = "Eu nunca tinha\nvisto esse\vPOKéMON…",
  ["TEXT_ILEX_FOREST_OBJ_008_SEEN"] = "Não chegue assim\nde repente!\fVocê assustou um\nPOKéMON!",
  ["TEXT_INDIGO_PLATEAU_POKECENTER1_F_OBJ_001"] = "Bom dia!\nBem-vindo ao nosso\vCENTRO POKéMON.",
  ["TEXT_INDIGO_PLATEAU_POKECENTER1_F_OBJ_002"] = "Na POKéMON LEAGUE\nvocê vai ser\ftestado pelos\nELITE FOUR.\fTem que vencer\ntodos eles. Se\fperder, começa\ntudo de novo!",
  ["TEXT_INDIGO_PLATEAU_POKECENTER1_F_OBJ_003"] = "Na POKéMON LEAGUE\nvocê vai ser\ftestado pelos\nELITE FOUR.\fTem que vencer\ntodos eles. Se\fperder, começa\ntudo de novo!",
  ["TEXT_INDIGO_PLATEAU_POKECENTER1_F_OBJ_005"] = "Ah! Você vai\ndesafiar os ELITE\fFOUR? Tem certeza\nque está pronto?\fSe precisar\ntreinar mais,\fmeu ABRA pode\najudar você.\fEle pode TELEPORT\nvocê para casa.\fVocê quer ir\npara casa agora?",
  ["TEXT_KARENS_ROOM_OBJ_001"] = "Eu sou KAREN, dos\nELITE FOUR.\fVocê é {PLAYER}?\nQue divertido.\fEu amo POKéMON\ndo tipo sombrio.\fAcho a imagem\nselvagem e dura\fdeles atraente. E\neles são fortes.\fAcha que dá conta\ndeles? Só tente\vme entreter.\fVamos lá.",
  ["TEXT_KOGAS_ROOM_OBJ_001"] = "Fuahahahaha!\fEu sou KOGA, dos\nELITE FOUR.\fEu vivo nas\nsombras, ninja!\fMeu estilo é\nintrincado e vai\vdestruir você!\fConfusão, sono,\nveneno…\fPrepare-se para\nser vítima da\vminha técnica!\fFuahahahaha!\fPOKéMON não é só\nforça bruta,\fvocê vai ver isso\nlogo, logo!",
  ["TEXT_KURTS_HOUSE_BG_002"] = "…Um PROF.OAK\njovem?",
  ["TEXT_KURTS_HOUSE_BG_003"] = "…Um PROF.OAK\njovem?",
  ["TEXT_KURTS_HOUSE_BG_004"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_KURTS_HOUSE_BG_005"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_KURTS_HOUSE_BG_006"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_KURTS_HOUSE_BG_007"] = "É uma estátua do\nprotetor da\vfloresta.",
  ["TEXT_KURTS_HOUSE_OBJ_001"] = "Hm? Quem é você?\f{PLAYER}, é? Quer\nque eu faça umas\vBALLS?\fDesculpe, mas isso\nvai esperar.\fConhece a TEAM\nROCKET? Ah, não\fimporta. Eu conto\nde qualquer forma\fA TEAM ROCKET é\numa gangue má que\fusa POKéMON para\no trabalho sujo.\fEra para eles\nterem se desfeito\vhá três anos.\fEnfim, estão no\nPOÇO, cortando\fSLOWPOKETAILS para\nvender!\fEntão eu vou lá\ndar uma lição\vdolorosa neles!\fAguente firme,\nSLOWPOKE! O velho\vKURT está indo!",
  ["TEXT_KURTS_HOUSE_OBJ_003"] = "SLOWPOKE: …\nBocejo?",
  ["TEXT_KURTS_HOUSE_OBJ_004"] = "Hm? Quem é você?\f{PLAYER}, é? Quer\nque eu faça umas\vBALLS?\fDesculpe, mas isso\nvai esperar.\fConhece a TEAM\nROCKET? Ah, não\fimporta. Eu conto\nde qualquer forma\fA TEAM ROCKET é\numa gangue má que\fusa POKéMON para\no trabalho sujo.\fEra para eles\nterem se desfeito\vhá três anos.\fEnfim, estão no\nPOÇO, cortando\fSLOWPOKETAILS para\nvender!\fEntão eu vou lá\ndar uma lição\vdolorosa neles!\fAguente firme,\nSLOWPOKE! O velho\vKURT está indo!",
  ["TEXT_LAKE_OF_RAGE_BG_001"] = "LAKE OF RAGE,\ntambém chamado de\vGYARADOS LAKE.",
  ["TEXT_LAKE_OF_RAGE_BG_002"] = "CASA DO\nFISHING GURU",
  ["TEXT_LAKE_OF_RAGE_HIDDEN_POWER_HOUSE_BG_001"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_LAKE_OF_RAGE_HIDDEN_POWER_HOUSE_BG_002"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_LAKE_OF_RAGE_HIDDEN_POWER_HOUSE_OBJ_001"] = "…Você vagou muito\nlonge…\fAqui eu meditei.\nDentro de mim,\fum novo poder\ndespertou.\fDeixe-me dividir\nmeu poder com\fseu POKéMON.\nTome, criança.",
  ["TEXT_LAKE_OF_RAGE_MAGIKARP_HOUSE_OBJ_001"] = "O LAKE OF RAGE é\nna verdade uma\fcratera feita por\nGYARADOS em fúria\fA cratera encheu\nde água de chuva\fe assim nasceu\no LAKE.\fÉ a história que\nveio do tataravô\fdo tataravô do\nmeu vovô.\fAntigamente dava\npara pescar\fMAGIKARP animados\nali, mas…\fEu não entendo o\nque está havendo.",
  ["TEXT_LAKE_OF_RAGE_OBJ_001"] = "Este lago está\ncheio de GYARADOS\ve mais nada…\fEntão os MAGIKARP\nestão sendo\vforçados a\vevoluir…",
  ["TEXT_LAKE_OF_RAGE_OBJ_002"] = "Os GYARADOS estão\nfuriosos!\fÉ mau agouro!",
  ["TEXT_LAKE_OF_RAGE_OBJ_003"] = "Ouvi que este lago\nfoi feito por\vGYARADOS em fúria\fSerá que tem\nalguma ligação\fcom esse surto\ntodo de agora?",
  ["TEXT_LAKE_OF_RAGE_OBJ_004"] = "Meus olhos me\nenganaram? Eu vi\fum GYARADOS\nvermelho no LAKE…\fMas eu achava que\nGYARADOS eram\vazuis, não?",
  ["TEXT_LAKE_OF_RAGE_OBJ_005"] = "Não perco como\npescador! Pesco\vPOKéMON todo dia",
  ["TEXT_LAKE_OF_RAGE_OBJ_005_AFTER"] = "Não perco como\npescador! Pesco\vPOKéMON todo dia",
  ["TEXT_LAKE_OF_RAGE_OBJ_005_BEATEN"] = "Sou bom pescador,\nmas péssimo como\ftreinador de\nPOKéMON…",
  ["TEXT_LAKE_OF_RAGE_OBJ_005_SEEN"] = "Deixe-me batalhar\ncom o POKéMON que\vacabei de pegar!",
  ["TEXT_LAKE_OF_RAGE_OBJ_006"] = "Por que não pego\nbons POKéMON?",
  ["TEXT_LAKE_OF_RAGE_OBJ_006_AFTER"] = "Por que não pego\nbons POKéMON?",
  ["TEXT_LAKE_OF_RAGE_OBJ_006_BEATEN"] = "Minha linha está\ntoda embaraçada…",
  ["TEXT_LAKE_OF_RAGE_OBJ_006_SEEN"] = "Não importa o que\nfaça, só pego os\fmesmos POKéMON…",
  ["TEXT_LAKE_OF_RAGE_OBJ_007"] = "POKéMON e o dono\nficam fortes\fcom batalha\nconstante.",
  ["TEXT_LAKE_OF_RAGE_OBJ_007_AFTER"] = "POKéMON e o dono\nficam fortes\fcom batalha\nconstante.",
  ["TEXT_LAKE_OF_RAGE_OBJ_007_BEATEN"] = "Ufa…\nBoa batalha.",
  ["TEXT_LAKE_OF_RAGE_OBJ_007_SEEN"] = "Se um treinador vê\noutro, ele tem\fque fazer um\ndesafio. Esse\fé o nosso\ndestino.",
  ["TEXT_LAKE_OF_RAGE_OBJ_008"] = "Pensando bem,\nvi um BUTTERFREE\vrosa.",
  ["TEXT_LAKE_OF_RAGE_OBJ_008_AFTER"] = "Pensando bem,\nvi um BUTTERFREE\vrosa.",
  ["TEXT_LAKE_OF_RAGE_OBJ_008_BEATEN"] = "Muito bem!",
  ["TEXT_LAKE_OF_RAGE_OBJ_008_SEEN"] = "O que aconteceu\ncom o GYARADOS\fvermelho? Sumiu?\fDroga. Vim\nà toa?\fJá sei, vamos\nbatalhar!",
  ["TEXT_LAKE_OF_RAGE_OBJ_009"] = "GYARADOS: Gyasha!",
  ["TEXT_LAKE_OF_RAGE_OBJ_010"] = "WESLEY: Olá, como\nvai você?\fJá que hoje é\nquarta-feira,\fsou o WESLEY da\nquarta.",
  ["TEXT_LANCES_ROOM_OBJ_001"] = "LANCE: Eu estava\nesperando você.\f{PLAYER}!\fEu sabia que você,\ncom seu talento,\fia acabar\nchegando até mim.\fNão é hora de\npalavras agora.\fVamos batalhar\npara decidir quem\fé o mais forte\nde nós dois.\fComo o treinador\nmais poderoso e\fcomo CAMPEÃO da\nPOKéMON LEAGUE…\fEu, LANCE, mestre\ndos dragões,\vaceito o desafio!",
  ["TEXT_LAVENDER_MART_OBJ_001"] = "REPEL é coisa\nnecessária se\fvai explorar uma\ncaverna.\fMesmo gostando de\nexplorar, ainda\fnão fui a todas\nas cavernas.",
  ["TEXT_LAVENDER_NAME_RATER_OBJ_001"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_LAVENDER_POKECENTER1_F_OBJ_001"] = "Bom dia!\nBem-vindo ao nosso\vCENTRO POKéMON.",
  ["TEXT_LAVENDER_POKECENTER1_F_OBJ_002"] = "Ao norte de\nLAVENDER fica o\fROCK TUNNEL. Vá\npor ele até a\vPOWER PLANT.",
  ["TEXT_LAVENDER_POKECENTER1_F_OBJ_003"] = "Tem um programa\nde rádio que toca\va POKé FLUTE.\fAh? Seu rádio\nprecisa do EXPN\vCARD para pegar.",
  ["TEXT_LAVENDER_POKECENTER1_F_OBJ_004"] = "A RADIO STATION\nnão pode ir ao ar\fporque a POWER\nPLANT parou.",
  ["TEXT_LAVENDER_SPEECH_HOUSE_OBJ_001"] = "LAVENDER é uma\nvila pequena e\fquieta, no pé da\nmontanha.\fFicou um pouco\nmais movimentada\fdesde que a RADIO\nTOWER foi feita.",
  ["TEXT_LAVENDER_TOWN_OBJ_001"] = "Que prédio é\nesse, hein?\fÉ a TORRE de\nRÁDIO de KANTO.",
  ["TEXT_LAVENDER_TOWN_OBJ_002"] = "KANTO tem muito\nprograma de rádio",
  ["TEXT_LAVENDER_TOWN_OBJ_003"] = "As pessoas vêm de\nlonge para\fhomenagear as\nalmas dos\vPOKéMON.",
  ["TEXT_LAVENDER_TOWN_OBJ_004"] = "Você precisa de\numa POKé FLUTE pra\vacordar\fPOKéMON. Todo\ntreinador sabe\vdisso!",
  ["TEXT_LAV_RADIO_TOWER1_F_OBJ_001"] = "Bem-vindo!\nFique à vontade\fpara olhar tudo\nneste andar.",
  ["TEXT_LAV_RADIO_TOWER1_F_OBJ_002"] = "Desculpe, mas você\nsó pode visitar\vo térreo.\fDesde que a RADIO\nTOWER de JOHTO\ffoi tomada por uma\ngangue, a gente\fteve que reforçar\na segurança.",
  ["TEXT_LAV_RADIO_TOWER1_F_OBJ_003"] = "Muita gente aqui\ntrabalha duro\fna RADIO\nTOWER.\fDevem estar dando\no melhor para\vbons programas.",
  ["TEXT_LAV_RADIO_TOWER1_F_OBJ_004"] = "Ah, não, não!\fA gente está fora\ndo ar desde que a\fPOWER PLANT\nparou.\fTodo o esforço de\nabrir esta rádio\fvira pó se eu\nnão for ao ar.\fEstou arruinado!",
  ["TEXT_LAV_RADIO_TOWER1_F_OBJ_005"] = "Olá, camarada!\fEu sou o super\nMUSIC DIRECTOR!\fHã? Seu POKéGEAR\nnão pega os meus\fprogramas.\nQue azar!\fSe pegar o EXPN\nCARD, você\fconsegue ouvir.\nVá atrás de um!",
  ["TEXT_MAHOGANY_GYM_OBJ_001"] = "POKéMON vivem\nmuitas coisas na\fvida deles, assim\ncomo nós.\fEu também já vi\ne sofri muito\vna minha vida.\fComo sou mais\nvelho, deixe eu\vmostrar o que é.\fEstou com POKéMON\ndesde antes\fde você\nnascer.\fEu não perco\nfácil.\fEu, PRYCE, o\ntreinador do\finverno, vou\nmostrar meu poder",
  ["TEXT_MAHOGANY_GYM_OBJ_002"] = "Sem patinar com\nprecisão, você\fnão vai longe\nneste GINÁSIO.",
  ["TEXT_MAHOGANY_GYM_OBJ_002_AFTER"] = "Sem patinar com\nprecisão, você\fnão vai longe\nneste GINÁSIO.",
  ["TEXT_MAHOGANY_GYM_OBJ_002_BEATEN"] = "Não perderia para\nvocê no esqui!",
  ["TEXT_MAHOGANY_GYM_OBJ_002_SEEN"] = "Para chegar ao\nPRYCE, você\fprecisa pensar\nantes de patinar.",
  ["TEXT_MAHOGANY_GYM_OBJ_003"] = "Acho que existe um\nmovimento que um\fPOKéMON pode usar\nmesmo congelado.",
  ["TEXT_MAHOGANY_GYM_OBJ_003_AFTER"] = "Acho que existe um\nmovimento que um\fPOKéMON pode usar\nmesmo congelado.",
  ["TEXT_MAHOGANY_GYM_OBJ_003_BEATEN"] = "Droga. Não pude\nfazer nada.",
  ["TEXT_MAHOGANY_GYM_OBJ_003_SEEN"] = "Vou congelar\nseus POKéMON, você\vnão fará nada!",
  ["TEXT_MAHOGANY_GYM_OBJ_004"] = "Não devia ter\nme gabado do meu\vesqui…",
  ["TEXT_MAHOGANY_GYM_OBJ_004_AFTER"] = "Não devia ter\nme gabado do meu\vesqui…",
  ["TEXT_MAHOGANY_GYM_OBJ_004_BEATEN"] = "Não! Você me fez\ncair!",
  ["TEXT_MAHOGANY_GYM_OBJ_004_SEEN"] = "Veja minha\nvirada paralela!",
  ["TEXT_MAHOGANY_GYM_OBJ_005"] = "Adoro patinar\ncom meus POKéMON\vneste GINÁSIO!",
  ["TEXT_MAHOGANY_GYM_OBJ_005_AFTER"] = "Adoro patinar\ncom meus POKéMON\vneste GINÁSIO!",
  ["TEXT_MAHOGANY_GYM_OBJ_005_BEATEN"] = "Você vê como\nsomos sérios?",
  ["TEXT_MAHOGANY_GYM_OBJ_005_SEEN"] = "Este GINÁSIO\ntem piso liso.\fÉ divertido, não\né?\fMas ei, aqui nós\nnão estamos\vbrincando!",
  ["TEXT_MAHOGANY_GYM_OBJ_006"] = "O segredo do\npoder de PRYCE…\fEle medita sob\numa cachoeira\fpara fortalecer\nmente e corpo.",
  ["TEXT_MAHOGANY_GYM_OBJ_006_AFTER"] = "O segredo do\npoder de PRYCE…\fEle medita sob\numa cachoeira\fpara fortalecer\nmente e corpo.",
  ["TEXT_MAHOGANY_GYM_OBJ_006_BEATEN"] = "Vou te contar o\nsegredo do PRYCE.",
  ["TEXT_MAHOGANY_GYM_OBJ_006_SEEN"] = "Conheço o segredo\ndo PRYCE.",
  ["TEXT_MAHOGANY_GYM_OBJ_007"] = "O PRYCE é veterano\ne treina POKéMON\fhá uns\n50 anos.\fDizem que ele é\nbom em congelar\fadversários com\ngolpes de gelo.\fOu seja, você tem\nque derreter ele\fcom sua ambição\nem chamas!",
  ["TEXT_MAHOGANY_MART1_F_OBJ_001"] = "Arrgh… Você achou\na escada\vsecreta…",
  ["TEXT_MAHOGANY_MART1_F_OBJ_002"] = "Heheh! O\nexperimento\vfuncionou que é\vuma beleza.\fMAGIKARP não valem\nnada, mas\fGYARADOS dão muito\ndinheiro.",
  ["TEXT_MAHOGANY_POKECENTER1_F_OBJ_001"] = "Bom dia!\nBem-vindo ao nosso\vCENTRO POKéMON.",
  ["TEXT_MAHOGANY_RED_GYARADOS_SPEECH_HOUSE_OBJ_001"] = "Ouvi que apareceu\num GYARADOS\vvermelho no LAKE.\fÉ estranho, pois\naté GYARADOS\fcomuns são raros\nnaquele lago…",
  ["TEXT_MAHOGANY_RED_GYARADOS_SPEECH_HOUSE_OBJ_002"] = "Meu programa de\nrádio favorito? O\vPOKéMON MUSIC.",
  ["TEXT_MAHOGANY_TOWN_OBJ_001"] = "O RAGECANDYBAR\nesgotou.\fEstou fechando.\nNão me amole,\vgarotinho.",
  ["TEXT_MAHOGANY_TOWN_OBJ_002"] = "Vai lá ver o\nGYARADOS em fúria\vno LAKE?",
  ["TEXT_MAHOGANY_TOWN_OBJ_003"] = "Já que veio até\naqui, aproveite\fpara passear um\npouco.\fVá para o norte\ne dê uma olhada\fno LAKE OF RAGE\nagora mesmo.",
  ["TEXT_MAHOGANY_TOWN_OBJ_004"] = "Visite a loja da\nVovó. Ela vende\fcoisas que mais\nninguém tem.",
  ["TEXT_MANIAS_HOUSE_OBJ_001"] = "Estou em choque!\fUm cara da sua\nidade, de olhar\fduro e cabelo\ncomprido entrou.\fEle me assustou e\nlevou o meu\vPOKéMON precioso!\fAinda tenho um,\nmas e se ele\vvoltar?\fVocê parece forte.\nVocê pode cuidar\fdo meu POKéMON\npor um tempo?",
  ["TEXT_MOUNT_MOON_GIFT_SHOP_OBJ_001"] = "Quando o sol se\npõe, os CLEFAIRY\vvêm brincar.",
  ["TEXT_MOUNT_MOON_GIFT_SHOP_OBJ_002"] = "Quando o sol se\npõe, os CLEFAIRY\vvêm brincar.",
  ["TEXT_MOUNT_MOON_SQUARE_BG_002"] = "MT.MOON SQUARE\nNão jogue lixo",
  ["TEXT_MOUNT_MOON_SQUARE_OBJ_003"] = "Cure Seus POKéMON!\nCENTRO POKéMON",
  ["TEXT_MOUNT_MORTAR1_FINSIDE_OBJ_001"] = "Cure Seus POKéMON!\nCENTRO POKéMON",
  ["TEXT_MOUNT_MORTAR1_FINSIDE_OBJ_007"] = "Há um tempo, um\ncara de karatê\fquis batalhar.\nEle era bom\vdemais.\fEle nos\ndestroçou fácil.\fEle foi mais\nfundo dizendo\vque era\ftreino. Será\ncomo ele está?",
  ["TEXT_MOUNT_MORTAR1_FINSIDE_OBJ_007_AFTER"] = "Há um tempo, um\ncara de karatê\fquis batalhar.\nEle era bom\vdemais.\fEle nos\ndestroçou fácil.\fEle foi mais\nfundo dizendo\vque era\ftreino. Será\ncomo ele está?",
  ["TEXT_MOUNT_MORTAR1_FINSIDE_OBJ_007_BEATEN"] = "Perdi pra uma\ncriança…?",
  ["TEXT_MOUNT_MORTAR1_FINSIDE_OBJ_007_SEEN"] = "Não vou perder\ndessa vez!",
  ["TEXT_MOUNT_MORTAR1_FINSIDE_OBJ_008"] = "Vim explorar\nMT.MORTAR, mas\fme separei do\nmeu parceiro…\fVocê encontrou um\ntreinador que usa\fum SEADRA que\nsabe WATERFALL?",
  ["TEXT_MOUNT_MORTAR1_FINSIDE_OBJ_008_AFTER"] = "Vim explorar\nMT.MORTAR, mas\fme separei do\nmeu parceiro…\fVocê encontrou um\ntreinador que usa\fum SEADRA que\nsabe WATERFALL?",
  ["TEXT_MOUNT_MORTAR1_FINSIDE_OBJ_008_BEATEN"] = "Te confundi com\noutra pessoa…",
  ["TEXT_MOUNT_MORTAR1_FINSIDE_OBJ_008_SEEN"] = "Ei! HUGH!",
  ["TEXT_MOUNT_MORTAR2_FINSIDE_OBJ_007"] = "Estou\ninvestigando a\vMT.MORTAR, mas\vmeu parceiro\vsumiu.\fVocê viu um\ntreinador que tem\fum SLOWPOKE que\nsabe STRENGTH?",
  ["TEXT_MOUNT_MORTAR2_FINSIDE_OBJ_007_AFTER"] = "Estou\ninvestigando a\vMT.MORTAR, mas\vmeu parceiro\vsumiu.\fVocê viu um\ntreinador que tem\fum SLOWPOKE que\nsabe STRENGTH?",
  ["TEXT_MOUNT_MORTAR2_FINSIDE_OBJ_007_BEATEN"] = "Foi mal, engano\nmeu.",
  ["TEXT_MOUNT_MORTAR2_FINSIDE_OBJ_007_SEEN"] = "Ei! MARKUS!",
  ["TEXT_MOUNT_MORTAR_B1_F_OBJ_004"] = "Ei!\fEu sou o KARATE\nKING!\fTreino sozinho\naqui no escuro!\fVocê!\nBatalhe comigo!\fHwaaarggh!",
  ["TEXT_MOVE_DELETERS_HOUSE_BG_001"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_MOVE_DELETERS_HOUSE_BG_002"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_MOVE_DELETERS_HOUSE_OBJ_001"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_MR_FUJIS_HOUSE_OBJ_001"] = "O MR.FUJI mora\naqui, mas não\festá em casa.\fEle deve estar na\nSOUL HOUSE.",
  ["TEXT_MR_FUJIS_HOUSE_OBJ_002"] = "Tem gente de\ncoração frio que\vlarga o POKéMON.\fO vô acolhe os\ncoitados sem lar\fe cuida deles com\ncarinho.",
  ["TEXT_MR_POKEMONS_HOUSE_OBJ_001"] = "Estou contando\ncom você!",
  ["TEXT_MR_PSYCHICS_HOUSE_BG_001"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_MR_PSYCHICS_HOUSE_BG_002"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_MR_PSYCHICS_HOUSE_OBJ_001"] = "…\f…\f…\f…Já sei!\fVocê queria isto!",
  ["TEXT_NATIONAL_PARK_BUG_CONTEST_OBJ_001"] = "DON: Vou\nvencer! Não me\vatrapalhe.",
  ["TEXT_NATIONAL_PARK_BUG_CONTEST_OBJ_002"] = "ED: Meu PARASECT\nfaz POKéMON\vdormir com SPORE.",
  ["TEXT_NATIONAL_PARK_BUG_CONTEST_OBJ_003"] = "NICK: Crio\nPOKéMON rápidos\vpara batalhas.",
  ["TEXT_NATIONAL_PARK_BUG_CONTEST_OBJ_004"] = "WILLIAM: Não me\nimporto em\vvencer.\fSó procuro\nPOKéMON raros.",
  ["TEXT_NATIONAL_PARK_BUG_CONTEST_OBJ_005"] = "BENNY: Ssh!\nVai espantar o\fSCYTHER. Falo\ncom você depois.",
  ["TEXT_NATIONAL_PARK_BUG_CONTEST_OBJ_006"] = "BARRY: Você\ndeve enfraquecer\fPOKéMON inseto,\njogue POKé BALL.",
  ["TEXT_NATIONAL_PARK_BUG_CONTEST_OBJ_007"] = "CINDY: O que foi?\fAcha engraçado\numa garota\fcaçando POKéMON\ninseto?",
  ["TEXT_NATIONAL_PARK_BUG_CONTEST_OBJ_008"] = "JOSH: Coleciono\nPOKéMON inseto\fdesde que era\nbem criança.\fNão tem jeito,\nvou vencer!",
  ["TEXT_NATIONAL_PARK_BUG_CONTEST_OBJ_009"] = "SAMUEL: Se tem\ntempo para\fconversar, procure\nPOKéMON inseto.",
  ["TEXT_NATIONAL_PARK_BUG_CONTEST_OBJ_010"] = "KIPP: Estudei\nmuito sobre\vPOKéMON inseto.\fVou vencer\ncom certeza.",
  ["TEXT_NATIONAL_PARK_OBJ_001"] = "Olhe! Veja a minha\nbolsa!\fImprimi os meus\nfavoritos da\fPOKéDEX e colei\nna minha bolsa.",
  ["TEXT_NATIONAL_PARK_OBJ_002"] = "Esta é uma MAIL da\nminha filha.\vEla me anima.",
  ["TEXT_NATIONAL_PARK_OBJ_003"] = "Atenção, por\nfavor!\f…Opa, preciso\nparar de pensar\fcomo professora o\ntempo todo.\fVocê deve ser um\ntreinador POKéMON\fJá que se esforça\ntanto, quero que\fvocê fique com\nisto.",
  ["TEXT_NATIONAL_PARK_OBJ_004"] = "Estou brincando\ncom adesivos que\vtirei da POKéDEX.",
  ["TEXT_NATIONAL_PARK_OBJ_005"] = "Se eu ganhar, fico\ncom o adesivo da\vPOKéDEX dele.",
  ["TEXT_NATIONAL_PARK_OBJ_006"] = "Eu passeio pelo\nPARK, mas nunca\fentro no meio do\nmato.\fTreinadores sempre\nquerem batalhar…",
  ["TEXT_NATIONAL_PARK_OBJ_007"] = "PERSIAN: Fufusha!",
  ["TEXT_NATIONAL_PARK_OBJ_008_AFTER"] = "Há muito\no que aprender.\fPor exemplo…\fExistem 50 tipos\nde TM.\fPOKéMON trocados\nsobem mais rápido",
  ["TEXT_NATIONAL_PARK_OBJ_008_BEATEN"] = "O-o quê?",
  ["TEXT_NATIONAL_PARK_OBJ_008_SEEN"] = "O mundo POKéMON\né profundo.\fAinda existem\nmuitas coisas que\vnão sabemos.\fMas eu sei mais\ndo que você!",
  ["TEXT_NATIONAL_PARK_OBJ_009_AFTER"] = "Minha amiga tem um\nMARILL. É tão\ffofo! Queria ter\num MARILL.",
  ["TEXT_NATIONAL_PARK_OBJ_009_BEATEN"] = "Talvez eu não\nte vença na luta…\fMas os meus são\nbem mais bonitos.",
  ["TEXT_NATIONAL_PARK_OBJ_009_SEEN"] = "Meus POKéMON são\ntão fofos. Vou\vmostrar a você.",
  ["TEXT_NATIONAL_PARK_OBJ_010"] = "Perdi a batalha,\nmas meus POKéMON\fganham o prêmio\npor serem fofos.",
  ["TEXT_NATIONAL_PARK_OBJ_010_AFTER"] = "Perdi a batalha,\nmas meus POKéMON\fganham o prêmio\npor serem fofos.",
  ["TEXT_NATIONAL_PARK_OBJ_010_BEATEN"] = "M-meu POKéMON!",
  ["TEXT_NATIONAL_PARK_OBJ_010_SEEN"] = "Adoramos nossos\nPOKéMON, mesmo que\veles não gostem.\fÉ isso que é\nser um FAN.",
  ["TEXT_NATIONAL_PARK_OBJ_011"] = "Pelo seu olhar,\npensei que você\vgostava de mim.\fAfinal, eu sou\nfofa!",
  ["TEXT_NATIONAL_PARK_OBJ_011_AFTER"] = "Pelo seu olhar,\npensei que você\vgostava de mim.\fAfinal, eu sou\nfofa!",
  ["TEXT_NATIONAL_PARK_OBJ_011_SEEN"] = "Olá? Por que você\nfica me olhando?\fAh, uma batalha?",
  ["TEXT_NATIONAL_PARK_OBJ_013"] = "Estou imprimindo a\nminha POKéDEX.\fDá para imprimir\noutras coisas,\fcomo MAIL e suas\nBOXES do PC.",
  ["TEXT_NEW_BARK_TOWN_OBJ_001"] = "Uau, sua POKéGEAR\né incrível!\fFoi sua mãe quem\nlhe deu ela?",
  ["TEXT_NEW_BARK_TOWN_OBJ_002"] = "Ei, {PLAYER}!\fSoube que o PROF.\nELM descobriu\vnovos POKéMON.",
  ["TEXT_NEW_BARK_TOWN_OBJ_003"] = "……\fEntão este é o\nfamoso LAB POKéMON\vdo ELM…",
  ["TEXT_OAKS_LAB_BG_001"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_OAKS_LAB_BG_002"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_OAKS_LAB_BG_003"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_OAKS_LAB_BG_004"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_OAKS_LAB_BG_005"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_OAKS_LAB_BG_006"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_OAKS_LAB_BG_007"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_OAKS_LAB_BG_008"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_OAKS_LAB_BG_009"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_OAKS_LAB_BG_010"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_OAKS_LAB_BG_011"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_OAKS_LAB_BG_012"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_OAKS_LAB_OBJ_001"] = "OAK: Ah, {PLAYER}!\nQue bom que você\fveio de tão longe\naté KANTO.\fO que você acha\ndos treinadores\fdaqui?\nBem durões, né?",
  ["TEXT_OAKS_LAB_OBJ_002"] = "O programa POKéMON\nTALK do PROF\fnão passa aqui\nem KANTO.\fÉ uma pena, eu\nqueria ouvir.",
  ["TEXT_OAKS_LAB_OBJ_003"] = "Graças ao seu\ntrabalho na\vPOKéDEX, a\vpesquisa\fdo PROF está indo\nmuito bem.",
  ["TEXT_OAKS_LAB_OBJ_004"] = "Não conte a\nninguém, mas o\fPOKéMON TALK não é\nao vivo.",
  ["TEXT_OLIVINE_CAFE_OBJ_001"] = "Hah! Seus POKéMON\nparecem mesmo ser\vpesos-leves!\fEles não têm força\npra mover de lado\vos pedregulhos.\fTome, use isto\ne ensine o golpe\vSTRENGTH a eles!\fVai precisar da\nBADGE do GINÁSIO\fde GOLDENROD pra\nusar fora de luta",
  ["TEXT_OLIVINE_CITY_BG_001"] = "CIDADE DE OLIVINE\fO Porto Mais Perto\nde Outras Terras",
  ["TEXT_OLIVINE_CITY_BG_002"] = "OLIVINE PORT\nPÍER DO FAST SHIP",
  ["TEXT_OLIVINE_CITY_BG_003"] = "CIDADE DE OLIVINE\nGINÁSIO POKéMON\vLÍDER: JASMINE\fA Garota Blindada\nda Defesa",
  ["TEXT_OLIVINE_CITY_OBJ_001"] = "Estradas escuras\nsão perigosas\vde noite.\fMas na escuridão\ntotal da noite,\fo mar é ainda\nmais traiçoeiro!\fSem a luz do farol\ndo LIGHTHOUSE\fpara guiar, navio\nnenhum navega.",
  ["TEXT_OLIVINE_CITY_OBJ_002"] = "Essa coisa que\nvocê tem, é uma\vPOKéGEAR, né? Uau,\vque legal.",
  ["TEXT_OLIVINE_CITY_OBJ_003"] = "Olá, rapazinho!\nO mar é doce!\fCante comigo!\nEi-ô! Puxa a corda\vcom força!…",
  ["TEXT_OLIVINE_GOOD_ROD_HOUSE_OBJ_001"] = "OLIVINE fica no\nmar!\fE se fica no mar,\ncom certeza há\vpeixes!\fPesco aqui há\n30 anos.\fQuer encarar o\nmar e pescar\vtambém?",
  ["TEXT_OLIVINE_GYM_OBJ_001"] = "…Obrigada pela sua\najuda no\vLIGHTHOUSE…\fMas isto é\ndiferente. Por\vfavor,\fpermita que eu me\napresente.\fSou JASMINE, LÍDER\nde GINÁSIO. Eu uso\vo tipo aço.\f…Você conhece o\ntipo aço?\fÉ um tipo que foi\ndescoberto há bem\vpouco tempo.\f…Hum… Começamos?",
  ["TEXT_OLIVINE_GYM_OBJ_002"] = "A JASMINE usa o\ntipo aço, que é\vbem recente.\fEu não sei quase\nnada sobre ele.",
  ["TEXT_OLIVINE_HOUSE_BETA_OBJ_001"] = "Quando meu POKéMON\nficou doente, o\fFARMACÊUTICO de\nECRUTEAK fez um\vremédio pra mim.",
  ["TEXT_OLIVINE_HOUSE_BETA_OBJ_002"] = "RHYDON: Grrugooh!",
  ["TEXT_OLIVINE_LIGHTHOUSE1_F_OBJ_001"] = "As pessoas treinam\nneste LIGHTHOUSE.\fNão é fácil subir\npor causa de todos\vos treinadores.",
  ["TEXT_OLIVINE_LIGHTHOUSE2_F_OBJ_001"] = "Que força!\nQue tal você\fnavegar os mares\ncomigo?",
  ["TEXT_OLIVINE_LIGHTHOUSE2_F_OBJ_001_BEATEN"] = "Argh!\nEu perco!",
  ["TEXT_OLIVINE_LIGHTHOUSE2_F_OBJ_001_SEEN"] = "Homens do mar\nsempre querem\vuma boa briga!",
  ["TEXT_OLIVINE_LIGHTHOUSE2_F_OBJ_002"] = "Lá em cima tem um\nPOKéMON que mantém\vo farol aceso.\fMas ouvi que ele\nestá doente e\fnão sara com\nremédio comum.",
  ["TEXT_OLIVINE_LIGHTHOUSE2_F_OBJ_002_AFTER"] = "Lá em cima tem um\nPOKéMON que mantém\vo farol aceso.\fMas ouvi que ele\nestá doente e\fnão sara com\nremédio comum.",
  ["TEXT_OLIVINE_LIGHTHOUSE2_F_OBJ_002_BEATEN"] = "Ah! Dá para ver\nque você é sério.",
  ["TEXT_OLIVINE_LIGHTHOUSE2_F_OBJ_002_SEEN"] = "Hm? Aqui não é\nlugar de brincar.",
  ["TEXT_OLIVINE_LIGHTHOUSE3_F_OBJ_001"] = "Toda vez que volto\na OLIVINE, eu\vvisito o GINÁSIO.\fO tipo de POKéMON\nda LÍDER mudou\fsem que eu\npercebesse.",
  ["TEXT_OLIVINE_LIGHTHOUSE3_F_OBJ_001_AFTER"] = "Toda vez que volto\na OLIVINE, eu\vvisito o GINÁSIO.\fO tipo de POKéMON\nda LÍDER mudou\fsem que eu\npercebesse.",
  ["TEXT_OLIVINE_LIGHTHOUSE3_F_OBJ_001_BEATEN"] = "Você é bom e\nforte também…",
  ["TEXT_OLIVINE_LIGHTHOUSE3_F_OBJ_001_SEEN"] = "Marinheiros são\nbons e fortes.\vE você?",
  ["TEXT_OLIVINE_LIGHTHOUSE3_F_OBJ_003"] = "Como diabos se\nsobe aqui?\fQuero visitar o\nPOKéMON doente,\fmas não consigo\nchegar lá…",
  ["TEXT_OLIVINE_LIGHTHOUSE3_F_OBJ_003_AFTER"] = "Como diabos se\nsobe aqui?\fQuero visitar o\nPOKéMON doente,\fmas não consigo\nchegar lá…",
  ["TEXT_OLIVINE_LIGHTHOUSE3_F_OBJ_003_BEATEN"] = "Você se importa\nde verdade…",
  ["TEXT_OLIVINE_LIGHTHOUSE3_F_OBJ_003_SEEN"] = "Por que está aqui?\nVeio só olhar?\fSugiro que\nvocê vá embora!",
  ["TEXT_OLIVINE_LIGHTHOUSE4_F_OBJ_001"] = "Falando em doente,\nouvi que tem\fuma boa farmácia\nem CIANWOOD.",
  ["TEXT_OLIVINE_LIGHTHOUSE4_F_OBJ_001_AFTER"] = "Falando em doente,\nouvi que tem\fuma boa farmácia\nem CIANWOOD.",
  ["TEXT_OLIVINE_LIGHTHOUSE4_F_OBJ_001_BEATEN"] = "Eu também não\nconsigo sorrir…",
  ["TEXT_OLIVINE_LIGHTHOUSE4_F_OBJ_001_SEEN"] = "A JASMINE deve\nestar muito\vpreocupada com\vos POKéMON daqui.\fEla nem sorri\nmais esses dias.",
  ["TEXT_OLIVINE_LIGHTHOUSE4_F_OBJ_002"] = "Certo. Qualquer um\nficaria preocupado\vse o POKéMON dele\vestivesse ferido.\fVou rezar pelo\nPOKéMON daqui,\fpara a JASMINE\nvoltar ao GINÁSIO",
  ["TEXT_OLIVINE_LIGHTHOUSE4_F_OBJ_002_AFTER"] = "Certo. Qualquer um\nficaria preocupado\vse o POKéMON dele\vestivesse ferido.\fVou rezar pelo\nPOKéMON daqui,\fpara a JASMINE\nvoltar ao GINÁSIO",
  ["TEXT_OLIVINE_LIGHTHOUSE4_F_OBJ_002_BEATEN"] = "Aaai! POKéMON!",
  ["TEXT_OLIVINE_LIGHTHOUSE4_F_OBJ_002_SEEN"] = "A JASMINE é a\nLÍDER daqui.\fPretendo trazer\nela de volta.\fÉ melhor ninguém\natrapalhar!",
  ["TEXT_OLIVINE_LIGHTHOUSE5_F_OBJ_001"] = "Um LÍDER não é só\nquestão de ser\fforte. Um LÍDER\ntambém precisa ter\vcompaixão.",
  ["TEXT_OLIVINE_LIGHTHOUSE5_F_OBJ_001_AFTER"] = "Um LÍDER não é só\nquestão de ser\fforte. Um LÍDER\ntambém precisa ter\vcompaixão.",
  ["TEXT_OLIVINE_LIGHTHOUSE5_F_OBJ_001_BEATEN"] = "Uau, uau. Você é\narrasador!",
  ["TEXT_OLIVINE_LIGHTHOUSE5_F_OBJ_001_SEEN"] = "Eu queria batalhar\ncom a JASMINE,\fmas ela não está\nbem. Topa\vbatalhar?",
  ["TEXT_OLIVINE_LIGHTHOUSE5_F_OBJ_002"] = "Meu POKéMON\naprendeu a usar\vFLY em CIANWOOD.\fBom, como eu perdi\nvou usar FLY para\vcruzar o mar…",
  ["TEXT_OLIVINE_LIGHTHOUSE5_F_OBJ_002_AFTER"] = "Meu POKéMON\naprendeu a usar\vFLY em CIANWOOD.\fBom, como eu perdi\nvou usar FLY para\vcruzar o mar…",
  ["TEXT_OLIVINE_LIGHTHOUSE5_F_OBJ_002_BEATEN"] = "Opa…Eles caíram…",
  ["TEXT_OLIVINE_LIGHTHOUSE5_F_OBJ_002_SEEN"] = "Estamos bem alto\naqui. Meus\fPOKéMON pássaro\nem plena forma.",
  ["TEXT_OLIVINE_LIGHTHOUSE6_F_OBJ_001"] = "JASMINE: … Este\nPOKéMON sempre\fmanteve o mar\naceso à noite.\f…Mas ele\nadoeceu… Está\vofegando…\f…Sei que há\numa ótima\fPHARMACY em\nCIANWOOD…\fMas isso fica\nalém do mar…\fE não posso\ndeixar o AMPHY…",
  ["TEXT_OLIVINE_LIGHTHOUSE6_F_OBJ_002"] = "A respiração\nestá difícil…",
  ["TEXT_OLIVINE_MART_OBJ_001"] = "Seus POKéMON já\nsabem o golpe pra\fcarregar pessoas\nsobre a água?",
  ["TEXT_OLIVINE_POKECENTER1_F_OBJ_001"] = "Bom dia!\nBem-vindo ao nosso\vCENTRO POKéMON.",
  ["TEXT_OLIVINE_POKECENTER1_F_OBJ_002"] = "Uau! Você e seu\nPOKéMON são muito\vunidos!",
  ["TEXT_OLIVINE_POKECENTER1_F_OBJ_003"] = "Os marinheiros\nsão generosos.\fUm me ensinou\no STRENGTH.\fAgora meu POKéMON\nmove pedregulhos.",
  ["TEXT_OLIVINE_PORT_OBJ_001"] = "Vamos partir logo.\nPor favor, suba\va bordo.",
  ["TEXT_OLIVINE_PORT_OBJ_002"] = "Não queremos que\nvocê caia no mar,\fentão não pode\nentrar.",
  ["TEXT_OLIVINE_PORT_OBJ_004"] = "SHELLDER é fácil\nde pegar aqui.\fEm outros lugares\né meio raro.",
  ["TEXT_OLIVINE_PORT_OBJ_005"] = "Quantas RODS você\ntem?\fRODS diferentes\npegam POKéMON\vdiferentes.",
  ["TEXT_OLIVINE_PORT_OBJ_006"] = "O S.S.AQUA usa\njatos e desliza\vsobre as ondas!",
  ["TEXT_OLIVINE_PORT_OBJ_007"] = "Tem um monte de\nPOKéMON em KANTO.\fQueria poder ir…",
  ["TEXT_OLIVINE_PUNISHMENT_SPEECH_HOUSE_OBJ_001"] = "No caminho para\nCIANWOOD, existem\fHá quatro ilhas\ndesertas.\fCrianças ruins são\nlevadas pras ilhas\vcomo castigo!",
  ["TEXT_OLIVINE_PUNISHMENT_SPEECH_HOUSE_OBJ_002"] = "Quando me meto em\nenrascada, papai\vsempre me assusta",
  ["TEXT_OLIVINE_TIMS_HOUSE_BG_001"] = "Revistas de\nPOKéMON… POKéMON\vPAL,\fPOKéMON HANDBOOK,\nPOKéMON GRAPH…",
  ["TEXT_OLIVINE_TIMS_HOUSE_BG_002"] = "Revistas de\nPOKéMON… POKéMON\vPAL,\fPOKéMON HANDBOOK,\nPOKéMON GRAPH…",
  ["TEXT_OLIVINE_TIMS_HOUSE_OBJ_001"] = "Revistas de\nPOKéMON… POKéMON\vPAL,\fPOKéMON HANDBOOK,\nPOKéMON GRAPH…",
  ["TEXT_PALLET_TOWN_OBJ_001"] = "Eu também crio\nPOKéMON.\fEles servem de\nmeus guardas",
  ["TEXT_PALLET_TOWN_OBJ_002"] = "Tecnologia é\nincrível!\fDá pra trocar\nPOKéMON no tempo\vcomo e-mail.",
  ["TEXT_PEWTER_CITY_OBJ_001"] = "Já visitou o\nPEWTER GYM?\fO LÍDER usa\nPOKéMON de pedra.",
  ["TEXT_PEWTER_CITY_OBJ_002"] = "De noite, CLEFAIRY\nvêm pra brincar no\vMT.MOON.\fMas nem toda\nnoite.",
  ["TEXT_PEWTER_CITY_OBJ_003"] = "Ah, você veio de\ntão longe, de\vJOHTO?\fIsso traz\nmemórias. Quando\veu\fera jovem, ia a\nJOHTO treinar.\fVocê me lembra\nmuito do que eu\fera, jovem como\nvocê.\fQuero que fique\ncom um item que\vachei em JOHTO.",
  ["TEXT_PEWTER_GYM_OBJ_001"] = "BROCK: É raro\nreceber desafio\fde treinador\nvindo de JOHTO.\fEu sou o BROCK,\nLÍDER de PEWTER.\fSou especialista\nem POKéMON pedra.\fMeus POKéMON são\nimunes à maioria\fdos ataques\nfísicos. Vai ser\fdifícil causar\nalgum dano.\fVenha!",
  ["TEXT_PEWTER_GYM_OBJ_002"] = "Ei, você!\nTreinador de\vJOHTO!\fBROCK é durão. Vai\nte punir se\fvocê não o levar a\nsério.",
  ["TEXT_PEWTER_GYM_OBJ_002_AFTER"] = "Ei, você!\nTreinador de\vJOHTO!\fBROCK é durão. Vai\nte punir se\fvocê não o levar a\nsério.",
  ["TEXT_PEWTER_GYM_OBJ_002_BEATEN"] = "Preciso vencer\nessas batalhas…",
  ["TEXT_PEWTER_GYM_OBJ_002_SEEN"] = "Os treinadores\ndeste GINÁSIO\vusam POKéMON de\fpedra. O tipo\npedra tem DEFESA\falta. As batalhas\npodem demorar\fbastante. Você\nestá preparado?",
  ["TEXT_PEWTER_GYM_OBJ_003"] = "Ei! Futuro\nCAMPEÃO!\fVocê está indo bem\nEstá enfrentando\fos LÍDERES de\nGINÁSIO de KANTO?\fSão gente forte e\ndedicada,\figual aos LÍDERES\nde JOHTO.",
  ["TEXT_PEWTER_MART_OBJ_001"] = "Oi! Olha o meu\nGYARADOS!\fCriei ele desde\nMAGIKARP. Não dá\fpara acreditar em\ncomo ficou forte.",
  ["TEXT_PEWTER_MART_OBJ_002"] = "Oi! Olha o meu\nGYARADOS!\fCriei ele desde\nMAGIKARP. Não dá\fpara acreditar em\ncomo ficou forte.",
  ["TEXT_PEWTER_NIDORAN_SPEECH_HOUSE_OBJ_001"] = "NIDORAN, pata!",
  ["TEXT_PEWTER_POKECENTER1_F_OBJ_001"] = "Bom dia!\nBem-vindo ao nosso\vCENTRO POKéMON.",
  ["TEXT_PEWTER_POKECENTER1_F_OBJ_002"] = "…É, e o GINÁSIO\nde CINNABAR\fsumiu. Eu fiquei\nespantado.\f…Sim? Estou no\ntelefone. Sai!",
  ["TEXT_PEWTER_POKECENTER1_F_OBJ_004"] = "Quase todo POKéMON\nfica com sono\fse ouve um\nJIGGLYPUFF cantar\fTem vários golpes\nque só dá para\fusar enquanto o\nPOKéMON dorme.",
  ["TEXT_PEWTER_SNOOZE_SPEECH_HOUSE_OBJ_001"] = "Gosto de cochilar\ncom o rádio ligado\v…Zzzz…",
  ["TEXT_PLAYERS_HOUSE2_F_BG_001"] = "Um bilhete lembra\nde visitar o ELM.",
  ["TEXT_PLAYERS_HOUSE2_F_BG_002"] = "POKéMON TALK DO\nPROF.OAK! Não\vperca a próxima!",
  ["TEXT_PLAYERS_HOUSE2_F_BG_003"] = "Uma coleção\ninteira de livros\vde POKéMON!",
  ["TEXT_PLAYERS_HOUSE2_F_BG_004"] = "Uma pequena\ndecoração está\vaqui.",
  ["TEXT_PLAYERS_HOUSE2_F_OBJ_001"] = "O console de jogos\nestá conectado.\fHora de começar\nsua jornada.",
  ["TEXT_PLAYERS_HOUSE2_F_OBJ_002"] = "É o seu PC.\nMelhor descer\vlogo.",
  ["TEXT_PLAYERS_HOUSE2_F_OBJ_003"] = "Uma estante\narrumada, cheia\vde anotações.",
  ["TEXT_PLAYERS_HOUSE2_F_OBJ_004"] = "Um rádio toca uma\nmúsica alegre.",
  ["TEXT_PLAYERS_NEIGHBORS_HOUSE_BG_001"] = "Revistas de\nPOKéMON… POKéMON\vPAL,\fPOKéMON HANDBOOK,\nPOKéMON GRAPH…",
  ["TEXT_PLAYERS_NEIGHBORS_HOUSE_BG_002"] = "Revistas de\nPOKéMON… POKéMON\vPAL,\fPOKéMON HANDBOOK,\nPOKéMON GRAPH…",
  ["TEXT_PLAYERS_NEIGHBORS_HOUSE_BG_003"] = "POKéMON TALK DO\nPROF.OAK! Não\vperca a próxima!",
  ["TEXT_PLAYERS_NEIGHBORS_HOUSE_OBJ_001"] = "PIKACHU é um\nPOKéMON evoluído.\fFiquei espantado\ncom as descobertas\vdo PROF.ELM.\fEle é bem famoso\npela pesquisa da\vevolução.\f…suspiro…\fEu queria poder\nser pesquisador\vcomo ele…",
  ["TEXT_PLAYERS_NEIGHBORS_HOUSE_OBJ_002"] = "Minha filha está\ndeterminada\fa se tornar\nassistente do\vPROF. ELM.\fEla ama demais\nPOKéMON!\fEu também amo!",
  ["TEXT_POKECENTER2_F_BG_001"] = "Olá! Você é o\n{PLAYER}, né?\fEu tenho uma\ncoisa para você.",
  ["TEXT_POKECENTER2_F_OBJ_001"] = "Bem-vindo ao CABLE\nCLUB TRADE CENTER\fAqui você troca\nos seus POKéMON\vcom um amigo.\fVocê quer\ntrocar?",
  ["TEXT_POKECENTER2_F_OBJ_002"] = "Bem-vindo ao CABLE\nCLUB COLOSSEUM.\fAqui você batalha\ncom um amigo.\fVocê quer\nbatalhar?",
  ["TEXT_POKECENTER2_F_OBJ_003"] = "Bem-vindo ao CABLE\nCLUB TIME CAPSULE\fDá para viajar ao\npassado e trocar\vos seus POKéMON.\fVocê quer trocar\ncom o passado?",
  ["TEXT_POKECENTER2_F_OBJ_004"] = "Olá! Você é o\n{PLAYER}, né?\fEu tenho uma\ncoisa para você.",
  ["TEXT_POKEMON_FAN_CLUB_OBJ_001"] = "Eu sou o CHAIRMAN\ndo POKéMON FAN\vCLUB.\fJá criei mais de\n150 POKéMON.\fEu sou bem\nexigente quando o\vassunto é POKéMON\fVocê veio só para\nouvir sobre os\vmeus POKéMON?",
  ["TEXT_POKEMON_FAN_CLUB_OBJ_002"] = "Nosso CHAIRMAN\nfala demais quando\vé sobre POKéMON…",
  ["TEXT_POKEMON_FAN_CLUB_OBJ_003"] = "Eu amo o jeito\nque o CLEFAIRY\fbalança o dedo\nquando vai usar\fMETRONOME.\nÉ tão adorável!",
  ["TEXT_POKEMON_FAN_CLUB_OBJ_004"] = "Olha o meu querido\nBAYLEEF!\fA folha na cabeça\ndele é tão fofa!",
  ["TEXT_POKEMON_FAN_CLUB_OBJ_005"] = "É um CLEFAIRY!\nHã?\fAh, é mesmo. É uma\nPOKé DOLL de\vCLEFAIRY.",
  ["TEXT_POWER_PLANT_BG_001"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_POWER_PLANT_BG_002"] = "Está cheia de\nlivros difíceis.",
  ["TEXT_POWER_PLANT_OBJ_001"] = "Um ladrão invadiu\na POWER PLANT…\fO que o mundo\nestá virando?",
  ["TEXT_POWER_PLANT_OBJ_002"] = "Alguém levou\numa peça que é\fessencial para\no gerador.\fSem ela, o\ngerador novo\vnão serve!",
  ["TEXT_POWER_PLANT_OBJ_003"] = "Esta POWER PLANT\ntinha sido\vabandonada.\fNós reativamos\nela pra dar\fenergia pro\nMAGNET TRAIN.",
  ["TEXT_POWER_PLANT_OBJ_004"] = "O MANAGER da\nPOWER PLANT está\vlogo à frente.\fMas como alguém\nquebrou o gerador,\vele ficou\vtriste e\vfurioso…",
  ["TEXT_POWER_PLANT_OBJ_005"] = "O MAGNET TRAIN\ngasta muita\veletricidade.\fNão anda se o\nnovo gerador\vnão funciona.",
  ["TEXT_POWER_PLANT_OBJ_006"] = "MANAGER: Eu vou\nexplodir alguém!\vQuem se atreve\fa estragar meu\ngerador?\fGastei tanto\ntempo nele!\fSe eu pegar,\nele vai ver o que\fé um ZAP\nCANNON!",
  ["TEXT_RADIO_TOWER1_F_OBJ_001"] = "Bem-vindo!",
  ["TEXT_RADIO_TOWER1_F_OBJ_002"] = "O BEN é um DJ\nfabuloso.\fA voz doce dele\nme derrete!",
  ["TEXT_RADIO_TOWER1_F_OBJ_003"] = "Adoro a MARY, do\nPOKéMON TALK.\fSó conheço a voz\ndela, mas nunca\va vi.",
  ["TEXT_RADIO_TOWER1_F_OBJ_004"] = "É forte demais.\fNosso plano pode\nruir. Preciso\vavisar os outros…",
  ["TEXT_RADIO_TOWER1_F_OBJ_004_AFTER"] = "É forte demais.\fNosso plano pode\nruir. Preciso\vavisar os outros…",
  ["TEXT_RADIO_TOWER1_F_OBJ_004_BEATEN"] = "Muito forte! Nós\ntemos que vigiar…",
  ["TEXT_RADIO_TOWER1_F_OBJ_004_SEEN"] = "Finalmente\nassumimos a\vRADIO TOWER!\fAgora todos vão\nconhecer o terror\fde verdade da\nTEAM ROCKET!\fVamos mostrar\ncomo assustamos!",
  ["TEXT_RADIO_TOWER1_F_OBJ_005"] = "Oi, você veio pelo\nLUCKY NUMBER\vSHOW?\fQuer que eu veja\nos números de ID\vdos seus POKéMON?\fSe der sorte, você\nganha um prêmio.",
  ["TEXT_RADIO_TOWER1_F_OBJ_006"] = "Temos uma promoção\nde quiz especial\vrolando agora.\fAcerte cinco\nperguntas e ganhe\vum RADIO CARD.\fEncaixe ele na sua\nPOKéGEAR e toque\fo rádio a qualquer\nhora e lugar.\fQuer responder ao\nquiz?",
  ["TEXT_RADIO_TOWER2_F_BG_001"] = "2F VENDAS",
  ["TEXT_RADIO_TOWER2_F_BG_002"] = "TALK POKéMON\nDO PROF.OAK\fO Show Mais Quente\nno Ar!",
  ["TEXT_RADIO_TOWER2_F_BG_006"] = "Em Qualquer Lugar\nPOKéMON Radio",
  ["TEXT_RADIO_TOWER2_F_OBJ_001"] = "Você pode ouvir\na radio em\vqualquer lugar.",
  ["TEXT_RADIO_TOWER2_F_OBJ_002"] = "Canções de ninar\nna radio podem\vfazer dormir.",
  ["TEXT_RADIO_TOWER2_F_OBJ_003"] = "Não vamos deixar\nvocê arruinar os\vnossos planos!",
  ["TEXT_RADIO_TOWER2_F_OBJ_003_AFTER"] = "Não vamos deixar\nvocê arruinar os\vnossos planos!",
  ["TEXT_RADIO_TOWER2_F_OBJ_003_BEATEN"] = "Ugh! Não fica\nengraçadinho!",
  ["TEXT_RADIO_TOWER2_F_OBJ_003_SEEN"] = "Há três anos, a\nTEAM ROCKET foi\vobrigada a parar.\fMas agora a volta\nvem com tudo!",
  ["TEXT_RADIO_TOWER2_F_OBJ_004"] = "Não somos sempre\nmalvados. Fazemos\vo que gostamos.",
  ["TEXT_RADIO_TOWER2_F_OBJ_004_AFTER"] = "Não somos sempre\nmalvados. Fazemos\vo que gostamos.",
  ["TEXT_RADIO_TOWER2_F_OBJ_004_BEATEN"] = "Você acha que é\num herói?",
  ["TEXT_RADIO_TOWER2_F_OBJ_004_SEEN"] = "Somos TEAM ROCKET,\nos que exploram\vos POKéMON!\fAmamos ser\nmalvados! Medo?",
  ["TEXT_RADIO_TOWER2_F_OBJ_005"] = "Nossos EXECUTIVOS\nestão tentando\vtomar este lugar.\fEles têm um plano\ngrande. Queria\vsaber o que é.",
  ["TEXT_RADIO_TOWER2_F_OBJ_005_AFTER"] = "Nossos EXECUTIVOS\nestão tentando\vtomar este lugar.\fEles têm um plano\ngrande. Queria\vsaber o que é.",
  ["TEXT_RADIO_TOWER2_F_OBJ_005_BEATEN"] = "Argh. Desisto.",
  ["TEXT_RADIO_TOWER2_F_OBJ_005_SEEN"] = "Ei, ei! Sai do\nnosso caminho!",
  ["TEXT_RADIO_TOWER2_F_OBJ_006"] = "Você me venceu e\nnão vou esquecer!",
  ["TEXT_RADIO_TOWER2_F_OBJ_006_AFTER"] = "Você me venceu e\nnão vou esquecer!",
  ["TEXT_RADIO_TOWER2_F_OBJ_006_BEATEN"] = "Q-quem é você?",
  ["TEXT_RADIO_TOWER2_F_OBJ_006_SEEN"] = "Hahaha!\fQue tédio.\nFoi fácil\fdemais tomar\neste lugar!\fVamos, me\ndivirta!",
  ["TEXT_RADIO_TOWER2_F_OBJ_007"] = "Desculpe. Somente\npessoal autorizado\valém daqui.\fNão era assim\nantes.\fAlgo esta errado\ncom o DIRETOR\v…",
  ["TEXT_RADIO_TOWER2_F_OBJ_008"] = "Sinta-se livre\npara olhar.\fO DIRETOR esta\nbom de novo,\vcomo era antes.",
  ["TEXT_RADIO_TOWER2_F_OBJ_009"] = "JIGGLYPUFF:\nJiggly…",
  ["TEXT_RADIO_TOWER3_F_BG_003"] = "E o slot da\nCHAVE-CARTAO.",
  ["TEXT_RADIO_TOWER3_F_OBJ_001"] = "Temos gravações\ndos gritos de\ftodos os POKéMON\nencontrados.\fDevemos ter uns\n200 tipos.",
  ["TEXT_RADIO_TOWER3_F_OBJ_002"] = "Para treinadores,\nPOKéMON são\vseus parceiros.\fE terrível como a\nTEAM ROCKET esta\ftentando controlar\nPOKéMON.",
  ["TEXT_RADIO_TOWER3_F_OBJ_003"] = "O chefe da TEAM\nROCKET trancou\vele mesmo lá.\fMas o DIRETOR\npode abrir.\fEle esta no\nquinto andar.\fSalve-o!",
  ["TEXT_RADIO_TOWER3_F_OBJ_004"] = "Falhei no meu\ntrabalho…\fVou ter desconto\nno meu salário…",
  ["TEXT_RADIO_TOWER3_F_OBJ_004_AFTER"] = "Falhei no meu\ntrabalho…\fVou ter desconto\nno meu salário…",
  ["TEXT_RADIO_TOWER3_F_OBJ_004_BEATEN"] = "O quê?!",
  ["TEXT_RADIO_TOWER3_F_OBJ_004_SEEN"] = "Recebi ordens\nrígidas.\fVou esmagar quem\ndesafiar a TEAM\vROCKET!",
  ["TEXT_RADIO_TOWER3_F_OBJ_005"] = "Estou péssimo por\nter perdido!\fDroga! Odeio\nPOKéMON inúteis!",
  ["TEXT_RADIO_TOWER3_F_OBJ_005_AFTER"] = "Estou péssimo por\nter perdido!\fDroga! Odeio\nPOKéMON inúteis!",
  ["TEXT_RADIO_TOWER3_F_OBJ_005_BEATEN"] = "Tá brincando!",
  ["TEXT_RADIO_TOWER3_F_OBJ_005_SEEN"] = "É ótimo mandar\nos POKéMON\vcometer crimes.",
  ["TEXT_RADIO_TOWER3_F_OBJ_006"] = "O quê?! Passou\npelos nossos,\vno UNDERGROUND?\fComo conseguiu?",
  ["TEXT_RADIO_TOWER3_F_OBJ_006_AFTER"] = "O quê?! Passou\npelos nossos,\vno UNDERGROUND?\fComo conseguiu?",
  ["TEXT_RADIO_TOWER3_F_OBJ_006_BEATEN"] = "Estou feito!",
  ["TEXT_RADIO_TOWER3_F_OBJ_006_SEEN"] = "Por que a persiana\nabriu? Você tem\falgo a ver com\nisso?",
  ["TEXT_RADIO_TOWER3_F_OBJ_007"] = "Bwahahaha…\fPosso transmitir\num sinal tão forte\vcomo eu precisar.",
  ["TEXT_RADIO_TOWER3_F_OBJ_007_AFTER"] = "Bwahahaha…\fPosso transmitir\num sinal tão forte\vcomo eu precisar.",
  ["TEXT_RADIO_TOWER3_F_OBJ_007_BEATEN"] = "Tsk! Eu te\nsubestimei!",
  ["TEXT_RADIO_TOWER3_F_OBJ_007_SEEN"] = "Uma criança\nperdida por aqui?\fQuem é você?",
  ["TEXT_RADIO_TOWER4_F_OBJ_001"] = "Ouvi a radio\nquando estava\vnas RUÍNAS.\fOuvi uma\ntransmissão lá.",
  ["TEXT_RADIO_TOWER4_F_OBJ_002"] = "MARY: Por que?\nPor que tenho que\vsofrer com isso?\fMEOWTH me ajuda!",
  ["TEXT_RADIO_TOWER4_F_OBJ_003"] = "MEOWTH: Meowth…",
  ["TEXT_RADIO_TOWER4_F_OBJ_004"] = "Não acredito!\nFui derrotado!",
  ["TEXT_RADIO_TOWER4_F_OBJ_004_AFTER"] = "Não acredito!\nFui derrotado!",
  ["TEXT_RADIO_TOWER4_F_OBJ_004_BEATEN"] = "Não pode ser!",
  ["TEXT_RADIO_TOWER4_F_OBJ_004_SEEN"] = "Pretende salvar\no DIRECTOR?\fIsso não será\npossível, pois vou\vte derrotar!",
  ["TEXT_RADIO_TOWER4_F_OBJ_005"] = "Você ganhou meu\nrespeito, então\vvai um conselho.\fNão é tarde.\nVocê ainda pode\vvoltar.",
  ["TEXT_RADIO_TOWER4_F_OBJ_005_AFTER"] = "Você ganhou meu\nrespeito, então\vvai um conselho.\fNão é tarde.\nVocê ainda pode\vvoltar.",
  ["TEXT_RADIO_TOWER4_F_OBJ_005_BEATEN"] = "A fortaleza\ncaiu!",
  ["TEXT_RADIO_TOWER4_F_OBJ_005_SEEN"] = "Pare! Sou\nconhecido como a\vfortaleza da TEAM\fROCKET! Você\nnão vai passar!",
  ["TEXT_RADIO_TOWER4_F_OBJ_006"] = "Eu amo a minha\nbeleza!\fQuem liga para\nos POKéMON?",
  ["TEXT_RADIO_TOWER4_F_OBJ_006_AFTER"] = "Eu amo a minha\nbeleza!\fQuem liga para\nos POKéMON?",
  ["TEXT_RADIO_TOWER4_F_OBJ_006_BEATEN"] = "Ah, não! Eles são\ntão inúteis!",
  ["TEXT_RADIO_TOWER4_F_OBJ_006_SEEN"] = "Não acho os\nPOKéMON fofos?\fVou achar os meus\nfofos, depois que\fderrotarem os\nseus!",
  ["TEXT_RADIO_TOWER4_F_OBJ_007"] = "Você acredita\nmesmo que pode\vparar a TEAM?",
  ["TEXT_RADIO_TOWER4_F_OBJ_007_AFTER"] = "Você acredita\nmesmo que pode\vparar a TEAM?",
  ["TEXT_RADIO_TOWER4_F_OBJ_007_BEATEN"] = "Hmmm…\fOs grandes planos\ntêm percalços.",
  ["TEXT_RADIO_TOWER4_F_OBJ_007_SEEN"] = "Excelente.\fEsta RADIO TOWER\nira realizar\vnosso plano.",
  ["TEXT_RADIO_TOWER5_F_BG_001"] = "5F ESCRITORIO\nDO DIRETOR",
  ["TEXT_RADIO_TOWER5_F_BG_002"] = "5F ESTUDIO 1",
  ["TEXT_RADIO_TOWER5_F_BG_003"] = "5F ESTUDIO 1",
  ["TEXT_RADIO_TOWER5_F_BG_004"] = "Revistas de\nPOKéMON… POKéMON\vPAL,\fPOKéMON HANDBOOK,\nPOKéMON GRAPH…",
  ["TEXT_RADIO_TOWER5_F_BG_005"] = "Revistas de\nPOKéMON… POKéMON\vPAL,\fPOKéMON HANDBOOK,\nPOKéMON GRAPH…",
  ["TEXT_RADIO_TOWER5_F_OBJ_001"] = "Escondemos o\nDIRETOR real\fno ARMAZEM\nSUBTERRANEO.\fE na ponta do\nSUBTERRANEO.\vMas duvido\fque você\nchegue lá.",
  ["TEXT_RADIO_TOWER5_F_OBJ_003"] = "{PLAYER}, não é?\fUm pirralho como\nvocê não vai\fapreciar a\nmagnificência da\fTEAM ROCKET.\nQue pena. Eu\vadmiro seu poder.",
  ["TEXT_RADIO_TOWER5_F_OBJ_003_AFTER"] = "{PLAYER}, não é?\fUm pirralho como\nvocê não vai\fapreciar a\nmagnificência da\fTEAM ROCKET.\nQue pena. Eu\vadmiro seu poder.",
  ["TEXT_RADIO_TOWER5_F_OBJ_003_BEATEN"] = "Isso não pode\nser verdade!\fLutei duro, mas\nainda perdi…",
  ["TEXT_RADIO_TOWER5_F_OBJ_003_SEEN"] = "Oi, garoto.\nLembra de mim do\fHIDEOUT em\nCIDADE DE\vMAHOGANY?\fEu perdi lá, mas\nagora não perco.",
  ["TEXT_RADIO_TOWER5_F_OBJ_004"] = "BEN: Você ouve\nnossa música?",
  ["TEXT_REDS_HOUSE1_F_OBJ_001"] = "Oi!\fO RED está fora\nfaz muito tempo.\fE também não\nligou, então eu\fnão faço ideia de\nonde ele está nem\vdo que faz.\fDizem que sem\nnotícia é sinal\fde que vai bem,\nmas eu me\vpreocupo com ele.",
  ["TEXT_ROUTE10_NORTH_BG_001"] = "KANTO POWER PLANT",
  ["TEXT_ROUTE10_NORTH_BG_002"] = "Cure Seus POKéMON!\nCENTRO POKéMON",
  ["TEXT_ROUTE10_POKECENTER1_F_OBJ_001"] = "Bom dia!\nBem-vindo ao nosso\vCENTRO POKéMON.",
  ["TEXT_ROUTE10_POKECENTER1_F_OBJ_002"] = "Um CENTRO POKéMON\nperto de caverna?\fIsso é muito\nconveniente!",
  ["TEXT_ROUTE10_POKECENTER1_F_OBJ_003"] = "O MANAGER da\nPOWER PLANT quer\fachar um homem\ncom POKéMON bom.\fEle precisa de\najuda pra pegar\fde volta algo que\nfoi roubado.",
  ["TEXT_ROUTE10_SOUTH_BG_001"] = "ROTA 10\fCIDADE DE CERULEAN\nCIDADE DE LAVENDER",
  ["TEXT_ROUTE10_SOUTH_OBJ_001"] = "A alergia está me\nfazendo espirrar!\vAtchiiim!",
  ["TEXT_ROUTE10_SOUTH_OBJ_001_AFTER"] = "A alergia está me\nfazendo espirrar!\vAtchiiim!",
  ["TEXT_ROUTE10_SOUTH_OBJ_001_BEATEN"] = "Hahaha-atchim!",
  ["TEXT_ROUTE10_SOUTH_OBJ_001_SEEN"] = "Hahahá!",
  ["TEXT_ROUTE10_SOUTH_OBJ_002"] = "Olha o que você\nfez com o POKéMON\fEu não vou\nesquecer disso…",
  ["TEXT_ROUTE10_SOUTH_OBJ_002_AFTER"] = "Olha o que você\nfez com o POKéMON\fEu não vou\nesquecer disso…",
  ["TEXT_ROUTE10_SOUTH_OBJ_002_BEATEN"] = "Eu diria que essa\nfoi derrota minha",
  ["TEXT_ROUTE10_SOUTH_OBJ_002_SEEN"] = "Você gosta de\nPOKéMON, né?\fEu também!",
  ["TEXT_ROUTE11_OBJ_001"] = "Lutei limpo e com\nhonra.\fNão me arrependo\nde nada.",
  ["TEXT_ROUTE11_OBJ_001_AFTER"] = "Lutei limpo e com\nhonra.\fNão me arrependo\nde nada.",
  ["TEXT_ROUTE11_OBJ_001_BEATEN"] = "Hã? Como isso\naconteceu?",
  ["TEXT_ROUTE11_OBJ_001_SEEN"] = "Não existe\ntrapaça em\vPOKéMON.\fVamos manter\ntudo justo!",
  ["TEXT_ROUTE11_OBJ_002"] = "Vou pegar mais\nPOKéMON ali\vno mato.",
  ["TEXT_ROUTE11_OBJ_002_AFTER"] = "Vou pegar mais\nPOKéMON ali\vno mato.",
  ["TEXT_ROUTE11_OBJ_002_BEATEN"] = "Aiaaai!\nFui pisoteado!",
  ["TEXT_ROUTE11_OBJ_002_SEEN"] = "Coça e faz cócega\num pouco quando\fando de shorts\nno mato.",
  ["TEXT_ROUTE11_OBJ_003"] = "…\fPerdi de olhos\nfechados…",
  ["TEXT_ROUTE11_OBJ_003_AFTER"] = "…\fPerdi de olhos\nfechados…",
  ["TEXT_ROUTE11_OBJ_004"] = "Força na\nconvicção…\fVocê é forte\nporque acredita\vnos seus POKéMON.",
  ["TEXT_ROUTE11_OBJ_004_AFTER"] = "Força na\nconvicção…\fVocê é forte\nporque acredita\vnos seus POKéMON.",
  ["TEXT_ROUTE11_OBJ_004_BEATEN"] = "Não previ a sua\nforça…",
  ["TEXT_ROUTE11_OBJ_004_SEEN"] = "Eu consigo ver…\fTudo o que há\npara ver em você…",
  ["TEXT_ROUTE12_OBJ_001"] = "Não tenho\npaciência para\vpescar…",
  ["TEXT_ROUTE12_OBJ_001_AFTER"] = "Não tenho\npaciência para\vpescar…",
  ["TEXT_ROUTE12_OBJ_001_BEATEN"] = "Aaargh!",
  ["TEXT_ROUTE12_OBJ_001_SEEN"] = "Paciência é a\nchave tanto pra\vpescar quanto\vpra POKéMON.",
  ["TEXT_ROUTE12_OBJ_002"] = "Você já ouviu as\nrádios de KANTO?\fA variedade aqui\né boa.",
  ["TEXT_ROUTE12_OBJ_002_AFTER"] = "Você já ouviu as\nrádios de KANTO?\fA variedade aqui\né boa.",
  ["TEXT_ROUTE12_OBJ_002_BEATEN"] = "Meu rádio idiota\nme distraiu!",
  ["TEXT_ROUTE12_OBJ_002_SEEN"] = "Fico tão à vontade\npescando e ouvindo\vuma música no\vmeu rádio.",
  ["TEXT_ROUTE12_OBJ_003"] = "Eu acho que a\neletricidade é o\fmais importante\ndo nosso dia.\fSe não fosse,\nninguém teria\ffeito tanto\nalarde quando a\fPOWER PLANT\nparou de vez.",
  ["TEXT_ROUTE12_OBJ_003_AFTER"] = "Eu acho que a\neletricidade é o\fmais importante\ndo nosso dia.\fSe não fosse,\nninguém teria\ffeito tanto\nalarde quando a\fPOWER PLANT\nparou de vez.",
  ["TEXT_ROUTE12_OBJ_003_BEATEN"] = "A resposta vem\nlogo depois!",
  ["TEXT_ROUTE12_OBJ_003_SEEN"] = "O que é mais\nimportante no\vnosso dia a dia?",
  ["TEXT_ROUTE12_OBJ_004"] = "Lembra mesmo?",
  ["TEXT_ROUTE12_OBJ_004_AFTER"] = "O puxão que você\nsente na ROD\fquando fisga um\nPOKéMON…\fÉ a melhor\nsensação para um\vpescador como eu.",
  ["TEXT_ROUTE12_OBJ_004_BEATEN"] = "Lembra mesmo?",
  ["TEXT_ROUTE12_OBJ_004_SEEN"] = "Você lembra?",
  ["TEXT_ROUTE12_SUPER_ROD_HOUSE_OBJ_001"] = "Eu sou o irmão\nmais novo do\vFISHING GURU.\fVejo que você\ngosta de pescar.\fNão tenho a menor\ndúvida disso!\fE aí? Sei que\nestou certo.",
  ["TEXT_ROUTE13_OBJ_001"] = "Seus POKéMON são\nmuito bem\vtreinados.",
  ["TEXT_ROUTE13_OBJ_001_AFTER"] = "Seus POKéMON são\nmuito bem\vtreinados.",
  ["TEXT_ROUTE13_OBJ_001_BEATEN"] = "Você me venceu na\nvelocidade…",
  ["TEXT_ROUTE13_OBJ_001_SEEN"] = "Agilidade é o\nponto forte dos\vPOKéMON pássaro.",
  ["TEXT_ROUTE13_OBJ_002"] = "Se escovar eles,\nPOKéMON ficam bem",
  ["TEXT_ROUTE13_OBJ_002_AFTER"] = "Se escovar eles,\nPOKéMON ficam bem",
  ["TEXT_ROUTE13_OBJ_002_BEATEN"] = "Droga!\nNão foi bastante!",
  ["TEXT_ROUTE13_OBJ_002_SEEN"] = "Olhe os meus\nPOKéMON. Veja a\vcor\fe a plumagem\ndeles.",
  ["TEXT_ROUTE13_OBJ_003"] = "Você parece ter\nmuitos POKéMON,\fmas PIKACHU ainda\né o melhor.",
  ["TEXT_ROUTE13_OBJ_003_AFTER"] = "Você parece ter\nmuitos POKéMON,\fmas PIKACHU ainda\né o melhor.",
  ["TEXT_ROUTE13_OBJ_003_SEEN"] = "Nihihi! Quer\nbatalhar com a\vminha gangue?",
  ["TEXT_ROUTE13_OBJ_004"] = "O relevo parece\nque não muda\vnunca.\fMas ele muda sim,\naos pouquinhos,\vcom o tempo.",
  ["TEXT_ROUTE13_OBJ_004_AFTER"] = "O relevo parece\nque não muda\vnunca.\fMas ele muda sim,\naos pouquinhos,\vcom o tempo.",
  ["TEXT_ROUTE13_OBJ_004_BEATEN"] = "Eu perdi…",
  ["TEXT_ROUTE13_OBJ_004_SEEN"] = "Eu devia ir ao\nROCK TUNNEL pegar\vum ONIX.",
  ["TEXT_ROUTE13_OBJ_005"] = "Todo mundo não\nsonha um dia ser\vum rei?",
  ["TEXT_ROUTE13_OBJ_005_AFTER"] = "Todo mundo não\nsonha um dia ser\vum rei?",
  ["TEXT_ROUTE13_OBJ_005_BEATEN"] = "Como… Como ousa\nzombar da realeza",
  ["TEXT_ROUTE13_OBJ_005_SEEN"] = "Curve-se ante meu\nPOKéMON real!",
  ["TEXT_ROUTE14_OBJ_001"] = "SQUIRTLE,\nCHARMANDER e\vBULBASAUR…\fAcho que é uma boa\nmistura.",
  ["TEXT_ROUTE14_OBJ_001_AFTER"] = "SQUIRTLE,\nCHARMANDER e\vBULBASAUR…\fAcho que é uma boa\nmistura.",
  ["TEXT_ROUTE14_OBJ_001_BEATEN"] = "Aaaah!",
  ["TEXT_ROUTE14_OBJ_001_SEEN"] = "Deixa eu contar,\nfoi difícil\fpegar meu POKéMON\nde estimação.",
  ["TEXT_ROUTE14_OBJ_002"] = "Você tem POKéMON\nque sabem o golpe\fFLY, não tem? Que\ninveja.",
  ["TEXT_ROUTE14_OBJ_002_AFTER"] = "Você tem POKéMON\nque sabem o golpe\fFLY, não tem? Que\ninveja.",
  ["TEXT_ROUTE14_OBJ_002_BEATEN"] = "Posso sonhar, mas\nnunca vou voar…",
  ["TEXT_ROUTE14_OBJ_002_SEEN"] = "Meu sonho é voar\ncom meu amado\vPOKéMON pássaro.",
  ["TEXT_ROUTE14_OBJ_003"] = "Se você tem BADGES\nde KANTO, elas\fajudam nas lutas\npor link.",
  ["TEXT_ROUTE14_OBJ_003_AFTER"] = "Se você tem BADGES\nde KANTO, elas\fajudam nas lutas\npor link.",
  ["TEXT_ROUTE14_OBJ_003_BEATEN"] = "Nossa! Forte\ndemais para mim!",
  ["TEXT_ROUTE14_OBJ_003_SEEN"] = "Você batalhou com\ntodos do GINÁSIO?",
  ["TEXT_ROUTE14_OBJ_004"] = "SQUIRTLE,\nCHARMANDER e\vBULBASAUR…\fAcho que é uma boa\nmistura.",
  ["TEXT_ROUTE15_BG_001"] = "ROTA 15\fCIDADE DE FUCHSIA\nCIDADE DE LAVENDER",
  ["TEXT_ROUTE15_OBJ_001"] = "Minha mãe se\npreocupa demais\feu tenho que ligar\ntoda hora.",
  ["TEXT_ROUTE15_OBJ_001_AFTER"] = "Minha mãe se\npreocupa demais\feu tenho que ligar\ntoda hora.",
  ["TEXT_ROUTE15_OBJ_001_BEATEN"] = "Desculpe, mãe!\nEu apanhei!",
  ["TEXT_ROUTE15_OBJ_001_SEEN"] = "Espera. Preciso\nligar pra mamãe",
  ["TEXT_ROUTE15_OBJ_002"] = "Sayonara! Acabei\nde aprender isso\vna aula japonesa",
  ["TEXT_ROUTE15_OBJ_002_AFTER"] = "Sayonara! Acabei\nde aprender isso\vna aula japonesa",
  ["TEXT_ROUTE15_OBJ_002_BEATEN"] = "Esqueci de fazer\na lição!",
  ["TEXT_ROUTE15_OBJ_002_SEEN"] = "Vamos batalhar.\nNão vou perder!",
  ["TEXT_ROUTE15_OBJ_003"] = "Cansei de andar.\nPreciso de uma\vpausa.",
  ["TEXT_ROUTE15_OBJ_003_AFTER"] = "Cansei de andar.\nPreciso de uma\vpausa.",
  ["TEXT_ROUTE15_OBJ_003_BEATEN"] = "Você é forte\ndemais!",
  ["TEXT_ROUTE15_OBJ_003_SEEN"] = "Estamos em\nexcursão na\vLAVENDER\fRADIO TOWER para\nestudos sociais.",
  ["TEXT_ROUTE15_OBJ_004"] = "Se POKéMON fosse\nmatéria na escola,\veu era o melhor!",
  ["TEXT_ROUTE15_OBJ_004_AFTER"] = "Se POKéMON fosse\nmatéria na escola,\veu era o melhor!",
  ["TEXT_ROUTE15_OBJ_004_BEATEN"] = "Ah, não!\nComo eu perdi?",
  ["TEXT_ROUTE15_OBJ_004_SEEN"] = "Aula favorita?\nEducação física!",
  ["TEXT_ROUTE15_OBJ_005"] = "Antes de virar\nprofessor, eu\fesquecia muita\ncoisa.",
  ["TEXT_ROUTE15_OBJ_005_AFTER"] = "Antes de virar\nprofessor, eu\fesquecia muita\ncoisa.",
  ["TEXT_ROUTE15_OBJ_005_SEEN"] = "Você esqueceu\nde algo?",
  ["TEXT_ROUTE15_OBJ_006"] = "Estudar é\nimportante, mas se\vexercitar também.",
  ["TEXT_ROUTE15_OBJ_006_AFTER"] = "Estudar é\nimportante, mas se\vexercitar também.",
  ["TEXT_ROUTE15_OBJ_006_BEATEN"] = "Eu não queria\nperder…",
  ["TEXT_ROUTE15_OBJ_006_SEEN"] = "Nos dias de sol,\nacho que\fas crianças\nprefeririam\vbrincar no pátio\fa estudar na sala\nde aula.",
  ["TEXT_ROUTE16_FUCHSIA_SPEECH_HOUSE_OBJ_001"] = "Se você descer a\nCYCLING ROAD,\fvocê vai parar\nem CIDADE DE\vFUCHSIA.",
  ["TEXT_ROUTE16_GATE_OBJ_001"] = "A CYCLING ROAD\ncomeça aqui. É\ftudo ladeira\nabaixo, e bem\vemocionante!\fUma sensação\nque só se sente\fem navio\nou trem.",
  ["TEXT_ROUTE17_OBJ_001"] = "Não se ache,\nmoleque de JOHTO!",
  ["TEXT_ROUTE17_OBJ_001_AFTER"] = "Não se ache,\nmoleque de JOHTO!",
  ["TEXT_ROUTE17_OBJ_001_BEATEN"] = "Nossa, você é\nboa!",
  ["TEXT_ROUTE17_OBJ_001_SEEN"] = "Ei, você! É de\nJOHTO, não é?",
  ["TEXT_ROUTE17_OBJ_002"] = "Eu pareço maneiro\nmas sou fraco, e\vaí não sou nada.\fTenho que treinar\nmais…",
  ["TEXT_ROUTE17_OBJ_002_AFTER"] = "Eu pareço maneiro\nmas sou fraco, e\vaí não sou nada.\fTenho que treinar\nmais…",
  ["TEXT_ROUTE17_OBJ_002_BEATEN"] = "Mas você não é só\naparência…",
  ["TEXT_ROUTE17_OBJ_002_SEEN"] = "Uau. Que BICYCLE\nmaneira!",
  ["TEXT_ROUTE17_OBJ_003"] = "Andar sem as mãos\né considerado bom\vna CYCLING ROAD.",
  ["TEXT_ROUTE17_OBJ_003_AFTER"] = "Andar sem as mãos\né considerado bom\vna CYCLING ROAD.",
  ["TEXT_ROUTE17_OBJ_003_BEATEN"] = "Eita! Você tem um\ntorque incrível!",
  ["TEXT_ROUTE17_OBJ_003_SEEN"] = "Ei! Quer fazer uma\nbatalha rápida?",
  ["TEXT_ROUTE17_OBJ_004"] = "Direção imprudente\ncausa acidente!\vVá com calma!",
  ["TEXT_ROUTE17_OBJ_004_AFTER"] = "Direção imprudente\ncausa acidente!\vVá com calma!",
  ["TEXT_ROUTE17_OBJ_004_BEATEN"] = "Arrrgh! Bati e\ncapotei!",
  ["TEXT_ROUTE17_OBJ_004_SEEN"] = "Somos as estrelas\nsem medo da via!",
  ["TEXT_ROUTE17_ROUTE18_GATE_OBJ_001"] = "CYCLING ROAD\na subida começa",
  ["TEXT_ROUTE18_OBJ_001"] = "Como você é forte\ndeve ser divertido\vbatalhar.",
  ["TEXT_ROUTE18_OBJ_001_AFTER"] = "Como você é forte\ndeve ser divertido\vbatalhar.",
  ["TEXT_ROUTE18_OBJ_001_BEATEN"] = "Aiiii!",
  ["TEXT_ROUTE18_OBJ_001_SEEN"] = "Se você procura\nPOKéMON, tem que\folhar no mato\nalto.",
  ["TEXT_ROUTE18_OBJ_002"] = "Se você não tem\numa BICYCLE, não\fpode usar o\natalho.",
  ["TEXT_ROUTE18_OBJ_002_AFTER"] = "Se você não tem\numa BICYCLE, não\fpode usar o\natalho.",
  ["TEXT_ROUTE18_OBJ_002_SEEN"] = "A CYCLING ROAD é\num atalho rápido\vpara CELADON.",
  ["TEXT_ROUTE19_FUCHSIA_GATE_OBJ_001"] = "O vulcão de\nCINNABAR estourou\fEle jogou pedras\nque fecharam a\vROTA 19 de vez.\fFico pensando se\no povo de CINNABAR\vestá a salvo…",
  ["TEXT_ROUTE19_OBJ_001"] = "É uma nadada bem\ncurta entre\fFUCHSIA e as\nSEAFOAM ISLANDS…\fPuxa, que homem\ngrande o meu\fnamorado! Banana!",
  ["TEXT_ROUTE19_OBJ_001_AFTER"] = "É uma nadada bem\ncurta entre\fFUCHSIA e as\nSEAFOAM ISLANDS…\fPuxa, que homem\ngrande o meu\fnamorado! Banana!",
  ["TEXT_ROUTE19_OBJ_001_BEATEN"] = "Eu ganharia de\nvocê na natação…",
  ["TEXT_ROUTE19_OBJ_001_SEEN"] = "Tenho nojo de\ngente banana!",
  ["TEXT_ROUTE19_OBJ_002"] = "À noite o mar\nfica preto.\fParece que ele vai\nte engolir.",
  ["TEXT_ROUTE19_OBJ_002_AFTER"] = "À noite o mar\nfica preto.\fParece que ele vai\nte engolir.",
  ["TEXT_ROUTE19_OBJ_002_SEEN"] = "Já nadou no mar\nà noite alguma\vvez?",
  ["TEXT_ROUTE19_OBJ_003"] = "Achei que eu ia\nganhar.",
  ["TEXT_ROUTE19_OBJ_003_AFTER"] = "Posso ser ruim de\nnatação, mas eu\vamo o mar.",
  ["TEXT_ROUTE19_OBJ_003_BEATEN"] = "Achei que eu ia\nganhar.",
  ["TEXT_ROUTE19_OBJ_003_SEEN"] = "Nadar? Eu sou\npéssimo.\fSó fico\nchapinhando nesta\vágua rasa aqui.",
  ["TEXT_ROUTE19_OBJ_004"] = "Eu… pedi para a\nminha namorada\vnadar até FUCHSIA",
  ["TEXT_ROUTE19_OBJ_004_AFTER"] = "Eu… pedi para a\nminha namorada\vnadar até FUCHSIA",
  ["TEXT_ROUTE19_OBJ_004_BEATEN"] = "Estou afogando!",
  ["TEXT_ROUTE19_OBJ_004_SEEN"] = "Ofego, ofego…\nSó… mais… um…\fpouco… até…\nFUCHSIA…",
  ["TEXT_ROUTE19_OBJ_005"] = "Desculpe. Esta\nestrada está em\vobras.\fSe quiser chegar\na CINNABAR, é\fmelhor ir pro sul\nde CIDADE DE\vPALLET.",
  ["TEXT_ROUTE19_OBJ_006"] = "Quem sabe quanto\ntempo pra mover\veste pedregulho…",
  ["TEXT_ROUTE1_BG_001"] = "ROTA 1\fCIDADE DE PALLET\nCIDADE DE VIRIDIAN",
  ["TEXT_ROUTE1_OBJ_001"] = "Para treinadores,\né lei que a gente\fbatalhe sempre que\nse encontra.",
  ["TEXT_ROUTE1_OBJ_001_AFTER"] = "Para treinadores,\né lei que a gente\fbatalhe sempre que\nse encontra.",
  ["TEXT_ROUTE1_OBJ_001_BEATEN"] = "Aah… Perco mais\ndo que ganho…",
  ["TEXT_ROUTE1_OBJ_001_SEEN"] = "Se treinadores se\nencontram,\vprimeiro é\vbatalhar.",
  ["TEXT_ROUTE1_OBJ_002"] = "Você é forte.\fDá para ver que\ntreinou bastante.",
  ["TEXT_ROUTE1_OBJ_002_AFTER"] = "Você é forte.\fDá para ver que\ntreinou bastante.",
  ["TEXT_ROUTE1_OBJ_002_BEATEN"] = "Nocauteado…",
  ["TEXT_ROUTE1_OBJ_002_SEEN"] = "Ei, você aí!\nQuer batalhar?",
  ["TEXT_ROUTE20_OBJ_001"] = "Nadar exercita\no corpo inteiro.\fFaz muito bem\npara você.",
  ["TEXT_ROUTE20_OBJ_001_AFTER"] = "Nadar exercita\no corpo inteiro.\fFaz muito bem\npara você.",
  ["TEXT_ROUTE20_OBJ_001_BEATEN"] = "Ah, não!",
  ["TEXT_ROUTE20_OBJ_001_SEEN"] = "Me sinto bem\nmais leve na água.",
  ["TEXT_ROUTE20_OBJ_002"] = "SURF já não é o\núnico golpe de HM\vque serve na água",
  ["TEXT_ROUTE20_OBJ_002_AFTER"] = "SURF já não é o\núnico golpe de HM\vque serve na água",
  ["TEXT_ROUTE20_OBJ_002_SEEN"] = "Que coleção de\nBADGES\fimpressionante.\nVamos batalhar!",
  ["TEXT_ROUTE20_OBJ_003"] = "Além do mar, eu\ntambém nado em\vlagos e rios.",
  ["TEXT_ROUTE20_OBJ_003_AFTER"] = "Além do mar, eu\ntambém nado em\vlagos e rios.",
  ["TEXT_ROUTE20_OBJ_003_BEATEN"] = "Aiya!",
  ["TEXT_ROUTE20_OBJ_003_SEEN"] = "Acho impossível\nnadar todo o\fcaminho até\nJOHTO.",
  ["TEXT_ROUTE21_OBJ_001"] = "Tenho que tomar\ncuidado com as\vmanchas do sol.",
  ["TEXT_ROUTE21_OBJ_001_AFTER"] = "Tenho que tomar\ncuidado com as\vmanchas do sol.",
  ["TEXT_ROUTE21_OBJ_001_BEATEN"] = "Estou preocupada\ncom queimadura…",
  ["TEXT_ROUTE21_OBJ_001_SEEN"] = "Oi!\fEu ia justamente\npassar protetor\vsolar.",
  ["TEXT_ROUTE21_OBJ_002"] = "Esse cara metido\nestava no vulcão\vde CINNABAR.",
  ["TEXT_ROUTE21_OBJ_002_AFTER"] = "Esse cara metido\nestava no vulcão\vde CINNABAR.",
  ["TEXT_ROUTE21_OBJ_002_SEEN"] = "Terra à vista!\nVamos em frente!",
  ["TEXT_ROUTE21_OBJ_003"] = "Vou voltar a\npescar…",
  ["TEXT_ROUTE21_OBJ_003_AFTER"] = "Vou voltar a\npescar…",
  ["TEXT_ROUTE21_OBJ_003_BEATEN"] = "Fracasso total…",
  ["TEXT_ROUTE21_OBJ_003_SEEN"] = "Cansei de pescar.\nVamos batalhar!",
  ["TEXT_ROUTE23_BG_001"] = "INDIGO PLATEAU\fO Objetivo Final\ndos Treinadores!\fLIGA POKéMON HQ",
  ["TEXT_ROUTE24_OBJ_001"] = "Ei, menino! Eu\nda TEAM ROCKET\vsou tipo cara!\fDe outro país\nvim, treinador\vnúmero um, eu!\fPensei eu, se\na energia parar,\fpânico grande\npara daqui gente!\fSegredo meu\nmissão é, então\vnão falo!\fMas! Se batalha\nganhar de mim,\fsou homem e meu\nsegredo conto.\fEi, garoto!\nBatalha começar!",
  ["TEXT_ROUTE25_OBJ_003"] = "Dei o meu melhor.\nNada a lamentar.",
  ["TEXT_ROUTE25_OBJ_003_AFTER"] = "Dei o meu melhor.\nNada a lamentar.",
  ["TEXT_ROUTE25_OBJ_003_BEATEN"] = "Uhu! Muito bom.",
  ["TEXT_ROUTE25_OBJ_003_SEEN"] = "Vença nós seis\ntreinadores e leve\vum belo prêmio!\fAcha que dá\nconta do recado?",
  ["TEXT_ROUTE25_OBJ_004"] = "Dei o meu melhor.\nNada a lamentar.",
  ["TEXT_ROUTE25_OBJ_004_AFTER"] = "Dei o meu melhor.\nNada a lamentar.",
  ["TEXT_ROUTE25_OBJ_004_BEATEN"] = "Como eu perdi?",
  ["TEXT_ROUTE25_OBJ_004_SEEN"] = "Sou o segundo.\nAgora é sério!",
  ["TEXT_ROUTE25_OBJ_005"] = "Dei o meu melhor.\nNada a lamentar.",
  ["TEXT_ROUTE25_OBJ_005_AFTER"] = "Dei o meu melhor.\nNada a lamentar.",
  ["TEXT_ROUTE25_OBJ_005_BEATEN"] = "Ai! Fui esmagado!",
  ["TEXT_ROUTE25_OBJ_005_SEEN"] = "Chegou o Nº 3!\nNão vou facilitar",
  ["TEXT_ROUTE25_OBJ_006"] = "Dei o meu melhor.\nNada a lamentar.",
  ["TEXT_ROUTE25_OBJ_006_AFTER"] = "Dei o meu melhor.\nNada a lamentar.",
  ["TEXT_ROUTE25_OBJ_006_BEATEN"] = "Eu também\nperdi…",
  ["TEXT_ROUTE25_OBJ_006_SEEN"] = "Eu sou o Nº 4!\nJá está cansado?",
  ["TEXT_ROUTE25_OBJ_007"] = "Dei o meu melhor.\nNada a lamentar.",
  ["TEXT_ROUTE25_OBJ_007_AFTER"] = "Dei o meu melhor.\nNada a lamentar.",
  ["TEXT_ROUTE25_OBJ_007_BEATEN"] = "Nossa! Demais.",
  ["TEXT_ROUTE25_OBJ_007_SEEN"] = "Certo! Sou o Nº 5.\nVou te esmagar!",
  ["TEXT_ROUTE25_OBJ_008"] = "Dei o meu melhor.\nNada a lamentar.",
  ["TEXT_ROUTE25_OBJ_008_AFTER"] = "Dei o meu melhor.\nNada a lamentar.",
  ["TEXT_ROUTE25_OBJ_008_BEATEN"] = "Só pode ser piada",
  ["TEXT_ROUTE25_OBJ_008_SEEN"] = "Sou o último da\nfila, mas eu digo:\vsou durão!",
  ["TEXT_ROUTE25_OBJ_009"] = "Você não está\ncansado nada?",
  ["TEXT_ROUTE25_OBJ_009_AFTER"] = "Desculpe… Não vou\ntrapacear mais…",
  ["TEXT_ROUTE25_OBJ_009_BEATEN"] = "Você não está\ncansado nada?",
  ["TEXT_ROUTE25_OBJ_009_SEEN"] = "Mufufufu…\fEu não tenho nada\na ver com os seis\vtreinadores.\fEsperei aqui para\nte vencer quando\festivesse cansado\nde tanta batalha.",
  ["TEXT_ROUTE25_OBJ_010"] = "Você enfrentou\nmais uma batalha\fdo que esperava,\nmas venceu.\fComo prometido,\nganhou um prêmio.",
  ["TEXT_ROUTE26_HEAL_HOUSE_OBJ_001"] = "Seus POKéMON estão\nmeio cansados.\fÉ bom deixar eles\ndescansar.",
  ["TEXT_ROUTE26_OBJ_001"] = "Vai ser difícil\nvencer na LEAGUE.\vPreciso treinar\fmais.\nOuvi dizer que a\fELITE FOUR é\nmais difícil que\fos LÍDERES de\nGINÁSIO.",
  ["TEXT_ROUTE26_OBJ_001_AFTER"] = "Vai ser difícil\nvencer na LEAGUE.\vPreciso treinar\fmais.\nOuvi dizer que a\fELITE FOUR é\nmais difícil que\fos LÍDERES de\nGINÁSIO.",
  ["TEXT_ROUTE26_OBJ_001_BEATEN"] = "Eu estraguei!",
  ["TEXT_ROUTE26_OBJ_001_SEEN"] = "Estou nos\npreparativos\ffinais pra POKéMON\nLEAGUE.",
  ["TEXT_ROUTE26_OBJ_002_AFTER"] = "Para chegar à\nLEAGUE POKéMON,\ftem que atravessar\na VICTORY ROAD.\fMas a VICTORY ROAD\né difícil.\fQuase ninguém\nvai lá!",
  ["TEXT_ROUTE26_OBJ_002_BEATEN"] = "Aaah! A vida é\ntão difícil!",
  ["TEXT_ROUTE26_OBJ_002_SEEN"] = "Passando por\nbatalhas duras,\vvocê ganha poder.",
  ["TEXT_ROUTE26_OBJ_003"] = "Eu derrotei\noito LÍDERES,\fentão estava\nconfiante.\fVou ter que\nme esforçar mais.",
  ["TEXT_ROUTE26_OBJ_003_AFTER"] = "Eu derrotei\noito LÍDERES,\fentão estava\nconfiante.\fVou ter que\nme esforçar mais.",
  ["TEXT_ROUTE26_OBJ_003_BEATEN"] = "Não! Eu não\nacredito nisso!",
  ["TEXT_ROUTE26_OBJ_003_SEEN"] = "Já que você chegou\naté aqui, deve ser\vbom.\fVou dar nessa\nbatalha tudo o\vque tenho!",
  ["TEXT_ROUTE26_OBJ_004"] = "É uma TV.",
  ["TEXT_ROUTE26_OBJ_004_AFTER"] = "É uma TV.",
  ["TEXT_ROUTE26_OBJ_004_BEATEN"] = "POKéMON não são\narmas de guerra.",
  ["TEXT_ROUTE26_OBJ_004_SEEN"] = "Perdi para o\n{RIVAL}.\fEle era muito\nforte, mas…\fEra como se ele\nquisesse vencer\va qualquer custo.\fSenti pena dos\nPOKéMON dele.",
  ["TEXT_ROUTE26_OBJ_005"] = "Pessoas e POKéMON\ncrescem com suas\vexperiências.\fNão fique parado\ne acomodado.",
  ["TEXT_ROUTE26_OBJ_005_AFTER"] = "Pessoas e POKéMON\ncrescem com suas\vexperiências.\fNão fique parado\ne acomodado.",
  ["TEXT_ROUTE26_OBJ_005_BEATEN"] = "Boa batalha!",
  ["TEXT_ROUTE26_OBJ_005_SEEN"] = "Uau, olha todas\nessas BADGES!\vImpressionado.\fMas você não\nse satisfaz só\fcoletando elas,\nné?",
  ["TEXT_ROUTE26_OBJ_006"] = "Como na pesca,\nem POKéMON está\ftudo perdido se\nvocê desistir.",
  ["TEXT_ROUTE26_OBJ_006_AFTER"] = "Como na pesca,\nem POKéMON está\ftudo perdido se\nvocê desistir.",
  ["TEXT_ROUTE26_OBJ_006_BEATEN"] = "Não! Não nesta\nbatalha!",
  ["TEXT_ROUTE26_OBJ_006_SEEN"] = "Estou me sentindo\nótimo hoje!\fSinto que poderia\nvencer até\vo CAMPEÃO!",
  ["TEXT_ROUTE27_OBJ_001"] = "Se você vencer\nesta trilha dura,\fa verdade será\nrevelada!\fHeh, desculpa, só\nqueria dizer\valgo legal.",
  ["TEXT_ROUTE27_OBJ_001_AFTER"] = "Se você vencer\nesta trilha dura,\fa verdade será\nrevelada!\fHeh, desculpa, só\nqueria dizer\valgo legal.",
  ["TEXT_ROUTE27_OBJ_001_SEEN"] = "Você parece\nbem forte.\vVamos batalhar!",
  ["TEXT_ROUTE27_OBJ_002"] = "Um bom treinador\nreconhece outros\vbons treinadores.",
  ["TEXT_ROUTE27_OBJ_002_AFTER"] = "Um bom treinador\nreconhece outros\vbons treinadores.",
  ["TEXT_ROUTE27_OBJ_002_BEATEN"] = "Como eu pensei!",
  ["TEXT_ROUTE27_OBJ_002_SEEN"] = "Hm? Você é bom,\nnão é?",
  ["TEXT_ROUTE27_OBJ_003_AFTER"] = "Você é um garoto,\nmas não dá para\fte subestimar.\nNem de longe.",
  ["TEXT_ROUTE27_OBJ_003_BEATEN"] = "Ah! Você é\nforte demais!",
  ["TEXT_ROUTE27_OBJ_003_SEEN"] = "Você não deveria\nsubestimar os\fPOKéMON selvagens\ndestas bandas.",
  ["TEXT_ROUTE27_OBJ_004"] = "Analiso os POKéMON\nantes e depois da\vevolução.\fEvoluir de verdade\ndeixa os POKéMON\vmais fortes.\fMas as formas\nevoluídas também\vaprendem depois.",
  ["TEXT_ROUTE27_OBJ_004_AFTER"] = "Analiso os POKéMON\nantes e depois da\vevolução.\fEvoluir de verdade\ndeixa os POKéMON\vmais fortes.\fMas as formas\nevoluídas também\vaprendem depois.",
  ["TEXT_ROUTE27_OBJ_004_BEATEN"] = "Ah! Você é\nrealmente forte!",
  ["TEXT_ROUTE27_OBJ_004_SEEN"] = "É raro ver\nalguém por aqui.\fVocê treina\nsozinho?",
  ["TEXT_ROUTE27_OBJ_005"] = "Com sua força,\nvocê vai bem na\vLEAGUE.\fÉ o que diz minha\npremonição.",
  ["TEXT_ROUTE27_OBJ_005_AFTER"] = "Com sua força,\nvocê vai bem na\vLEAGUE.\fÉ o que diz minha\npremonição.",
  ["TEXT_ROUTE27_OBJ_005_BEATEN"] = "Você é demais!",
  ["TEXT_ROUTE27_OBJ_005_SEEN"] = "Não diga nada!\fDeixe-me adivinhar\no que você pensa.\fMmmmmmm…\fAchei! Você está\nno desafio da\vLEAGUE POKéMON!",
  ["TEXT_ROUTE27_OBJ_006_AFTER"] = "BIRD KEEPERS, nós\nimitamos assobios\fpara comandar\nos POKéMON.",
  ["TEXT_ROUTE27_OBJ_006_BEATEN"] = "Piu!",
  ["TEXT_ROUTE27_OBJ_006_SEEN"] = "Tweet! Tweet!\nTetweet!",
  ["TEXT_ROUTE27_OBJ_009"] = "Sabe o que você\nacabou de fazer?\fVocê deu seu\nprimeiro passo\vem KANTO.\fConfira no\nmapa da POKéGEAR",
  ["TEXT_ROUTE27_SANDSTORM_HOUSE_OBJ_001"] = "Para onde você vai\ncom POKéMON?\fPOKéMON LEAGUE?\fSeus POKéMON são\nleais o bastante\vpara você vencer?\fDeixe eu ver…",
  ["TEXT_ROUTE28_STEEL_WING_HOUSE_BG_001"] = "Revistas de\nPOKéMON… POKéMON\vPAL,\fPOKéMON HANDBOOK,\nPOKéMON GRAPH…",
  ["TEXT_ROUTE28_STEEL_WING_HOUSE_BG_002"] = "Revistas de\nPOKéMON… POKéMON\vPAL,\fPOKéMON HANDBOOK,\nPOKéMON GRAPH…",
  ["TEXT_ROUTE28_STEEL_WING_HOUSE_OBJ_001"] = "Ai, meu Deus.\nVocê me achou.\fPor favor, não\nconte a ninguém.\fEu te dou isto\npara guardar o\vsegredo. Sim?",
  ["TEXT_ROUTE29_OBJ_001"] = "Hã? Quer que eu\nmostre como\vpegar POKéMON?",
  ["TEXT_ROUTE29_OBJ_002"] = "E aí. Como estão\nseus POKéMON?\fSe estão fracos\ne sem preparo,\ffique fora do\nmato.",
  ["TEXT_ROUTE29_OBJ_003"] = "Viu aqueles\nbarrancos? Dá medo\vpular deles.\fMas dá para ir a\nNEW BARK sem\fpassar pelo\nmato.",
  ["TEXT_ROUTE29_OBJ_005"] = "Quis dar uma\npausa, e salvei\fpara guardar meu\nprogresso.",
  ["TEXT_ROUTE29_OBJ_006"] = "Estou esperando\nPOKéMON que\fsó aparecem à\nnoite.",
  ["TEXT_ROUTE29_OBJ_007"] = "TUSCANY: Creio eu\nque esta é a\fprimeira vez que\nnos vemos?\fPermita-me que eu\nme apresente.\fSou TUSCANY, de\nterça-feira.",
  ["TEXT_ROUTE29_ROUTE46_GATE_OBJ_001"] = "Não dá para subir\nbarranco.\fMas dá para pular\nde cima deles e\vcortar caminho.",
  ["TEXT_ROUTE2_NUGGET_HOUSE_OBJ_001"] = "Oi! Nossa, que bom\nver você.\fVocê é a primeira\nvisita que eu\vtenho faz tempo.\fEstou super feliz!\nDeixa eu te dar\vum presentinho.",
  ["TEXT_ROUTE2_OBJ_001"] = "Vou procurar\nPOKéMON inseto\vmais fortes.",
  ["TEXT_ROUTE2_OBJ_001_AFTER"] = "Vou procurar\nPOKéMON inseto\vmais fortes.",
  ["TEXT_ROUTE2_OBJ_001_BEATEN"] = "Fui destroçado…",
  ["TEXT_ROUTE2_OBJ_001_SEEN"] = "Meus POKéMON\ninseto são fortes.\vPrepare-se pra\vperder!",
  ["TEXT_ROUTE2_OBJ_002"] = "Arde de verdade\nquando você toma\vbanho.",
  ["TEXT_ROUTE2_OBJ_002_AFTER"] = "Arde de verdade\nquando você toma\vbanho.",
  ["TEXT_ROUTE2_OBJ_002_BEATEN"] = "Ai, ai, ai!",
  ["TEXT_ROUTE2_OBJ_002_SEEN"] = "Se você anda no\nmato alto de\fshorts, se corta\ntodo?",
  ["TEXT_ROUTE2_OBJ_003"] = "Bom dia!\nBem-vindo ao nosso\vCENTRO POKéMON.",
  ["TEXT_ROUTE2_OBJ_003_AFTER"] = "POKéMON inseto\nafundam feito\fpelúcia quando\nvocê aperta.\fEu adoro essa\nsensação!",
  ["TEXT_ROUTE2_OBJ_003_BEATEN"] = "Não deu!",
  ["TEXT_ROUTE2_OBJ_003_SEEN"] = "Por que as meninas\nnão gostam deles?",
  ["TEXT_ROUTE30_BERRY_HOUSE_OBJ_001"] = "Sabe, POKéMON\ncome BERRIES.\fBom, o meu POKéMON\nficou mais forte\vcomendo uma BERRY\fToma. Vou dividir\numa com você!",
  ["TEXT_ROUTE30_OBJ_001"] = "Vai, RATTATA!\fTACKLE!",
  ["TEXT_ROUTE30_OBJ_002_AFTER"] = "Preciso ter\nmais POKéMON para\vbatalhas.\fVou pegar mais\num pouco!",
  ["TEXT_ROUTE30_OBJ_002_BEATEN"] = "Ugh. Não tenho\nmais POKéMON.",
  ["TEXT_ROUTE30_OBJ_002_SEEN"] = "Acabei de perder,\nvou procurar\vmais POKéMON.\fEspera! Você\nparece fraco!\vVamos batalhar!",
  ["TEXT_ROUTE30_OBJ_003"] = "Virar um bom\ntreinador é\vdifícil.\fVou batalhar\ncom outras pessoas\vpara melhorar.",
  ["TEXT_ROUTE30_OBJ_003_AFTER"] = "Virar um bom\ntreinador é\vdifícil.\fVou batalhar\ncom outras pessoas\vpara melhorar.",
  ["TEXT_ROUTE30_OBJ_003_BEATEN"] = "Estranho.\nEu venci antes.",
  ["TEXT_ROUTE30_OBJ_003_SEEN"] = "Você é um\ntreinador, certo?\fEntão você tem que\nbatalhar!",
  ["TEXT_ROUTE30_OBJ_004"] = "Fiquei sem POKé\nBALLS enquanto\vcapturava POKéMON\fDevia ter trazido\nmais…",
  ["TEXT_ROUTE30_OBJ_004_AFTER"] = "Fiquei sem POKé\nBALLS enquanto\vcapturava POKéMON\fDevia ter trazido\nmais…",
  ["TEXT_ROUTE30_OBJ_004_BEATEN"] = "Argh! Você é\nforte demais!",
  ["TEXT_ROUTE30_OBJ_004_SEEN"] = "Em vez de um\nPOKéMON, achei\vum treinador!",
  ["TEXT_ROUTE30_OBJ_005"] = "A casa do\nMR.POKéMON? Fica\vum pouco adiante.",
  ["TEXT_ROUTE30_OBJ_010"] = "Não sou treinador\fMas se olhar nos\nolhos de um,\vprepare-se.",
  ["TEXT_ROUTE31_BG_001"] = "ROTA 31\fCIDADE DE VIOLET\nCIDADE DE\vCHERRYGROVE",
  ["TEXT_ROUTE31_BG_002"] = "DARK CAVE",
  ["TEXT_ROUTE31_OBJ_001"] = "… Hnnn… Hã?\fAndei demais hoje\nprocurando\vPOKéMON.\fMeus pés doem e\nestou com sono…\fSe eu fosse um\nPOKéMON selvagem,\vseria fácil…\f…Zzzz…",
  ["TEXT_ROUTE31_OBJ_002"] = "Achei um bom\nPOKéMON na DARK\vCAVE.\fVou criar ele\npara encarar o\vFALKNER.\fEle é o líder do\nGINÁSIO de VIOLET",
  ["TEXT_ROUTE31_OBJ_003_AFTER"] = "Você pode pegar\nPOKéMON mesmo se\fvocê tiver seis.\nSe pegar um, ele\fvai para a sua\nBOX\vautomaticamente.",
  ["TEXT_ROUTE31_OBJ_003_BEATEN"] = "Aaaah…",
  ["TEXT_ROUTE31_OBJ_003_SEEN"] = "Peguei um monte\nde POKéMON. Vamos\vbatalhar com você",
  ["TEXT_ROUTE31_OBJ_004"] = "DARK CAVE…\fSe um POKéMON\niluminasse, eu\vexploraria.",
  ["TEXT_ROUTE32_OBJ_001"] = "Calmo, concentrado\nA essência da\fpesca e dos\nPOKéMON é a\vmesma.",
  ["TEXT_ROUTE32_OBJ_001_AFTER"] = "Calmo, concentrado\nA essência da\fpesca e dos\nPOKéMON é a\vmesma.",
  ["TEXT_ROUTE32_OBJ_001_BEATEN"] = "Splash!",
  ["TEXT_ROUTE32_OBJ_001_SEEN"] = "Uau!\fVocê me fez perder\naquele peixe!",
  ["TEXT_ROUTE32_OBJ_002_AFTER"] = "Pescar é paixão\nde uma vida.\fPOKéMON são amigos\nde uma vida!",
  ["TEXT_ROUTE32_OBJ_002_BEATEN"] = "Tch! Quis apressar\nas coisas…",
  ["TEXT_ROUTE32_OBJ_002_SEEN"] = "Sou um bom\npescador, mas um\vtreinador melhor!",
  ["TEXT_ROUTE32_OBJ_003"] = "POKéMON\nrecém-pegos não\vsão\fpáreo para os bem\ncriados.",
  ["TEXT_ROUTE32_OBJ_003_AFTER"] = "POKéMON\nrecém-pegos não\vsão\fpáreo para os bem\ncriados.",
  ["TEXT_ROUTE32_OBJ_003_SEEN"] = "Meus POKéMON?\nRecém-pescados!",
  ["TEXT_ROUTE32_OBJ_004"] = "Vou tentar ser o\nmelhor com os\vmeus favoritos.\fNão uso os mesmos\nPOKéMON fortes que\vtodo mundo usa.",
  ["TEXT_ROUTE32_OBJ_004_AFTER"] = "Vou tentar ser o\nmelhor com os\vmeus favoritos.\fNão uso os mesmos\nPOKéMON fortes que\vtodo mundo usa.",
  ["TEXT_ROUTE32_OBJ_004_BEATEN"] = "Você é forte!",
  ["TEXT_ROUTE32_OBJ_004_SEEN"] = "Nunca vi você\npor aqui antes.\fEntão você se acha\nbem durão?",
  ["TEXT_ROUTE32_OBJ_005"] = "O mato está cheio\nde coisa grudenta",
  ["TEXT_ROUTE32_OBJ_005_AFTER"] = "O mato está cheio\nde coisa grudenta",
  ["TEXT_ROUTE32_OBJ_005_BEATEN"] = "Droga. Achei que\nia ganhar.",
  ["TEXT_ROUTE32_OBJ_005_SEEN"] = "Achei uns POKéMON\nbons ali no\vmato!\fAcho que eles vão\ndar conta!",
  ["TEXT_ROUTE32_OBJ_006"] = "Se não quiser\nbatalhar, evite\volhar nos olhos.",
  ["TEXT_ROUTE32_OBJ_006_AFTER"] = "Se não quiser\nbatalhar, evite\volhar nos olhos.",
  ["TEXT_ROUTE32_OBJ_006_BEATEN"] = "Hmmm. Que\ndecepção.",
  ["TEXT_ROUTE32_OBJ_006_SEEN"] = "Aquele olhar…\nÉ intrigante.",
  ["TEXT_ROUTE32_OBJ_007_AFTER"] = "E eu estava numa\nboa conversa.",
  ["TEXT_ROUTE32_OBJ_007_BEATEN"] = "Vai com calma!\nQue maldade!",
  ["TEXT_ROUTE32_OBJ_007_SEEN"] = "Aham. É, e\nsabe como é…\fComo? Batalhar?\nEstou ao telefone\fAh, tá bom. Mas\nseja rápido.",
  ["TEXT_ROUTE32_OBJ_008"] = "{PLAYER}, né?\nUm cara de óculos\festava procurando\npor você.\fVá ver você mesmo.\nEle espera por\fvocê no CENTRO\nPOKéMON.",
  ["TEXT_ROUTE32_OBJ_009"] = "Eu devia treinar\nde novo no GINÁSIO\vde CIDADE DE\vVIOLET.",
  ["TEXT_ROUTE32_OBJ_009_AFTER"] = "Eu devia treinar\nde novo no GINÁSIO\vde CIDADE DE\vVIOLET.",
  ["TEXT_ROUTE32_OBJ_009_BEATEN"] = "Eu sei quais são\nminhas fraquezas.",
  ["TEXT_ROUTE32_OBJ_009_SEEN"] = "Essa BADGE! É de\nCIDADE DE VIOLET!\fVenceu o FALKNER?",
  ["TEXT_ROUTE32_OBJ_010"] = "Que tal levar\nesta gostosa e\fnutritiva\nSLOWPOKETAIL?\fPara você agora,\nsó ¥1.000.000!\fVai querer!",
  ["TEXT_ROUTE32_OBJ_012"] = "WROOOAR!\nGENTE FOGE QUANDO\fEU RUJO! MAS VOCÊ\nVEIO ATRÁS!\fISSO ME AGRADA!\nAGORA PEGUE ISTO!",
  ["TEXT_ROUTE32_OBJ_013"] = "FRIEDA: Oba!\nÉ sexta-feira!\fSou a FRIEDA de\nsexta!\fPrazer!",
  ["TEXT_ROUTE32_POKECENTER1_F_OBJ_001"] = "Bom dia!\nBem-vindo ao nosso\vCENTRO POKéMON.",
  ["TEXT_ROUTE32_POKECENTER1_F_OBJ_002"] = "Este é um ótimo\nlugar pra pescar.\fVocê viu gente\npescando? Que tal\vvocê?\fQuer uma das\nminhas RODS?",
  ["TEXT_ROUTE32_RUINS_OF_ALPH_GATE_OBJ_001"] = "RUÍNAS DE ALPH\fUm Turismo de\nVer e Tocar\fTente os painéis\nde pedra!",
  ["TEXT_ROUTE32_RUINS_OF_ALPH_GATE_OBJ_002"] = "Está estudando\nas RUÍNAS?\fVejo um cientista\nem formação.",
  ["TEXT_ROUTE32_RUINS_OF_ALPH_GATE_OBJ_003"] = "Há desenhos\nnas pedras.\fTentei mover\neles. Será que\vsão o quê?",
  ["TEXT_ROUTE33_BG_001"] = "ROTA 33",
  ["TEXT_ROUTE33_OBJ_001_AFTER"] = "Nós HIKERS somos\nmelhores nas\vmontanhas.",
  ["TEXT_ROUTE33_OBJ_001_BEATEN"] = "Uau, garoto! Você\ntem mais gás.",
  ["TEXT_ROUTE33_OBJ_001_SEEN"] = "Vim pelo túnel,\nmas ainda tenho\fmuita energia\nsobrando.",
  ["TEXT_ROUTE34_ILEX_FOREST_GATE_OBJ_001"] = "Ah, querido. Faz\numa POKéDEX?\fDeve ser difícil\nse os POKéMON\fnão aparecem.\nTente usar a TM.",
  ["TEXT_ROUTE34_OBJ_001_AFTER"] = "Talvez eu devesse\ndeixar um no\vDAYCARE. O que eu\vfaço?",
  ["TEXT_ROUTE34_OBJ_001_BEATEN"] = "Eu não fiz um\ntrabalho bom?",
  ["TEXT_ROUTE34_OBJ_001_SEEN"] = "Tenho confiança\nna minha forma\vde criar POKéMON.\fQuer ver?",
  ["TEXT_ROUTE34_OBJ_002"] = "O que aconteceu?",
  ["TEXT_ROUTE34_OBJ_002_AFTER"] = "Vou treinar ainda\nmais forte.\fAfinal, quero\nvirar LÍDER de\vGINÁSIO.",
  ["TEXT_ROUTE34_OBJ_002_BEATEN"] = "O que aconteceu?",
  ["TEXT_ROUTE34_OBJ_002_SEEN"] = "É aqui que eu\ntreino!",
  ["TEXT_ROUTE34_OBJ_003_AFTER"] = "Me esforço para\nser o destaque\vda minha turma.",
  ["TEXT_ROUTE34_OBJ_003_BEATEN"] = "Não! Tem\ntreinadores\vmelhores…",
  ["TEXT_ROUTE34_OBJ_003_SEEN"] = "Sou o melhor da\nturma em POKéMON.",
  ["TEXT_ROUTE34_OBJ_004_AFTER"] = "Você é forte\ndemais para ser\vmeu parceiro.",
  ["TEXT_ROUTE34_OBJ_004_BEATEN"] = "Ah, não! Eu não\nconsigo ganhar…",
  ["TEXT_ROUTE34_OBJ_004_SEEN"] = "Você é treinador?\fVamos fazer uma\nbatalha de treino",
  ["TEXT_ROUTE34_OBJ_005"] = "Bom dia!\nBem-vindo ao nosso\vCENTRO POKéMON.",
  ["TEXT_ROUTE34_OBJ_006_AFTER"] = "Meu POKéMON sabia\ngolpes que eu nem\vsabia que tinha.\fIsso me confundiu\ndemais!",
  ["TEXT_ROUTE34_OBJ_006_BEATEN"] = "Por que termina\nassim?",
  ["TEXT_ROUTE34_OBJ_006_SEEN"] = "Acabei de pegar\nmeu POKéMON de\vvolta no DAY-CARE\fVamos ver o quanto\nele ficou forte!",
  ["TEXT_ROUTE34_OBJ_010_AFTER"] = "IRENE: Minha irmã\nKATE vai te pegar\vpor isso!",
  ["TEXT_ROUTE34_OBJ_010_BEATEN"] = "IRENE: Ooooh!\nEle é forte!",
  ["TEXT_ROUTE34_OBJ_010_SEEN"] = "IRENE: Aaaai!\nUm menino achou!",
  ["TEXT_ROUTE34_OBJ_011_AFTER"] = "JENN: Não se ache\ndemais! Minha irmã\vKATE é durona!",
  ["TEXT_ROUTE34_OBJ_011_BEATEN"] = "JENN: Me desculpe,\nIRENE! Maninha!",
  ["TEXT_ROUTE34_OBJ_011_SEEN"] = "JENN: Não dá para\nvencer a IRENE e\vficar impune!",
  ["TEXT_ROUTE34_OBJ_012_AFTER"] = "KATE: Você é forte\ndemais. Eu não\vtive chance.\fTome. Você merece\nisto.",
  ["TEXT_ROUTE34_OBJ_012_BEATEN"] = "KATE: Não! Não\nacredito nisso.",
  ["TEXT_ROUTE34_OBJ_012_SEEN"] = "KATE: Você foi bem\nmalvado com as\vminhas irmãzinhas",
  ["TEXT_ROUTE35_GOLDENROD_GATE_OBJ_001"] = "Ei, moço!\nPode fazer um\vfavor?\fPode levar este\nPOKéMON com MAIL\vpro meu amigo?\fNa ROTA 31.",
  ["TEXT_ROUTE35_GOLDENROD_GATE_OBJ_002"] = "Uma árvore\nestranha bloqueia\fa estrada.\nEla se mexe\fse você falar.\nDizem que ela\fficou selvagem\ncom SQUIRTBOTTLE.",
  ["TEXT_ROUTE35_NATIONAL_PARK_GATE_OBJ_002"] = "Quando é o\npróximo Concurso\vde Insetos?",
  ["TEXT_ROUTE35_NATIONAL_PARK_GATE_OBJ_003"] = "Fazemos Concursos\nno PARK toda\fhora. Deveria\ntentar.",
  ["TEXT_ROUTE35_OBJ_001"] = "A música do rádio\nmuda o humor dos\vPOKéMON selvagens",
  ["TEXT_ROUTE35_OBJ_001_AFTER"] = "A música do rádio\nmuda o humor dos\vPOKéMON selvagens",
  ["TEXT_ROUTE35_OBJ_001_BEATEN"] = "Eu desisto!",
  ["TEXT_ROUTE35_OBJ_001_SEEN"] = "Venho pegando\ndados de POKéMON\fno rádio. Acho\nque estou bom.",
  ["TEXT_ROUTE35_OBJ_002"] = "Fui humilhado\nna frente da minha\vnamorada…",
  ["TEXT_ROUTE35_OBJ_002_AFTER"] = "Fui humilhado\nna frente da minha\vnamorada…",
  ["TEXT_ROUTE35_OBJ_002_BEATEN"] = "Queria que você\ntivesse perdido…",
  ["TEXT_ROUTE35_OBJ_002_SEEN"] = "Vou mostrar para\nminha namorada que\veu sou bom!",
  ["TEXT_ROUTE35_OBJ_003"] = "Confio mais nos\nmeus POKéMON que\vno meu namorado.",
  ["TEXT_ROUTE35_OBJ_003_AFTER"] = "Confio mais nos\nmeus POKéMON que\vno meu namorado.",
  ["TEXT_ROUTE35_OBJ_003_BEATEN"] = "Nossa! Você é\ntão forte!",
  ["TEXT_ROUTE35_OBJ_003_SEEN"] = "Meu namorado é\nfraco, não dá para\vcontar com ele.",
  ["TEXT_ROUTE35_OBJ_004"] = "As BADGES de\nGINÁSIO são lindas\vEu coleciono.",
  ["TEXT_ROUTE35_OBJ_004_AFTER"] = "As BADGES de\nGINÁSIO são lindas\vEu coleciono.",
  ["TEXT_ROUTE35_OBJ_004_BEATEN"] = "Ah. Eu não\nconsegui…",
  ["TEXT_ROUTE35_OBJ_004_SEEN"] = "Você vai para o\nGINÁSIO? Eu vou!",
  ["TEXT_ROUTE35_OBJ_005"] = "Alguns POKéMON\nfogem na hora.\fTente pegar eles\ncom a FAST BALL\vdo KURT.\fSempre que acho um\nWHT APRICORN, eu\vlevo para o KURT.\fEle faz uma POKé\nBALL sob medida.",
  ["TEXT_ROUTE35_OBJ_005_AFTER"] = "Alguns POKéMON\nfogem na hora.\fTente pegar eles\ncom a FAST BALL\vdo KURT.\fSempre que acho um\nWHT APRICORN, eu\vlevo para o KURT.\fEle faz uma POKé\nBALL sob medida.",
  ["TEXT_ROUTE35_OBJ_005_BEATEN"] = "Eita! Não fui\nrápido o bastante",
  ["TEXT_ROUTE35_OBJ_005_SEEN"] = "Que tipo de POKé\nBALL você usa?",
  ["TEXT_ROUTE35_OBJ_006"] = "A POKéMON March\nno rádio atrai\vPOKéMON do mato.",
  ["TEXT_ROUTE35_OBJ_006_AFTER"] = "A POKéMON March\nno rádio atrai\vPOKéMON do mato.",
  ["TEXT_ROUTE35_OBJ_006_BEATEN"] = "Ai! Queimei a\nponta do nariz!",
  ["TEXT_ROUTE35_OBJ_006_SEEN"] = "Estou treinando\nmeu sopro de fogo",
  ["TEXT_ROUTE35_OBJ_007_AFTER"] = "Meu VENONAT ganhou\no Concurso de\fCaptura Insetos\nno NATIONAL PARK.",
  ["TEXT_ROUTE35_OBJ_007_BEATEN"] = "Entendi. Então\nvocê luta assim.",
  ["TEXT_ROUTE35_OBJ_007_SEEN"] = "Eu vou a qualquer\nlugar onde apareça\vPOKéMON inseto.",
  ["TEXT_ROUTE35_OBJ_008"] = "Eu ia deslumbrar\nvocê com o meu\vPOKéMON premiado.\fMas a sua força\nme eletrizou!",
  ["TEXT_ROUTE35_OBJ_008_AFTER"] = "Eu ia deslumbrar\nvocê com o meu\vPOKéMON premiado.\fMas a sua força\nme eletrizou!",
  ["TEXT_ROUTE35_OBJ_008_BEATEN"] = "Ufa! Que choque\nfoi esse!",
  ["TEXT_ROUTE35_OBJ_008_SEEN"] = "Veja como eu sou\nbom com a BALL!",
  ["TEXT_ROUTE35_OBJ_009"] = "Bom dia!\nBem-vindo ao nosso\vCENTRO POKéMON.",
  ["TEXT_ROUTE36_BG_002"] = "RUÍNAS DE ALPH\nENTRADA NORTE",
  ["TEXT_ROUTE36_BG_003"] = "ROTA 36",
  ["TEXT_ROUTE36_BG_004"] = "TRAINER TIPS\fStatus de POKéMON\nvariam , mesmo\vdentro da mesma\fespécie. Seus\nstatus podem\fser parecidos. Mas\nas diferenças\fse tornar claras\nconforme crescem.",
  ["TEXT_ROUTE36_NATIONAL_PARK_GATE_OBJ_002"] = "DON: Uau, você me\nvenceu. Você e\vmuito bom.",
  ["TEXT_ROUTE36_NATIONAL_PARK_GATE_OBJ_003"] = "ED: Invidio você.\nNão consegui\vdesta vez.",
  ["TEXT_ROUTE36_NATIONAL_PARK_GATE_OBJ_004"] = "NICK: Muito bem!\nVou criar meus\vPOKéMON melhor.",
  ["TEXT_ROUTE36_NATIONAL_PARK_GATE_OBJ_005"] = "WILLIAM: Você e\no vencedor? O que\vvocê capturou?",
  ["TEXT_ROUTE36_NATIONAL_PARK_GATE_OBJ_006"] = "BENNY: Parabéns!\nVocê ganhou meu\vrespeito!",
  ["TEXT_ROUTE36_NATIONAL_PARK_GATE_OBJ_007"] = "BARRY: O POKéMON\nque você capturou\v…e incrível!",
  ["TEXT_ROUTE36_NATIONAL_PARK_GATE_OBJ_008"] = "CINDY: Venceu?\nQue ótimo!\fVocê quer ir\ncaçar POKéMON\vinsetos comigo?",
  ["TEXT_ROUTE36_NATIONAL_PARK_GATE_OBJ_009"] = "JOSH: Eu… não\nacredito que perdi\vno concurso…",
  ["TEXT_ROUTE36_NATIONAL_PARK_GATE_OBJ_010"] = "SAMUEL: Na próxima\nvou vencer.",
  ["TEXT_ROUTE36_NATIONAL_PARK_GATE_OBJ_011"] = "KIPP: Você pode\nme dar dicas?\fQuero estudar\nseu estilo.",
  ["TEXT_ROUTE36_NATIONAL_PARK_GATE_OBJ_012"] = "Alguns POKéMON só\npodem ser vistos\vno PARQUE.",
  ["TEXT_ROUTE36_OBJ_001"] = "Eu seria forte\nse pudesse saber\fo que meu oponente\nestá pensando.",
  ["TEXT_ROUTE36_OBJ_001_AFTER"] = "Eu seria forte\nse pudesse saber\fo que meu oponente\nestá pensando.",
  ["TEXT_ROUTE36_OBJ_001_BEATEN"] = "Te avaliei mal!",
  ["TEXT_ROUTE36_OBJ_001_SEEN"] = "Vou ler os\nseus pensamentos!",
  ["TEXT_ROUTE36_OBJ_002_AFTER"] = "Droga. Estudo 5\nhoras/dia também.\fHá muita coisa\nque não se aprende\vsó lendo livros.",
  ["TEXT_ROUTE36_OBJ_002_BEATEN"] = "Ops! Erro de\ncálculo?",
  ["TEXT_ROUTE36_OBJ_002_SEEN"] = "Graças aos meus\nestudos, encaro\vqualquer POKéMON!",
  ["TEXT_ROUTE36_OBJ_003"] = "E uma árvore\nestranha?",
  ["TEXT_ROUTE36_OBJ_004"] = "Uma árvore\nestá bloqueando\vo caminho para\fCIDADE DE\nGOLDENROD.\vEstá me impedindo\fde comprar.\nAlguém deve agir.",
  ["TEXT_ROUTE36_OBJ_005"] = "Wa-hey!\fEu ia quebrar\nessa árvore\fcom meu soco\ndireto.\fMas não consegui!\nSou um fracasso!",
  ["TEXT_ROUTE36_OBJ_007"] = "ARTHUR: Quem e\nvocê?\fSou ARTHUR de\nquinta-feira.",
  ["TEXT_ROUTE36_RUINS_OF_ALPH_GATE_OBJ_001"] = "Não se pergunta\nquem faria algo\vassim?\vE por quê?",
  ["TEXT_ROUTE36_RUINS_OF_ALPH_GATE_OBJ_002"] = "Você viu aquela\nárvore estranha\vna estrada?\fIsso pode explicar\npor que menos\fpessoas visitam\nas RUÍNAS.",
  ["TEXT_ROUTE37_OBJ_001"] = "ANN: Eu sei o que\nminha irmã e meus\fPOKéMON estão\npensando.",
  ["TEXT_ROUTE37_OBJ_001_AFTER"] = "ANN: Eu sei o que\nminha irmã e meus\fPOKéMON estão\npensando.",
  ["TEXT_ROUTE37_OBJ_001_BEATEN"] = "ANN & ANNE: Você\né mau!",
  ["TEXT_ROUTE37_OBJ_001_SEEN"] = "ANN: Eu e ANNE\nestamos juntas\vnessa!",
  ["TEXT_ROUTE37_OBJ_002"] = "ANNE: Sentimos o\nmesmo que os\vnossos POKéMON.",
  ["TEXT_ROUTE37_OBJ_002_AFTER"] = "ANNE: Sentimos o\nmesmo que os\vnossos POKéMON.",
  ["TEXT_ROUTE37_OBJ_002_BEATEN"] = "ANN & ANNE: Você\né mau!",
  ["TEXT_ROUTE37_OBJ_002_SEEN"] = "ANNE: Eu e a ANN\nestamos nisso\vjuntas!",
  ["TEXT_ROUTE37_OBJ_003"] = "Fazer o POKéMON\ndormir ou deixar\vele paralisado são\vboas técnicas.",
  ["TEXT_ROUTE37_OBJ_003_AFTER"] = "Fazer o POKéMON\ndormir ou deixar\vele paralisado são\vboas técnicas.",
  ["TEXT_ROUTE37_OBJ_003_BEATEN"] = "Perdi. Que\ntristeza…",
  ["TEXT_ROUTE37_OBJ_003_SEEN"] = "POKéMON não fazem\nnada se estiverem\vdormindo.\fVou mostrar como\nisso é assustador",
  ["TEXT_ROUTE37_OBJ_005"] = "SUNNY: Oi!\fEu sou o SUNNY de\nsábado, ou seja,\vhoje é sábado!",
  ["TEXT_ROUTE38_OBJ_001_AFTER"] = "Tenho tantas\nprovas para fazer\fque sobra pouco\ntempo pro POKéMON\fEntão quando dá\npara jogar, eu me\vconcentro mesmo.",
  ["TEXT_ROUTE38_OBJ_001_BEATEN"] = "Acho que não\nestudei bastante.",
  ["TEXT_ROUTE38_OBJ_001_SEEN"] = "Deixa eu tentar\numa coisa que\vaprendi hoje.",
  ["TEXT_ROUTE38_OBJ_002_AFTER"] = "Eu sei de uma\nboa!\fO leite da MOOMOO\nFARM é famoso pelo\vsabor.",
  ["TEXT_ROUTE38_OBJ_002_BEATEN"] = "Entendi. Então dá\npara lutar assim.",
  ["TEXT_ROUTE38_OBJ_002_SEEN"] = "Você é bom em\ntreinar?\fSe for, pode me\nmostrar como?",
  ["TEXT_ROUTE38_OBJ_003"] = "Pretendo treinar\nem CIDADE DE\vCIANWOOD\fpara meu POKéMON\naprender a voar.",
  ["TEXT_ROUTE38_OBJ_003_AFTER"] = "Pretendo treinar\nem CIDADE DE\vCIANWOOD\fpara meu POKéMON\naprender a voar.",
  ["TEXT_ROUTE38_OBJ_003_BEATEN"] = "Dá vontade de sair\nvoando agora.",
  ["TEXT_ROUTE38_OBJ_003_SEEN"] = "Voe alto no céu,\nmeu amado\vPOKéMON ave!",
  ["TEXT_ROUTE38_OBJ_004"] = "Quando vejo\nPOKéMON, meus\vnervos se\vacalmam.",
  ["TEXT_ROUTE38_OBJ_004_AFTER"] = "Quando vejo\nPOKéMON, meus\vnervos se\vacalmam.",
  ["TEXT_ROUTE38_OBJ_004_BEATEN"] = "Que bom que eu vi\nseus POKéMON!",
  ["TEXT_ROUTE38_OBJ_004_SEEN"] = "Oi! Que treinador\nfofo você é!\fPosso ver seus\nPOKéMON?",
  ["TEXT_ROUTE38_OBJ_005"] = "Todo tipo de\ngente pelo mundo\fvive feliz com\nos POKéMON.",
  ["TEXT_ROUTE38_OBJ_005_AFTER"] = "Todo tipo de\ngente pelo mundo\fvive feliz com\nos POKéMON.",
  ["TEXT_ROUTE38_OBJ_005_BEATEN"] = "Sua habilidade é\nde nível mundial!",
  ["TEXT_ROUTE38_OBJ_005_SEEN"] = "Já estive no\nexterior, então\fconheço todo tipo\nde POKéMON!",
  ["TEXT_ROUTE38_OBJ_007_AFTER"] = "MOOMOO MILK é boa\npra beleza\fe saúde, mas,\ninfelizmente,\fsó vendem uma\ngarrafa por vez.",
  ["TEXT_ROUTE38_OBJ_007_BEATEN"] = "Bebemos MOOMOO\nMILK todo dia.",
  ["TEXT_ROUTE38_OBJ_007_SEEN"] = "Não acha que eu e\nmeu POKéMON somos\vlindos?",
  ["TEXT_ROUTE39_BARN_OBJ_001"] = "MOOMOO doente…\fEla precisa de\nmuitas BERRIES.",
  ["TEXT_ROUTE39_BARN_OBJ_002"] = "MOOMOO doente…\fEla precisa de\nmuitas BERRIES.",
  ["TEXT_ROUTE39_FARMHOUSE_BG_001"] = "Uma coleção\ninteira de livros\vde POKéMON!",
  ["TEXT_ROUTE39_FARMHOUSE_BG_002"] = "Uma coleção\ninteira de livros\vde POKéMON!",
  ["TEXT_ROUTE39_FARMHOUSE_OBJ_001"] = "A MILTANK não me\ndá leite mais não.\vagora.\fEsta FAZENDA aqui\ntem leite famoso.\fQuase todo mundo\nquer beber.\fEla me dá bastante\nleite se eu der\fmuitas BERRIES,\neu acho.",
  ["TEXT_ROUTE39_FARMHOUSE_OBJ_002"] = "Nosso leite vai\naté para KANTO.\fEntão se nossa\nMILTANK não der\fleite, ficamos\nem apuros.",
  ["TEXT_ROUTE39_OBJ_001"] = "Meus POKéMON foram\npegos e criados no\vexterior.\fSão meus\ncompanheiros nas\vlongas viagens.",
  ["TEXT_ROUTE39_OBJ_001_AFTER"] = "Meus POKéMON foram\npegos e criados no\vexterior.\fSão meus\ncompanheiros nas\vlongas viagens.",
  ["TEXT_ROUTE39_OBJ_001_BEATEN"] = "Aaaargh!",
  ["TEXT_ROUTE39_OBJ_001_SEEN"] = "Acabei de voltar\npara OLIVINE.\fQue tal uma\nbatalha POKéMON?",
  ["TEXT_ROUTE39_OBJ_002_AFTER"] = "Não vou ouvir\nvocê se gabar!\fNós POKé FANS\ntemos a regra de\fnão ouvir os\noutros se gabarem",
  ["TEXT_ROUTE39_OBJ_002_BEATEN"] = "Nem consigo me\ngabar…",
  ["TEXT_ROUTE39_OBJ_002_SEEN"] = "Você se importa se\neu me gabar dos\vmeus POKéMON?",
  ["TEXT_ROUTE39_OBJ_003"] = "Não me importo\nde perder.",
  ["TEXT_ROUTE39_OBJ_003_AFTER"] = "Você conhece os\nPOKéMON bebês?\fAposto que são\nadoráveis!",
  ["TEXT_ROUTE39_OBJ_003_BEATEN"] = "Não me importo\nde perder.",
  ["TEXT_ROUTE39_OBJ_003_SEEN"] = "Que POKéMON\nqueridos.\fVamos mostrar os\nnossos POKéMON\vao mesmo tempo.",
  ["TEXT_ROUTE39_OBJ_008"] = "Ooh, seus POKéMON\ntêm potencial.",
  ["TEXT_ROUTE39_OBJ_008_AFTER"] = "Sabe como cada\nPOKéMON tem uma\vhabilidade?\fCom gente é igual\nCada um tem um\vpotencial\vdiferente.",
  ["TEXT_ROUTE39_OBJ_008_BEATEN"] = "Ooh, seus POKéMON\ntêm potencial.",
  ["TEXT_ROUTE39_OBJ_008_SEEN"] = "Deixa eu ver do\nque os seus\vPOKéMON são bons.",
  ["TEXT_ROUTE3_OBJ_001"] = "Quando chove, é\ndifícil dar a\vpartida…",
  ["TEXT_ROUTE3_OBJ_001_AFTER"] = "Quando chove, é\ndifícil dar a\vpartida…",
  ["TEXT_ROUTE3_OBJ_001_BEATEN"] = "Está sol, mas eu\nestou encharcado…",
  ["TEXT_ROUTE3_OBJ_001_SEEN"] = "Ah! O tempo\nestá ótimo como\vsempre.",
  ["TEXT_ROUTE3_OBJ_002"] = "Você parecia bom.\fFiquei com medo de\nte encarar…",
  ["TEXT_ROUTE3_OBJ_002_AFTER"] = "Você parecia bom.\fFiquei com medo de\nte encarar…",
  ["TEXT_ROUTE3_OBJ_002_BEATEN"] = "Eu sabia que\nperderia…",
  ["TEXT_ROUTE3_OBJ_002_SEEN"] = "Hmmm… Não sei o\nque fazer…",
  ["TEXT_ROUTE3_OBJ_003"] = "Eu uso shorts o\nano inteiro.\fÉ a minha regra\nde moda.",
  ["TEXT_ROUTE3_OBJ_003_AFTER"] = "Eu uso shorts o\nano inteiro.\fÉ a minha regra\nde moda.",
  ["TEXT_ROUTE3_OBJ_003_BEATEN"] = "Arrasado!",
  ["TEXT_ROUTE3_OBJ_003_SEEN"] = "Eu corro como o\nvento!",
  ["TEXT_ROUTE3_OBJ_004"] = "O maior cuspidor\nde fogo de KANTO\vsou eu.\fMas não o melhor\ntreinador…",
  ["TEXT_ROUTE3_OBJ_004_AFTER"] = "O maior cuspidor\nde fogo de KANTO\vsou eu.\fMas não o melhor\ntreinador…",
  ["TEXT_ROUTE3_OBJ_004_BEATEN"] = "Ai! Que quente!",
  ["TEXT_ROUTE3_OBJ_004_SEEN"] = "Chegue mais perto\ne dê uma olhada!",
  ["TEXT_ROUTE40_OBJ_001"] = "CIDADE DE CIANWOOD\nfica bem longe\vdaqui.",
  ["TEXT_ROUTE40_OBJ_001_AFTER"] = "CIDADE DE CIANWOOD\nfica bem longe\vdaqui.",
  ["TEXT_ROUTE40_OBJ_001_BEATEN"] = "Tá! Chega! Perdi!",
  ["TEXT_ROUTE40_OBJ_001_SEEN"] = "Tem que aquecer\nantes de entrar\vna água.\fIsso é básico.",
  ["TEXT_ROUTE40_OBJ_002"] = "Nadar exercita\no corpo inteiro.\vÉ saudável.",
  ["TEXT_ROUTE40_OBJ_002_AFTER"] = "Nadar exercita\no corpo inteiro.\vÉ saudável.",
  ["TEXT_ROUTE40_OBJ_002_BEATEN"] = "Ops. Eu perdi…",
  ["TEXT_ROUTE40_OBJ_002_SEEN"] = "Um jovem como\nvocê devia nadar.\fNão use SURF no\nseu POKéMON.",
  ["TEXT_ROUTE40_OBJ_003"] = "Eu diria que nado\nmelhor que você.\vÉ isso aí!",
  ["TEXT_ROUTE40_OBJ_003_AFTER"] = "Eu diria que nado\nmelhor que você.\vÉ isso aí!",
  ["TEXT_ROUTE40_OBJ_003_BEATEN"] = "Perdi essa!",
  ["TEXT_ROUTE40_OBJ_003_SEEN"] = "Você vai para\nCIANWOOD?\fQue tal uma luta\nrápida antes?",
  ["TEXT_ROUTE40_OBJ_004"] = "Ooh, estou ficando\ntonto!",
  ["TEXT_ROUTE40_OBJ_004_AFTER"] = "Enquanto eu boio\nassim, as ondas\vme levam.",
  ["TEXT_ROUTE40_OBJ_004_BEATEN"] = "Ooh, estou ficando\ntonto!",
  ["TEXT_ROUTE40_OBJ_004_SEEN"] = "Boia não é\ncomigo.\fEstou agarrado a\num POKéMON do mar",
  ["TEXT_ROUTE40_OBJ_008"] = "Mesmo não\nvendo daqui,\fCIANWOOD fica\ndo outro lado",
  ["TEXT_ROUTE40_OBJ_009"] = "MONICA: Prazer, eu\nsou a MONICA de\fsegunda.",
  ["TEXT_ROUTE41_OBJ_001"] = "Não é relaxante\nsó boiar assim?\vNé?",
  ["TEXT_ROUTE41_OBJ_001_AFTER"] = "Não é relaxante\nsó boiar assim?\vNé?",
  ["TEXT_ROUTE41_OBJ_001_BEATEN"] = "Eita! Minha pele\nestá enrugada!",
  ["TEXT_ROUTE41_OBJ_001_SEEN"] = "A água está\nquente aqui.\vEstou solto.\fClaro, vou\nte enfrentar!",
  ["TEXT_ROUTE41_OBJ_002"] = "É tão longe até\nCIANWOOD.\fMas voltar para\nOLIVINE também\vnão é fácil.\fO que eu faço?",
  ["TEXT_ROUTE41_OBJ_002_AFTER"] = "É tão longe até\nCIANWOOD.\fMas voltar para\nOLIVINE também\vnão é fácil.\fO que eu faço?",
  ["TEXT_ROUTE41_OBJ_002_BEATEN"] = "Ofegante…",
  ["TEXT_ROUTE41_OBJ_002_SEEN"] = "Estou cansado.\nSe eu ganhar, me\vempreste um.",
  ["TEXT_ROUTE41_OBJ_003"] = "Era uma noite\nescura e de\ftempestade… Eu vi\num POKéMON gigante\vvoando das ilhas.\fEle espalhava\npenas das asas\vprateadas dele.",
  ["TEXT_ROUTE41_OBJ_003_AFTER"] = "Era uma noite\nescura e de\ftempestade… Eu vi\num POKéMON gigante\vvoando das ilhas.\fEle espalhava\npenas das asas\vprateadas dele.",
  ["TEXT_ROUTE41_OBJ_003_BEATEN"] = "Qual é o segredo\nda sua força?",
  ["TEXT_ROUTE41_OBJ_003_SEEN"] = "Viu aquelas ilhas\nbloqueadas por\vredemoinhos?\fTem que ter um\nsegredo ali!",
  ["TEXT_ROUTE41_OBJ_005"] = "Um segredo das\nWHIRL ISLANDS…\fLá dentro é\nescuro total!",
  ["TEXT_ROUTE41_OBJ_005_AFTER"] = "Um segredo das\nWHIRL ISLANDS…\fLá dentro é\nescuro total!",
  ["TEXT_ROUTE41_OBJ_005_BEATEN"] = "Ooh, você tem\nmuito fôlego!",
  ["TEXT_ROUTE41_OBJ_005_SEEN"] = "Você busca os\nsegredos das\vWHIRL ISLANDS?",
  ["TEXT_ROUTE41_OBJ_006"] = "Dizem que tem um\nPOKéMON enorme lá\vno fundo das\vWHIRL ISLANDS.\fO que será que\npode ser?",
  ["TEXT_ROUTE41_OBJ_006_AFTER"] = "Dizem que tem um\nPOKéMON enorme lá\vno fundo das\vWHIRL ISLANDS.\fO que será que\npode ser?",
  ["TEXT_ROUTE41_OBJ_006_BEATEN"] = "É assim que se\nfaz?",
  ["TEXT_ROUTE41_OBJ_006_SEEN"] = "Estou indo para\nas WHIRL ISLANDS.\fVou explorar com\nuns amigos.",
  ["TEXT_ROUTE41_OBJ_007"] = "Não tinha uma\nmúsica sobre um\vmenino no LAPRAS?",
  ["TEXT_ROUTE41_OBJ_007_AFTER"] = "Não tinha uma\nmúsica sobre um\vmenino no LAPRAS?",
  ["TEXT_ROUTE41_OBJ_007_SEEN"] = "Você fica tão\nelegante montado\vno seu POKéMON.",
  ["TEXT_ROUTE41_OBJ_008"] = "Queimadura de sol\né ruim pra pele.\fMas eu não uso\nprotetor.\fNão vou poluir\na água.",
  ["TEXT_ROUTE41_OBJ_008_AFTER"] = "Queimadura de sol\né ruim pra pele.\fMas eu não uso\nprotetor.\fNão vou poluir\na água.",
  ["TEXT_ROUTE41_OBJ_008_SEEN"] = "O tempo está tão\nlindo que eu fico\vabobado!",
  ["TEXT_ROUTE41_OBJ_009"] = "Ouvi rugidos lá\ndo fundo das\vISLANDS.",
  ["TEXT_ROUTE41_OBJ_009_AFTER"] = "Ouvi rugidos lá\ndo fundo das\vISLANDS.",
  ["TEXT_ROUTE41_OBJ_009_BEATEN"] = "Oh! Você tem mais\nenergia que eu.",
  ["TEXT_ROUTE41_OBJ_009_SEEN"] = "Se precisar\ndescansar, é só\vboiar.\fVocê recupera o\nfôlego e pode\fseguir em frente\ncom força.",
  ["TEXT_ROUTE41_OBJ_010"] = "Os cardumes de\nSTARYU acendem\vao mesmo tempo.\fÉ tão bonito que\nchega a assustar.",
  ["TEXT_ROUTE41_OBJ_010_AFTER"] = "Os cardumes de\nSTARYU acendem\vao mesmo tempo.\fÉ tão bonito que\nchega a assustar.",
  ["TEXT_ROUTE41_OBJ_010_BEATEN"] = "Ah, céus…",
  ["TEXT_ROUTE41_OBJ_010_SEEN"] = "À noite, STARYU\nse juntam perto\vda superfície.",
  ["TEXT_ROUTE42_OBJ_001_AFTER"] = "Quero virar o\ntreinador CAMPEÃO\fcom os POKéMON\nque eu pesquei.\fÉ a melhor parte\nde pescar!",
  ["TEXT_ROUTE42_OBJ_001_BEATEN"] = "O quê? Isso não\nestá certo.",
  ["TEXT_ROUTE42_OBJ_001_SEEN"] = "Vou mostrar o\npoder do POKéMON\vque eu peguei!",
  ["TEXT_ROUTE42_OBJ_002"] = "Perder parece\npouca coisa se\fvocê olha para o\ncéu enorme!",
  ["TEXT_ROUTE42_OBJ_002_AFTER"] = "Perder parece\npouca coisa se\fvocê olha para o\ncéu enorme!",
  ["TEXT_ROUTE42_OBJ_002_BEATEN"] = "Rahahá!",
  ["TEXT_ROUTE42_OBJ_002_SEEN"] = "Ah, que bom estar\nao ar livre!\vMe sinto livre!",
  ["TEXT_ROUTE42_OBJ_003"] = "Você está fazendo\numa POKéDEX?\fUau, deve conhecer\nalguns POKéMON\vbem raros!\fPosso ver?\nPor favor?",
  ["TEXT_ROUTE42_OBJ_003_AFTER"] = "Você está fazendo\numa POKéDEX?\fUau, deve conhecer\nalguns POKéMON\vbem raros!\fPosso ver?\nPor favor?",
  ["TEXT_ROUTE42_OBJ_003_BEATEN"] = "Devia ter usado\na MOON STONE…",
  ["TEXT_ROUTE42_OBJ_003_SEEN"] = "EI!\fEste é o meu lugar\nsecreto! Some,\vseu forasteiro!",
  ["TEXT_ROUTE43_GATE_OBJ_001"] = "Fui expulso do\nmeu posto por\vaqueles de preto.\fEles deixaram\nisto para trás.\fIsso me deixa\ndesconfortável.\vPode levar?",
  ["TEXT_ROUTE43_GATE_OBJ_002"] = "Hihihi. Estamos\nenchendo o bolso.\fTodo mundo quer\nver o que rola\fno LAKE OF\nRAGE.",
  ["TEXT_ROUTE43_GATE_OBJ_003"] = "Hihihi. Estamos\nenchendo o bolso.\fTodo mundo quer\nver o que rola\fno LAKE OF\nRAGE.",
  ["TEXT_ROUTE43_MAHOGANY_GATE_OBJ_001"] = "Só quem vai ao\nLAKE OF RAGE\fpassou por aqui\nultimamente.",
  ["TEXT_ROUTE43_OBJ_001"] = "Do que mais eu\ngosto além de\vPOKéMON?\fA MARY do rádio.\nDeve ser fofa!",
  ["TEXT_ROUTE43_OBJ_001_AFTER"] = "Do que mais eu\ngosto além de\vPOKéMON?\fA MARY do rádio.\nDeve ser fofa!",
  ["TEXT_ROUTE43_OBJ_001_BEATEN"] = "Como você pôde\nfazer isso comigo",
  ["TEXT_ROUTE43_OBJ_001_SEEN"] = "Eu amo POKéMON!\fFoi por isso que\ncomecei--e por\fisso vou\ncontinuar\vcolecionando!",
  ["TEXT_ROUTE43_OBJ_002_AFTER"] = "Eu ficaria feliz\nsó de ter um\vPOKéMON raro.",
  ["TEXT_ROUTE43_OBJ_002_BEATEN"] = "Ah, meus pobres\nPOKéMON queridos!",
  ["TEXT_ROUTE43_OBJ_002_SEEN"] = "Ei! Você tem algum\nPOKéMON raro?",
  ["TEXT_ROUTE43_OBJ_003"] = "Não tem problema\nas pessoas\fgostarem de tipos\ndiferentes.\fPOKéMON não é só\nter o mais\vpoderoso.",
  ["TEXT_ROUTE43_OBJ_003_AFTER"] = "Não tem problema\nas pessoas\fgostarem de tipos\ndiferentes.\fPOKéMON não é só\nter o mais\vpoderoso.",
  ["TEXT_ROUTE43_OBJ_003_BEATEN"] = "Meu NIDOKING foi\nmuito bem!",
  ["TEXT_ROUTE43_OBJ_003_SEEN"] = "Você acredita\nnisso?\fUm cara chamado\n{RIVAL} zoou os\vmeus POKéMON!\fDroga! Meu POKéMON\né ótimo!",
  ["TEXT_ROUTE43_OBJ_004"] = "A LURE BALL do\nKURT é a melhor\fpara pegar POKéMON\nfisgado.\fÉ bem mais\neficaz que uma\vULTRA BALL.",
  ["TEXT_ROUTE43_OBJ_004_AFTER"] = "A LURE BALL do\nKURT é a melhor\fpara pegar POKéMON\nfisgado.\fÉ bem mais\neficaz que uma\vULTRA BALL.",
  ["TEXT_ROUTE43_OBJ_004_BEATEN"] = "Perdi, mas me\nsinto melhor.",
  ["TEXT_ROUTE43_OBJ_004_SEEN"] = "Estou numa fase\fDeve ser o\nequipamento.\fVamos lutar para\nmudar o clima!",
  ["TEXT_ROUTE43_OBJ_005_BEATEN"] = "Brinquei demais!",
  ["TEXT_ROUTE43_OBJ_005_SEEN"] = "Você também vai\nao LAKE OF RAGE?\fVamos brincar um\npouquinho!",
  ["TEXT_ROUTE43_OBJ_006"] = "O que está\nhavendo no LAKE?\fA gente ia\nacampar lá.",
  ["TEXT_ROUTE43_OBJ_006_AFTER"] = "O que está\nhavendo no LAKE?\fA gente ia\nacampar lá.",
  ["TEXT_ROUTE43_OBJ_006_BEATEN"] = "Perder não tem\ngraça nenhuma…",
  ["TEXT_ROUTE43_OBJ_006_SEEN"] = "Dá para fazer\ntanta coisa com\vmeu POKéMON!",
  ["TEXT_ROUTE44_OBJ_001_AFTER"] = "Aquele POLIWAG\nque escapou…\vEra enorme.\fJuro que tinha uns\n5 metros!",
  ["TEXT_ROUTE44_OBJ_001_BEATEN"] = "Deixa pra\nlá.",
  ["TEXT_ROUTE44_OBJ_001_SEEN"] = "Ah! Você fez eu\nperder um\vPOLIWAG!\fO que você vai\nfazer sobre isso?",
  ["TEXT_ROUTE44_OBJ_002"] = "São 100 vitórias\ne 101 derrotas.\fNão vou lutar de\nnovo tão cedo.",
  ["TEXT_ROUTE44_OBJ_002_AFTER"] = "São 100 vitórias\ne 101 derrotas.\fNão vou lutar de\nnovo tão cedo.",
  ["TEXT_ROUTE44_OBJ_002_BEATEN"] = "Hmmmm…\nNão está certo.",
  ["TEXT_ROUTE44_OBJ_002_SEEN"] = "Eu pesco até não\naguentar mais.\fE luto até\ncair também.\fÉ essa a minha\nrelação com os\vmeus POKéMON.",
  ["TEXT_ROUTE44_OBJ_003"] = "É importante ter\nconvicção do seu\vlado.",
  ["TEXT_ROUTE44_OBJ_003_AFTER"] = "É importante ter\nconvicção do seu\vlado.",
  ["TEXT_ROUTE44_OBJ_003_BEATEN"] = "Arrgh… Que\nderrota chocante…",
  ["TEXT_ROUTE44_OBJ_003_SEEN"] = "Eu vou ganhar,\ncom certeza!",
  ["TEXT_ROUTE44_OBJ_004"] = "Se um POKéMON tem\ncores diferentes\fdo normal, ele\nvale mais.\fO quê? Isso não\né verdade?",
  ["TEXT_ROUTE44_OBJ_004_AFTER"] = "Se um POKéMON tem\ncores diferentes\fdo normal, ele\nvale mais.\fO quê? Isso não\né verdade?",
  ["TEXT_ROUTE44_OBJ_004_BEATEN"] = "Oooh, seus POKéMON\nsão atraentes.",
  ["TEXT_ROUTE44_OBJ_004_SEEN"] = "Faço qualquer\ncoisa para pôr a\vmão em raros!",
  ["TEXT_ROUTE44_OBJ_005_AFTER"] = "ARTICUNO, ZAPDOS\ne MOLTRES são\fos três POKéMON\npássaro lendários\fMas ouvi que tem\noutros pássaros\vlendários também.",
  ["TEXT_ROUTE44_OBJ_005_BEATEN"] = "Ufa! Você é bom\nmesmo.",
  ["TEXT_ROUTE44_OBJ_005_SEEN"] = "Você conhece os\nPOKéMON pássaro\vlendários?",
  ["TEXT_ROUTE44_OBJ_006"] = "Uau. Você tem\nmuitas BADGES.\fNão é à toa que\né tão forte.\fSerá que o MORTY\ndo GINÁSIO de\fECRUTEAK ainda\nestá treinando?\fEle me arrebentou\nfeio.",
  ["TEXT_ROUTE44_OBJ_006_AFTER"] = "Uau. Você tem\nmuitas BADGES.\fNão é à toa que\né tão forte.\fSerá que o MORTY\ndo GINÁSIO de\fECRUTEAK ainda\nestá treinando?\fEle me arrebentou\nfeio.",
  ["TEXT_ROUTE44_OBJ_006_BEATEN"] = "Tch! Foi derrota\ntotal pra mim.",
  ["TEXT_ROUTE44_OBJ_006_SEEN"] = "Dá para ver que\nvocê é um bom\vtreinador.\fEu sou bom em\nPOKéMON e vejo que\vvocê também é.",
  ["TEXT_ROUTE44_OBJ_007"] = "Não! Assim não\ndá mesmo.",
  ["TEXT_ROUTE44_OBJ_007_AFTER"] = "A gente melhora\nvivendo muitas\vbatalhas.\fLutei muito para\nser o que sou\vhoje, uma elite.",
  ["TEXT_ROUTE44_OBJ_007_BEATEN"] = "Não! Assim não\ndá mesmo.",
  ["TEXT_ROUTE44_OBJ_007_SEEN"] = "Você parece forte\fBons treinadores\nprocuram rivais\vfortes por si.",
  ["TEXT_ROUTE45_OBJ_001"] = "Vou voltar para o\nICE PATH de\fBLACKTHORN e\ntreinar mais.",
  ["TEXT_ROUTE45_OBJ_001_AFTER"] = "Vou voltar para o\nICE PATH de\fBLACKTHORN e\ntreinar mais.",
  ["TEXT_ROUTE45_OBJ_001_BEATEN"] = "Ah, eu perdi!",
  ["TEXT_ROUTE45_OBJ_001_SEEN"] = "Esteja pronto\npra tudo!\fVou ver se seus\nPOKéMON foram\vbem criados!",
  ["TEXT_ROUTE45_OBJ_002"] = "Nossa, como eu\namo PS UP! Hmmm!\fFico bebendo o\ndos meus POKéMON!\fNão me controlo!",
  ["TEXT_ROUTE45_OBJ_002_AFTER"] = "Nossa, como eu\namo PS UP! Hmmm!\fFico bebendo o\ndos meus POKéMON!\fNão me controlo!",
  ["TEXT_ROUTE45_OBJ_002_BEATEN"] = "Meus POKéMON não\ntiveram garra!",
  ["TEXT_ROUTE45_OBJ_002_SEEN"] = "Ei! Você tem\ngarra! Mas sabe?\fQuando o assunto é\ngarra pura, o cara\vsou eu!",
  ["TEXT_ROUTE45_OBJ_003_AFTER"] = "Eu não sou bom de\npensar, sabe?\fEntão eu vou de\nforça mesmo!",
  ["TEXT_ROUTE45_OBJ_003_BEATEN"] = "Uahahah! Eu sou o\ngrande perdedor!",
  ["TEXT_ROUTE45_OBJ_003_SEEN"] = "Meus POKéMON são\npura força!",
  ["TEXT_ROUTE45_OBJ_004"] = "Derrotas…\nTambém estão lá!",
  ["TEXT_ROUTE45_OBJ_004_AFTER"] = "A melhor coisa que\njá me\faconteceu foi\nconhecer POKéMON.",
  ["TEXT_ROUTE45_OBJ_004_BEATEN"] = "Derrotas…\nTambém estão lá!",
  ["TEXT_ROUTE45_OBJ_004_SEEN"] = "Por que eu subo\nmontanhas?\fPorque elas estão\nlá.\fPor que eu treino\nPOKéMON?\fPorque eles estão\nlá!",
  ["TEXT_ROUTE45_OBJ_005_AFTER"] = "Isso pede medidas\nextremas.\fVou para as\nmontanhas treinar\vna solidão.",
  ["TEXT_ROUTE45_OBJ_005_BEATEN"] = "Aaaargh!",
  ["TEXT_ROUTE45_OBJ_005_SEEN"] = "Eu estava\ntreinando sozinho\vaqui.\fVeja o fruto do\nmeu trabalho!",
  ["TEXT_ROUTE45_OBJ_006"] = "Vejo que você cria\nos seus POKéMON\vcom carinho.\fO laço que vocês\ncriam vai salvar\vvocê nos apertos.",
  ["TEXT_ROUTE45_OBJ_006_AFTER"] = "Vejo que você cria\nos seus POKéMON\vcom carinho.\fO laço que vocês\ncriam vai salvar\vvocê nos apertos.",
  ["TEXT_ROUTE45_OBJ_006_BEATEN"] = "Você ganhou meu\nrespeito.",
  ["TEXT_ROUTE45_OBJ_006_SEEN"] = "O que você acha\nsobre criar\vPOKéMON?",
  ["TEXT_ROUTE45_OBJ_007"] = "Não sou a favor\nde golpes fortes\vdemais.\fQuero ganhar, mas\ntambém não quero\vferir POKéMON.",
  ["TEXT_ROUTE45_OBJ_007_AFTER"] = "Não sou a favor\nde golpes fortes\vdemais.\fQuero ganhar, mas\ntambém não quero\vferir POKéMON.",
  ["TEXT_ROUTE45_OBJ_007_BEATEN"] = "Tá bom. Perdi.",
  ["TEXT_ROUTE45_OBJ_007_SEEN"] = "Qual é a sua\nestratégia?\fÉ tolice usar\ngolpes fortes\vsem critério.",
  ["TEXT_ROUTE46_OBJ_001"] = "Acabou. Tudo bem.\nNós HIKERS somos\vassim mesmo.",
  ["TEXT_ROUTE46_OBJ_001_AFTER"] = "Acabou. Tudo bem.\nNós HIKERS somos\vassim mesmo.",
  ["TEXT_ROUTE46_OBJ_001_BEATEN"] = "Piedade! Você me\nmostrou a força!",
  ["TEXT_ROUTE46_OBJ_001_SEEN"] = "Beleza! Vou\nmostrar o poder\vdos POKéMON da\vmontanha!",
  ["TEXT_ROUTE46_OBJ_002"] = "Dei o meu melhor\ne não bastou.\fSem desculpa, eu\nadmito que perdi.",
  ["TEXT_ROUTE46_OBJ_002_AFTER"] = "Dei o meu melhor\ne não bastou.\fSem desculpa, eu\nadmito que perdi.",
  ["TEXT_ROUTE46_OBJ_002_SEEN"] = "Eu também crio\nPOKéMON!\fQuer batalhar\ncomigo?",
  ["TEXT_ROUTE46_OBJ_003_AFTER"] = "Já fui a muitos\nGINÁSIOS, mas o\fde GOLDENROD é o\nmeu favorito.\fEle é cheio de\nflores lindas!",
  ["TEXT_ROUTE46_OBJ_003_BEATEN"] = "Ah, droga!",
  ["TEXT_ROUTE46_OBJ_003_SEEN"] = "Eu também crio\nPOKéMON!\fVamos lutar!",
  ["TEXT_ROUTE4_BG_001"] = "MT.MOON SQUARE\fÉ só subir as\nescadas.",
  ["TEXT_ROUTE4_OBJ_001"] = "Perdi? Isso é\nnovidade também…",
  ["TEXT_ROUTE4_OBJ_001_AFTER"] = "Eu talvez vá à\nPOWER PLANT. É\vperto do TUNNEL?",
  ["TEXT_ROUTE4_OBJ_001_BEATEN"] = "Perdi? Isso é\nnovidade também…",
  ["TEXT_ROUTE4_OBJ_001_SEEN"] = "Estou criando meu\nPOKéMON. Quer\vbatalhar comigo?",
  ["TEXT_ROUTE4_OBJ_002"] = "Aah, você é forte\ndemais.",
  ["TEXT_ROUTE4_OBJ_002_AFTER"] = "Ouvi que CLEFAIRY\nvêm na MT.MOON.\fMas onde será\nque eles estão?",
  ["TEXT_ROUTE4_OBJ_002_BEATEN"] = "Aah, você é forte\ndemais.",
  ["TEXT_ROUTE4_OBJ_002_SEEN"] = "Tenho a impressão\nde que vou ganhar\fVamos ver se eu\nestou certo!",
  ["TEXT_ROUTE4_OBJ_003"] = "……Vou treinar\nmais um pouco…",
  ["TEXT_ROUTE4_OBJ_003_AFTER"] = "……Vou treinar\nmais um pouco…",
  ["TEXT_ROUTE5_CLEANSE_TAG_HOUSE_OBJ_001"] = "Iiiaaah!\fEu sinto uma\nsombra sinistra\vpairando em você.\fLeve isto para\nafastar ela!",
  ["TEXT_ROUTE5_CLEANSE_TAG_HOUSE_OBJ_002"] = "Minha avó gosta de\nafastar o que ela\facredita serem\nespíritos ruins.\fDesculpe se ela\nassustou você.",
  ["TEXT_ROUTE5_OBJ_001"] = "A estrada está\nfechada até que\fo problema na\nUSINA se resolva.",
  ["TEXT_ROUTE5_SAFFRON_GATE_OBJ_001"] = "Você é de JOHTO,\nnão é?\fO que achou de\nKANTO? É bacana,\vnão concorda?",
  ["TEXT_ROUTE5_UNDERGROUND_PATH_ENTRANCE_OBJ_001"] = "Muitas cidades de\nJOHTO são antigas\fEu adoraria\nvisitar!",
  ["TEXT_ROUTE6_BG_001"] = "UNDERGROUND PATH\fCIDADE DE\vCERULEAN\vCIDADE DE\vVERMILION",
  ["TEXT_ROUTE6_OBJ_001"] = "A estrada está\nfechada até que\fo problema na\nUSINA se resolva.",
  ["TEXT_ROUTE6_OBJ_002_AFTER"] = "Olha que fofo\nmeu PHANPY é!\fNão é fofo o\nsuficiente pra\vderreter seu\vcoração?",
  ["TEXT_ROUTE6_OBJ_002_BEATEN"] = "Meu PHANPY!",
  ["TEXT_ROUTE6_OBJ_002_SEEN"] = "Meu PHANPY é o\nmais fofo do\vmundo.",
  ["TEXT_ROUTE6_OBJ_003_AFTER"] = "Olha que fofo\nmeu TEDDIURSA é!\fNão é fofo o\nsuficiente pra\vderreter seu\vcoração?",
  ["TEXT_ROUTE6_OBJ_003_BEATEN"] = "Meu TEDDIURSA!",
  ["TEXT_ROUTE6_OBJ_003_SEEN"] = "Meu TEDDIURSA é\no mais fofo do\vmundo.",
  ["TEXT_ROUTE6_SAFFRON_GATE_OBJ_001"] = "Bem-vindo à\nCIDADE DE\vSAFFRON, lar do\vMAGNET TRAIN!\f…É o que eu diria\nnormalmente, mas\fo MAGNET TRAIN\nnão está rodando.\fNão está\nrecebendo energia\fporque tem algo\nerrado\fcom a POWER\nPLANT.",
  ["TEXT_ROUTE7_BG_001"] = "Que aviso é esse?\f…Os treinadores\nmal-educados têm\fbatalhado no\nUNDERGROUND PATH.\fPor causa das\nreclamações dos\vmoradores locais,\vo UNDERGROUND PATH\vfoi lacrado\vindefinidamente.\fCELADON POLÍCIA",
  ["TEXT_ROUTE7_SAFFRON_GATE_OBJ_001"] = "Você soube do\nacidente na USINA\vDE ENERGIA?\fFica a leste,\nperto da CIDADE DE\vLAVENDER.",
  ["TEXT_ROUTE8_OBJ_001"] = "A KANTO POKéMON\nFEDERATION nunca\vvai cair!",
  ["TEXT_ROUTE8_OBJ_001_AFTER"] = "A KANTO POKéMON\nFEDERATION nunca\vvai cair!",
  ["TEXT_ROUTE8_OBJ_001_BEATEN"] = "D-desculpa!",
  ["TEXT_ROUTE8_OBJ_001_SEEN"] = "Somos o grupo de\ntreinadores da\vKANTO POKéMON\vFEDERATION.\fVamos passar por\ncima de você!",
  ["TEXT_ROUTE8_OBJ_002"] = "Arrasado por um\nmoleque de JOHTO…",
  ["TEXT_ROUTE8_OBJ_002_AFTER"] = "Arrasado por um\nmoleque de JOHTO…",
  ["TEXT_ROUTE8_OBJ_002_BEATEN"] = "M-me perdoa!",
  ["TEXT_ROUTE8_OBJ_002_SEEN"] = "A polícia fechou o\nnosso UNDERGROUND\fPATH! Isso me dá\nmuita raiva!",
  ["TEXT_ROUTE8_OBJ_003"] = "Vamos tentar não\nincomodar ninguém\vdaqui pra frente",
  ["TEXT_ROUTE8_OBJ_003_AFTER"] = "Vamos tentar não\nincomodar ninguém\vdaqui pra frente",
  ["TEXT_ROUTE8_OBJ_003_BEATEN"] = "Nossa! Desculpa!",
  ["TEXT_ROUTE8_OBJ_003_SEEN"] = "Somos a KANTO\nPOKéMON\vFEDERATION! É isso\vaí, cara!",
  ["TEXT_ROUTE8_OBJ_004"] = "A força dos ímãs\né impressionante!",
  ["TEXT_ROUTE8_OBJ_004_AFTER"] = "A força dos ímãs\né impressionante!",
  ["TEXT_ROUTE8_OBJ_004_BEATEN"] = "Eu só quero ver o\nMAGNET TRAIN…",
  ["TEXT_ROUTE8_OBJ_004_SEEN"] = "Como o MAGNET\nTRAIN funciona?",
  ["TEXT_ROUTE8_OBJ_005"] = "A POWER PLANT ao\nnorte de LAVENDER\ffornece energia\nao MAGNET TRAIN.",
  ["TEXT_ROUTE8_OBJ_005_AFTER"] = "A POWER PLANT ao\nnorte de LAVENDER\ffornece energia\nao MAGNET TRAIN.",
  ["TEXT_ROUTE8_OBJ_005_BEATEN"] = "Não desperdice\nenergia!",
  ["TEXT_ROUTE8_OBJ_005_SEEN"] = "Não vivemos sem\neletricidade.\fA POWER PLANT\nfornece energia\vpara a gente.",
  ["TEXT_ROUTE9_BG_001"] = "ROTA 9\fCIDADE DE CERULEAN\nROCK TUNNEL",
  ["TEXT_ROUTE9_OBJ_001"] = "Meus POKéMON se\nmachucaram antes\fde entrar no ROCK\nTUNNEL.\fÉ melhor levar\neles ao CENTRO\vPOKéMON já.",
  ["TEXT_ROUTE9_OBJ_001_AFTER"] = "Meus POKéMON se\nmachucaram antes\fde entrar no ROCK\nTUNNEL.\fÉ melhor levar\neles ao CENTRO\vPOKéMON já.",
  ["TEXT_ROUTE9_OBJ_001_BEATEN"] = "Opa! Perigo, cara",
  ["TEXT_ROUTE9_OBJ_001_SEEN"] = "Vim explorar o\nROCK TUNNEL.",
  ["TEXT_ROUTE9_OBJ_002"] = "A gente assa um\nmonte de doces\fe divide com todo\nmundo. É delícia!",
  ["TEXT_ROUTE9_OBJ_002_AFTER"] = "A gente assa um\nmonte de doces\fe divide com todo\nmundo. É delícia!",
  ["TEXT_ROUTE9_OBJ_002_BEATEN"] = "Aaah!",
  ["TEXT_ROUTE9_OBJ_002_SEEN"] = "Você já foi a um\npiquenique?\fÉ muito\ndivertido!",
  ["TEXT_ROUTE9_OBJ_003"] = "Desculpe. Você não\njogou lixo. Foi\vengano meu.",
  ["TEXT_ROUTE9_OBJ_003_AFTER"] = "Desculpe. Você não\njogou lixo. Foi\vengano meu.",
  ["TEXT_ROUTE9_OBJ_003_BEATEN"] = "Eu só estava\navisando…",
  ["TEXT_ROUTE9_OBJ_003_SEEN"] = "Ei, você!\nNão jogue lixo!",
  ["TEXT_ROUTE9_OBJ_004"] = "Economizar energia\né importante, mas\fo meio ambiente é\nainda mais.",
  ["TEXT_ROUTE9_OBJ_004_AFTER"] = "Economizar energia\né importante, mas\fo meio ambiente é\nainda mais.",
  ["TEXT_ROUTE9_OBJ_004_SEEN"] = "As pessoas não\ndeviam deixar\vlixo por aí.",
  ["TEXT_ROUTE9_OBJ_005"] = "Batalha é uma\nquestão de foco.",
  ["TEXT_ROUTE9_OBJ_005_AFTER"] = "Batalha é uma\nquestão de foco.",
  ["TEXT_ROUTE9_OBJ_005_BEATEN"] = "Eu estava ocupada\ncantando…",
  ["TEXT_ROUTE9_OBJ_005_SEEN"] = "Ela vem descendo a\nMT.SILVER quando\vela vier…\fA MT.SILVER fica\nem JOHTO, né?",
  ["TEXT_ROUTE9_OBJ_006"] = "A POWER PLANT fica\ndo outro lado de\vum riacho.",
  ["TEXT_ROUTE9_OBJ_006_AFTER"] = "A POWER PLANT fica\ndo outro lado de\vum riacho.",
  ["TEXT_ROUTE9_OBJ_006_BEATEN"] = "Ah, droga!\nPerdi essa…",
  ["TEXT_ROUTE9_OBJ_006_SEEN"] = "Vou te contar um\nsegredo.\fMas primeiro a\ngente luta!",
  ["TEXT_RUINS_OF_ALPH_HO_OH_CHAMBER_BG_001"] = "É uma réplica\nde um POKéMON\vantigo.",
  ["TEXT_RUINS_OF_ALPH_HO_OH_CHAMBER_BG_002"] = "É uma réplica\nde um POKéMON\vantigo.",
  ["TEXT_RUINS_OF_ALPH_INNER_CHAMBER_OBJ_001"] = "Esta sala é\ngrande, mas não\vhá nada aqui.",
  ["TEXT_RUINS_OF_ALPH_INNER_CHAMBER_OBJ_002"] = "Este lugar tem\numa qualidade\vmística.\fParece até\netéreo.",
  ["TEXT_RUINS_OF_ALPH_KABUTO_CHAMBER_OBJ_001"] = "Bem-vindo a esta\ncâmara.\fHá painéis\ndeslizantes que\fretratam um\nPOKéMON antigo.\fDeslize os\npainéis para\vformar a figura.\fÀ direita, a\ndescrição do\vPOKéMON.",
  ["TEXT_RUINS_OF_ALPH_OUTSIDE_OBJ_001"] = "Gosto de pensar\naqui.",
  ["TEXT_RUINS_OF_ALPH_OUTSIDE_OBJ_001_AFTER"] = "Gosto de pensar\naqui.",
  ["TEXT_RUINS_OF_ALPH_OUTSIDE_OBJ_001_SEEN"] = "Hmmm… Este é um\nlugar estranho.",
  ["TEXT_RUINS_OF_ALPH_OUTSIDE_OBJ_002"] = "Hm? Isso é uma\nPOKéDEX, não é?\vPosso ver?\fHá muitos tipos de\nPOKéMON.\fHm? O que é isto?\fQue POKéMON é\neste?\fParece a escrita\nestranha nas\fparedes das\nRUINS.\fSe esses desenhos\nsão mesmo POKéMON,\vdeve haver muitos\vmais.\fSei! Vou atualizar\nsua POKéDEX.\vSiga-me.",
  ["TEXT_RUINS_OF_ALPH_RESEARCH_CENTER_BG_002"] = "RUÍNAS DE ALPH\fExploração\nAno 10",
  ["TEXT_RUINS_OF_ALPH_RESEARCH_CENTER_BG_003"] = "Parece que ainda\nnão funciona.",
  ["TEXT_RUINS_OF_ALPH_RESEARCH_CENTER_OBJ_001"] = "Bom dia!\nBem-vindo ao nosso\vCENTRO POKéMON.",
  ["TEXT_RUINS_OF_ALPH_RESEARCH_CENTER_OBJ_002"] = "Há padrões\ndesenhados nas\fparedes das\nRUÍNAS.\fDevem ser a chave\npara desvendar\vo mistério\vdas RUÍNAS.",
  ["TEXT_RUINS_OF_ALPH_RESEARCH_CENTER_OBJ_003"] = "Os UNOWN que\nvocê pegar serão\vtodos registrados\fVerifique quantos\ntipos existem.",
  ["TEXT_S5D_4F2F"] = "Hã? Meus próprios\nolhos erraram?",
  ["TEXT_S61_4DFA"] = "Ufa…\fQuantas vezes eu\njá fui e voltei\fentre KANTO\ne JOHTO?",
  ["TEXT_SAFARI_ZONE_WARDENS_HOME_BG_003"] = "É a foto de um\nvelho sorridente\fcercado de\nPOKéMON.",
  ["TEXT_SAFARI_ZONE_WARDENS_HOME_BG_004"] = "É a foto de uma\nplanície enorme\fcom POKéMON raros\nbrincando nela.",
  ["TEXT_SAFARI_ZONE_WARDENS_HOME_OBJ_001"] = "Meu avô é o\nWARDEN da\vSAFARI ZONE.\fOu era…\fEle resolveu tirar\nférias e\ffoi para fora\ndo país sozinho.\fLargou a SAFARI\nZONE assim,\vdo nada.",
  ["TEXT_SAFFRON_CITY_OBJ_001"] = "Uma menininha\nexpert em imitar\fas pessoas mora\naqui.\fEla imita até quem\nestá\fconversando com\nela. É confuso.",
  ["TEXT_SAFFRON_CITY_OBJ_002"] = "Você veio de\nJOHTO?\fVocê pode voltar\npra casa de MAGNET\vTRAIN.",
  ["TEXT_SAFFRON_CITY_OBJ_003"] = "Fui ao GINÁSIO, a\nfim de batalhar\vcom treinadores…\fNo fim, acabei\nentrando\fno GINÁSIO vago ao\nlado.\fNossa, que\nsemgraça!",
  ["TEXT_SAFFRON_CITY_OBJ_004"] = "Esta é a SILPH\nCO., famosa por\vprodutos POKéMON.\fNo passado, a\nTEAM ROCKET\fqueria a empresa\npor causa disso.",
  ["TEXT_SAFFRON_CITY_OBJ_005"] = "Nhoc… Nhoc…\fOuvi dizer que há\num grande problema\vna USINA.\fNhoc… Nhoc…",
  ["TEXT_SAFFRON_CITY_OBJ_006"] = "Entrar num beco\npela primeira\fvez me deixa\nmeio ansioso.",
  ["TEXT_SAFFRON_CITY_OBJ_007"] = "Existe um lugar\nchamado TRAINER\fHOUSE em VIRIDIAN\nonde treinadores\fde todo canto\nse reúnem.",
  ["TEXT_SAFFRON_CITY_OBJ_008"] = "Nossa cidade foi\ncitada num\vprograma de rádio\fÉ bom ouvir\nelogios pra sua\fcidade, mas é um\npouco semgraça\vtambém.",
  ["TEXT_SAFFRON_GYM_OBJ_001"] = "SABRINA: Eu sabia\nque você viria…\fFaz três anos eu\ntive uma visão da\vsua chegada.\fVocê quer a minha\nINSÍGNIA.\fEu não gosto de\nbatalhar, mas é\fmeu dever de LÍDER\ndar INSÍGNIAS\fa quem provar\nque é digno\vou digna.\fJá que você quer,\neu vou mostrar meu\vpoder psíquico!",
  ["TEXT_SAFFRON_GYM_OBJ_002"] = "De onde vem a\nsua força?",
  ["TEXT_SAFFRON_GYM_OBJ_002_AFTER"] = "De onde vem a\nsua força?",
  ["TEXT_SAFFRON_GYM_OBJ_002_BEATEN"] = "Forte…\nForte demais…",
  ["TEXT_SAFFRON_GYM_OBJ_002_SEEN"] = "A força de todos\nque você venceu\vvem para mim!",
  ["TEXT_SAFFRON_GYM_OBJ_003"] = "Você fortaleceu a\nalma, não só as\vhabilidades.",
  ["TEXT_SAFFRON_GYM_OBJ_003_AFTER"] = "Você fortaleceu a\nalma, não só as\vhabilidades.",
  ["TEXT_SAFFRON_GYM_OBJ_003_BEATEN"] = "Sua alma tem mais\nforça que a minha",
  ["TEXT_SAFFRON_GYM_OBJ_003_SEEN"] = "O poder psíquico\né o poder da sua\valma.",
  ["TEXT_SAFFRON_GYM_OBJ_004"] = "Droga! Esqueci\nque eu previ que\vperderia para ti",
  ["TEXT_SAFFRON_GYM_OBJ_004_AFTER"] = "Droga! Esqueci\nque eu previ que\vperderia para ti",
  ["TEXT_SAFFRON_GYM_OBJ_004_BEATEN"] = "Mesmo te lendo,\neu perdi…",
  ["TEXT_SAFFRON_GYM_OBJ_004_SEEN"] = "Fufufufu…\nVejo com clareza.\fEu enxergo\nna sua alma!",
  ["TEXT_SAFFRON_GYM_OBJ_005"] = "O KARATE KING,\nmestre do\fFIGHTING DOJO, foi\narrasado agora\vpela SABRINA.",
  ["TEXT_SAFFRON_GYM_OBJ_005_AFTER"] = "O KARATE KING,\nmestre do\fFIGHTING DOJO, foi\narrasado agora\vpela SABRINA.",
  ["TEXT_SAFFRON_GYM_OBJ_005_BEATEN"] = "Não tive chance…",
  ["TEXT_SAFFRON_GYM_OBJ_005_SEEN"] = "O FIGHTING DOJO\ndo lado já foi\vo GINÁSIO daqui.",
  ["TEXT_SAFFRON_GYM_OBJ_006"] = "Ei, futuro\nCAMPEÃO!\fUm treinador tão\nbom quanto você\fnão precisa que\ndigam como lidar\fcom POKéMON do\ntipo psíquico?\fEspero grandes\ncoisas de você!\fBoa sorte!",
  ["TEXT_SAFFRON_MAGNET_TRAIN_STATION_OBJ_001"] = "Desculpe, mas o\nMAGNET TRAIN não\vestá rodando.",
  ["TEXT_SAFFRON_MAGNET_TRAIN_STATION_OBJ_002"] = "O MAGNET TRAIN\né um trem super\fmoderno que usa\neletricidade e\fímãs para chegar\na uma velocidade\vincrível.\fSó que, se não\nhouver energia\velétrica…",
  ["TEXT_SAFFRON_MAGNET_TRAIN_STATION_OBJ_003"] = "Antes de fazerem\na MAGNET TRAIN\fSTATION, tinha uma\ncasa ali.\fUma menina\nchamada COPYCAT\vmorava lá.",
  ["TEXT_SAFFRON_MAGNET_TRAIN_STATION_OBJ_004"] = "Oi. Você tem um\nPASS de trem? Eu\ftenho um. Todo\nmundo em SAFFRON\fque anda no MAGNET\nTRAIN tem um.",
  ["TEXT_SAFFRON_MART_OBJ_001"] = "Tem uma RADIO\nTOWER bem grande\vem LAVENDER.",
  ["TEXT_SAFFRON_MART_OBJ_002"] = "Tem uma RADIO\nTOWER bem grande\vem LAVENDER.",
  ["TEXT_SAFFRON_POKECENTER1_F_OBJ_001"] = "Bom dia!\nBem-vindo ao nosso\vCENTRO POKéMON.",
  ["TEXT_SAFFRON_POKECENTER1_F_OBJ_002"] = "Tem uma POWER\nPLANT enorme ao\vnorte de LAVENDER",
  ["TEXT_SAFFRON_POKECENTER1_F_OBJ_003"] = "Por acaso eu\npassei pelo ROCK\fTUNNEL. Tinha um\nrebuliço lá na\vPOWER PLANT.",
  ["TEXT_SEAFOAM_GYM_OBJ_001"] = "BLAINE: Uaaah!\fMeu GINÁSIO em\nCINNABAR queimou.\fEu e meus POKéMON\nde fogo ficamos\fsem casa por\ncausa do vulcão.\fBuaaah!\fMas voltei à ativa\ncomo LÍDER de\fGINÁSIO aqui na\ncaverna.\fSe você me vencer\neu te dou\vuma BADGE.\fHa! Melhor levar\nBURN HEAL!",
  ["TEXT_SEAFOAM_GYM_OBJ_002"] = "E aí!\f…Hein? Já acabou?\ntão rápido?\fDesculpa, cara!\fO GINÁSIO de\nCINNABAR sumiu,\fentão não sabia\nonde te achar.\fMas você está\nbem forte, mesmo\fsem meu conselho.\nEu já sabia!",
  ["TEXT_SILPH_CO1_F_OBJ_001"] = "Bem-vindo. Este é\no PRÉDIO da SEDE\vda SILPH CO.",
  ["TEXT_SILPH_CO1_F_OBJ_002"] = "Só funcionário\npode subir\vas escadas.\fMas já que você\nveio de longe,\fleve esta\nlembrancinha.",
  ["TEXT_SILVER_CAVE_OUTSIDE_BG_001"] = "Cure Seus POKéMON!\nCENTRO POKéMON",
  ["TEXT_SILVER_CAVE_OUTSIDE_BG_002"] = "MT.SILVER",
  ["TEXT_SILVER_CAVE_POKECENTER1_F_OBJ_001"] = "Bom dia!\nBem-vindo ao nosso\vCENTRO POKéMON.",
  ["TEXT_SLOWPOKE_WELL_B1_F_OBJ_001"] = "Sim, a gente vem\ncortando o rabo\fdos SLOWPOKE e\nvendendo elas.\fTudo o que fazemos\né por lucro.\fIsso mesmo!\nSomos a TEAM\fROCKET, e fazemos\ntudo por grana!",
  ["TEXT_SLOWPOKE_WELL_B1_F_OBJ_001_AFTER"] = "Sim, a gente vem\ncortando o rabo\fdos SLOWPOKE e\nvendendo elas.\fTudo o que fazemos\né por lucro.\fIsso mesmo!\nSomos a TEAM\fROCKET, e fazemos\ntudo por grana!",
  ["TEXT_SLOWPOKE_WELL_B1_F_OBJ_001_BEATEN"] = "Arrgh! Hoje NÃO é\no meu dia!",
  ["TEXT_SLOWPOKE_WELL_B1_F_OBJ_001_SEEN"] = "Droga! Eu estava\nde guarda lá em\fcima quando um\nvelho gritou.\fMe assustou tanto\nque eu caí aqui\vembaixo.\fAcho que vou\ndescontar a raiva\vem você!",
  ["TEXT_SLOWPOKE_WELL_B1_F_OBJ_002"] = "É, a TEAM ROCKET\nfoi desfeita\vhá três anos.\fMas continuamos\ncom as atividades\vescondidos.\fAgora divirta-se\nvendo a gente\vaprontar!",
  ["TEXT_SLOWPOKE_WELL_B1_F_OBJ_002_AFTER"] = "É, a TEAM ROCKET\nfoi desfeita\vhá três anos.\fMas continuamos\ncom as atividades\vescondidos.\fAgora divirta-se\nvendo a gente\vaprontar!",
  ["TEXT_SLOWPOKE_WELL_B1_F_OBJ_002_BEATEN"] = "Você foi bem hoje\npirralho, mas\vespere a próxima!",
  ["TEXT_SLOWPOKE_WELL_B1_F_OBJ_002_SEEN"] = "O que você quer?\fSe atrapalhar o\nnosso trabalho,\vnão terá piedade!",
  ["TEXT_SLOWPOKE_WELL_B1_F_OBJ_003"] = "A gente precisa da\ngrana, mas vender\vSLOWPOKETAILS?\fÉ duro ser um\nROCKET GRUNT!",
  ["TEXT_SLOWPOKE_WELL_B1_F_OBJ_003_AFTER"] = "A gente precisa da\ngrana, mas vender\vSLOWPOKETAILS?\fÉ duro ser um\nROCKET GRUNT!",
  ["TEXT_SLOWPOKE_WELL_B1_F_OBJ_003_BEATEN"] = "Simplesmente…\nForte demais…",
  ["TEXT_SLOWPOKE_WELL_B1_F_OBJ_003_SEEN"] = "Parar de tirar\nSLOWPOKETAILS?\fSe obedecêssemos,\na fama da TEAM\vROCKET acabava!",
  ["TEXT_SLOWPOKE_WELL_B1_F_OBJ_004"] = "SLOWPOKETAILS\ncrescem rápido!\fQual o problema\nde vender elas?",
  ["TEXT_SLOWPOKE_WELL_B1_F_OBJ_004_AFTER"] = "SLOWPOKETAILS\ncrescem rápido!\fQual o problema\nde vender elas?",
  ["TEXT_SLOWPOKE_WELL_B1_F_OBJ_004_BEATEN"] = "Seu pirralho!",
  ["TEXT_SLOWPOKE_WELL_B1_F_OBJ_004_SEEN"] = "Parar as TAILS?\fÉ, tente vencer\ntodos nós então!",
  ["TEXT_SLOWPOKE_WELL_B1_F_OBJ_005"] = "Um SLOWPOKE com a\nTAIL cortada…\fHã? Tem uma MAIL.\nLer?",
  ["TEXT_SLOWPOKE_WELL_B1_F_OBJ_006"] = "Um SLOWPOKE com a\nTAIL cortada…",
  ["TEXT_SLOWPOKE_WELL_B1_F_OBJ_007"] = "KURT: Olá aí,\n{PLAYER}!\fOs guardas lá em\ncima fugiram\vquando eu gritei.\fMas aí eu caí\npoço abaixo\vaqui.\fBati as costas\ncom força e agora\vnão consigo andar\fDroga! Se eu\nestivesse bem, o\fPOKéMON teria dado\no troco…\fAh, não tem\njeito.\f{PLAYER}, mostre a\neles a sua coragem\vno meu lugar!",
  ["TEXT_SLOWPOKE_WELL_B2_F_OBJ_001"] = "Espero o momento\nde evolução do\vSLOWPOKE.\fPelas minhas\nobservações,\vdescobri algo.\fUm SLOWPOKE com\numa KING'S ROCK\fé mordido por\num SHELLDER.\fAqui, vou te\ndar uma KING'S\vROCK.",
  ["TEXT_SOUL_HOUSE_OBJ_001"] = "MR.FUJI: Olá.\fHum… Parece que\nvocê cria os seus\fPOKéMON com amor\ne bondade.\fQuem ama POKéMON\nvem aqui prestar\frespeito aos que\njá se foram.\fDeixe as suas\ncondolências\fpara as almas dos\nPOKéMON que foram\fTenho certeza que\nisso os alegra.",
  ["TEXT_SOUL_HOUSE_OBJ_002"] = "Tem outros túmulos\nde POKéMON aqui,\veu acho.\fTem muitas salas\nem que só o\vMR.FUJI entra.",
  ["TEXT_SOUL_HOUSE_OBJ_003"] = "Eu vim com a minha\nmãe ver túmulos\vde POKéMON…",
  ["TEXT_SPROUT_TOWER1_F_OBJ_001"] = "Só quem chega ao\ntopo é que ganha\vum HM.",
  ["TEXT_SPROUT_TOWER1_F_OBJ_002"] = "A SPROUT TOWER foi\nerguida há muito\fcomo lugar de\ntreino POKéMON.",
  ["TEXT_SPROUT_TOWER1_F_OBJ_003"] = "Um BELLSPROUT de\nmais de 30 metros\fDizem que ele\nvirou o pilar\vcentral daqui.",
  ["TEXT_SPROUT_TOWER1_F_OBJ_004"] = "Viu o pilar\ntremendo?\fEstão treinando\nlá em cima.",
  ["TEXT_SPROUT_TOWER1_F_OBJ_005"] = "Todos os seres\nvivos coexistem\vem cooperação.\fDevemos sempre ser\ngratos por isso.",
  ["TEXT_SPROUT_TOWER1_F_OBJ_005_AFTER"] = "Todos os seres\nvivos coexistem\vem cooperação.\fDevemos sempre ser\ngratos por isso.",
  ["TEXT_SPROUT_TOWER1_F_OBJ_005_BEATEN"] = "O-obrigado!",
  ["TEXT_SPROUT_TOWER1_F_OBJ_005_SEEN"] = "Nós vigiamos\nesta torre.\fAqui, expressamos\nnossa gratidão\vpra honrar todos\vos POKéMON.",
  ["TEXT_SPROUT_TOWER2_F_OBJ_001"] = "A coluna flexível\nprotege a TOWER\fmesmo contra\nterremotos.",
  ["TEXT_SPROUT_TOWER2_F_OBJ_001_AFTER"] = "A coluna flexível\nprotege a TOWER\fmesmo contra\nterremotos.",
  ["TEXT_SPROUT_TOWER2_F_OBJ_001_BEATEN"] = "Lutei duro, mas\nsou fraco demais.",
  ["TEXT_SPROUT_TOWER2_F_OBJ_001_SEEN"] = "Não importa como\nlutemos, a TOWER\vvai continuar\vforte.",
  ["TEXT_SPROUT_TOWER2_F_OBJ_002"] = "Tentei copiar os\nmovimentos gentis\fdo BELLSPROUT\npara a batalha…\fMas não treinei\nbem o bastante.",
  ["TEXT_SPROUT_TOWER2_F_OBJ_002_AFTER"] = "Tentei copiar os\nmovimentos gentis\fdo BELLSPROUT\npara a batalha…\fMas não treinei\nbem o bastante.",
  ["TEXT_SPROUT_TOWER2_F_OBJ_002_BEATEN"] = "Ah, sou fraco!",
  ["TEXT_SPROUT_TOWER2_F_OBJ_002_SEEN"] = "…Balance como\nfolhas ao vento…",
  ["TEXT_SPROUT_TOWER3_F_OBJ_001"] = "Quando os POKéMON\nficam fortes, o\vtreinador também.\fEspera. Quando o\ntreinador fica\fforte, os POKéMON\ntambém.",
  ["TEXT_SPROUT_TOWER3_F_OBJ_001_AFTER"] = "Quando os POKéMON\nficam fortes, o\vtreinador também.\fEspera. Quando o\ntreinador fica\fforte, os POKéMON\ntambém.",
  ["TEXT_SPROUT_TOWER3_F_OBJ_001_BEATEN"] = "Derrotado por\numa mera criança!",
  ["TEXT_SPROUT_TOWER3_F_OBJ_001_SEEN"] = "Treino para achar\niluminação nos\vPOKéMON!",
  ["TEXT_SPROUT_TOWER3_F_OBJ_002"] = "Não é longe até\no ELDER.",
  ["TEXT_SPROUT_TOWER3_F_OBJ_002_AFTER"] = "Não é longe até\no ELDER.",
  ["TEXT_SPROUT_TOWER3_F_OBJ_002_BEATEN"] = "Sim, a sua\nconfiança é real!",
  ["TEXT_SPROUT_TOWER3_F_OBJ_002_SEEN"] = "Deixe-me ver o\nquanto você confia\vnos seus POKéMON.",
  ["TEXT_SPROUT_TOWER3_F_OBJ_003"] = "Que bom você\nter vindo!\fA SPROUT TOWER,\nlugar de treino.\fPessoas e POKéMON\ntestam seus laços\fpara construir\num futuro juntos.\fSou o teste\nfinal.\fDeixe-me ver\nos laços entre\fvocê e seus\nPOKéMON!",
  ["TEXT_SPROUT_TOWER3_F_OBJ_004"] = "Que haja luz\nna sua jornada.",
  ["TEXT_SPROUT_TOWER3_F_OBJ_004_AFTER"] = "Que haja luz\nna sua jornada.",
  ["TEXT_SPROUT_TOWER3_F_OBJ_004_BEATEN"] = "É a minha cabeça\nque é brilhante!",
  ["TEXT_SPROUT_TOWER3_F_OBJ_004_SEEN"] = "O HM do ELDER\nilumina até a\vescuridão total.",
  ["TEXT_TEAM_ROCKET_BASE_B1_F_BG_001"] = "Um botão secreto!\nMelhor apertar.",
  ["TEXT_TEAM_ROCKET_BASE_B1_F_BG_002"] = "É uma estátua de\nPERSIAN…\fOs olhos dela são\nmuito brilhantes.",
  ["TEXT_TEAM_ROCKET_BASE_B1_F_BG_003"] = "É uma estátua de\nPERSIAN…\fOs olhos dela são\nmuito brilhantes.",
  ["TEXT_TEAM_ROCKET_BASE_B1_F_BG_004"] = "É uma estátua de\nPERSIAN…\fOs olhos dela são\nmuito brilhantes.",
  ["TEXT_TEAM_ROCKET_BASE_B1_F_BG_005"] = "É uma estátua de\nPERSIAN…\fOs olhos dela são\nmuito brilhantes.",
  ["TEXT_TEAM_ROCKET_BASE_B1_F_BG_006"] = "É uma estátua de\nPERSIAN…\fOs olhos dela são\nmuito brilhantes.",
  ["TEXT_TEAM_ROCKET_BASE_B1_F_BG_007"] = "JURAMENTO ROCKET\fRoubar POKéMON\npor lucro!\fExplorar POKéMON\npor lucro!\fPOKéMON existem\npara a glória da\vTEAM ROCKET!",
  ["TEXT_TEAM_ROCKET_BASE_B1_F_BG_008"] = "JURAMENTO ROCKET\fRoubar POKéMON\npor lucro!\fExplorar POKéMON\npor lucro!\fPOKéMON existem\npara a glória da\vTEAM ROCKET!",
  ["TEXT_TEAM_ROCKET_BASE_B1_F_OBJ_002"] = "Eu nem sei onde\nas armadilhas\vestão.\fVocê vai ter que\njuntar coragem\ve caminhar.",
  ["TEXT_TEAM_ROCKET_BASE_B1_F_OBJ_002_AFTER"] = "Eu nem sei onde\nas armadilhas\vestão.\fVocê vai ter que\njuntar coragem\ve caminhar.",
  ["TEXT_TEAM_ROCKET_BASE_B1_F_OBJ_002_BEATEN"] = "Bum!",
  ["TEXT_TEAM_ROCKET_BASE_B1_F_OBJ_002_SEEN"] = "Heheh. Está se\nachando sortudo?\fVai lá, dê mais\num passo.\fTemos armadilhas\npostas no chão!",
  ["TEXT_TEAM_ROCKET_BASE_B1_F_OBJ_003"] = "Está bem. Vou\ncontar um segredo\vdo esconderijo.\fAquilo no chão ali\nna frente é um\vpainel de salto\fSe você pisar,\nvai ser mandado\fde volta para a\nentrada.",
  ["TEXT_TEAM_ROCKET_BASE_B1_F_OBJ_003_AFTER"] = "Está bem. Vou\ncontar um segredo\vdo esconderijo.\fAquilo no chão ali\nna frente é um\vpainel de salto\fSe você pisar,\nvai ser mandado\fde volta para a\nentrada.",
  ["TEXT_TEAM_ROCKET_BASE_B1_F_OBJ_003_BEATEN"] = "Entendi…",
  ["TEXT_TEAM_ROCKET_BASE_B1_F_OBJ_003_SEEN"] = "Isto já foi um\nesconderijo ninja\fTem armadilhas\npara confundir\vinvasores.",
  ["TEXT_TEAM_ROCKET_BASE_B2_F_BG_001"] = "A porta fechou…\fPrecisa de senha\npara abrir.",
  ["TEXT_TEAM_ROCKET_BASE_B2_F_BG_002"] = "A porta fechou…\fPrecisa de senha\npara abrir.",
  ["TEXT_TEAM_ROCKET_BASE_B2_F_BG_003"] = "É o transmissor\nde rádio que está\fmandando o sinal\nsinistro.\fEstá funcionando\na todo vapor.",
