  ["TEXT_TEAM_ROCKET_BASE_B2_F_BG_014"] = "É o transmissor\nde rádio que está\fmandando o sinal\nsinistro.\fEstá funcionando\na todo vapor.",
  ["TEXT_TEAM_ROCKET_BASE_B2_F_BG_015"] = "É o transmissor\nde rádio que está\fmandando o sinal\nsinistro.\fEstá funcionando\na todo vapor.",
  ["TEXT_TEAM_ROCKET_BASE_B2_F_BG_016"] = "É o transmissor\nde rádio que está\fmandando o sinal\nsinistro.\fEstá funcionando\na todo vapor.",
  ["TEXT_TEAM_ROCKET_BASE_B2_F_BG_017"] = "É o transmissor\nde rádio que está\fmandando o sinal\nsinistro.\fEstá funcionando\na todo vapor.",
