  ["TEXT_TEAM_ROCKET_BASE_B2_F_BG_019"] = "É o transmissor\nde rádio que está\fmandando o sinal\nsinistro.\fEstá funcionando\na todo vapor.",
  ["TEXT_TEAM_ROCKET_BASE_B2_F_BG_020"] = "É o transmissor\nde rádio que está\fmandando o sinal\nsinistro.\fEstá funcionando\na todo vapor.",
  ["TEXT_TEAM_ROCKET_BASE_B2_F_BG_021"] = "É o transmissor\nde rádio que está\fmandando o sinal\nsinistro.\fEstá funcionando\na todo vapor.",
  ["TEXT_TEAM_ROCKET_BASE_B2_F_BG_022"] = "É o transmissor\nde rádio que está\fmandando o sinal\nsinistro.\fEstá funcionando\na todo vapor.",
  ["TEXT_TEAM_ROCKET_BASE_B2_F_OBJ_011"] = "Heh, eu sou só um\nGRUNT.\fEu não sei a\nsenha. Azar\vo seu.",
  ["TEXT_TEAM_ROCKET_BASE_B2_F_OBJ_011_AFTER"] = "Heh, eu sou só um\nGRUNT.\fEu não sei a\nsenha. Azar\vo seu.",
  ["TEXT_TEAM_ROCKET_BASE_B2_F_OBJ_011_BEATEN"] = "Quê? Eu perdi?",
  ["TEXT_TEAM_ROCKET_BASE_B2_F_OBJ_011_SEEN"] = "A porta não\nabre?\fOra, claro.\nPrecisa de uma\fsenha que só a\nTEAM ROCKET sabe.",
  ["TEXT_TEAM_ROCKET_BASE_B2_F_OBJ_012"] = "Eu apanhei de uma\ncriança na última\vmissão também.\fQuando a gente\nestava roubando\fPOKéMON, um garoto\nruivo de olhar\fmau me\narrasou…",
  ["TEXT_TEAM_ROCKET_BASE_B2_F_OBJ_012_AFTER"] = "Eu apanhei de uma\ncriança na última\vmissão também.\fQuando a gente\nestava roubando\fPOKéMON, um garoto\nruivo de olhar\fmau me\narrasou…",
  ["TEXT_TEAM_ROCKET_BASE_B2_F_OBJ_012_BEATEN"] = "Eu sabia que\nperderia…",
  ["TEXT_TEAM_ROCKET_BASE_B2_F_OBJ_012_SEEN"] = "Ah, uma criança?\nNão gosto disso,\fmas tenho que\neliminar você.",
  ["TEXT_TEAM_ROCKET_BASE_B2_F_OBJ_013"] = "Heh, só o chefe\nsabe a senha\vdaquela porta.\fOnde está o chefe?\nSei lá. Vá\vprocurar você.",
  ["TEXT_TEAM_ROCKET_BASE_B2_F_OBJ_013_AFTER"] = "Heh, só o chefe\nsabe a senha\vdaquela porta.\fOnde está o chefe?\nSei lá. Vá\vprocurar você.",
  ["TEXT_TEAM_ROCKET_BASE_B2_F_OBJ_013_SEEN"] = "Seu pestinha\ninsuportável!",
  ["TEXT_TEAM_ROCKET_BASE_B3_F_BG_001"] = "A porta fechou…\fPrecisa de duas\nsenhas para abrir",
  ["TEXT_TEAM_ROCKET_BASE_B3_F_BG_002"] = "A porta fechou…\fPrecisa de duas\nsenhas para abrir",
  ["TEXT_TEAM_ROCKET_BASE_B3_F_BG_003"] = "JURAMENTO ROCKET\fRoubar POKéMON\npor lucro!\fExplorar POKéMON\npor lucro!\fPOKéMON existem\npara a glória da\vTEAM ROCKET!",
  ["TEXT_TEAM_ROCKET_BASE_B3_F_BG_004"] = "JURAMENTO ROCKET\fRoubar POKéMON\npor lucro!\fExplorar POKéMON\npor lucro!\fPOKéMON existem\npara a glória da\vTEAM ROCKET!",
  ["TEXT_TEAM_ROCKET_BASE_B3_F_BG_005"] = "JURAMENTO ROCKET\fRoubar POKéMON\npor lucro!\fExplorar POKéMON\npor lucro!\fPOKéMON existem\npara a glória da\vTEAM ROCKET!",
  ["TEXT_TEAM_ROCKET_BASE_B3_F_BG_006"] = "JURAMENTO ROCKET\fRoubar POKéMON\npor lucro!\fExplorar POKéMON\npor lucro!\fPOKéMON existem\npara a glória da\vTEAM ROCKET!",
  ["TEXT_TEAM_ROCKET_BASE_B3_F_BG_007"] = "JURAMENTO ROCKET\fRoubar POKéMON\npor lucro!\fExplorar POKéMON\npor lucro!\fPOKéMON existem\npara a glória da\vTEAM ROCKET!",
  ["TEXT_TEAM_ROCKET_BASE_B3_F_BG_008"] = "JURAMENTO ROCKET\fRoubar POKéMON\npor lucro!\fExplorar POKéMON\npor lucro!\fPOKéMON existem\npara a glória da\vTEAM ROCKET!",
  ["TEXT_TEAM_ROCKET_BASE_B3_F_BG_009"] = "JURAMENTO ROCKET\fRoubar POKéMON\npor lucro!\fExplorar POKéMON\npor lucro!\fPOKéMON existem\npara a glória da\vTEAM ROCKET!",
  ["TEXT_TEAM_ROCKET_BASE_B3_F_BG_010"] = "JURAMENTO ROCKET\fRoubar POKéMON\npor lucro!\fExplorar POKéMON\npor lucro!\fPOKéMON existem\npara a glória da\vTEAM ROCKET!",
  ["TEXT_TEAM_ROCKET_BASE_B3_F_OBJ_001"] = "LANCE: Precisa de\nduas senhas para\fentrar na sala\ndo chefe.\fSó uns poucos\nROCKETS conhecem\vessas senhas.\fAquele ROCKET ali\nteve a bondade\vde me contar.\f{PLAYER}, vamos\nbuscar as senhas.",
  ["TEXT_TEAM_ROCKET_BASE_B3_F_OBJ_003"] = "MURKROW: A senha\né…\fSALVE GIOVANNI.",
  ["TEXT_TEAM_ROCKET_BASE_B3_F_OBJ_004"] = "A senha da sala\ndo chefe é\fSLOWPOKETAIL.\fMas não adianta\nse você não tiver\vas duas senhas.",
  ["TEXT_TEAM_ROCKET_BASE_B3_F_OBJ_004_AFTER"] = "A senha da sala\ndo chefe é\fSLOWPOKETAIL.\fMas não adianta\nse você não tiver\vas duas senhas.",
  ["TEXT_TEAM_ROCKET_BASE_B3_F_OBJ_004_BEATEN"] = "Está bem. Pare.\nEu conto.",
  ["TEXT_TEAM_ROCKET_BASE_B3_F_OBJ_004_SEEN"] = "Se eu sei a\nsenha?\fTalvez.\fMas nenhum fracote\nvai conseguir!",
  ["TEXT_TEAM_ROCKET_BASE_B3_F_OBJ_005"] = "O que é isto?\fAh, é um\nincensário!",
  ["TEXT_TEAM_ROCKET_BASE_B3_F_OBJ_005_AFTER"] = "Ruarrr-rarr-rarr!\fA senha da sala\ndo chefe…\fAhn…, eu acho que\né RATICATE TAIL.",
  ["TEXT_TEAM_ROCKET_BASE_B3_F_OBJ_005_BEATEN"] = "Ruarrr-rarr-rarr!\nVocê é bom!",
  ["TEXT_TEAM_ROCKET_BASE_B3_F_OBJ_005_SEEN"] = "Ruarrr-rarr-rarr!\fVocê está me\ndesafiando?\fHah! Você é louco,\nmas tem coragem!\fDisso eu gosto!\fSe me vencer, eu\nconto para você\fuma senha da sala\ndo chefe!",
  ["TEXT_TEAM_ROCKET_BASE_B3_F_OBJ_006"] = "Um sinal de rádio\nque enlouquece os\vPOKéMON…\fMeu experimento é\num sucesso total.\fMinha promoção\nestá garantida.\fEsta derrota não\nsignifica nada.",
  ["TEXT_TEAM_ROCKET_BASE_B3_F_OBJ_006_AFTER"] = "Um sinal de rádio\nque enlouquece os\vPOKéMON…\fMeu experimento é\num sucesso total.\fMinha promoção\nestá garantida.\fEsta derrota não\nsignifica nada.",
  ["TEXT_TEAM_ROCKET_BASE_B3_F_OBJ_006_BEATEN"] = "Um mero erro de\ntática me custou…",
  ["TEXT_TEAM_ROCKET_BASE_B3_F_OBJ_006_SEEN"] = "Eu trabalhava na\nSILPH, mas agora\fchefio a pesquisa\nda TEAM ROCKET.\fUma criança xereta\ncomo você precisa\vser punida.",
  ["TEXT_TEAM_ROCKET_BASE_B3_F_OBJ_007"] = "Se aumentarmos a\npotência do sinal\fde rádio para\ntransmitir longe…\fSó de pensar já\nme anima!",
  ["TEXT_TEAM_ROCKET_BASE_B3_F_OBJ_007_AFTER"] = "Se aumentarmos a\npotência do sinal\fde rádio para\ntransmitir longe…\fSó de pensar já\nme anima!",
  ["TEXT_TEAM_ROCKET_BASE_B3_F_OBJ_007_BEATEN"] = "Pensar é o meu\nforte, não\vbatalhar.",
  ["TEXT_TEAM_ROCKET_BASE_B3_F_OBJ_007_SEEN"] = "Não ligo se os\nPOKéMON sofrem\vcom a experiência",
  ["TEXT_TEAM_ROCKET_BASE_B3_F_OBJ_008"] = "Urrggh… O cara\nde capa é\vforte demais…",
  ["TEXT_TIME_CAPSULE_BG_001"] = "O seu amigo\nestá pronto.",
  ["TEXT_TIME_CAPSULE_BG_002"] = "O seu amigo\nestá pronto.",
  ["TEXT_TRADE_CENTER_BG_001"] = "O seu amigo\nestá pronto.",
  ["TEXT_TRADE_CENTER_BG_002"] = "O seu amigo\nestá pronto.",
  ["TEXT_TRADE_CENTER_OBJ_001"] = "O seu amigo\nestá pronto.",
  ["TEXT_TRADE_CENTER_OBJ_002"] = "O seu amigo\nestá pronto.",
  ["TEXT_TRAINER_HOUSE1_F_OBJ_001"] = "Bem-vindo à\nTRAINER HOUSE,\fo lugar mais novo\ne badalado daqui.\fA gente só abre\npara treinador.\fDá para enfrentar\nos melhores\fdos melhores logo\naqui embaixo.",
  ["TEXT_TRAINER_HOUSE1_F_OBJ_002"] = "VIRIDIAN é a vila\nmais perto do\vINDIGO PLATEAU.\fFizeram este lugar\nporque muito\ftreinador passa\npor aqui subindo\fao INDIGO\nPLATEAU.",
  ["TEXT_TRAINER_HOUSE1_F_OBJ_003"] = "Fazem batalhas de\ntreino aqui\vembaixo.\fEu adoraria ver\no quanto um\ftreinador de JOHTO\nbatalha bem.",
  ["TEXT_TRAINER_HOUSE1_F_OBJ_004"] = "Acho que não dá\npara ser CAMPEÃO\fsem rodar o mundo\ntodo e batalhar\fcom todo tipo\nde gente.\fO CAMPEÃO de\nPALLET viajou por\ftodas as cidades\ne vilas de KANTO.",
  ["TEXT_TRAINER_HOUSE1_F_OBJ_005"] = "Ufa… Estou dando\num descanso das\vbatalhas.",
  ["TEXT_UNION_CAVE1_F_OBJ_001"] = "Uau! Fui derrotado\nfeio!",
  ["TEXT_UNION_CAVE1_F_OBJ_001_AFTER"] = "Fui enganado e\ncomprei uma\vSLOWPOKETAIL.\fTenho pena do\npobre POKéMON.",
  ["TEXT_UNION_CAVE1_F_OBJ_001_BEATEN"] = "Uau! Fui derrotado\nfeio!",
  ["TEXT_UNION_CAVE1_F_OBJ_001_SEEN"] = "Uau! Que\nsurpresa!\fNão esperava ver\nninguém aqui!",
  ["TEXT_UNION_CAVE1_F_OBJ_002"] = "Ugh. Meus pobres\nPOKéMON…",
  ["TEXT_UNION_CAVE1_F_OBJ_002_AFTER"] = "Toda sexta dá para\nouvir rugidos de\fPOKéMON lá do\nfundo da caverna.",
  ["TEXT_UNION_CAVE1_F_OBJ_002_BEATEN"] = "Ugh. Meus pobres\nPOKéMON…",
  ["TEXT_UNION_CAVE1_F_OBJ_002_SEEN"] = "Eu ando por toda\nparte procurando\vPOKéMON.\fVocê também está\nprocurando?\fEntão você é meu\nrival de coleção!",
  ["TEXT_UNION_CAVE1_F_OBJ_003"] = "Muito bem, então!\nEu decidi.\fNão vou sair daqui\naté meus POKéMON\vficarem fortes!",
  ["TEXT_UNION_CAVE1_F_OBJ_003_AFTER"] = "Muito bem, então!\nEu decidi.\fNão vou sair daqui\naté meus POKéMON\vficarem fortes!",
  ["TEXT_UNION_CAVE1_F_OBJ_003_BEATEN"] = "Ah, ah, ah!",
  ["TEXT_UNION_CAVE1_F_OBJ_003_SEEN"] = "Você está indo\npra AZALEA, não\vé?\fVamos ver se meu\nPOKéMON acha você\vbom o bastante\vpra batalhar.",
  ["TEXT_UNION_CAVE1_F_OBJ_004"] = "É o fogo do meu\nPOKéMON que acende\vesta caverna.",
  ["TEXT_UNION_CAVE1_F_OBJ_004_AFTER"] = "É o fogo do meu\nPOKéMON que acende\vesta caverna.",
  ["TEXT_UNION_CAVE1_F_OBJ_004_SEEN"] = "Com luz, caverna\nnão assusta.\fSe você é forte,\nPOKéMON também\vnão assustam.",
  ["TEXT_UNION_CAVE1_F_OBJ_005_AFTER"] = "No fim de semana\ndá para ouvir\frugidos estranhos\nlá no fundo.",
  ["TEXT_UNION_CAVE1_F_OBJ_005_BEATEN"] = "Me estraguei!",
  ["TEXT_UNION_CAVE1_F_OBJ_005_SEEN"] = "O SUPERSONIC dos\nZUBAT vive\vdeixando eu\vconfuso.\fIsso me irrita\nmuito mesmo!",
  ["TEXT_UNION_CAVE_B1_F_OBJ_001"] = "Estou perdido faz\nmuito tempo…\fNão me importo de\nficar aqui, mas\vque fome!",
  ["TEXT_UNION_CAVE_B1_F_OBJ_001_AFTER"] = "Estou perdido faz\nmuito tempo…\fNão me importo de\nficar aqui, mas\vque fome!",
  ["TEXT_UNION_CAVE_B1_F_OBJ_001_BEATEN"] = "Uuurgh…",
  ["TEXT_UNION_CAVE_B1_F_OBJ_001_SEEN"] = "Faz tempo que\nnão via outra\vpessoa.\fNão seja tímido.\nVamos batalhar!",
  ["TEXT_UNION_CAVE_B1_F_OBJ_002"] = "Eu moro aqui.\fVocê também pode,\nse quiser.\fTem espaço de\nsobra, sabe.",
  ["TEXT_UNION_CAVE_B1_F_OBJ_002_AFTER"] = "Eu moro aqui.\fVocê também pode,\nse quiser.\fTem espaço de\nsobra, sabe.",
  ["TEXT_UNION_CAVE_B1_F_OBJ_002_BEATEN"] = "Uahahah! Você é\ndanado!",
  ["TEXT_UNION_CAVE_B1_F_OBJ_002_SEEN"] = "Veja só!\nUma visita!",
  ["TEXT_UNION_CAVE_B1_F_OBJ_003"] = "Só eu e os meus\nPOKéMON. Estou\vlouco de alegria.",
  ["TEXT_UNION_CAVE_B1_F_OBJ_003_AFTER"] = "Só eu e os meus\nPOKéMON. Estou\vlouco de alegria.",
  ["TEXT_UNION_CAVE_B1_F_OBJ_003_BEATEN"] = "Vai…\nVai embora!",
  ["TEXT_UNION_CAVE_B1_F_OBJ_003_SEEN"] = "Quem está aí?\fDeixe eu e meus\nPOKéMON em paz!",
  ["TEXT_UNION_CAVE_B1_F_OBJ_004"] = "Devo reunir e\ndivulgar o que\vdescobri.\fQuem sabe eu fique\nfamoso como o\vPROF.ELM.",
  ["TEXT_UNION_CAVE_B1_F_OBJ_004_AFTER"] = "Devo reunir e\ndivulgar o que\vdescobri.\fQuem sabe eu fique\nfamoso como o\vPROF.ELM.",
  ["TEXT_UNION_CAVE_B1_F_OBJ_004_BEATEN"] = "Você demonstrou\nem mim!",
  ["TEXT_UNION_CAVE_B1_F_OBJ_004_SEEN"] = "Vim de tão longe\npara fazer minha\vpesquisa POKéMON.\fDeixe eu mostrar\no que descobri\vnuma luta real!",
  ["TEXT_UNION_CAVE_B1_F_OBJ_006"] = "Cure Seus POKéMON!\nCENTRO POKéMON",
  ["TEXT_UNION_CAVE_B2_F_OBJ_001"] = "Seu estilo POKéMON\né impressionante\ve colorido, sim.\fVocê só vai\nmelhorar!",
  ["TEXT_UNION_CAVE_B2_F_OBJ_001_AFTER"] = "Seu estilo POKéMON\né impressionante\ve colorido, sim.\fVocê só vai\nmelhorar!",
  ["TEXT_UNION_CAVE_B2_F_OBJ_001_BEATEN"] = "Você tem um\nestilo brilhante!",
  ["TEXT_UNION_CAVE_B2_F_OBJ_001_SEEN"] = "Existem dois\ntipos de pessoa.\fAs com estilo,\ne as que não\vtêm.\fQue tipo de\npessoa é você?",
  ["TEXT_UNION_CAVE_B2_F_OBJ_002"] = "Vou treinar\nsozinho até eu\vmelhorar.",
  ["TEXT_UNION_CAVE_B2_F_OBJ_002_AFTER"] = "Vou treinar\nsozinho até eu\vmelhorar.",
  ["TEXT_UNION_CAVE_B2_F_OBJ_002_BEATEN"] = "Aah, não! Você é\nbom demais.",
  ["TEXT_UNION_CAVE_B2_F_OBJ_002_SEEN"] = "Estou treinando.\nTopa uma partida?",
  ["TEXT_UNION_CAVE_B2_F_OBJ_003"] = "Uma vez por semana\num POKéMON vem\vaté a beira.\fEu queria ver\nesse POKéMON…",
  ["TEXT_UNION_CAVE_B2_F_OBJ_003_AFTER"] = "Uma vez por semana\num POKéMON vem\vaté a beira.\fEu queria ver\nesse POKéMON…",
  ["TEXT_UNION_CAVE_B2_F_OBJ_003_BEATEN"] = "Prefiro fazer\ncarinho neles!",
  ["TEXT_UNION_CAVE_B2_F_OBJ_003_SEEN"] = "Se o POKéMON que\neu gosto estivesse\vlá, eu iria.\fÉ o que um\ntreinador faz.",
  ["TEXT_UNION_CAVE_B2_F_OBJ_006"] = "Seu estilo POKéMON\né impressionante\ve colorido, sim.\fVocê só vai\nmelhorar!",
  ["TEXT_VERMILION_CITY_OBJ_001"] = "VERMILION PORT é\na porta marítima\vde KANTO.\fNavios de luxo\ndo mundo todo\vaportam aqui.",
  ["TEXT_VERMILION_CITY_OBJ_002"] = "Meu POKéMON está\npreparando o\vterreno para a\vobra.\fMas não tenho\ndinheiro para\vcomeçar…",
  ["TEXT_VERMILION_CITY_OBJ_004"] = "Há oito GINÁSIOS\nem KANTO.\fAquele prédio\ngrande é o GINÁSIO\vde VERMILION.",
  ["TEXT_VERMILION_CITY_OBJ_005"] = "SNORLAX ronca\ntranquilamente…",
  ["TEXT_VERMILION_CITY_OBJ_006"] = "Treinadores\nhabilidosos se\freúnem em KANTO.\nOs LÍDERES são\ffortes e não são\nfáceis de vencer.",
  ["TEXT_VERMILION_FISHING_SPEECH_HOUSE_BG_001"] = "É uma foto de\ngente pescando…\fParecem estar\nse divertindo…",
  ["TEXT_VERMILION_FISHING_SPEECH_HOUSE_OBJ_001"] = "Eu sou o FISHING\nGURU, o mais velho\vdos FISHING BROS.\fPor acaso conhece\no FISHERMAN\fWILTON? Ele pesca\nna ROTA 44.\fEle me ligou com\numa dica\vincrível.\fGraças a ele, eu\npeguei um monte\fde um POKéMON raro\nQue dia aquele!",
  ["TEXT_VERMILION_GYM_BG_001"] = "Nada! Só tem lixo\naqui.",
  ["TEXT_VERMILION_GYM_BG_002"] = "Nada! Só tem lixo\naqui.",
  ["TEXT_VERMILION_GYM_BG_003"] = "Nada! Só tem lixo\naqui.",
  ["TEXT_VERMILION_GYM_BG_004"] = "Nada! Só tem lixo\naqui.",
  ["TEXT_VERMILION_GYM_BG_005"] = "Nada! Só tem lixo\naqui.",
  ["TEXT_VERMILION_GYM_BG_006"] = "Nada! Só tem lixo\naqui.",
  ["TEXT_VERMILION_GYM_BG_007"] = "Nada! Só tem lixo\naqui.",
  ["TEXT_VERMILION_GYM_BG_008"] = "Nada! Só tem lixo\naqui.",
  ["TEXT_VERMILION_GYM_BG_009"] = "Nada! Só tem lixo\naqui.",
  ["TEXT_VERMILION_GYM_BG_010"] = "Nada! Só tem lixo\naqui.",
  ["TEXT_VERMILION_GYM_BG_011"] = "Nada! Só tem lixo\naqui.",
  ["TEXT_VERMILION_GYM_BG_012"] = "Nada! Só tem lixo\naqui.",
  ["TEXT_VERMILION_GYM_BG_013"] = "Nada! Só tem lixo\naqui.",
  ["TEXT_VERMILION_GYM_BG_014"] = "Nada! Só tem lixo\naqui.",
  ["TEXT_VERMILION_GYM_BG_015"] = "Nada! Só tem lixo\naqui.",
  ["TEXT_VERMILION_GYM_OBJ_001"] = "SURGE: Ei,\ngarotinho!\fTenho que admitir.\nPode não ser lá\fmuito esperto me\ndesafiar, mas\vtem coragem!\fQuando o assunto é\nPOKéMON elétrico,\vsou o número um!\fNunca perdi no\ncampo de batalha.\fVou fritar você\nigual fritei meus\vinimigos!",
  ["TEXT_VERMILION_GYM_OBJ_002_AFTER"] = "Quando eu estava\nno exército, o\fLT.SURGE salvou\na minha vida.",
  ["TEXT_VERMILION_GYM_OBJ_002_BEATEN"] = "Desculpe, falhei\ncom o LT.SURGE,\vsenhor!",
  ["TEXT_VERMILION_GYM_OBJ_002_SEEN"] = "Veio derrotar o\nLT.SURGE?\fNão enquanto eu\nestiver aqui!",
  ["TEXT_VERMILION_GYM_OBJ_003_AFTER"] = "Se as armadilhas\nfuncionassem,\fvocê já estaria\nfrito…",
  ["TEXT_VERMILION_GYM_OBJ_003_BEATEN"] = "Ooh, que choque!",
  ["TEXT_VERMILION_GYM_OBJ_003_SEEN"] = "LT.SURGE viu meu\npotencial com\fPOKéMON\nelétricos.\fAcha que vai me\nvencer?",
  ["TEXT_VERMILION_GYM_OBJ_004_AFTER"] = "Nada de se achar\npor me vencer.\fLT.SURGE é muito\ndurão.",
  ["TEXT_VERMILION_GYM_OBJ_004_BEATEN"] = "Gwaaah!\nFui superado…",
  ["TEXT_VERMILION_GYM_OBJ_004_SEEN"] = "Vou te derrubar!\nPrepare-se para\vlevar um choque!",
  ["TEXT_VERMILION_GYM_OBJ_005"] = "Ei! Futuro\nCAMPEÃO!\fVocê deu sorte\ndesta vez.\fO LT.SURGE é muito\ncauteloso.\fTem armadilhas por\ntodo o GINÁSIO.\fMas, he-heh, as\narmadilhas não\vestão ligadas.\fVocê não vai ter\nproblema para\vchegar nele.",
  ["TEXT_VERMILION_MAGNET_TRAIN_SPEECH_HOUSE_OBJ_001"] = "Você conhece o\nMAGNET TRAIN?\fÉ uma ferrovia\nque vai até\vGOLDENROD, JOHTO.",
  ["TEXT_VERMILION_MAGNET_TRAIN_SPEECH_HOUSE_OBJ_002"] = "Quero ir a SAFFRON\npara ver o\vMAGNET TRAIN.",
  ["TEXT_VERMILION_MART_OBJ_001"] = "A TEAM ROCKET\nsumiu de KANTO.\fSó isso já me\ndeixa feliz.",
  ["TEXT_VERMILION_POKECENTER1_F_OBJ_001"] = "Bom dia!\nBem-vindo ao nosso\vCENTRO POKéMON.",
  ["TEXT_VERMILION_POKECENTER1_F_OBJ_002"] = "Um POKéMON dorme\nbem na frente da\vDIGLETT'S CAVE.\fÉ uma chance ótima\nde pegar ele,\fmas como acordar\no bicho?",
  ["TEXT_VERMILION_PORT_OBJ_001"] = "Vamos partir logo.\nPor favor, suba\va bordo.",
  ["TEXT_VERMILION_PORT_OBJ_002"] = "Bem-vindo ao FAST\nSHIP S.S.AQUA.\fVai embarcar\nhoje?",
  ["TEXT_VERMILION_PORT_OBJ_003"] = "Você veio de\nJOHTO?\fDizem que muitos\nPOKéMON raros\vvivem lá.",
  ["TEXT_VICTORY_ROAD_GATE_OBJ_001"] = "Só passa o\ntreinador que já\vprovou seu valor.",
  ["TEXT_VICTORY_ROAD_GATE_OBJ_002"] = "Este caminho leva\nao MT.SILVER.\fVocê vai ver\nPOKéMON fortes de\vdar medo lá.",
  ["TEXT_VIOLET_CITY_OBJ_001"] = "Olá!\nVocê treinador?\fLutar com LÍDER,\nganhar você?",
  ["TEXT_VIOLET_CITY_OBJ_002"] = "Dizem que aparecem\nfantasmas na\vSPROUT TOWER.\fDiziam que ataques\nnormais não pegam\fnos fantasmas.\nNada mesmo.",
  ["TEXT_VIOLET_CITY_OBJ_003"] = "Ei, você é\ntreinador POKéMON\fSe vencer o LÍDER\nde GINÁSIO daqui,\fvai estar pronto\npara valer!",
  ["TEXT_VIOLET_CITY_OBJ_004"] = "FALKNER, do\nGINÁSIO POKéMON\fde VIOLET, é um\nótimo treinador!\fEle herdou o\nginásio do pai\fe fez um belo\ntrabalho nele.",
  ["TEXT_VIOLET_CITY_OBJ_005"] = "Vi uma árvore que\nse mexe adiante!\fSe você tocar,\nela se contorce\ve dança! Legal!",
  ["TEXT_VIOLET_GYM_OBJ_001"] = "Sou FALKNER, líder\ndo GINÁSIO POKéMON\vde VIOLET!\fDizem que dá para\ncortar as asas de\fPOKéMON voadores\ncom um choque\velétrico…\fNão vou permitir\ntal insulto às\vaves POKéMON!\fVou lhe mostrar o\npoder de verdade\fdas magníficas\naves POKéMON!",
  ["TEXT_VIOLET_GYM_OBJ_002"] = "O talento do\nFALKNER é real!\fNão se ache só\nporque venceu\va mim!",
  ["TEXT_VIOLET_GYM_OBJ_002_AFTER"] = "O talento do\nFALKNER é real!\fNão se ache só\nporque venceu\va mim!",
  ["TEXT_VIOLET_GYM_OBJ_002_BEATEN"] = "Aaah!",
  ["TEXT_VIOLET_GYM_OBJ_002_SEEN"] = "A palavra de\nordem é raça!\fO pessoal aqui\ntreina noite e\fdia para virar\nmestre de POKéMON\fvoador. Venha!",
  ["TEXT_VIOLET_GYM_OBJ_003"] = "Que vergonha,\nperder para um\vnovato…",
  ["TEXT_VIOLET_GYM_OBJ_003_AFTER"] = "Que vergonha,\nperder para um\vnovato…",
  ["TEXT_VIOLET_GYM_OBJ_003_BEATEN"] = "Isso não pode\nser verdade!",
  ["TEXT_VIOLET_GYM_OBJ_003_SEEN"] = "Deixa eu ver se\nvocê é bom o\vbastante!",
  ["TEXT_VIOLET_GYM_OBJ_004"] = "Ei! Não sou\ntreinador, mas dou\vum conselho!\fAcredite em mim!\nSe você acredita,\fo sonho de ser\ncampeão acontece.\fAcredita?\nEntão escute.\fO tipo planta é\nfraco contra o\ftipo voador. Não\nesqueça disso.",
  ["TEXT_VIOLET_KYLES_HOUSE_OBJ_001"] = "POKéMON trocado\ncresce\vrápido.\fMas sem a GYM\nBADGE certa,\feles podem\ndesobedecer você.",
  ["TEXT_VIOLET_MART_OBJ_001"] = "Quando você pega\num POKéMON novo,\vele é fraco.\fMas com o tempo\nele vai ficar\vforte.\fÉ importante\ntratar POKéMON com\vcarinho.",
  ["TEXT_VIOLET_NICKNAME_SPEECH_HOUSE_OBJ_001"] = "Ela usa os nomes\ndas suas comidas\vpreferidas.\fNos apelidos\nque ela dá aos\vPOKéMON, digo.",
  ["TEXT_VIOLET_NICKNAME_SPEECH_HOUSE_OBJ_002"] = "Chamo meu PIDGEY\nde STRAWBERRY!",
  ["TEXT_VIOLET_NICKNAME_SPEECH_HOUSE_OBJ_003"] = "STRAWBERRY:Pijji!",
  ["TEXT_VIOLET_POKECENTER1_F_OBJ_001"] = "Bom dia!\nBem-vindo ao nosso\vCENTRO POKéMON.",
  ["TEXT_VIOLET_POKECENTER1_F_OBJ_002"] = "Um cara chamado\nBILL fez o sistema\vde POKéMON do PC.",
  ["TEXT_VIOLET_POKECENTER1_F_OBJ_003"] = "Foi há mais ou\nmenos três anos.\fA TEAM ROCKET\nfazia maldades\vcom POKéMON.\fMas a justiça\nvenceu: um garoto\vacabou com eles.",
  ["TEXT_VIOLET_POKECENTER1_F_OBJ_004"] = "POKéMON são\nespertos.\fNão obedecem a\num treinador que\fnão respeitam.\nSem as GYM BADGES\fcertas, eles só\nagem como querem.",
  ["TEXT_VIOLET_POKECENTER1_F_OBJ_005"] = "{PLAYER}, faz\ntempo, hein!\fPROF.ELM pediu\npra te achar.\fEle quer pedir\noutro favor.\fAceita levar o\nPOKéMON EGG?",
  ["TEXT_VIRIDIAN_CITY_OBJ_001"] = "Ei, garoto! Acabei\nde tomar um café\fbem forte e estou\nligado no 220!\fPreciso conversar\ncom alguém, e você\vvai servir!\fPode não parecer,\nmas eu era expert\fem capturar\nPOKéMON.\fAcredita em mim?",
  ["TEXT_VIRIDIAN_CITY_OBJ_002"] = "Este GINÁSIO não\ntinha um LÍDER\vaté pouco tempo.\fUm rapaz de\nPALLET virou o\fLÍDER, mas vive\nfora.",
  ["TEXT_VIRIDIAN_CITY_OBJ_003"] = "Bocejo!\fDevo ter dormido\nno sol.\f…Tive um sonho\ncom um DROWZEE\fcomendo meu sonho.\nEstranho, né?\fHã?\nO que é isto?\fDe onde veio\nessa MT?\fQue sinistro!\nTome, pode ficar\vcom esta MT.",
  ["TEXT_VIRIDIAN_CITY_OBJ_004"] = "Ouvi dizer que há\nmuitos itens no\fchão da\nVIRIDIAN FOREST.",
  ["TEXT_VIRIDIAN_GYM_OBJ_001"] = "BLUE: Ei! Enfim\nchegou aqui, né?\fEu não tava a fim\nem CINNABAR,\fmas agora estou\npronto para você.\f…\fEstá me dizendo\nque venceu JOHTO\vinteira?\fHa! Então os\nGINÁSIOS de JOHTO\vdevem ser fracos.\fEi, não esquenta\ncom isso.\fEu vou saber se\nvocê é bom ou não\fbatalhando com\nvocê agora.\fPronto, garoto?",
  ["TEXT_VIRIDIAN_GYM_OBJ_002"] = "Ei, futuro\nCAMPEÃO!\fComo vai isso?\nParece que você\vestá embalado.\fO LÍDER daqui é\num cara que lutou\fcom o CAMPEÃO faz\ntrês anos.\fNão é mole não.\fDê tudo o que\nvocê tem!",
  ["TEXT_VIRIDIAN_MART_OBJ_001"] = "O LÍDER daqui\né totalmente\vsensacional.",
  ["TEXT_VIRIDIAN_NICKNAME_SPEECH_HOUSE_OBJ_001"] = "Você pensa muito\nna hora de\fdar nome aos\nseus POKéMON?\fBons apelidos\ndeixam a troca\fcom os outros\nmais divertida.",
  ["TEXT_VIRIDIAN_NICKNAME_SPEECH_HOUSE_OBJ_002"] = "São o SPEARY,\num SPEAROW, e o\vRATTEY, RATTATA.",
  ["TEXT_VIRIDIAN_POKECENTER1_F_OBJ_001"] = "Bom dia!\nBem-vindo ao nosso\vCENTRO POKéMON.",
  ["TEXT_VIRIDIAN_POKECENTER1_F_OBJ_002"] = "Onde diabos está\no LÍDER do\fGINÁSIO daqui?\nQueria desafiar.",
  ["TEXT_WHIRL_ISLAND_B1_F_OBJ_006"] = "Cure Seus POKéMON!\nCENTRO POKéMON",
  ["TEXT_WILLS_ROOM_OBJ_001"] = "{PLAYER}, bem-vindo\nà POKéMON LEAGUE.\fDeixe eu me\napresentar. Eu sou\vo WILL.\fEu treinei no\nmundo inteiro,\fdeixando meus\npsíquicos fortes.\fE, enfim, eu fui\naceito nos\vELITE FOUR.\fEu só posso ficar\ncada vez melhor!\fPerder não é uma\nopção!",
  ["TEXT_WISE_TRIOS_ROOM_OBJ_004_AFTER"] = "Ah, então é você\nque diz ter visto\fSUICUNE, ENTEI e\nRAIKOU\venquanto dormiam?\fInacreditável!\fDiz a lenda que\neles não podem\vser vistos\vdormindo…",
  ["TEXT_WISE_TRIOS_ROOM_OBJ_004_BEATEN"] = "Mais forte do\nque pensamos?\vTalvez…",
  ["TEXT_WISE_TRIOS_ROOM_OBJ_004_SEEN"] = "Diz a lenda que,\nquando surge\fum treinador\ncapaz de tocar\fa alma dos\nPOKéMON, um\vPOKéMON\faparece pra pôr\nesse treinador\fà prova na TIN\nTOWER.\fA lenda se\ntornou realidade!\fO lendário\nPOKéMON SUICUNE\vchegou!\fNós, o TRIO\nSÁBIO, vamos\vtestar se você\fmerece entrar!",
  ["TEXT_WISE_TRIOS_ROOM_OBJ_005_AFTER"] = "No passado, havia\nduas torres de\vnove andares aqui.\fA BRASS TOWER,\nque dizem que\fdespertava\nPOKéMON, e a TIN\vTOWER,\fonde os POKéMON\ndescansavam.\fA vista do topo\ndas TOWERS\fdeve ter sido\nmagnífica.\fNa época, um\nimenso POKéMON\fprateado dizem\nque fazia ninho\fno topo da\nBRASS TOWER.\fPorém…\fHá cerca de 150\nanos, um raio\fatingiu uma\ndas TOWERS.\fEla foi tomada\npor chamas que\vduraram três\vdias.\fUma chuva\nrepentina apagou\vo fogo.\fE foi assim que\nsurgiu a BURNED\vTOWER.",
  ["TEXT_WISE_TRIOS_ROOM_OBJ_005_BEATEN"] = "…Vou te contar\na verdade…",
  ["TEXT_WISE_TRIOS_ROOM_OBJ_005_SEEN"] = "Pode ser confiado\ncom a verdade?\fPreciso confirmar\nseu mérito.",
  ["TEXT_WISE_TRIOS_ROOM_OBJ_006_AFTER"] = "Você… É o\ntreinador que\fos POKéMON\nlendários esperam?",
  ["TEXT_WISE_TRIOS_ROOM_OBJ_006_BEATEN"] = "Forte demais!\nPor quê?",
  ["TEXT_WISE_TRIOS_ROOM_OBJ_006_SEEN"] = "Deixe-me ver\nseu poder!",
  ["TVText"] = "É uma TV.",
  ["TakeChikoritaText"] = "ELM: Então gosta\nda CHIKORITA, a\vPOKéMON planta?",
  ["TakeCyndaquilText"] = "ELM: Vai levar o\nCYNDAQUIL, o\vPOKéMON de fogo?",
  ["TakeTotodileText"] = "ELM: Você quer o\nTOTODILE, o\vPOKéMON de água?",
  ["TeacherColetteAfterBattleText"] = "Antes de virar\nprofessor, eu\fesquecia muita\ncoisa.",
  ["TeacherHillaryAfterBattleText"] = "Estudar é\nimportante, mas se\vexercitar também.",
  ["TeacherHillaryBeatenText"] = "Eu não queria\nperder…",
  ["TeacherHillarySeenText"] = "Nos dias de sol,\nacho que\fas crianças\nprefeririam\vbrincar no pátio\fa estudar na sala\nde aula.",
  ["TeacherShirleyAfterBattleText"] = "Estamos em\nexcursão nas\vRUÍNAS perto de\vVIOLET.",
  ["TeacherShirleySeenText"] = "Não encoste um\ndedo nos alunos!",
  ["TeacherText_CrunchCrunch"] = "Nhac… nhac…",
  ["TeacherText_KeepEating"] = "Nhac… nhac…\fAinda posso comer",
  ["TeacherText_MoreChef"] = "Manda mais, CHEF!",
  ["TeacherText_NoCoinCase"] = "Ninguém aqui vai\nte dar uma COIN\fCASE. Procure em\nJOHTO.",
  ["TeamRocketBaseB1FSecretSwitchText"] = "Um botão secreto!\nMelhor apertar.",
  ["TeamRocketBaseB1FSecurityCameraText"] = "É uma estátua de\nPERSIAN…\fOs olhos dela são\nmuito brilhantes.",
  ["TeamRocketBaseB1FSwitchOffText"] = "O botão está\ndesligado.",
  ["TeamRocketBaseB3FLockedDoorNeedsPasswordText"] = "A porta fechou…\fPrecisa de duas\nsenhas para abrir",
  ["TeamRocketBaseB3FLockedDoorOpenSesameText"] = "A porta fechou…\f{PLAYER} digitou\nas duas senhas.\fA porta abriu!",
  ["TeamRocketBaseB3FRocketText"] = "Urrggh… O cara\nde capa é\vforte demais…",
  ["TeamRocketOathText"] = "JURAMENTO ROCKET\fRoubar POKéMON\npor lucro!\fExplorar POKéMON\npor lucro!\fPOKéMON existem\npara a glória da\vTEAM ROCKET!",
  ["TeleportGuyNoText"] = "Certo, certo.\nBoa sorte!",
  ["TeleportGuyText1"] = "Ah! Você vai\ndesafiar os ELITE\fFOUR? Tem certeza\nque está pronto?\fSe precisar\ntreinar mais,\fmeu ABRA pode\najudar você.\fEle pode TELEPORT\nvocê para casa.\fVocê quer ir\npara casa agora?",
  ["TeleportGuyYesText"] = "Certo, certo.\nImagine a sua casa\vna cabeça…",
  ["Text_BattleReceptionistIntro"] = "Bem-vindo ao CABLE\nCLUB COLOSSEUM.\fAqui você batalha\ncom um amigo.\fVocê quer\nbatalhar?",
  ["Text_BattleRoomClosed"] = "Sinto muito, a\nBATTLE MACHINE\vestá em ajuste.",
  ["Text_CallMomOnGear"] = "Ligue para sua mãe\nna POKéGEAR para\fcontar como você\nestá indo.",
  ["Text_CantLinkToThePast"] = "Não dá para ligar\nao passado aqui.",
  ["Text_CharcoalMasterIntro"] = "Ah! O FARFETCH'D!\fVocê achou ele\npara nós, garoto?\fSem ele, a gente\nnão conseguiria\fusar CUT para\nfazer carvão.\fObrigado, garoto!\fComo posso\nagradecer…\fJá sei! Tome,\nfique com isto.",
  ["Text_CharcoalMasterOutro"] = "É o HM de CUT.\nEnsine a um\fPOKéMON para\ncortar arvoretas.\fClaro, você\nprecisa da BADGE\fdo GINÁSIO de\nAZALEA para usar.",
  ["Text_CharcoalMasterTalkAfter"] = "Quer virar meu\naprendiz\fde carvoeiro\ncomigo?\fEm dez anos você\nestará craque!",
  ["Text_ClairIsBeaten"] = "Você derrotou\nnosso LÍDER?\vIsso e incrível!\fCom seu poder,\nvocê deve ter\fsucesso na\nLIGA POKéMON.",
  ["Text_ClairIsIn"] = "Nosso LÍDER esta\nte esperando.\fPorém, seria\nimpossível para\fum treinador comum\nvencer.",
  ["Text_ClairIsOut"] = "Me desculpe.\fNosso LÍDER esta\ntreinando na\vcaverna lá atrás.\fNão tenho ideia\nquando nosso LÍDER\vvai voltar.",
  ["Text_EarlAsksIfYouBeatFalkner"] = "Olá!\nVocê treinador?\fLutar com LÍDER,\nganhar você?",
  ["Text_ElmDiscoveredNewMon"] = "Ei, {PLAYER}!\fSoube que o PROF.\nELM descobriu\vnovos POKéMON.",
  ["Text_FollowEarl"] = "É mesmo? Então\nestudar você deve!\vMe siga!",
  ["Text_GearIsImpressive"] = "Uau, sua POKéGEAR\né incrível!\fFoi sua mãe quem\nlhe deu ela?",
  ["Text_GrampsLookingForYou"] = "O vovô estava\nprocurando você.",
  ["Text_HeadbuttIntro"] = "O que eu faço?\fSacudo árvores\ncom HEADBUTT.\fÉ divertido. Tente\nvocê também!",
  ["Text_HeadbuttOutro"] = "Sacuda as árvores\ncom HEADBUTT. Às\vvezes cai um\vPOKéMON dormindo.",
  ["Text_HereTeacherIAm"] = "Aqui, professor eu\nsou. Bom é você\vestudar aqui!",
  ["Text_IlexForestShrine"] = "SANTUÁRIO da ILEX\nFOREST…\fÉ em honra ao\nprotetor da\vfloresta…",
  ["Text_IncompatibleRooms"] = "Seu amigo escolheu\noutra sala.",
  ["Text_ItsDangerousToGoAlone"] = "É perigoso sair\nsem um\vPOKéMON!\fPOKéMON selvagens\npulam do mato\fno caminho para\na próxima cidade.",
  ["Text_ItsTheMissingPokemon"] = "É o POKéMON que\nsumiu!",
  ["Text_Kwaaaa"] = "FARFETCH'D: Kwaa!",
  ["Text_LinkTimedOut"] = "A conexão foi\nfechada por falta\vde atividade.\fFale com o seu\namigo e volte\voutra hora.",
  ["Text_MillionDollarSlowpokeTail"] = "Que tal levar\nesta gostosa e\fnutritiva\nSLOWPOKETAIL?\fPara você agora,\nsó ¥1.000.000!\fVai querer!",
  ["Text_MustSaveGame"] = "Antes de abrir a\nconexão, você tem\vque salvar.",
  ["Text_MysteryGiftDeliveryGuy_HereYouGo"] = "Aqui está!",
  ["Text_MysteryGiftDeliveryGuy_Intro"] = "Olá! Você é o\n{PLAYER}, né?\fEu tenho uma\ncoisa para você.",
  ["Text_MysteryGiftDeliveryGuy_NoRoom"] = "Ah, você não tem\nespaço para isto.\fPasse em qualquer\nCENTRO POKéMON\fdo país para\npegar depois.",
  ["Text_MysteryGiftDeliveryGuy_Outro"] = "Esperamos atender\nvocê de novo.",
  ["Text_MysteryGiftDeliveryGuy_SaidNo"] = "Não? Isso é bem\nestranho…",
  ["Text_NoRoomForDragonFang"] = "Mas {PLAYER}\nnão pode levar\vmais itens.",
  ["Text_PleaseComeIn"] = "Pode entrar.",
  ["Text_PleaseComeInDuplicate"] = "Pode entrar.",
  ["Text_PleaseWait"] = "Aguarde um pouco.",
  ["Text_ReceivedEarthBadge"] = "{PLAYER} recebeu\na EARTHBADGE.",
  ["Text_ReceivedFogBadge"] = "{PLAYER} recebeu\na FOGBADGE.",
  ["Text_ReceivedGlacierBadge"] = "{PLAYER} recebeu\na GLACIERBADGE.",
  ["Text_ReceivedHiveBadge"] = "{PLAYER} recebeu\na HIVEBADGE.",
  ["Text_ReceivedMineralBadge"] = "{PLAYER} recebeu\na MINERALBADGE.",
  ["Text_ReceivedSoulBadge"] = "{PLAYER} recebeu\na SOULBADGE.",
  ["Text_RefusedToBuySlowpokeTail"] = "Não quer? Então\nfora daqui. Xô!",
  ["Text_RoarIntro"] = "WROOOAR!\nGENTE FOGE QUANDO\fEU RUJO! MAS VOCÊ\nVEIO ATRÁS!\fISSO ME AGRADA!\nAGORA PEGUE ISTO!",
  ["Text_RoarOutro"] = "WROOOAR!\nÉ O ROAR!\fATÉ POKéMON FOGEM\nDE UM BOM ROAR!",
  ["Text_Route31CantTakeLastMon"] = "Se eu levar esse\nPOKéMON de você,\fo que vai usar\nna batalha?",
  ["Text_Route31DeclinedToHandOverMail"] = "O quê? Você não\nquer nada?",
  ["Text_Route31DescribeNightmare"] = "TM50 é NIGHTMARE.\fÉ um golpe cruel\nque rói devagar\fo PS de um inimigo\nadormecido.\fOoooh…\nQue medo…\fNão quero ter\npesadelos.",
  ["Text_Route31HandOverMailMon"] = "{PLAYER} entregou\no POKéMON que\vsegurava a MAIL.",
  ["Text_Route31MissingMail"] = "Por que este\nPOKéMON é raro?\fEle não tem\nMAIL nenhuma.",
  ["Text_Route31ReadingMail"] = "Vejamos…\f…DARK CAVE leva\na outra estrada…\fBom saber\ndisso.\fObrigado por\ntrazer isto.\fMeu amigo é gente\nboa, e você\vtambém é!\fQuero fazer algo\nde bom em troca\vtambém!\fJá sei! Quero que\nfique com isto!",
  ["Text_Route31SleepyMan"] = "… Hnnn… Hã?\fAndei demais hoje\nprocurando\vPOKéMON.\fMeus pés doem e\nestou com sono…\fSe eu fosse um\nPOKéMON selvagem,\vseria fácil…\f…Zzzz…",
  ["Text_Route31SleepyManGotMail"] = "…Zzzz… Hã?\fO que é isso? Tem\nMAIL para mim?",
  ["Text_Route31WrongMail"] = "Esta MAIL não é\npara mim.",
  ["Text_TellMomIfLeaving"] = "Oi, {PLAYER}!\nSaindo de novo?\fVocê devia avisar\nsua mãe quando\vsair.",
  ["Text_ThisIsABigBattle"] = "O quê? Esta é uma\nbatalha séria!\vMe deixe em paz!",
  ["Text_ThoughtKidsWereLoaded"] = "Tsc! Pensei que\na molecada de hoje\vtinha dinheiro…",
  ["Text_TimeCapsuleClosed"] = "Sinto muito, a\nTIME CAPSULE está\vem ajuste.",
  ["Text_TimeCapsuleReceptionistIntro"] = "Bem-vindo ao CABLE\nCLUB TIME CAPSULE\fDá para viajar ao\npassado e trocar\vos seus POKéMON.\fVocê quer trocar\ncom o passado?",
  ["Text_TradeReceptionistIntro"] = "Bem-vindo ao CABLE\nCLUB TRADE CENTER\fAqui você troca\nos seus POKéMON\vcom um amigo.\fVocê quer\ntrocar?",
  ["Text_TradeRoomClosed"] = "Sinto muito, a\nTRADE MACHINE está\vem ajuste.",
  ["Text_UseTackle"] = "Vai, RATTATA!\fTACKLE!",
  ["Text_VeryNiceIndeed"] = "Ooh, la la!\nMuito bom mesmo!",
  ["Text_WaitPlayer"] = "Espere, {PLAYER}!",
  ["Text_WhatDoYouThinkYoureDoing"] = "O que você pensa\nque está fazendo?",
  ["Text_YourMonIsAdorable"] = "Oh! Seu POKéMON\né adorável!\vQueria ter um!",
  ["TimeCapsuleFriendScript.FriendReadyText"] = "O seu amigo\nestá pronto.",
  ["TinTower1FEusineHoOhText"] = "Eu sabia.\fEu sabia que você\nia ver o POKéMON\fde cores do\narco-íris,\v{PLAYER}.\fFoi exatamente\ncomo eu previ.\fPosso dizer que\nminha pesquisa\vnão é ruim.\fVou continuar\nestudando POKéMON\fpra virar um\nPOKéMANIAC\vfamoso!",
  ["TinTower1FEusineSuicuneText"] = "EUSINE: Incrível!\nAté demais!\fNunca vi uma\nbatalha tão boa.\fAquilo foi\nrealmente\vinspirador.\fSUICUNE foi duro,\nmas você foi ainda\fmais incrível,\n{PLAYER}.\fOuvi que o poder\nmístico de SUICUNE\finvoca um POKéMON\nde cor arco-íris.\fTalvez, só talvez,\no que aconteceu\fhoje faça esse\nPOKéMON aparecer.\fVou estudar mais\nas lendas.\fObrigado por me\nmostrar essa\vbatalha incrível.\fAté mais,\n{PLAYER}!",
  ["TinTower1FSage1Text"] = "Segundo\na lenda…\fQuando as almas de\nPOKéMON e humanos\fse comunicam, dos\ncéus desce um\fPOKéMON de cores\ndo arco-íris…\fSerá que os\nPOKéMON lendários\vestão testando\vnós, humanos?",
  ["TinTower1FSage2Text"] = "Quando a BRASS\nTOWER pegou fogo,\fdisseram que três\nPOKéMON sem nome\fmorreram. Foi\ntrágico.\fPorém…\fUm POKéMON\nde cor arco-íris…\fEm outras\npalavras…\fHO-OH desceu\ndo céu e deu\fnova vida aos\ntrês POKéMON.\fEles são…\fSUICUNE, ENTEI e\nRAIKOU.\fÉ o que\ndizem.",
  ["TinTower1FSage3Text"] = "Dizem que as duas\nTOWERS foram\fconstruídas para\npromover amizade\fe esperança entre\nPOKéMON e as\vpessoas.\fIsso foi há 700\nanos, mas o ideal\fainda é\nimportante hoje.",
  ["TinTower1FSage4Text1"] = "HO-OH parece ter\ndescido\fbem aqui, na TIN\nTOWER!",
  ["TinTower1FSage4Text2"] = "Dizem que os\nPOKéMON lendários\frepresentam três\npoderes…\fO raio que\natingiu a TOWER.\fO fogo que\nqueimou a TOWER.\fE a chuva que\napagou o fogo…",
  ["TinTower1FSage5Text1"] = "Isto vai te\nproteger. Pegue.",
  ["TinTower1FSage5Text2"] = "Agora, vá.",
  ["TinTower1FSage5Text3"] = "Quando os POKéMON\nlendários\vsurgiram…\fEles causaram\nterror em quem\vos viu surgir.\fE…\fAlguns até\npartiram pro\vataque, em vão.\fOs POKéMON\nlendários, cientes\fdo próprio poder,\vfugiram e\vignoraram as\vpessoas\vassustadas.",
  ["TinTower1FSage6Text1"] = "Acredito que você\nestá sendo\vtestado.\fLivre sua mente\nda incerteza\ve avance.",
  ["TinTower1FSage6Text2"] = "Dizem que, dos\nPOKéMON lendários,\fSUICUNE é o mais\npróximo de HO-OH.\fOuvi dizer que\ntambém há um\felo com o POKéMON\nUNOWN.\fO POKéMON UNOWN\ndeve compartilhar\fum vínculo com\no SUICUNE.",
  ["TinTowerSignText"] = "TIN TOWER\fDizem que um\nPOKéMON lendário\vpousa aqui.",
  ["TohjoFallsSignText"] = "TOHJO FALLS\fA ligação entre\nKANTO e JOHTO",
  ["TradeCenterFriendReadyText"] = "O seu amigo\nestá pronto.",
  ["TrainerGruntM1WhenTalkText"] = "É, a TEAM ROCKET\nfoi desfeita\vhá três anos.\fMas continuamos\ncom as atividades\vescondidos.\fAgora divirta-se\nvendo a gente\vaprontar!",
  ["TrainerHouse1FCooltrainerFText"] = "Fazem batalhas de\ntreino aqui\vembaixo.\fEu adoraria ver\no quanto um\ftreinador de JOHTO\nbatalha bem.",
  ["TrainerHouse1FCooltrainerMText"] = "VIRIDIAN é a vila\nmais perto do\vINDIGO PLATEAU.\fFizeram este lugar\nporque muito\ftreinador passa\npor aqui subindo\fao INDIGO\nPLATEAU.",
  ["TrainerHouse1FGentlemanText"] = "Ufa… Estou dando\num descanso das\vbatalhas.",
  ["TrainerHouse1FReceptionistText"] = "Bem-vindo à\nTRAINER HOUSE,\fo lugar mais novo\ne badalado daqui.\fA gente só abre\npara treinador.\fDá para enfrentar\nos melhores\fdos melhores logo\naqui embaixo.",
  ["TrainerHouse1FYoungsterText"] = "Acho que não dá\npara ser CAMPEÃO\fsem rodar o mundo\ntodo e batalhar\fcom todo tipo\nde gente.\fO CAMPEÃO de\nPALLET viajou por\ftodas as cidades\ne vilas de KANTO.",
  ["TrainerHouseB1FAskWantToBattleText"] = "Você quer\nbatalhar?",
  ["TrainerHouseB1FCalBeatenText"] = "Eu perdi…\nDroga…",
  ["TrainerHouseB1FCalBeforeText"] = "Eu viajei até\naqui só para\vbatalhar contigo.",
  ["TrainerHouseB1FGoRightInText"] = "Por favor, pode\nentrar.\fVocê já pode\ncomeçar.",
  ["TrainerHouseB1FIntroText"] = "Oi. Bem-vindo ao\nTRAINING HALL.\fVocê pode batalhar\ncom um treinador\vuma vez por dia.",
  ["TrainerHouseB1FPleaseComeAgainText"] = "Desculpe. Só os\ntreinadores que\fvão batalhar podem\nentrar.",
  ["TrainerHouseB1FSecondChallengeDeniedText"] = "Sinto muito,\nsenhor.\fSeria a segunda\nvez hoje. Só é\fpermitido entrar\numa vez por dia.",
  ["TrainerHouseB1FYourOpponentIsText"] = "{RAM:D099} é seu\nadversário hoje.",
  ["TrainerHouseIllegibleText"] = "…O que é isto?\nUm plano de luta?\fA letra parece\nrastro de ONIX…\fEstá totalmente\nilegível…",
  ["TrainerHouseSign1Text"] = "As batalhas de\ntreino acontecem\fno TRAINING HALL\naqui embaixo.\fTreinadores bons\nestão convidados\va participar.",
  ["TrainerHouseSign2Text"] = "Não tem regra nem\nregulamento nas\fpartidas de treino\nIgual às batalhas\fde campo, vale\ntudo!",
  ["TrainerHouseSignText"] = "TRAINER HOUSE\fO Clube das Lutas\nentre Treinadores",
  ["TrashCanText"] = "Não tem nada\naqui dentro…",
  ["TuscanyGaveGiftText"] = "TUSCANY: Não acha\nque ele é mesmo\vadorável?\fEle fortalece\nataques normais.\fTenho certeza que\nserá útil.",
  ["TuscanyGivesGiftText"] = "Como apresentação,\naceite este\fpresente, um\nPINK BOW.",
  ["TuscanyNotTuesdayText"] = "TUSCANY: Hoje não\né terça-feira.\vQue pena…",
  ["TuscanyTuesdayText"] = "TUSCANY: Conhece\nMONICA, minha\virmã mais velha?\fOu meu irmão\ncaçula, WESLEY?\fSou a segunda de\nsete filhos.",
  ["TwinsAmyandmay1AfterBattleText"] = "AMY: Você é\nmuito forte!",
  ["TwinsAmyandmay1BeatenText"] = "AMY & MAY: Oh,\nduplamente bom!",
  ["TwinsAmyandmay1SeenText"] = "AMY: Oi! Você vai\ndesafiar o LÍDER?\vNem pensar!",
  ["TwinsAmyandmay2AfterBattleText"] = "MAY: Meus insetos\nperderam! Que\vpena!",
  ["TwinsAmyandmay2BeatenText"] = "AMY & MAY: Oh,\nduplamente bom!",
  ["TwinsAmyandmay2SeenText"] = "MAY: Você quer\nver o LÍDER?\vNós primeiro!",
  ["TwinsAnnandanne1AfterBattleText"] = "ANN: Eu sei o que\nminha irmã e meus\fPOKéMON estão\npensando.",
  ["TwinsAnnandanne1BeatenText"] = "ANN & ANNE: Você\né mau!",
  ["TwinsAnnandanne2AfterBattleText"] = "ANNE: Sentimos o\nmesmo que os\vnossos POKéMON.",
  ["TwinsAnnandanne2BeatenText"] = "ANN & ANNE: Você\né mau!",
  ["TwinsAnnandanne2SeenText"] = "ANNE: Eu e a ANN\nestamos nisso\vjuntas!",
  ["TwinsJoAndZoe1AfterBattleText"] = "ERIKA vai se\nvingar por nós!",
  ["TwinsJoAndZoe1SeenText"] = "Vamos mostrar\ngolpes que ERIKA\vnos ensinou!",
  ["TwinsJoAndZoe2AfterBattleText"] = "ERIKA é muito,\nmuito mais forte!",
  ["TwinsJoAndZoe2BeatenText"] = "Não conseguimos…",
  ["TwinsJoAndZoe2SeenText"] = "Nós vamos proteger\na ERIKA!",
  ["TwinsMegandpeg1AfterBattleText"] = "Bebê é um jeito\ngrosso de chamar\vnós, meninas!",
  ["TwinsMegandpeg1SeenText"] = "Você acha que eu\nsou bebê?\vIsso não é justo!",
  ["TwinsMegandpeg2AfterBattleText"] = "Às vezes crianças\nsão mais espertas\vque adultos!",
  ["TwinsMegandpeg2SeenText"] = "Eu não sou bebê!\fNão é bonito falar\nassim com a dama!",
  ["UndergroundRivalAfterText"] = "…Não entendo…\fÉ verdade o que o\nLANCE disse?\fQue não trato bem\nos POKéMON?\fAmor…\fConfiança…\fSão mesmo o que me\nfalta?\fSerá que me\nimpedem?\fEu… só não\nentendo.\fMas não vai\nterminar aqui.\fAgora não. Não por\nisso.\fNão vou desistir\ndo sonho de\fser o melhor\nmestre POKéMON!",
  ["UndergroundRivalBeforeText"] = "Espera aí!\fTe vi, então\nte segui.\fNão preciso de\nvocê atrapalhando\fenquanto cuido\nda TEAM ROCKET.\f…Espera aí.\nVocê me venceu\vantes, não foi?\fAquilo foi\nsó sorte.\fMas eu pago\nminhas dívidas!",
  ["UndergroundRivalLossText"] = "Humf. Este é o\nmeu poder real.\fVou acabar com\na TEAM ROCKET.\fE vou\nesmagar o LANCE\vsob meus pés.",
  ["UndergroundRivalWinText"] = "…Por quê…\nPor que perco?\fJuntei os POKéMON\nmais fortes.\fNão aliviei\nno ritmo.\fPor que perco?",
  ["UnusedBugCatchingContestExplanationText"] = "O Concurso de\nCaptura Insetos\fé realizado na\nterça, quinta e\fsábado.\nNão só você ganha\fum prêmio por vir,\ncomo também pode\fficar com um\nPOKéMON inseto.",
  ["UseSquirtbottleText"] = "E uma árvore\nestranha?",
  ["UsedSquirtbottleText"] = "{PLAYER} usou o\nSQUIRTBOTTLE.",
  ["VermilionCityBadgeGuyAllBadgesText"] = "Parabéns!\fVocê pegou as\nBADGES de KANTO.\fTenho um prêmio\npra você.",
  ["VermilionCityBadgeGuyBattleEdgeText"] = "Uma variedade\nde tipos POKéMON\fte dá vantagem\nna batalha.\fTenho certeza\nque as GYM BADGES\vde KANTO ajudam.",
  ["VermilionCityBadgeGuyMostBadgesText"] = "Acho que você\nvai acabar logo\fcom a conquista\ndos GINÁSIOS de\fKANTO.\nMe avise se\vpegar as oito",
  ["VermilionCityBadgeGuySomeBadgesText"] = "Você começou a\ncolecionar as\vBADGES de KANTO?\fVocê não acha\nque os treinadores\vdaqui são fortes?",
  ["VermilionCityBadgeGuyTrainerText"] = "Treinadores\nhabilidosos se\freúnem em KANTO.\nOs LÍDERES são\ffortes e não são\nfáceis de vencer.",
  ["VermilionCityDiglettsCaveSignText"] = "CAVERNA DIGLETT",
  ["VermilionCityPortSignText"] = "VERMILION PORT\nENTRADA",
  ["VermilionCityRadioNearSnorlaxText"] = "Colocaram a\nPOKéGEAR perto do\vSNORLAX dormindo…\f…\fSNORLAX acordou!",
  ["VermilionCitySignText"] = "CIDADE DE\nVERMILION\fO Porto dos\nBelos Pôr do Sol",
  ["VermilionCitySnorlaxSleepingText"] = "SNORLAX ronca\ntranquilamente…",
  ["VermilionCitySuperNerdText"] = "Há oito GINÁSIOS\nem KANTO.\fAquele prédio\ngrande é o GINÁSIO\vde VERMILION.",
  ["VermilionCityTeacherText"] = "VERMILION PORT é\na porta marítima\vde KANTO.\fNavios de luxo\ndo mundo todo\vaportam aqui.",
  ["VermilionDiglettsCaveSpeechHouseGentlemanText"] = "Ao longo de anos,\nos DIGLETT cavaram\vum túnel enorme.\fEsse túnel vai\na uma vila longe.",
  ["VermilionGymGuideText"] = "Ei! Futuro\nCAMPEÃO!\fVocê deu sorte\ndesta vez.\fO LT.SURGE é muito\ncauteloso.\fTem armadilhas por\ntodo o GINÁSIO.\fMas, he-heh, as\narmadilhas não\vestão ligadas.\fVocê não vai ter\nproblema para\vchegar nele.",
  ["VermilionGymGuideWinText"] = "Ufa! Que combate\neletrizante!\fMe deixou mesmo\nnervoso.",
  ["VermilionGymSignText"] = "CIDADE DE\nVERMILION\vPOKéMON GYM\vLÍDER: LT.SURGE\fO Americano\nRelâmpago",
  ["VermilionGymTrashCanText"] = "Nada! Só tem lixo\naqui.",
  ["VermilionMachopOwnerText"] = "Meu POKéMON está\npreparando o\vterreno para a\vobra.\fMas não tenho\ndinheiro para\vcomeçar…",
  ["VermilionMachopText2"] = "Um MACHOP rosna\nenquanto pisa o\vchão para\vaplainar.",
  ["VermilionMagnetTrainSpeechHousePokefanFText"] = "Você conhece o\nMAGNET TRAIN?\fÉ uma ferrovia\nque vai até\vGOLDENROD, JOHTO.",
  ["VermilionMagnetTrainSpeechHouseYoungsterText"] = "Quero ir a SAFFRON\npara ver o\vMAGNET TRAIN.",
  ["VermilionMartBeautyText"] = "Estou pensando em\nfazer compras em\vSAFFRON.",
  ["VermilionMartSuperNerdText"] = "A TEAM ROCKET\nsumiu de KANTO.\fSó isso já me\ndeixa feliz.",
  ["VermilionPokecenter1FBugCatcherText"] = "Ué? Você tem umas\nINSÍGNIAS que eu\vnunca vi.\fAh, já sei. Você\npegou em JOHTO.",
  ["VermilionPokecenter1FFishingGuruText"] = "Um POKéMON dorme\nbem na frente da\vDIGLETT'S CAVE.\fÉ uma chance ótima\nde pegar ele,\fmas como acordar\no bicho?",
  ["VermilionPokecenter1FFishingGuruText_FoughtSnorlax"] = "Antes tinha um\nPOKéMON dormindo\fbem na frente da\nDIGLETT'S CAVE.\fMas parece que\nele sumiu.",
  ["VermilionPokecenter1FSailorText"] = "O FAST SHIP é um\nótimo lugar para\fachar e enfrentar\ntreinadores.",
  ["VermilionPortAskBoardingText"] = "Bem-vindo ao FAST\nSHIP S.S.AQUA.\fVai embarcar\nhoje?",
  ["VermilionPortAskTicketText"] = "Posso ver o seu\nS.S.TICKET?",
  ["VermilionPortCantBoardText"] = "Desculpe. Não dá\npara embarcar.",
  ["VermilionPortComeAgainText"] = "Esperamos vê-lo\nnovamente!",
  ["VermilionPortDepartingText"] = "Vamos partir logo.\nPor favor, suba\va bordo.",
  ["VermilionPortNoTicketText"] = "{PLAYER} tentou\nmostrar o S.S.\vTICKET…\f…Mas não tem!\fDesculpe!\nSó pode embarcar\fquem tiver um\nS.S.TICKET.",
  ["VermilionPortPassageTeacherText"] = "O FAST SHIP zarpa\nàs quartas e aos\vdomingos, toda\vsemana.",
  ["VermilionPortSSTicketText"] = "{PLAYER} mostrou\no S.S.TICKET.\fÉ isso.\nObrigado!",
  ["VermilionPortSailSundayText"] = "O FAST SHIP zarpa\ndomingo que vem.",
  ["VermilionPortSailWednesdayText"] = "O FAST SHIP zarpa\nna quarta-feira.",
  ["VermilionPortSuperNerdText"] = "Você veio de\nJOHTO?\fDizem que muitos\nPOKéMON raros\vvivem lá.",
  ["VictoryRoadEntranceSignText"] = "LIGA POKéMON\fVICTORY ROAD\nENTRADA",
  ["VictoryRoadGateEightBadgesText"] = "Oh! As oito\nINSÍGNIAS!\fPor favor, pode\nseguir, senhor!",
  ["VictoryRoadGateLeftBlackBeltText"] = "Este caminho leva\nao MT.SILVER.\fVocê vai ver\nPOKéMON fortes de\vdar medo lá.",
  ["VictoryRoadGateNotEnoughBadgesText"] = "Você não tem todas\nas INSÍGNIAS de\vJOHTO.\fSinto muito, mas\nnão posso deixar\vvocê passar.",
  ["VictoryRoadGateOfficerText"] = "Só passa o\ntreinador que já\vprovou seu valor.",
  ["VictoryRoadGateRightBlackBeltText"] = "Indo para a\nPOKéMON LEAGUE?\fOs ELITE FOUR são\ntão fortes que dá\fmedo, e estão\nprontos para você",
  ["VictoryRoadRivalAfterText"] = "…Não desisti\nde me tornar o\vmaior treinador…\fVou descobrir\npor que não\fconsigo vencer\ne ser mais forte…\fQuando descobrir,\neu te desafio.\fE vou te derrotar\ncom toda a minha\vforça.\f…Humf! Continue\naté lá.",
  ["VictoryRoadRivalBeforeText"] = "Espera aí.\f…Vai encarar o\ndesafio da LIGA\vPOKéMON?\f…Não me faça\nrir.\fVocê é bem mais\nfraco que eu.\fNão sou como\nantes.\fAgora tenho os\nmelhores e mais\ffortes POKéMON.\nSou invencível!\f{PLAYER}!\nEu te desafio!",
  ["VictoryRoadRivalDefeatText"] = "…Não venci…\fDei tudo o que\ntinha…\fO que você tem,\ne o que me falta…\fComeço a entender\no que aquele\fmestre de dragões\nme disse…",
  ["VictoryRoadRivalVictoryText"] = "…Humf!\fNo fim das\ncontas, nada\vvence a força.\fNão preciso de\nmais nada.",
  ["VioletCityElmsAideFullPartyText"] = "Ah, não. Você\nnão pode levar\vmais POKéMON.\fVou esperar\nenquanto você\varruma espaço.",
  ["VioletCityGrampsText"] = "FALKNER, do\nGINÁSIO POKéMON\fde VIOLET, é um\nótimo treinador!\fEle herdou o\nginásio do pai\fe fez um belo\ntrabalho nele.",
  ["VioletCityLassText"] = "Dizem que aparecem\nfantasmas na\vSPROUT TOWER.\fDiziam que ataques\nnormais não pegam\fnos fantasmas.\nNada mesmo.",
  ["VioletCitySignText"] = "CIDADE DE VIOLET\fA cidade dos\naromas de outrora",
  ["VioletCitySuperNerdText"] = "Ei, você é\ntreinador POKéMON\fSe vencer o LÍDER\nde GINÁSIO daqui,\fvai estar pronto\npara valer!",
  ["VioletCityYoungsterText"] = "Vi uma árvore que\nse mexe adiante!\fSe você tocar,\nela se contorce\ve dança! Legal!",
  ["VioletGymGuideText"] = "Ei! Não sou\ntreinador, mas dou\vum conselho!\fAcredite em mim!\nSe você acredita,\fo sonho de ser\ncampeão acontece.\fAcredita?\nEntão escute.\fO tipo planta é\nfraco contra o\ftipo voador. Não\nesqueça disso.",
  ["VioletGymGuideWinText"] = "Boa batalha!\nContinue assim e\fvocê vira CAMPEÃO\nnum piscar!",
  ["VioletGymSignText"] = "CIDADE DE VIOLET\nGINÁSIO POKéMON\vLÍDER: FALKNER\fO elegante mestre\ndo tipo voador",
  ["VioletKylesHousePokefanMText"] = "POKéMON trocado\ncresce\vrápido.\fMas sem a GYM\nBADGE certa,\feles podem\ndesobedecer você.",
  ["VioletMartCooltrainerMText"] = "POKéMON podem\nsegurar itens como\vPOTION e ANTIDOTE\fMas parece que não\nsabem usar\fitens feitos por\ngente.",
  ["VioletMartGrannyText"] = "Quando você pega\num POKéMON novo,\vele é fraco.\fMas com o tempo\nele vai ficar\vforte.\fÉ importante\ntratar POKéMON com\vcarinho.",
  ["VioletNicknameSpeechHouseBirdText"] = "STRAWBERRY:Pijji!",
  ["VioletNicknameSpeechHouseLassText"] = "Chamo meu PIDGEY\nde STRAWBERRY!",
  ["VioletNicknameSpeechHouseTeacherText"] = "Ela usa os nomes\ndas suas comidas\vpreferidas.\fNos apelidos\nque ela dá aos\vPOKéMON, digo.",
  ["VioletPokecenter1FGameboyKidText"] = "Um cara chamado\nBILL criou o\vsistema de PC dos\vPOKéMON.",
  ["VioletPokecenter1FGentlemanText"] = "Foi há mais ou\nmenos três anos.\fA TEAM ROCKET\nfazia maldades\vcom POKéMON.\fMas a justiça\nvenceu: um garoto\vacabou com eles.",
  ["VioletPokecenter1FYoungsterText"] = "POKéMON são\nespertos.\fNão obedecem a\num treinador que\fnão respeitam.\nSem as GYM BADGES\fcertas, eles só\nagem como querem.",
  ["VioletPokecenterElmsAideAskEggText"] = "{PLAYER}, você\nleva o EGG?",
  ["VioletPokecenterElmsAideFavorText"] = "{PLAYER}, faz\ntempo, hein!\fPROF.ELM pediu\npra te achar.\fEle quer pedir\noutro favor.\fAceita levar o\nPOKéMON EGG?",
  ["VioletPokecenterElmsAideGiveEggText"] = "Descobrimos que\num POKéMON não\fchoca até\ncrescer no EGG.\fEle também tem\nde ficar com\voutros POKéMON.\f{PLAYER}, você\né o único em\vquem confiamos.\fLigue pro PROF.\nELM quando o EGG\vchocar!",
  ["VioletPokecenterElmsAideRefuseText"] = "M-mas… O PROF.ELM\npediu por você…",
  ["ViridianCityCoffeeGrampsBelievedText"] = "Bom, bom. Sim, eu\nera alguém fora\fdo comum, posso\ndizer!",
  ["ViridianCityCoffeeGrampsDoubtedText"] = "O quê? Seu\nmoleque!\fSe eu fosse um\npouco mais jovem,\feu te mostraria\numa ou duas. Tsc!",
  ["ViridianCityCoffeeGrampsQuestionText"] = "Ei, garoto! Acabei\nde tomar um café\fbem forte e estou\nligado no 220!\fPreciso conversar\ncom alguém, e você\vvai servir!\fPode não parecer,\nmas eu era expert\fem capturar\nPOKéMON.\fAcredita em mim?",
  ["ViridianCityDreamEaterFisherGotDreamEaterText"] = "A MT42 contém\nDREAM EATER…\f…Zzzzz…",
  ["ViridianCityDreamEaterFisherText"] = "Bocejo!\fDevo ter dormido\nno sol.\f…Tive um sonho\ncom um DROWZEE\fcomendo meu sonho.\nEstranho, né?\fHã?\nO que é isto?\fDe onde veio\nessa MT?\fQue sinistro!\nTome, pode ficar\vcom esta MT.",
  ["ViridianCityGrampsNearGymBlueReturnedText"] = "Vai encarar o\nLÍDER?\fBoa sorte.\nVai precisar.",
  ["ViridianCityGrampsNearGymText"] = "Este GINÁSIO não\ntinha um LÍDER\vaté pouco tempo.\fUm rapaz de\nPALLET virou o\fLÍDER, mas vive\nfora.",
  ["ViridianCitySignText"] = "CIDADE DE VIRIDIAN\fO Paraíso Verde\nEterno",
  ["ViridianCityWelcomeSignText"] = "Bem-vindo a\nCIDADE DE\vVIRIDIAN,\fa Porta de Entrada\nda INDIGO PLATEAU",
  ["ViridianCityYoungsterText"] = "Ouvi dizer que há\nmuitos itens no\fchão da\nVIRIDIAN FOREST.",
  ["ViridianGymGuideText"] = "Ei, futuro\nCAMPEÃO!\fComo vai isso?\nParece que você\vestá embalado.\fO LÍDER daqui é\num cara que lutou\fcom o CAMPEÃO faz\ntrês anos.\fNão é mole não.\fDê tudo o que\nvocê tem!",
  ["ViridianGymGuideWinText"] = "Cara, você é forte\nde verdade…\fFoi uma batalha\ne tanto, das que\finspiram. Chorei\nde emoção.",
  ["ViridianGymSignText"] = "CIDADE DE VIRIDIAN\nPOKéMON GYM\vLÍDER: …\fO resto do texto\nestá ilegível…",
  ["ViridianMartCooltrainerMText"] = "Você já foi a\nCINNABAR?\fÉ uma ilha bem\nao sul daqui.",
  ["ViridianMartLassText"] = "O LÍDER daqui\né totalmente\vsensacional.",
  ["ViridianNicknameSpeechHouseLassText"] = "São o SPEARY,\num SPEAROW, e o\vRATTEY, RATTATA.",
  ["ViridianNicknameSpeechHousePokefanMText"] = "Você pensa muito\nna hora de\fdar nome aos\nseus POKéMON?\fBons apelidos\ndeixam a troca\fcom os outros\nmais divertida.",
  ["ViridianPokecenter1FBugCatcherText"] = "Meu sonho é virar\nLÍDER de GINÁSIO.",
  ["ViridianPokecenter1FCooltrainerFText"] = "Ouvi dizer que o\nGINÁSIO de\vCINNABAR sumiu.\fFico pensando no\nque foi feito do\vBLAINE, o LÍDER.",
  ["ViridianPokecenter1FCooltrainerMText"] = "Onde diabos está\no LÍDER do\fGINÁSIO daqui?\nQueria desafiar.",
  ["ViridianPokecenter1FCooltrainerMText_BlueReturned"] = "Não tem TREINADOR\nde GINÁSIO no\vGINÁSIO daqui.\fO LÍDER diz que a\npolítica dele é\fvencer sem ter\nsubordinado.",
  ["VolunteerPokemonHouseSignText"] = "LAVENDER VOLUNTEER\nPOKéMON",
  ["WardenPhotoText"] = "É a foto de um\nvelho sorridente\fcercado de\nPOKéMON.",
  ["WardensGranddaughterText1"] = "Meu avô é o\nWARDEN da\vSAFARI ZONE.\fOu era…\fEle resolveu tirar\nférias e\ffoi para fora\ndo país sozinho.\fLargou a SAFARI\nZONE assim,\vdo nada.",
  ["WardensGranddaughterText2"] = "Muita gente ficou\ndecepcionada\fcom a SAFARI ZONE\nfechada, mas o vô\vé teimoso demais…",
  ["WardensHomeSignText"] = "SAFARI ZONE\nCASA do GUARDIÃO",
  ["WesleyGaveGiftText"] = "WESLEY: BLACKBELT\naumenta a força\vde golpes lutador",
  ["WesleyGivesGiftText"] = "Prazer em te\nconhecer. Aceite\vuma lembrança.",
  ["WesleyNotWednesdayText"] = "WESLEY: Hoje não\né quarta-feira.\vQue pena.",
  ["WesleyWednesdayText"] = "WESLEY: Se me\nachou, deve ter\fconhecido meus\nirmãos e irmãs.\fOu foi só\nsorte sua?",
  ["WhitneyAttractText"] = "É o ATTRACT!\nEle usa todo o\fcharme de um\nPOKéMON.\fNão é perfeito\npara uma fofa\vcomo eu?",
  ["WhitneyBeforeText"] = "Oi! Sou WHITNEY!\fTodo mundo curtia\nPOKéMON, então eu\ventrei também!\fPOKéMON são\nfofos demais!\fQuer batalhar?\nEstou avisando,\veu sou boa!",
  ["WhitneyGoodCryText"] = "Ah, chorei bem!\nQue alívio!\fVolte para visitar\nde novo! Tchau!",
  ["WhitneyPlainBadgeText"] = "A PLAINBADGE deixa\nseu POKéMON usar\fSTRENGTH fora da\nbatalha.\fEla também aumenta\na VELOCIDADE do\vseu POKéMON.\fAh, pode ficar\ncom isto também!",
  ["WhitneyShouldntBeSoSeriousText"] = "Snif…\f…Buááááá!\nVocê é mau!\fNão devia levar\ntão a sério! Você,\vvocê, criança!",
  ["WhitneyWhatDoYouWantText"] = "…Snif…\fO quê? O que você\nquer? Uma BADGE?\fAh, é. Eu tinha\nesquecido. Tome a\vPLAINBADGE.",
  ["WhitneyYouMeanieText"] = "Buááááá!\fBuááááá!\f…Funga, soluço…\n…Seu malvado!",
  ["WillScript_WillBeatenText"] = "Eu… eu não…\nacredito nisso…",
  ["WillScript_WillBeforeText"] = "{PLAYER}, bem-vindo\nà POKéMON LEAGUE.\fDeixe eu me\napresentar. Eu sou\vo WILL.\fEu treinei no\nmundo inteiro,\fdeixando meus\npsíquicos fortes.\fE, enfim, eu fui\naceito nos\vELITE FOUR.\fEu só posso ficar\ncada vez melhor!\fPerder não é uma\nopção!",
  ["WillScript_WillDefeatText"] = "Mesmo derrotado,\neu não vou mudar\vo meu caminho.\fVou continuar\nbatalhando até\festar acima de\ntodo treinador!\fAgora, {PLAYER},\nsiga em frente e\fsinta a fúria\ndos ELITE FOUR.",
  ["WindowText"] = "Meu reflexo!\nTô bonito!",
  ["WiseTriosRoomSage1Text"] = "Espantoso…\fSUICUNE, ENTEI e\nRAIKOU acordaram\vdo sono deles…\fSerá que a lenda\nestá se tornando\vrealidade?",
  ["WiseTriosRoomSage2Text"] = "Treinamos na\nBURNED TOWER, mas\fnunca ouvimos\nde um buraco lá\fantes. Deve ter\nsido feito\fde propósito\npor alguém.",
  ["WiseTriosRoomSage3BlocksExitText"] = "A TIN TOWER pode\nser visitada por\fquem tem a BADGE\nde ECRUTEAK.\fPorém, agora que\nSUICUNE, RAIKOU\fe ENTEI\ndespertaram, peço\fque você não\nentre!",
  ["WiseTriosRoomSage3Text"] = "Nós, o TRIO\nSÁBIO, somos os\fprotetores dos\nPOKéMON\vlendários.",
  ["YoungsterAlbertAfterText"] = "Vou tentar ser o\nmelhor com os\vmeus favoritos.\fNão uso os mesmos\nPOKéMON fortes que\vtodo mundo usa.",
  ["YoungsterAlbertSeenText"] = "Nunca vi você\npor aqui antes.\fEntão você se acha\nbem durão?",
  ["YoungsterGordonAfterText"] = "O mato está cheio\nde coisa grudenta",
  ["YoungsterGordonBeatenText"] = "Droga. Achei que\nia ganhar.",
  ["YoungsterGordonSeenText"] = "Achei uns POKéMON\nbons ali no\vmato!\fAcho que eles vão\ndar conta!",
  ["YoungsterIanAfterText"] = "Me esforço para\nser o destaque\vda minha turma.",
  ["YoungsterIanBeatenText"] = "Não! Tem\ntreinadores\vmelhores…",
  ["YoungsterIanSeenText"] = "Sou o melhor da\nturma em POKéMON.",
  ["YoungsterJasonAfterBattleText"] = "Vou pegar mais\nPOKéMON ali\vno mato.",
  ["YoungsterJasonBeatenText"] = "Aiaaai!\nFui pisoteado!",
  ["YoungsterJasonSeenText"] = "Coça e faz cócega\num pouco quando\fando de shorts\nno mato.",
  ["YoungsterJimmyAfterBattleText"] = "Eu uso shorts o\nano inteiro.\fÉ a minha regra\nde moda.",
  ["YoungsterJimmySeenText"] = "Eu corro como o\nvento!",
  ["YoungsterJoey1AfterText"] = "Preciso ter\nmais POKéMON para\vbatalhas.\fVou pegar mais\num pouco!",
  ["YoungsterJoey1BeatenText"] = "Ugh. Não tenho\nmais POKéMON.",
  ["YoungsterJoey1SeenText"] = "Acabei de perder,\nvou procurar\vmais POKéMON.\fEspera! Você\nparece fraco!\vVamos batalhar!",
  ["YoungsterMikeyAfterText"] = "Virar um bom\ntreinador é\vdifícil.\fVou batalhar\ncom outras pessoas\vpara melhorar.",
  ["YoungsterMikeyBeatenText"] = "Estranho.\nEu venci antes.",
  ["YoungsterMikeySeenText"] = "Você é um\ntreinador, certo?\fEntão você tem que\nbatalhar!",
  ["YoungsterOwenAfterBattleText"] = "Lutei limpo e com\nhonra.\fNão me arrependo\nde nada.",
  ["YoungsterOwenBeatenText"] = "Hã? Como isso\naconteceu?",
  ["YoungsterSamuelAfterText"] = "Vou treinar ainda\nmais forte.\fAfinal, quero\nvirar LÍDER de\vGINÁSIO.",
  ["YoungsterSamuelBeatenText"] = "O que aconteceu?",
  ["YoungsterWarrenAfterBattleText"] = "Você parecia bom.\fFiquei com medo de\nte encarar…",
  ["YoungsterWarrenSeenText"] = "Hmmm… Não sei o\nque fazer…",
  ["YourFriendIsNotReadyText"] = "O seu amigo não\nestá pronto.",
  ["_HaveNoRoomText"] = "Você não tem\nespaço para isto.",
  ["_HeyItsFruitText"] = "Ei! É\n{RAM:wStringBuffer3}!",
  ["_LookTownMapText"] = "É o TOWN MAP.",
  ["_MartNoMoneyText"] = "Você não tem\ndinheiro.",
  ["_NotEnoughMoneyText"] = "Você não tem\ndinheiro.",
  ["_ObtainedFruitText"] = "Obteve\n{RAM:wStringBuffer3}!",
  ["_PhoneThankYouText"] = "Obrigado!",
}
